def _install_fake_residency_policy_module(monkeypatch: pytest.MonkeyPatch) -> None:
    real_import = importlib.import_module
    inference_torch = SimpleNamespace(NativeResidencyPolicy=FakeNativeResidencyPolicy)
    monkeypatch.setattr(
        importlib,
        "import_module",
        lambda name: inference_torch if name == "dinkster_inference_torch" else real_import(name),
    )


@pytest.mark.parametrize(
    "family_id",
    (
        "dinkster.flux_dev",
        "dinkster.flux_schnell",
        "dinkster.sd15",
        "dinkster.sdxl",
        "dinkster.sdxl_refiner",
        "dinkster.minimax_h3",
        "dinkster.minimax_music3",
    ),
)
def test_dtype_policy_resolves_every_native_dispatch_family(family_id: str) -> None:
    diffusion, text, vae = resolve_dtype_policy(
        family_id,
        {"diffusion": "bfloat16", "textEncoder": "float16", "vae": "float32"},
    )
    assert (diffusion.name, text.name, vae.name) == (
        "bfloat16",
        "float16",
        "float32",
    )


@pytest.mark.parametrize(
    ("family_id", "expected"),
    (
        ("dinkster.flux_dev", ("float16", "float32", "float32")),
        # Text falls back to float32, never float16, even for families
        # whose bfloat16 diffusion default degrades to float16: T5-class
        # RMS variance overflows at float16.
        ("dinkster.minimax_h3", ("float16", "float32", "float16")),
        ("dinkster.minimax_music3", ("float16", "float32", "float32")),
        ("dinkster.qwen_image", ("float16", "float32", "float16")),
        ("dinkster.sdxl", ("float16", "float32", "float32")),
        ("dinkster.wan21", ("float16", "float32", "float16")),
    ),
)
def test_dtype_policy_auto_falls_back_when_hardware_lacks_native_bfloat16(
    family_id: str, expected: tuple[str, str, str]
) -> None:
    diffusion, text, vae = resolve_dtype_policy(
        family_id,
        {"diffusion": "auto", "textEncoder": "auto", "vae": "auto"},
        frozenset({"float16", "float32"}),
    )
    assert (diffusion.name, text.name, vae.name) == expected


@pytest.mark.parametrize(
    ("family_id", "expected"),
    (
        ("dinkster.flux_dev", ("bfloat16", "bfloat16", "bfloat16")),
        ("dinkster.sd15", ("float16", "float32", "bfloat16")),
        ("dinkster.minimax_h3", ("bfloat16", "bfloat16", "float16")),
        ("dinkster.minimax_music3", ("bfloat16", "bfloat16", "float32")),
        ("dinkster.qwen_image", ("bfloat16", "bfloat16", "bfloat16")),
        ("dinkster.triposplat", ("bfloat16", "bfloat16", "float16")),
        ("dinkster.wan21", ("bfloat16", "float32", "bfloat16")),
    ),
)
def test_dtype_policy_auto_uses_family_defaults(
    family_id: str, expected: tuple[str, str, str]
) -> None:
    diffusion, text, vae = resolve_dtype_policy(
        family_id,
        {"diffusion": "auto", "textEncoder": "auto", "vae": "auto"},
    )
    assert (diffusion.name, text.name, vae.name) == expected


class FakeDevice:
    def __init__(self, name: str) -> None:
        self.name = name
        self.type = name.split(":", 1)[0]
        self.index = int(name.split(":", 1)[1]) if ":" in name else None

    def __str__(self) -> str:
        return self.name

    def __repr__(self) -> str:
        return f"FakeDevice({self.name!r})"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, FakeDevice) and self.name == other.name

    def __hash__(self) -> int:
        return hash(self.name)


class FakeCUDAOutOfMemoryError(RuntimeError):
    pass


class FakeTensor:
    def __init__(
        self,
        shape: tuple[int, ...],
        name: str = "tensor",
        *,
        device: object = "cpu",
        dtype: object = "float32",
        nbytes: int | None = None,
    ) -> None:
        self.shape = shape
        self.name = name
        self.device = FakeTorch.device(device)
        self.dtype = dtype
        self.nbytes = nbytes if nbytes is not None else max(1, _product(shape)) * 4
        self.moves: list[object] = []
        self.permutes: list[tuple[int, ...]] = []
        self.setitems: list[tuple[object, object]] = []

    @property
    def ndim(self) -> int:
        return len(self.shape)

    @property
    def layout(self) -> str:
        return "strided"

    def is_floating_point(self) -> bool:
        return self.dtype in ("float16", "bfloat16", "float32")

    def to(self, device: object) -> FakeTensor:
        resolved = FakeTorch.device(device)
        self.moves.append(resolved)
        self.device = resolved
        return self

    def detach(self) -> FakeTensor:
        return self

    def contiguous(self) -> FakeTensor:
        return self

    def float(self) -> FakeTensor:
        self.dtype = "float32"
        return self

    def permute(self, *dims: int) -> FakeTensor:
        self.permutes.append(dims)
        return FakeTensor(
            tuple(self.shape[index] for index in dims),
            self.name,
            device=self.device,
            dtype=self.dtype,
        )

    def movedim(self, source: int, destination: int) -> FakeTensor:
        rank = len(self.shape)
        source %= rank
        destination %= rank
        dims = list(range(rank))
        moved = dims.pop(source)
        dims.insert(destination, moved)
        return self.permute(*dims)

    def __getitem__(self, raw_key: object) -> FakeTensor:
        keys = raw_key if isinstance(raw_key, tuple) else (raw_key,)
        shape: list[int] = []
        for size, key in zip(self.shape, keys, strict=False):
            if isinstance(key, int):
                continue
            if isinstance(key, slice):
                start, stop, step = key.indices(size)
                shape.append(len(range(start, stop, step)))
            else:
                shape.append(size)
        shape.extend(self.shape[len(keys) :])
        return FakeTensor(tuple(shape), self.name, device=self.device, dtype=self.dtype)

    def __setitem__(self, key: object, value: object) -> None:
        self.setitems.append((key, value))

    def reshape(self, *shape: int) -> FakeTensor:
        return FakeTensor(tuple(shape), self.name, device=self.device, dtype=self.dtype)

    def transpose(self, dim0: int, dim1: int) -> FakeTensor:
        dims = list(range(len(self.shape)))
        dims[dim0], dims[dim1] = dims[dim1], dims[dim0]
        return self.permute(*dims)

    def flatten(self, start_dim: int = 0, end_dim: int = -1) -> FakeTensor:
        rank = len(self.shape)
        if start_dim < 0:
            start_dim += rank
        if end_dim < 0:
            end_dim += rank
        shape = (
            *self.shape[:start_dim],
            _product(self.shape[start_dim : end_dim + 1]),
            *self.shape[end_dim + 1 :],
        )
        return FakeTensor(shape, self.name, device=self.device, dtype=self.dtype)

    def unsqueeze(self, dim: int) -> FakeTensor:
        if dim < 0:
            dim += len(self.shape) + 1
        shape = (*self.shape[:dim], 1, *self.shape[dim:])
        return FakeTensor(shape, self.name, device=self.device, dtype=self.dtype)

    def repeat(self, *repeats: int) -> FakeTensor:
        return FakeTensor(
            tuple(size * repeat for size, repeat in zip(self.shape, repeats, strict=True)),
            self.name,
            device=self.device,
            dtype=self.dtype,
        )

    def narrow(self, dim: int, start: int, length: int) -> FakeTensor:
        assert start == 0
        shape = list(self.shape)
        shape[dim] = length
        return FakeTensor(tuple(shape), self.name, device=self.device, dtype=self.dtype)

    def _binary(self, other: object, operation: str) -> FakeTensor:
        del other
        return FakeTensor(self.shape, operation, device=self.device, dtype=self.dtype)

    def __add__(self, other: object) -> FakeTensor:
        return self._binary(other, "add")

    def __mul__(self, other: object) -> FakeTensor:
        return self._binary(other, "mul")

    def __rsub__(self, other: object) -> FakeTensor:
        return self._binary(other, "rsub")


def _product(values: tuple[int, ...]) -> int:
    result = 1
    for value in values:
        result *= value
    return result


class FakeTorch:
    Tensor = FakeTensor
    float16 = "float16"
    bfloat16 = "bfloat16"
    float32 = "float32"
    float8_e4m3fn = "float8_e4m3fn"
    float8_e5m2 = "float8_e5m2"
    strided = "strided"
    __version__ = "2.13.0"

    def __init__(
        self,
        *,
        cuda: bool = False,
        mps: bool = False,
        xpu: bool = False,
        cuda_version: str | None = "13.0",
        hip_version: str | None = None,
        total_bytes: int = 24_000,
        cuda_current_device: int = 0,
        xpu_current_device: int = 0,
    ) -> None:
        self.cuda = SimpleNamespace(
            OutOfMemoryError=FakeCUDAOutOfMemoryError,
            is_available=lambda: cuda,
            current_device=lambda: cuda_current_device,
            mem_get_info=lambda _device: (6_000, total_bytes),
        )
        self.xpu = SimpleNamespace(
            is_available=lambda: xpu,
            current_device=lambda: xpu_current_device,
        )
        self.backends = SimpleNamespace(mps=SimpleNamespace(is_available=lambda: mps))
        self.version = SimpleNamespace(cuda=cuda_version, hip=hip_version)
        self.inference_entries = 0
        self.inference_depth = 0

    @staticmethod
    def device(name: object, index: int | None = None) -> FakeDevice:
        if isinstance(name, FakeDevice):
            return name
        return FakeDevice(str(name) if index is None else f"{name}:{index}")

    @staticmethod
    def equal(left: object, right: object) -> bool:
        return left == right

    @staticmethod
    def full(
        shape: tuple[int, ...],
        _value: float,
        *,
        device: object,
        dtype: object,
    ) -> FakeTensor:
        return FakeTensor(shape, "full", device=device, dtype=dtype)

    @staticmethod
    def zeros(
        shape: tuple[int, ...],
        *,
        device: object,
        dtype: object = "float32",
        layout: object = "strided",
    ) -> FakeTensor:
        assert layout == "strided"
        return FakeTensor(shape, "zeros", device=device, dtype=dtype)

    @staticmethod
    def zeros_like(tensor: FakeTensor, *, device: object | None = None) -> FakeTensor:
        return FakeTensor(
            tensor.shape,
            "zeros",
            device=tensor.device if device is None else device,
            dtype=tensor.dtype,
        )

    @staticmethod
    def count_nonzero(tensor: FakeTensor) -> int:
        return int(tensor.name == "nonzero")

    @staticmethod
    def ones(
        shape: tuple[int, ...],
        *,
        device: object,
        dtype: object = "float32",
    ) -> FakeTensor:
        return FakeTensor(shape, "ones", device=device, dtype=dtype)

    @staticmethod
    def cat(tensors: tuple[FakeTensor, ...], dim: int = 0) -> FakeTensor:
        shape = list(tensors[0].shape)
        shape[dim] = sum(tensor.shape[dim] for tensor in tensors)
        return FakeTensor(
            tuple(shape),
            "cat",
            device=tensors[0].device,
            dtype=tensors[0].dtype,
        )

    @staticmethod
    def frombuffer(buffer: bytearray, *, dtype: object) -> FakeTensor:
        return FakeTensor((len(buffer) // 4,), "frombuffer", dtype=dtype)

    @contextmanager
    def inference_mode(self):
        self.inference_entries += 1
        self.inference_depth += 1
        try:
            yield
        finally:
            self.inference_depth -= 1

    def no_grad(self):
        return self.inference_mode()


class FixedResolver:
    def __init__(self, path: Path) -> None:
        self.path = path

    def resolve(self, digest: str) -> Path | None:
        del digest
        return self.path


class FakeModule:
    def __init__(self, nbytes: int = 16, *, buffer_nbytes: int = 0) -> None:
        self.moves: list[object] = []
        self.weight = FakeTensor((1,), "weight", nbytes=nbytes)
        self.buffer = FakeTensor((1,), "buffer", nbytes=buffer_nbytes) if buffer_nbytes else None

    def to(self, device: object) -> FakeModule:
        resolved = FakeTorch.device(device)
        self.moves.append(resolved)
        self.weight.device = resolved
        return self

    def parameters(self):  # noqa: ANN201
        return iter((self.weight,))

    def buffers(self):  # noqa: ANN201
        return iter(()) if self.buffer is None else iter((self.buffer,))

    def state_dict(self) -> dict[str, FakeTensor]:
        return {"layer.weight": self.weight}


class FakeMechanism:
    def __init__(
        self,
        module: FakeModule,
        *,
        load_device: object,
        offload_device: object,
        demand_paged: bool = False,
    ) -> None:
        self.module = module
        self.load_device = FakeTorch.device(load_device)
        self.offload_device = FakeTorch.device(offload_device)
        self._demand_paged = demand_paged
        self._loaded_bytes = 0
        self.partially_load_calls: list[int | None] = []
        self.partially_unload_calls: list[int] = []
        self.unload_calls = 0
        self.retain_offload_storage_calls = 0
        self.fail_unload = False
        self.execution_events: list[str] = []
        self.working_set_events: list[str] = []
        self.release_working_buffers_calls = 0
        self.working_buffers_released = False

    @property
    def demand_paged(self) -> bool:
        return self._demand_paged

    def total_bytes(self) -> int:
        return sum(tensor.nbytes for tensor in self.module.parameters()) + sum(
            tensor.nbytes for tensor in self.module.buffers()
        )

    def loaded_bytes(self) -> int:
        return self._loaded_bytes

    def offloaded_bytes(self) -> int:
        return self.total_bytes() - self.loaded_bytes()

    def working_set_reservation_bytes(self) -> int:
        return self.total_bytes()

    def partially_load(self, extra_memory: int | None) -> int:
        self.partially_load_calls.append(extra_memory)
        before = self._loaded_bytes
        if extra_memory is None:
            self._loaded_bytes = self.total_bytes()
        elif extra_memory < 0:
            return -self.partially_unload(-extra_memory)
        else:
            self._loaded_bytes = min(self.total_bytes(), self._loaded_bytes + extra_memory)
        if before == 0 and self._loaded_bytes > 0:
            self.module.to(self.load_device)
        return self._loaded_bytes - before

    def partially_unload(self, memory_to_free: int) -> int:
        self.partially_unload_calls.append(memory_to_free)
        before = self._loaded_bytes
        self._loaded_bytes = max(0, before - memory_to_free)
        if before > 0 and self._loaded_bytes == 0:
            self.module.to(self.offload_device)
        return before - self._loaded_bytes

    def unload(self) -> None:
        self.unload_calls += 1
        if self.fail_unload:
            raise RuntimeError("fake unload failed")
        if self._loaded_bytes > 0:
            self.module.to(self.offload_device)
            self._loaded_bytes = 0

    def release_working_buffers(self) -> bool:
        self.release_working_buffers_calls += 1
        released = self.working_buffers_released
        self.working_buffers_released = False
        return released

    def retain_offload_storage(self) -> None:
        assert self._loaded_bytes == 0
        self.retain_offload_storage_calls += 1

    @contextmanager
    def execution_context(self):  # noqa: ANN201
        self.execution_events.append("enter")
        try:
            yield
        finally:
            self.execution_events.append("exit")

    @contextmanager
    def reserve_working_set(self):  # noqa: ANN201
        self.working_set_events.append("enter")
        try:
            yield
        finally:
            self.working_set_events.append("exit")


def _fake_enroll_assembled(
    assembled: object,
    *,
    load_device: object,
    offload_device: object,
    patch_sets: object | None = None,
    patch_weight_dtype: object | None = None,
    patch_key_prefixes: object | None = None,
    storage_dtypes: object | None = None,
    mechanism_factory: object | None = None,
    memory_policy: object | None = None,
    mps_snapshot: object | None = None,
) -> dict[str, FakeMechanism]:
    del (
        patch_sets,
        patch_weight_dtype,
        patch_key_prefixes,
        storage_dtypes,
        mechanism_factory,
        memory_policy,
        mps_snapshot,
    )
    enrolled: dict[str, FakeMechanism] = {}
    for name in (
        "diffusion",
        "clip_l",
        "clip_g",
        "clip_vision",
        "t5xxl",
        "umt5xxl",
        "qwen3_4b",
        "vae",
    ):
        module = getattr(assembled, name, None)
        if module is not None:
            enrolled[name] = FakeMechanism(
                module,
                load_device=load_device,
                offload_device=offload_device,
            )
    return enrolled


class FakeManager:
    def __init__(self, *, partial_load_bytes: int | None = None) -> None:
        self._registered: list[object] = []
        self.loads: list[tuple[tuple[object, ...], int, bool]] = []
        self.removes: list[tuple[object, ...]] = []
        self.empty_cache_calls: list[object] = []
        self.partial_load_bytes = partial_load_bytes
        self.policy = object()
        self.mps_snapshot = lambda _device: object()

    def current_policy(self) -> object:
        return self.policy

    def load(
        self,
        mechanisms,
        *,
        memory_required: int = 0,
        minimum_memory: int | None = None,
        force_full_load: bool = False,
    ) -> None:  # noqa: ANN001
        del minimum_memory
        batch = tuple(mechanisms)
        self.loads.append((batch, memory_required, force_full_load))
        for mechanism in batch:
            mechanism.partially_load(self.partial_load_bytes)
            if mechanism not in self._registered:
                self._registered.insert(0, mechanism)

    def remove(  # noqa: ANN001
        self, mechanisms, *, unload: bool = True, discard: bool = False
    ) -> None:
        if discard and not unload:
            raise ValueError("discard requires unload=True")
        batch = tuple(mechanisms)
        self.removes.append(batch)
        for mechanism in batch:
            if unload:
                mechanism.unload()
            if mechanism in self._registered:
                self._registered.remove(mechanism)

    def registered(self) -> tuple[object, ...]:
        return tuple(self._registered)

    @contextmanager
    def reserve_working_sets(self, mechanisms):  # noqa: ANN001, ANN201
        with ExitStack() as stack:
            for mechanism in mechanisms:
                stack.enter_context(mechanism.reserve_working_set())
            yield

    def empty_cache(self, device: object) -> None:
        self.empty_cache_calls.append(device)


class FakePool:
    def __init__(self) -> None:
        self.labels: list[tuple[object, str]] = []
        self.loaded: list[tuple[object, bool]] = []

    def label(self, value: object, label: str) -> str:
        self.labels.append((value, label))
        return label

    def set_loaded(self, value: object, loaded: bool) -> None:
        self.loaded.append((value, loaded))


class ControlPool(FakePool):
    def __init__(self) -> None:
        super().__init__()
        self.objects: dict[str, object] = {}
        self.ids: dict[int, str] = {}

    def rid_for(self, value: object) -> str:
        rid = self.ids.get(id(value))
        if rid is None:
            rid = f"control-{len(self.objects)}"
            self.ids[id(value)] = rid
            self.objects[rid] = value
        return rid

    def get(self, rid: str) -> object:
        return self.objects[rid]


class UncopyableAttachment:
    def __deepcopy__(self, _memo: object) -> object:
        raise RuntimeError("copy denied")


def _safetensors(path: Path) -> Path:
    header = json.dumps({"weight": {"dtype": "F32", "shape": [1], "data_offsets": [0, 4]}}).encode()
    path.write_bytes(struct.pack("<Q", len(header)) + header + b"\0" * 4)
    return path


def _safetensors_shapes(path: Path, shapes: dict[str, tuple[int, ...]]) -> Path:
    offset = 0
    header: dict[str, object] = {}
    for key, shape in shapes.items():
        nbytes = _product(shape) * 4
        header[key] = {
            "dtype": "F32",
            "shape": list(shape),
            "data_offsets": [offset, offset + nbytes],
        }
        offset += nbytes
    encoded = json.dumps(header).encode()
    path.write_bytes(struct.pack("<Q", len(encoded)) + encoded + b"\0" * offset)
    return path


def _asset(path: Path) -> AssetRef:
    return AssetRef(
        digest=digest_file(path),
        name=path.name,
        size=path.stat().st_size,
        resolver=FixedResolver(path),
    )


def _mock_component_builders(
    monkeypatch: pytest.MonkeyPatch,
    family_id: str,
    component_builder: Callable[..., object] | None = None,
    model_builder: Callable[..., object] | None = None,
) -> None:
    from dinkster_inference import component_catalog
    from dinkster_inference.component_registry import ComponentRegistry

    descriptor = component_catalog.default_component_registry().get(family_id)
    assert descriptor is not None
    roles = (descriptor.model_role, *descriptor.text_encoder_roles[:1], *descriptor.codec_roles[:1])
    descriptor = replace(
        descriptor,
        detector=lambda _source, _path: tuple((role, object()) for role in roles),
    )
    registry = ComponentRegistry()
    registry.register(descriptor)
    monkeypatch.setattr(component_catalog, "default_component_registry", lambda: registry)

    def build(
        selected: object,
        asset: AssetRef,
        role: str,
        identity: str,
        torch: object,
        *,
        compute_dtype: str,
        as_model: bool,
        load_device: object,
        attention_policy: str,
        attention_route_token: object,
        storage_dtype: object | None = None,
    ) -> object:
        assert selected is descriptor
        assert attention_policy == "auto"
        assert attention_route_token is None
        if as_model:
            assert role == descriptor.model_role
            assert model_builder is not None
            assert load_device is None
            options = {"compute_dtype": compute_dtype}
            if storage_dtype is not None:
                options["storage_dtype"] = storage_dtype
            return model_builder(asset, identity, torch, **options)
        options: dict[str, object] = {"compute_dtype": compute_dtype}
        if role in descriptor.text_encoder_roles:
            options["load_device"] = load_device
        else:
            assert load_device is None
        assert component_builder is not None
        return component_builder(asset, role, identity, torch, **options)

    monkeypatch.setattr(_native_arm(), "_build_component_runtime_handle", build)


def _split_assets(
    tmp_path: Path,
    roles: tuple[str, ...] = ("clip_l", "diffusion", "t5xxl", "vae"),
) -> dict[str, AssetRef]:
    assets = {}
    for index, role in enumerate(roles, 1):
        path = _safetensors_shapes(tmp_path / f"{role}.safetensors", {f"{role}.weight": (index,)})
        assets[role] = AssetRef(
            digest=digest_file(path),
            name=path.name,
            size=path.stat().st_size,
            media_type=f"application/x-{role}",
            virtual_path=f"models/{path.name}",
            resolver=FixedResolver(path),
        )
    return assets


