def test_comfy_v3_node_adapter_prepares_hidden_context(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    model3d = importlib.import_module("dinkster_compat_comfy.model3d")
    prepared_with: list[object] = []

    class Node:
        @classmethod
        def PREPARE_CLASS_CLONE(cls, data: object):
            prepared_with.append(data)

            class Prepared:
                @classmethod
                def execute(cls, *, value: object):
                    return SimpleNamespace(result=(value,))

            return Prepared

    module = SimpleNamespace(Node=Node)
    monkeypatch.setattr(model3d.importlib, "import_module", lambda _name: module)
    assert model3d._node_outputs("comfy.fake", "Node", value="ok") == ("ok",)
    assert prepared_with == [{"hidden_inputs": {}}]


def test_memory_intensive_mesh_operations_offload_native_models_before_gpu_scratch(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    model3d = importlib.import_module("dinkster_compat_comfy.model3d")
    device = FakeDevice("cuda:1")
    torch = FakeTorch(cuda=True, cuda_current_device=1)
    order: list[object] = []
    mechanisms = (
        SimpleNamespace(load_device=device, loaded_bytes=lambda: 300),
        SimpleNamespace(load_device=FakeDevice("cpu"), loaded_bytes=lambda: 500),
    )

    class PlacementPass:
        def __enter__(self):
            order.append("lock")

        def __exit__(self, *_args: object) -> None:
            order.append("unlock")

    manager = SimpleNamespace(
        policy_memory=lambda candidate: (
            SimpleNamespace(free_total=600) if candidate == device else None
        ),
        registered=lambda: mechanisms,
        free=lambda required, candidate: order.append(("free", required, candidate)),
        empty_cache=lambda candidate: order.append(("empty", candidate)),
    )
    coordinator = SimpleNamespace(manager=manager, placement_pass=PlacementPass)
    result = SimpleNamespace(vertices=object(), faces=object())

    monkeypatch.setattr(model3d, "_torch", lambda: torch)
    monkeypatch.setattr(
        model3d.importlib,
        "import_module",
        lambda name: pytest.fail(f"unexpected dynamic import: {name}"),
    )
    monkeypatch.setattr(model3d, "default_native_residency", lambda: coordinator)
    monkeypatch.setattr(
        model3d,
        "_node_outputs",
        lambda *_args, **_kwargs: order.append("execute") or (result,),
    )
    monkeypatch.setattr(model3d, "_triangle_mesh_batch", lambda value: value)

    assert model3d.GenerationRemeshMesh.execute(mesh=object()) == {"mesh": result}
    assert order == [
        "lock",
        ("free", 900, device),
        ("empty", device),
        "execute",
        "unlock",
    ]

    order.clear()
    assert model3d.GenerationUnwrapMesh.execute(mesh=object()) == {"mesh": result}
    assert order == [
        "lock",
        ("free", 900, device),
        ("empty", device),
        "execute",
        "unlock",
    ]

    order.clear()
    assert model3d.GenerationPaintMesh.execute(mesh=object(), voxel_colors=object()) == {
        "mesh": result
    }
    assert order == ["lock", "execute", "unlock"]


