def _coordinator(arm, manager: FakeManager | None = None):  # noqa: ANN001, ANN201
    del arm
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    return residency.NativeResidencyCoordinator(manager or FakeManager())


def _handle(
    arm,
    runtime: object,
    torch: FakeTorch | None = None,
    *,
    load_device: str = "cuda:0",
    coordinator=None,  # noqa: ANN001
    recipe=None,  # noqa: ANN001
):  # noqa: ANN001, ANN201
    resolved_torch = torch or FakeTorch(cuda=True)
    resolved_recipe = _recipe() if recipe is None else recipe
    if not hasattr(runtime, "assembled"):
        cast(Any, runtime).assembled = _runtime().assembled
    if not hasattr(runtime, "runtime_identity"):
        cast(Any, runtime).runtime_identity = resolved_recipe.runtime_identity
    return arm.NativeRuntimeHandle(
        runtime,
        resolved_torch.device(load_device),
        recipe=resolved_recipe,
        coordinator=coordinator or _coordinator(arm),
        _torch_module=resolved_torch,
        _enroll_assembled=_fake_enroll_assembled,
    )


def _control_resource(  # noqa: ANN001, ANN201
    arm, *, digest: str = "a" * 64, discard_on_release: bool = False
):
    model = FakeModule(12)
    cast(Any, model).resource_digest = digest
    mechanism = FakeMechanism(model, load_device="cuda:0", offload_device="cpu")
    handle = arm.NativeComponentHandle(
        model,
        mechanism,
        FakeTorch.device("cuda:0"),
        resource_identity=digest,
        coordinator=_coordinator(arm),
        discard_on_release=discard_on_release,
    )
    return (
        arm._NativeControlNetResource(
            handle,
            "blake3:" + "1" * 64,
            digest,
            "canonical",
        ),
        mechanism,
    )


def _capture_soft_empty_cache(arm: Any, monkeypatch: pytest.MonkeyPatch) -> list[object]:
    devices: list[object] = []
    real_import_module = arm.importlib.import_module

