def test_native_scheduling_schemas_declare_pure_node_type_replacements() -> None:
    arm = _native_arm()
    for node in arm.NATIVE_SCHEDULING_NODES:
        schema = node.schema()
        assert schema.dispatch_affinity == "native"
        (alias,) = schema.aliases
        (rule,) = schema.replacements
        (case,) = rule.cases
        assert rule.from_type == f"comfy.{alias}"
        assert case.to == schema.node_type
        assert dict(case.inputs) == {spec.id: MappingSource.copy(spec.id) for spec in schema.inputs}
        assert dict(case.outputs) == {spec.id: spec.id for spec in schema.outputs}


def test_serialized_legacy_scheduling_graph_validates_and_executes() -> None:
    arm = _native_arm()
    node = arm.NativeCreateHookKeyframe
    schemas = build_schemas((node,))
    serialized = json.dumps(
        {
            "nodes": {
                "keyframe": {
                    "nodeType": "comfy.CreateHookKeyframe",
                    "inputs": {"strength_mult": 0.5, "start_percent": 0.25},
                }
            }
        }
    )
    legacy = graph_from_wire(json.loads(serialized))
    migrated = migrate_pure_node_type_replacements(legacy, schemas)

    registry = TypeRegistry()
    register_core_types(registry)
    registry.register(
        "comfy.HOOK_KEYFRAMES",
        encode=lambda value: json.dumps(cast("Any", value).points).encode(),
        decode=lambda value: arm.ScheduledHookKeyframes(
            tuple((float(percent), float(strength)) for percent, strength in json.loads(value))
        ),
    )
    effective, elaboration_diagnostics = elaborate_graph(migrated, schemas)
    diagnostics = elaboration_diagnostics + validate(
        migrated,
        schemas,
        ("keyframe",),
        effective,
        registry,
    )
    assert not has_errors(diagnostics)

    result = asyncio.run(
        Engine(
            schemas=schemas,
            registry=registry,
            worker=InProcessWorker(build_node_types((node,)), registry),
            cache=MemoryLRUCache(),
        ).run(legacy, ("keyframe",))
    )
    assert cast("Any", result.outputs["keyframe"]["HOOK_KF"].resolve()).points == ((0.25, 0.5),)
    assert "comfy.CreateHookKeyframe" not in schemas


