def test_build_text_recipe_handle_forwards_registered_attention_backends(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    component_registry = importlib.import_module("dinkster_inference.component_registry")
    text_recipes = importlib.import_module("dinkster_inference.text_recipes")
    asset = _asset(_safetensors(tmp_path / "text.safetensors"))
    attention_backends = (("gemma3_12b", "qwen"), ("connectors", "flux"))
    recipe = SimpleNamespace(runtime_identity="text-identity", overlays=())
    binding = SimpleNamespace(
        id="ltxv",
        family_id="dinkster.ltxav",
        components=(),
        loader="test:loader",
        runtime_class="test:runtime",
        recipe=lambda *args, **kwargs: recipe,
    )
    registry = SimpleNamespace(
        detect=lambda source, path: (),
        get=lambda family_id: SimpleNamespace(
            family=SimpleNamespace(engine=SimpleNamespace(attention_backends=attention_backends))
        ),
    )
    load_calls: list[dict[str, object]] = []
    loaded = SimpleNamespace(module={})
    runtime = object()
    handle = object()

    def load(_binding: object, **kwargs: object) -> object:
        load_calls.append(kwargs)
        return loaded

    def execution_symbol(reference: str) -> object:
        if reference == "test:loader":
            return load
        if reference == "test:runtime":
            return lambda loaded_value, **kwargs: runtime
        raise AssertionError(reference)

    monkeypatch.setattr(
        arm,
        "_active_inference_registries",
        lambda: SimpleNamespace(components=registry),
    )
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch(cuda=False))
    monkeypatch.setattr(arm, "_weight_source_ref", lambda *args: object())
    monkeypatch.setattr(arm, "_materialize_patch_sets", lambda *args: {})
    monkeypatch.setattr(arm, "_enroll_component_handle", lambda *args, **kwargs: handle)
    monkeypatch.setattr(component_registry, "execution_symbol", execution_symbol)
    monkeypatch.setattr(text_recipes, "resolve_text_recipe", lambda *args: binding)

    assert (
        arm.build_text_recipe_handle(
            (asset,),
            "ltxv",
            "text-identity",
            compute_dtype="bfloat16",
        )
        is handle
    )
    assert load_calls[0]["attention_backends"] == attention_backends


@pytest.mark.parametrize("same_asset", (False, True))
def test_compat_load_dual_clip_preserves_sources_and_refuses_unknown_type(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    same_asset: bool,
) -> None:
    native = importlib.import_module("dinkster_compat_comfy.native")
    first = _asset(_safetensors(tmp_path / "first.safetensors"))
    second = first if same_asset else _asset(_safetensors(tmp_path / "second.safetensors"))
    cpu = object()
    flux = object()
    calls: list[dict[str, object]] = []

    class Clip:
        def __init__(self) -> None:
            self.patcher = SimpleNamespace(cached_patcher_init=(object(), ()))

    def load_clip(**kwargs: object) -> object:
        calls.append(kwargs)
        return Clip()

    monkeypatch.setitem(sys.modules, "torch", SimpleNamespace(device=lambda _name: cpu))
    monkeypatch.setitem(
        sys.modules,
        "comfy.sd",
        SimpleNamespace(
            CLIPType=SimpleNamespace(FLUX=flux),
            load_clip=load_clip,
        ),
    )
    monkeypatch.setitem(
        sys.modules,
        "folder_paths",
        SimpleNamespace(get_folder_paths=lambda _name: ["/models/embeddings"]),
    )

    with pytest.raises(ValueError, match="unknown dual text encoding recipe 'unknown'"):
        native.LoadDualClip.execute(
            text_encoder1=first,
            text_encoder2=second,
            type="unknown",
            device="cpu",
        )
    assert not calls

    result = native.LoadDualClip.execute(
        text_encoder1=first,
        text_encoder2=second,
        type="flux",
        device="cpu",
    )

    assert calls == [
        {
            "ckpt_paths": [str(first.local_path()), str(second.local_path())],
            "embedding_directory": ["/models/embeddings"],
            "clip_type": flux,
            "model_options": {"load_device": cpu, "offload_device": cpu},
        }
    ]
    assert result["clip"].patcher.cached_patcher_init is None


def test_minimax_h3_component_builder_enrolls_through_aimdo(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "conditioner.safetensors"))
    inference = importlib.import_module("dinkster_inference")
    descriptor = replace(
        arm._component_descriptor("dinkster.minimax_h3"), loader="load_minimax_h3_component"
    )
    module = FakeModule()
    plan = inference.ComponentPlan(
        "qwen3vl-32b-conditioner", asset.local_path(), "synthetic", {}, {}, {}
    )
    loaded = SimpleNamespace(module=module, role="qwen3vl-32b-conditioner", plan=plan)
    recipe = descriptor.recipe(arm._weight_source_ref(inference, asset), loaded, "bfloat16")
    dynamic_mechanism = object()
    dynamic_free_memory = object()
    coordinator_calls: list[dict[str, object]] = []
    enrollment_calls: list[dict[str, object]] = []

    class Coordinator:
        def __init__(self, **kwargs: object) -> None:
            coordinator_calls.append(dict(kwargs))

        def enroll_component(self, component: object, **kwargs: object) -> object:
            enrollment_calls.append({"component": component, **kwargs})
            factory = kwargs.get("mechanism_factory")
            assert callable(factory)
            return factory(SimpleNamespace(module=component))

    class Handle:
        def __init__(self, _module: object, mechanism: object, _device: object, **kwargs: object):
            self.mechanism = mechanism
            self.residency_route = cast("Callable[[], object]", kwargs["residency_route_facts"])()

        def attach_pool(self, _pool: object) -> None:
            pass

    inference_torch = SimpleNamespace(
        ResidentWeights=lambda *_args, **_kwargs: object(),
        dynamic_free_memory=dynamic_free_memory,
        load_minimax_h3_component=lambda *_args, **_kwargs: loaded,
        enroll_component=object(),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: inference_torch if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(arm, "default_native_residency", Coordinator)
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "default_pool", FakePool)
    monkeypatch.setattr(
        arm,
        "_aimdo_mechanism_factory",
        lambda *_args: (lambda *_factory_args, **_factory_kwargs: dynamic_mechanism, None),
    )
    monkeypatch.setenv("DINKSTER_AIMDO_ARM", "auto")

    handle = arm._build_component_runtime_handle(
        descriptor,
        asset,
        "qwen3vl-32b-conditioner",
        recipe.runtime_identity,
        FakeTorch(cuda=True),
        compute_dtype="bfloat16",
        load_device="cuda:0",
    )

    assert handle.mechanism is dynamic_mechanism
    assert handle.residency_route == arm.ResidencyRouteFacts(
        requested="auto",
        mechanism="aimdo",
        dynamic_components=("qwen3vl-32b-conditioner",),
    )
    assert coordinator_calls == [{"free_memory": dynamic_free_memory}]
    assert "mechanism_factory" in enrollment_calls[0]


