def test_qwen_diffusion_model_handle_rebuilds_as_runtime_handle(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from dinkster_inference import (
        BFLOAT16,
        QWEN_IMAGE,
        QWEN_IMAGE_CONFIG,
    )

    arm = _native_arm()
    torch = FakeTorch(cuda=True)
    asset = _asset(_safetensors(tmp_path / "qwen-diffusion.safetensors"))
    inference = importlib.import_module("dinkster_inference")
    plan = inference.ComponentPlan("diffusion", asset.local_path(), QWEN_IMAGE_CONFIG, {}, {}, {})
    descriptor = arm._component_descriptor(QWEN_IMAGE.id)
    recipe = descriptor.recipe(
        arm._weight_source_ref(inference, asset),
        SimpleNamespace(role="diffusion", plan=plan),
        BFLOAT16.name,
    )
    loaded_modules: list[FakeModule] = []

    class Runtime:
        def __init__(
            self,
            diffusion: object,
            family: object,
            *,
            runtime_identity: str,
        ) -> None:
            self.assembled = SimpleNamespace(diffusion=diffusion)
            self.family = family
            self.runtime_identity = runtime_identity

    def load_component(*_args: object, **kwargs: object) -> object:
        assert kwargs["expected_role"] == "diffusion"
        assert kwargs["expected_identity"] == recipe.runtime_identity
        module = FakeModule(40)
        loaded_modules.append(module)
        return SimpleNamespace(module=module, role="diffusion", plan=plan)

    fake_torch_inference = SimpleNamespace(
        QwenImageDiffusionRuntime=Runtime,
        load_qwen_image_component=load_component,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    coordinator = _coordinator(arm)

    def build_handle(runtime: object, torch_module: object, **kwargs: object) -> object:
        return arm.NativeRuntimeHandle(
            runtime,
            FakeDevice("cuda:0"),
            recipe=kwargs["recipe"],
            materializer=kwargs["materializer"],
            source_resolvers=kwargs["source_resolvers"],
            coordinator=coordinator,
            _torch_module=torch_module,
            _enroll_assembled=_fake_enroll_assembled,
        )

    monkeypatch.setattr(arm, "_build_runtime_handle", build_handle)

    handle = arm._build_component_runtime_handle(
        descriptor,
        asset,
        "diffusion",
        recipe.runtime_identity,
        torch,
        compute_dtype=BFLOAT16.name,
        as_model=True,
    )

    assert isinstance(handle, arm.NativeRuntimeHandle)
    assert handle.recipe == recipe
    assert handle.runtime.family is QWEN_IMAGE
    assert handle.runtime.runtime_identity == recipe.runtime_identity
    assert handle.runtime.assembled.diffusion is loaded_modules[0]
    old_runtime = handle.runtime
    handle.terminal_release()
    rebuilt = handle.rebuild()
    assert isinstance(rebuilt, arm.NativeRuntimeHandle)
    assert rebuilt.recipe == recipe
    assert rebuilt.runtime is not old_runtime
    assert rebuilt.runtime.runtime_identity == recipe.runtime_identity
    assert rebuilt.runtime.assembled.diffusion is loaded_modules[1]


@pytest.mark.parametrize("dtype_name", ("float16", "bfloat16"))
def test_native_controlnet_loader_uses_descriptor_with_provenance(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, dtype_name: str
) -> None:
    from dinkster_inference import component_catalog, component_registry

    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "controlnet.safetensors"))
    torch = FakeTorch(cuda=True)
    model = FakeModule(12)
    monkeypatch.setattr(model, "resource_digest", "a" * 64, raising=False)
    plan = SimpleNamespace(source_layout="canonical", component=SimpleNamespace(config=object()))
    descriptor = SimpleNamespace(
        id="test.new_control",
        loader="test.new_control:load",
        hint_channels=3,
        default_diffusion_dtype=SimpleNamespace(name=dtype_name),
        family=SimpleNamespace(
            engine=SimpleNamespace(
                attention_backend=lambda role: "unet" if role == "controlnet" else None,
                attention_requires_route=True,
            )
        ),
    )
    source = object()
    mechanism = FakeMechanism(model, load_device="cuda:0", offload_device="cpu")
    pool = FakePool()
    seen: dict[str, object] = {}
    inference = SimpleNamespace(
        load_safetensors_header=lambda path, *, asset_digest, asset_size: (
            seen.update(path=path, asset_digest=asset_digest, asset_size=asset_size) or source
        ),
    )
    inference_torch = SimpleNamespace(
        enroll_component=lambda candidate, *, load_device, offload_device: (
            seen.update(
                model=candidate,
                load_device=load_device,
                offload_device=offload_device,
            )
            or mechanism
        ),
    )
    registry = SimpleNamespace(
        select=lambda candidate, path, kind: (
            seen.update(source=candidate, selected_path=path, kind=kind)
            or (descriptor, "controlnet", plan)
        )
    )
    monkeypatch.setattr(component_catalog, "default_component_registry", lambda: registry)
    monkeypatch.setattr(
        arm,
        "_builtin_inference_registries",
        lambda: SimpleNamespace(components=registry),
    )

    def resolve_loader(reference: str):
        assert reference == descriptor.loader

        def load(candidate: object, dtype: object, **kwargs: object) -> object:
            seen.update(plan=candidate, dtype=dtype, **kwargs)
            return model

        return load

    monkeypatch.setattr(component_registry, "execution_symbol", resolve_loader)
    real_import_module = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference":
            return inference
        if name == "dinkster_inference_torch":
            return inference_torch
        return real_import_module(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    route_token = object()
    monkeypatch.setattr(
        arm,
        "current_execution_context",
        lambda: SimpleNamespace(attention_policy="sdpa", attention_route_token=route_token),
    )
    monkeypatch.setattr(arm, "default_native_residency", lambda: _coordinator(arm))
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    resource = arm.NativeControlNetLoader.execute(control_net_name=asset)["control_net"]

    assert isinstance(resource, arm._NativeControlNetResource)
    assert resource.handle is not None
    assert resource.handle.module is model
    assert not resource.handle.discard_on_release
    assert (resource.asset_digest, resource.resource_digest, resource.source_layout) == (
        asset.digest,
        "a" * 64,
        "canonical",
    )
    assert seen == {
        "path": asset.local_path(),
        "source": source,
        "asset_digest": asset.digest,
        "asset_size": asset.size,
        "selected_path": asset.local_path(),
        "kind": "controlnet",
        "plan": plan,
        "dtype": getattr(torch, dtype_name),
        "attention_policy": "sdpa",
        "attention_route_token": route_token,
        "attention_backend": "unet",
        "model": model,
        "load_device": torch.device("cuda:0"),
        "offload_device": torch.device("cpu"),
    }
    assert pool.labels == [(resource.handle, asset.name)]


