def test_native_controlnet_apply_snapshots_and_chains_oldest_to_newest(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import ControlApplication, PercentRange

    arm = _native_arm()
    resource, _mechanism = _control_resource(arm)
    pool = ControlPool()
    snapshot = arm._ControlHintSnapshot((1, 3, 8, 8), b"\x01" * (1 * 3 * 8 * 8 * 4), "b" * 64)
    real_import_module = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return SimpleNamespace()
        return real_import_module(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch())
    monkeypatch.setattr(arm, "_snapshot_control_hint", lambda *_args: snapshot)
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    positive = [[FakeTensor((1, 77, 4)), {"pooled_output": FakeTensor((1, 4))}]]
    negative = [[FakeTensor((1, 77, 4)), {}]]

    first = arm.NativeControlNetApplyAdvanced.execute(
        positive=positive,
        negative=negative,
        control_net=resource,
        image=object(),
        strength=1.0,
        start_percent=0.0,
        end_percent=0.75,
    )
    second = arm.NativeControlNetApplyAdvanced.execute(
        positive=first["positive"],
        negative=first["negative"],
        control_net=resource,
        image=object(),
        strength=0.5,
        start_percent=0.25,
        end_percent=1.0,
    )

    positive_binding = second["positive"][0][1]["control"]
    negative_binding = second["negative"][0][1]["control"]
    assert isinstance(positive_binding, arm._ClassicControlBinding)
    assert positive_binding == negative_binding
    assert not positive_binding.apply_to_uncond
    assert len(positive_binding.entries) == 2
    application = positive_binding.application
    assert type(application) is ControlApplication
    assert (application.strength, application.window) == (0.5, PercentRange(0.25, 1.0))
    assert application.previous is not None
    assert (application.previous.strength, application.previous.window) == (
        1.0,
        PercentRange(0.0, 0.75),
    )
    assert application.hint.id == snapshot.digest
    assert positive_binding.entries[0].hint is snapshot
    assert positive_binding.entries[1].hint is snapshot
    assert pickle.loads(pickle.dumps(positive_binding)) == positive_binding
    assert "control" not in positive[0][1]
    assert "control" not in negative[0][1]


