def test_generation_controlnet_carriers_chain_and_roundtrip_with_resource_dependencies(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ConditioningSet,
        ResidentConditioningCarrier,
        make_conditioning_carrier,
        register_conditioning_type,
    )
    from dinkster_values import RESOURCE_REFS_META_KEY, ResidencyTable, TypeRegistry

    arm = _native_arm()
    resource, _mechanism = _control_resource(arm)
    pool = ResidencyTable()
    snapshot = arm._ControlHintSnapshot((1, 3, 8, 8), bytes(3 * 8 * 8 * 4), "b" * 64)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: SimpleNamespace() if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch())
    monkeypatch.setattr(arm, "_snapshot_control_hint", lambda *_args: snapshot)
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    carrier = make_conditioning_carrier(ConditioningSet(()), ())
    union = arm.GenerationSetControlNetUnionType.execute(
        control_net=resource, type="canny/lineart/anime_lineart/mlsd"
    )["control_net"]
    assert union.mode.token == "canny"
    assert resource.mode is None
    automatic = arm.GenerationSetControlNetUnionType.execute(control_net=union)["control_net"]
    assert automatic.mode is None

    first = arm.GenerationApplyControlNetAdvanced.execute(
        positive=carrier, negative=carrier, control_net=union, image=object(), vae=object()
    )
    second = arm.GenerationApplyControlNetAdvanced.execute(
        positive=first["positive"],
        negative=first["negative"],
        control_net=resource,
        image=object(),
        strength=0.5,
        start_percent=0.25,
        end_percent=0.75,
    )
    result = second["positive"]
    assert isinstance(result, ResidentConditioningCarrier)
    assert cast("Any", result.payload).conditioning is carrier
    binding = arm._select_classic_control_binding(result, second["negative"])
    assert binding.application.strength == 0.5
    assert binding.application.previous.mode.token == "canny"
    assert len(binding.entries) == 2
    assert result._dinkster_resident_refs == (resource.handle, resource.handle)

    spec = register_conditioning_type(TypeRegistry(), resident_table=pool)
    assert spec.fingerprint is not None
    assert spec.meta is not None
    assert spec.decode(spec.encode(result)) is result
    assert spec.fingerprint(result) == spec.fingerprint(second["negative"])
    assert spec.fingerprint(result) != spec.fingerprint(first["positive"])
    assert spec.meta(result)[RESOURCE_REFS_META_KEY] == (
        "resident:" + pool.rid_for(resource.handle),
    )
    with pytest.raises(ValueError, match="chains must match"):
        arm._select_classic_control_binding(result, first["negative"])
    deprecated = arm.GenerationApplyControlNet.execute(
        conditioning=carrier, control_net=resource, image=object()
    )["conditioning"]
    assert arm._select_classic_control_binding(deprecated, carrier).apply_to_uncond
    bypass = arm.GenerationApplyControlNetAdvanced.execute(
        positive=carrier, negative=carrier, control_net=None, image=None, strength=0.0
    )
    assert bypass == {"positive": carrier, "negative": carrier}


