def test_native_memory_policy_reads_fresh_process_values(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    policy_module = importlib.import_module("dinkster_compat_comfy.memory_policy")
    constructed: list[dict[str, object]] = []

    def memory_policy(**kwargs: object) -> object:
        constructed.append(kwargs)
        return object()

    monkeypatch.setattr(
        policy_module.importlib,
        "import_module",
        lambda name: SimpleNamespace(MemoryPolicy=memory_policy),
    )
    monkeypatch.delenv("DINKSTER_ACCELERATOR_HEADROOM_BYTES", raising=False)
    monkeypatch.delenv("DINKSTER_ACCELERATOR_BUDGETS", raising=False)
    monkeypatch.delenv("DINKSTER_ACCELERATOR", raising=False)
    policy_module.native_memory_policy()
    monkeypatch.setenv("DINKSTER_ACCELERATOR_HEADROOM_BYTES", "0")
    monkeypatch.setenv("DINKSTER_ACCELERATOR_BUDGETS", "1=50,0=0")
    policy_module.native_memory_policy()
    monkeypatch.setenv("DINKSTER_ACCELERATOR", "xpu")
    policy_module.native_memory_policy()
    monkeypatch.setenv("DINKSTER_ACCELERATOR", "rocm")
    policy_module.native_memory_policy()

    assert constructed == [
        {"physical_headroom": 256 * 1024**2, "hard_budgets": {}},
        {
            "physical_headroom": 0,
            "hard_budgets": {"cuda:0": 0, "cuda:1": 50},
        },
        {
            "physical_headroom": 0,
            "hard_budgets": {"xpu:0": 0, "xpu:1": 50},
        },
        {
            "physical_headroom": 0,
            "hard_budgets": {"cuda:0": 0, "cuda:1": 50},
        },
    ]


