def test_native_component_handle_stages_unloads_and_releases_terminally() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    torch = FakeTorch(cuda=True)
    module = FakeModule(20)
    mechanism = FakeMechanism(
        module,
        load_device=torch.device("cuda:0"),
        offload_device=torch.device("cpu"),
    )
    manager = FakeManager()
    coordinator = residency.NativeResidencyCoordinator(manager)
    route = residency.ResidencyRouteFacts(requested="auto", mechanism="aimdo")
    handle = residency.NativeComponentHandle(
        module,
        mechanism,
        torch.device("cuda:0"),
        resource_identity="native:test-component:" + "1" * 64,
        coordinator=coordinator,
        residency_route_facts=lambda: route,
    )
    pool = FakePool()
    handle.attach_pool(pool)

    assert handle.residency_route is route

    with handle.stage(memory_required=1234, observer_stage="sample"):
        assert handle.module is module
        assert mechanism.loaded_bytes() == mechanism.total_bytes()
        assert mechanism.execution_events == ["enter"]
    coordinator.advisory_unload_components("native:other:" + "2" * 64)
    assert mechanism.loaded_bytes() == mechanism.total_bytes()
    coordinator.advisory_unload_components(handle.resource_identity)
    assert mechanism.loaded_bytes() == 0
    handle.terminal_release()
    coordinator.advisory_unload_components(handle.resource_identity)

    assert manager.removes == [(mechanism,)]
    assert manager.loads == [((mechanism,), 1234, False)]
    assert mechanism.execution_events == ["enter", "exit"]
    assert pool.loaded == [
        (handle, False),
        (handle, True),
        (handle, True),
        (handle, False),
        (handle, False),
    ]
    with pytest.raises(residency.NativeRuntimeReleasedError, match="component handle"):
        handle.require_active()
    with pytest.raises(residency.NativeRuntimeReleasedError, match="component handle"):
        _ = handle.module


