def test_native_component_handle_evicts_and_rebuilds_from_recipe() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    torch = FakeTorch(cuda=True)
    manager = FakeManager()
    coordinator = residency.NativeResidencyCoordinator(manager)
    recipe = _recipe()
    built: list[object] = []

    def build(retained_recipe: object, _resolvers: Mapping[str, object]):
        module = FakeModule(20)
        mechanism = FakeMechanism(
            module,
            load_device=torch.device("cuda:0"),
            offload_device=torch.device("cpu"),
        )
        handle = residency.NativeComponentHandle(
            module,
            mechanism,
            torch.device("cuda:0"),
            resource_identity=recipe.runtime_identity,
            coordinator=coordinator,
            recipe=retained_recipe,
            materializer=build,
        )
        built.append(handle)
        return handle

    component = build(recipe, {})
    first_module = component.module
    with component.stage():
        assert component.mechanisms[0].loaded_bytes() == 20
    component.advisory_unload()
    assert component.mechanisms[0].loaded_bytes() == 0
    with component.stage():
        assert component.mechanisms[0].loaded_bytes() == 20

    component.terminal_release()
    rebuilt = component.rebuild()
    assert component.released
    assert rebuilt is built[-1]
    assert rebuilt is not component
    assert rebuilt.module is not first_module
    assert rebuilt.resource_identity == component.resource_identity == recipe.runtime_identity
    assert rebuilt.recipe == recipe


def test_native_component_handle_clone_appends_overlays_and_resolvers() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    torch = FakeTorch(cuda=True)
    recipe = _recipe()
    overlay = _overlay()
    existing_resolver = object()
    added_resolver = object()
    calls: list[tuple[object, Mapping[str, object]]] = []
    clone = object()

    def materialize(retained_recipe: object, resolvers: Mapping[str, object]) -> object:
        calls.append((retained_recipe, dict(resolvers)))
        return clone

    component = residency.NativeComponentHandle(
        FakeModule(20),
        FakeMechanism(
            FakeModule(20),
            load_device=torch.device("cuda:0"),
            offload_device=torch.device("cpu"),
        ),
        torch.device("cuda:0"),
        resource_identity=recipe.runtime_identity,
        coordinator=residency.NativeResidencyCoordinator(FakeManager()),
        recipe=recipe,
        materializer=cast("Any", materialize),
        source_resolvers={"existing": existing_resolver},
    )

    result = component.clone((overlay,), source_resolvers={"added": added_resolver})

    assert result is clone
    assert calls == [
        (
            recipe.append_overlays((overlay,)),
            {"existing": existing_resolver, "added": added_resolver},
        )
    ]


def test_native_component_publisher_enrolls_and_releases_pack_components() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    torch = FakeTorch(cuda=True)
    cast("Any", torch).nn = SimpleNamespace(Module=FakeModule)
    manager = FakeManager()
    coordinator = residency.NativeResidencyCoordinator(manager)
    pool = FakePool()
    enrolled: list[tuple[object, object, object]] = []

    def enroll_component(
        module: object,
        *,
        load_device: object,
        offload_device: object,
    ) -> FakeMechanism:
        enrolled.append((module, load_device, offload_device))
        return FakeMechanism(
            cast("FakeModule", module),
            load_device=load_device,
            offload_device=offload_device,
        )

    publisher = residency.NativeComponentPublisher(
        coordinator=coordinator,
        _torch_module=torch,
        _enroll_component=enroll_component,
        _pool=pool,
    )
    module = FakeModule(20)
    identity = "native:test-component:" + "4" * 64
    handle = publisher.publish(module, resource_identity=identity)

    assert handle.component is module
    assert handle.resource_identity == identity
    assert enrolled == [(module, torch.device("cuda:0"), torch.device("cpu"))]
    assert pool.labels == [(handle, identity)]
    publisher.close()
    assert handle.released
    assert len(manager.removes) == 1
    publisher.close()
    with pytest.raises(RuntimeError, match="publisher is closed"):
        publisher.publish(FakeModule(1), resource_identity=identity)


