    mechanism = FakeMechanism(
        FakeModule(20),
        load_device=torch.device("cuda:0"),
        offload_device=torch.device("cpu"),
    )

    class FailingPool(FakePool):
        def label(self, value: object, label: str) -> str:
            del value, label
            raise RuntimeError("label failed")

    publisher = residency.NativeComponentPublisher(
        coordinator=coordinator,
        _torch_module=torch,
        _enroll_component=lambda *_args, **_kwargs: mechanism,
        _pool=FailingPool(),
    )

