def test_native_load_lora_defers_diffusion_overlay_and_warns_for_unmatched(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    caplog: pytest.LogCaptureFixture,
) -> None:
    arm = _native_arm()
    lora = _asset(
        _safetensors_shapes(
            tmp_path / "style.safetensors",
            {
                "lora_unet_layer.lora_down.weight": (1, 1),
                "lora_unet_layer.lora_up.weight": (1, 1),
                "unmatched.tensor": (1,),
            },
        )
    )
    lora_sidecar = tmp_path / "style.resolved.safetensors"
    shutil.copyfile(lora.local_path(), lora_sidecar)
    resolved_loras: list[Path] = []

    def resolve_lora(path: Path, *, logical_name: str | None = None) -> Path:
        resolved_loras.append(path)
        assert logical_name == lora.name
        return lora_sidecar

    monkeypatch.setattr(arm, "resolve_weight_source", resolve_lora)
    built: list[tuple[object, dict[str, object]]] = []

    def materializer(next_recipe: object, resolvers: object):
        runtime = _runtime()
        runtime.runtime_identity = cast(Any, next_recipe).runtime_identity
        runtime.sample_proof = 7 + 42 * len(cast(Any, next_recipe).overlays)
        handle = arm.NativeRuntimeHandle(
            runtime,
            FakeDevice("cuda:0"),
            recipe=next_recipe,
            materializer=materializer,
            source_resolvers=cast(dict[str, object], resolvers),
            coordinator=_coordinator(arm),
            _torch_module=FakeTorch(cuda=True),
            _enroll_assembled=_fake_enroll_assembled,
        )
        built.append((handle, dict(cast(dict[str, object], resolvers))))
        return handle

    pool = FakePool()
    base = arm.NativeRuntimeHandle(
        _runtime(),
        FakeDevice("cuda:0"),
        recipe=_recipe(),
        materializer=materializer,
        coordinator=_coordinator(arm),
        _torch_module=FakeTorch(cuda=True),
        _enroll_assembled=_fake_enroll_assembled,
    )
    base.runtime.sample_proof = 7
    base.attach_pool(pool)
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    outputs = arm.NativeLoadLora.execute(
        model=base,
        clip=base,
        lora=lora,
        strength_model=0.75,
        strength_clip=0.25,
    )

    model = outputs["model"]
    assert isinstance(model, arm._NativeModelOverlay)
    assert model.handle is base
    assert outputs["clip"] is base
    assert built == []
    assert base.recipe.overlays == ()
    (overlay,) = model.overlays
    assert overlay.source.digest == lora.digest
    assert overlay.source.name == lora.name
    assert resolved_loras == [lora.local_path()]
    assert overlay.strength_model == "0.75"
    assert overlay.strength_clip == "0.25"
    assert overlay.key_map == "native.dinkster.sd15.v1"
    assert tuple((patch.component, patch.target.key) for patch in overlay.patches) == (
        ("diffusion", "layer.weight"),
    )
    assert model.source_resolvers == {lora.digest: lora.resolver}
    assert base.runtime.sample_proof == 7
    assert "unmatched keys" in caplog.text
    assert "unmatched.tensor" in caplog.text
    assert pool.labels == []
    assert base.recipe.overlays == ()
    assert base.runtime.runtime_identity == _recipe().runtime_identity


def test_recipe_materializer_groups_overlays_and_enables_compute_following_storage(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from dataclasses import replace

    from dinkster_inference import (
        DiffPatchRef,
        OverlayPatch,
        PatchEntry,
        PatchOverlay,
        PatchSet,
        PatchTarget,
        SetPatch,
        load_safetensors_header,
    )

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    checkpoint = _asset(_safetensors_shapes(tmp_path / "checkpoint.safetensors", {"weight": (1,)}))
    first_asset = _asset(_safetensors_shapes(tmp_path / "first.safetensors", {"first": (2,)}))
    second_asset = _asset(_safetensors_shapes(tmp_path / "second.safetensors", {"second": (3,)}))
    resolved_paths: list[Path] = []
    sidecars: dict[Path, Path] = {}
    for asset in (checkpoint, first_asset, second_asset):
        original = asset.local_path()
        sidecar = original.with_name(f"{original.stem}.resolved.safetensors")
        shutil.copyfile(original, sidecar)
        sidecars[original] = sidecar

    def resolve_source(path: Path, *, logical_name: str | None = None) -> Path:
        resolved_paths.append(path)
        assert logical_name == next(
            asset.name
            for asset in (checkpoint, first_asset, second_asset)
            if asset.local_path() == path
        )
        return sidecars[path]

    monkeypatch.setattr(arm, "resolve_weight_source", resolve_source)

    def declared_overlay(
        asset: AssetRef, strength: float, decoded_key: str, *, include_clip: bool
    ) -> PatchOverlay:
        patches = [OverlayPatch("diffusion", PatchTarget("weight"), DiffPatchRef(decoded_key))]
        if include_clip:
            patches.append(OverlayPatch("clip_l", PatchTarget("weight"), DiffPatchRef(decoded_key)))
        return PatchOverlay.from_decoded(
            source=arm._weight_source_ref(inference, asset),
            dialect="none",
            key_map="native.dinkster.sd15.v1",
            strength_model=strength,
            strength_clip=0.0,
            patches=tuple(patches),
        )

    overlays = (
        declared_overlay(first_asset, 0.25, "first", include_clip=True),
        declared_overlay(second_asset, 0.75, "second", include_clip=False),
    )
    recipe = replace(
        _recipe(),
        sources=(
            inference.WeightSourceBinding(
                "checkpoint", arm._weight_source_ref(inference, checkpoint)
            ),
        ),
        overlays=overlays,
    )
    calls: list[tuple[str, float]] = []

    def load_tensors(path: Path, _keys: object) -> dict[str, object]:
        return {"source": path.name}

    def build_patch_set(decoded: object, tensors: object, *, strength: float) -> object:
        [(target, patch)] = cast(Any, decoded).items()
        source_name = cast(Any, tensors)["source"]
        calls.append((source_name, strength))
        return PatchSet(
            cast(
                Any,
                {
                    target.key: (
                        PatchEntry(
                            SetPatch(cast(Any, (source_name, patch.key))),
                            strength=strength,
                        ),
                    )
                },
            )
        )

    load_calls: list[dict[str, object]] = []

    def load_runtime(**kwargs: object) -> object:
        load_calls.append(dict(kwargs))
        return SimpleNamespace(runtime_identity=recipe.runtime_identity)

    inference_torch = SimpleNamespace(
        build_patch_set=build_patch_set,
        load_runtime=load_runtime,
        load_tensors=load_tensors,
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    plan = SimpleNamespace(family=SimpleNamespace(id=recipe.family_id), identity_components=())
    monkeypatch.setattr(inference, "plan_native", lambda **_sources: plan)
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference":
            return inference
        if name == "dinkster_inference_torch":
            return inference_torch
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    built: list[dict[str, object]] = []

    def build_handle(runtime: object, _torch: object, **kwargs: object) -> object:
        built.append({"runtime": runtime, **kwargs})
        return SimpleNamespace(recipe=recipe, runtime=runtime)

    monkeypatch.setattr(arm, "_build_runtime_handle", build_handle)
    resolvers = {
        checkpoint.digest: checkpoint.resolver,
        first_asset.digest: first_asset.resolver,
        second_asset.digest: second_asset.resolver,
    }

    handle = arm._materialize_recipe_handle(recipe, resolvers, FakeTorch())

    assert handle.recipe is recipe
    assert load_calls == [
        {
            "checkpoint": load_safetensors_header(
                sidecars[checkpoint.local_path()],
                asset_digest=checkpoint.digest,
                asset_size=checkpoint.size,
            ),
            "expected_identity": recipe.runtime_identity,
            "storage_dtype_follows_compute": True,
            "fp8_matmul": False,
            "diffusion_dtype": FakeTorch.float16,
            "text_dtype": FakeTorch.float32,
            "vae_dtype": FakeTorch.float32,
            "patch_overlay_digests": tuple(overlay.structural_digest for overlay in overlays),
        }
    ]
    assert calls == [
        ("first.resolved.safetensors", 0.25),
        ("second.resolved.safetensors", 0.75),
    ]
    assert resolved_paths == [
        checkpoint.local_path(),
        first_asset.local_path(),
        second_asset.local_path(),
    ]
    assert recipe.sources[0].source.digest == checkpoint.digest
    assert recipe.sources[0].source.name == checkpoint.name
    patch_sets = cast(dict[str, Any], built[0]["patch_sets"])
    assert tuple(patch_sets) == ("diffusion",)
    assert patch_sets["diffusion"].structural_digest == recipe.patch_stack_digest
    assert [
        cast(Any, entry.value).value for entry in patch_sets["diffusion"].entries("weight")
    ] == [
        ("first.resolved.safetensors", "first"),
        ("second.resolved.safetensors", "second"),
    ]


def test_split_recipe_sorts_roles_and_retains_complete_asset_refs(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    assets = _split_assets(tmp_path)
    unsorted_assets = {role: assets[role] for role in ("vae", "t5xxl", "diffusion", "clip_l")}
    headers = {role: object() for role in unsorted_assets}
    planned: list[dict[str, object]] = []
    plan = SimpleNamespace(
        family=SimpleNamespace(id="dinkster.flux_dev"),
        identity_components=("plan",),
    )
    monkeypatch.setattr(
        inference,
        "plan_native",
        lambda **sources: planned.append(dict(sources)) or plan,
    )
    monkeypatch.setattr(
        inference,
        "runtime_component_identity",
        lambda family, _components: (f"family={family}", "split-proof"),
    )

    recipe = arm._runtime_recipe(
        inference,
        unsorted_assets,
        headers,
        fp8_matmul=True,
        extension_snapshot_digest=None,
    )

    planned_sources = dict(planned[0])
    assert planned_sources.pop("fp8_matmul") is True
    assert tuple(planned_sources) == ("clip_l", "diffusion", "t5xxl", "vae")
    assert tuple(binding.role for binding in recipe.sources) == tuple(planned_sources)
    for binding in recipe.sources:
        asset = assets[binding.role]
        assert binding.source.digest == asset.digest
        assert binding.source.name == asset.name
        assert binding.source.size == asset.size
        assert binding.source.media_type == asset.media_type
        assert binding.source.virtual_path == asset.virtual_path


