def test_split_recipe_materializer_verifies_and_loads_every_named_source(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    assets = _split_assets(tmp_path)
    recipe = _split_recipe(arm, assets)
    expected_paths = {role: asset.local_path() for role, asset in assets.items()}
    events: list[str] = []
    planned: list[dict[str, object]] = []
    loaded: list[dict[str, object]] = []
    real_local_path = AssetRef.local_path
    real_load_header = inference.load_safetensors_header

    def local_path(self: AssetRef) -> Path:
        events.append("resolve")
        return real_local_path(self)

    def load_header(path: Path, **_identity: object) -> object:
        assert events == ["resolve"] * 4 + ["header"] * events.count("header")
        events.append("header")
        return real_load_header(path)

    def plan_native(**sources: object) -> object:
        planned.append(dict(sources))
        return SimpleNamespace(
            family=SimpleNamespace(id=recipe.family_id),
            identity_components=(_clip_text_plan(),),
        )

    def load_runtime(**kwargs: object) -> object:
        loaded.append(dict(kwargs))
        return SimpleNamespace(runtime_identity=recipe.runtime_identity)

    monkeypatch.setattr(AssetRef, "local_path", local_path)
    monkeypatch.setattr(
        arm,
        "resolve_weight_source",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("split sources must not use legacy filename resolution")
        ),
    )
    monkeypatch.setattr(inference, "load_safetensors_header", load_header)
    monkeypatch.setattr(inference, "plan_native", plan_native)
    monkeypatch.setattr(
        inference,
        "runtime_component_identity",
        lambda _family, _components: recipe.component_identity,
    )
    inference_torch = SimpleNamespace(
        load_runtime=load_runtime,
        torch_sampler_registry=_fake_torch_sampler_registry,
        worker_planning_context=lambda: pytest.fail(
            "generic native reconstruction must not request MiniMax H3 planning context"
        ),
    )
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference":
            return inference
        if name == "dinkster_inference_torch":
            return inference_torch
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    built: list[dict[str, object]] = []

    def build_handle(runtime: object, _torch: object, **kwargs: object) -> object:
        built.append({"runtime": runtime, **kwargs})
        return SimpleNamespace(recipe=recipe, runtime=runtime)

    monkeypatch.setattr(arm, "_build_runtime_handle", build_handle)
    resolvers = {asset.digest: asset.resolver for asset in assets.values()}

    handle = arm._materialize_recipe_handle(recipe, resolvers, FakeTorch())

    roles = ("clip_l", "diffusion", "t5xxl", "vae")
    assert handle.recipe is recipe
    assert planned[0].pop("fp8_matmul") is False
    assert tuple(planned[0]) == roles
    assert tuple(loaded[0])[:4] == roles
    for role in roles:
        assert cast(Any, planned[0][role]).path == expected_paths[role]
        assert loaded[0][role] is planned[0][role]
    assert events == ["resolve"] * 4 + ["header"] * 4
    assert loaded[0]["expected_identity"] == recipe.runtime_identity
    assert loaded[0]["storage_dtype_follows_compute"] is True
    assert loaded[0]["fp8_matmul"] is False
    assert loaded[0]["patch_overlay_digests"] == ()
    assert built[0]["source_resolvers"] is resolvers


