def test_split_recipe_materializer_refuses_swapped_roles(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from dataclasses import replace

    from dinkster_inference import WeightSourceBinding

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    assets = _split_assets(tmp_path)
    recipe = _split_recipe(arm, assets)
    refs = {binding.role: binding.source for binding in recipe.sources}
    swapped = replace(
        recipe,
        sources=tuple(
            WeightSourceBinding(
                role,
                refs[
                    "diffusion" if role == "clip_l" else "clip_l" if role == "diffusion" else role
                ],
            )
            for role in sorted(refs)
        ),
    )

    def refuse_swapped(**sources: object) -> object:
        assert cast(Any, sources["clip_l"]).path.name == "diffusion.safetensors"
        assert cast(Any, sources["diffusion"]).path.name == "clip_l.safetensors"
        raise RuntimeError("swapped source role")

    monkeypatch.setattr(inference, "plan_native", refuse_swapped)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            inference
            if name == "dinkster_inference"
            else SimpleNamespace()
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    resolvers = {asset.digest: asset.resolver for asset in assets.values()}

    with pytest.raises(RuntimeError, match="swapped source role"):
        arm._materialize_recipe_handle(swapped, resolvers, object())


