def test_native_lora_stack_clones_all_ordered_overlays_once(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    base = _handle(arm, _runtime())
    first = _asset(_safetensors(tmp_path / "first.safetensors"))
    second = _asset(_safetensors(tmp_path / "second.safetensors"))
    overlays: list[object] = []

    def overlay(_handle: object, lora: object, model: float, clip: float) -> object:
        value = SimpleNamespace(
            lora=lora,
            model=model,
            clip=clip,
            patches=(SimpleNamespace(component="diffusion", target=SimpleNamespace(offset=None)),),
        )
        overlays.append(value)
        return value

    clone = object()
    calls: list[tuple[object, object]] = []
    monkeypatch.setattr(arm, "_native_lora_overlay", overlay)
    monkeypatch.setattr(
        base,
        "clone",
        lambda items, *, source_resolvers: calls.append((items, source_resolvers)) or clone,
    )
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    result = arm._apply_native_lora_stack(
        base,
        base,
        ((first, 0.25, 0.5), (second, 0.75, 0.125)),
        "precalculate",
    )

    assert result == (clone, clone)
    assert calls == [
        (
            tuple(overlays),
            {first.digest: first.resolver, second.digest: second.resolver},
        )
    ]
    assert [item.lora for item in cast("list[Any]", overlays)] == [first, second]
    assert pool.labels == [(clone, "test.safetensors + second.safetensors")]


