    assert isinstance(model, arm._NativeModelOverlay)
    assert model.handle is base
    assert model.overlays == tuple(overlays)
    assert model.source_resolvers == {
        first.digest: first.resolver,
        second.digest: second.resolver,
    }
    assert (
        arm.NativeLoadLoraModelOnly.execute(model=model, lora=second, strength_model=0.0)["model"]
        is model
    )


