@pytest.mark.parametrize(
    ("family_id", "sampling_shift"),
    (
        ("dinkster.wan21", None),
        ("dinkster.wan22", 8.0),
    ),
)
def test_runtime_without_scheduled_lora_resolution_precalculates_and_preserves_sampling(
    family_id: str,
    sampling_shift: float | None,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    caplog: pytest.LogCaptureFixture,
) -> None:
    arm = _native_arm()
    runtime = _runtime()
    runtime.family = SimpleNamespace(id=family_id)
    runtime.sample_scheduled = None
    base = _handle(arm, runtime)
    model: object = base
    if sampling_shift is not None:
        model = arm._NativeModelOverlay(base, (), {}, sampling_shift=sampling_shift)
    lora = _asset(_safetensors(tmp_path / "wan.safetensors"))
    overlay = SimpleNamespace(patches=(SimpleNamespace(component="diffusion"),))
    full_clone, model_clone, attached_full_clone, attached_model_clone = (
        object(),
        object(),
        object(),
        object(),
    )
    clones = iter((full_clone, model_clone, attached_full_clone, attached_model_clone))
    clone_calls: list[tuple[object, object]] = []
    monkeypatch.setattr(arm, "_native_lora_overlay", lambda *_args: overlay)
    monkeypatch.setattr(
        base,
        "clone",
        lambda overlays, *, source_resolvers: (
            clone_calls.append((overlays, source_resolvers)) or next(clones)
        ),
    )
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    full = arm.NativeLoadLora.execute(
        model=model,
        clip=base,
        lora=lora,
        strength_model=0.5,
        strength_clip=0.0,
    )
    model_only = arm.NativeLoadLoraModelOnly.execute(
        model=model,
        lora=lora,
        strength_model=0.5,
    )

    if sampling_shift is None:
        assert full == {"model": full_clone, "clip": full_clone}
        assert model_only == {"model": model_clone}
    else:
        assert full["clip"] is full_clone
        assert isinstance(full["model"], arm._NativeModelOverlay)
        assert full["model"].handle is full_clone
        assert full["model"].sampling_shift == sampling_shift
        assert isinstance(model_only["model"], arm._NativeModelOverlay)
        assert model_only["model"].handle is model_clone
        assert model_only["model"].sampling_shift == sampling_shift
    assert clone_calls == [
        ((overlay,), {lora.digest: lora.resolver}),
        ((overlay,), {lora.digest: lora.resolver}),
    ]
    for node, kwargs, expected_model in (
        (
            arm.NativeLoadLora,
            {
                "model": model,
                "clip": base,
                "lora": lora,
                "strength_model": 0.5,
                "strength_clip": 0.0,
            },
            attached_full_clone,
        ),
        (
            arm.NativeLoadLoraModelOnly,
            {"model": model, "lora": lora, "strength_model": 0.5},
            attached_model_clone,
        ),
    ):
        output = node.execute(**kwargs, execution_mode="attach")
        if sampling_shift is None:
            assert output["model"] is expected_model
        else:
            assert output["model"].handle is expected_model
    warning = (
        "native runtime does not support scheduled LoRA patch resolution; "
        "falling back to precalculate execution mode"
    )
    assert caplog.text.count(warning) == 4


