def test_aimdo_factory_failure_propagates_without_eager_fallback_or_sticky_state() -> None:
    arm = _native_arm()
    modules = {name: FakeModule(1) for name in ("diffusion", "clip_l", "vae", "video_vae")}
    error = RuntimeError("VBAR allocation failed")

    def mechanism_factory(weights: object, **_kwargs: Any) -> object:
        if cast(Any, weights).module is modules["clip_l"]:
            raise error
        return object()

    factory = arm._AimdoComponentFactory(
        "auto",
        mechanism_factory,
        lambda _weights, **_kwargs: object(),
        {id(module): name for name, module in modules.items()},
        frozenset({"video_vae"}),
    )
    factory(SimpleNamespace(module=modules["diffusion"]))
    factory(SimpleNamespace(module=modules["video_vae"]))
    with pytest.raises(RuntimeError) as caught:
        factory(SimpleNamespace(module=modules["clip_l"]))
    assert caught.value is error
    factory(SimpleNamespace(module=modules["vae"]))
    assert factory.route_facts() == arm.ResidencyRouteFacts(
        requested="auto",
        mechanism="aimdo",
        dynamic_components=("diffusion", "vae"),
        resident_components=("video_vae",),
    )


