def test_aimdo_second_component_failure_prevents_handle_publication(
    caplog: pytest.LogCaptureFixture,
) -> None:
    arm = _native_arm()
    runtime = _runtime()
    modules = runtime.assembled
    aimdo_calls: list[FakeModule] = []
    eager_calls: list[FakeModule] = []

    def aimdo_factory(weights: object, **kwargs: Any) -> FakeMechanism:
        module = cast(Any, weights).module
        aimdo_calls.append(module)
        if len(aimdo_calls) == 2:
            raise RuntimeError("VBAR allocation failed")
        return FakeMechanism(module, demand_paged=True, **kwargs)

    def eager_factory(weights: object, **kwargs: Any) -> FakeMechanism:
        module = cast(Any, weights).module
        eager_calls.append(module)
        return FakeMechanism(module, **kwargs)

    component_by_module = {
        id(modules.diffusion): "diffusion",
        id(modules.clip_l): "clip_l",
        id(modules.vae): "vae",
    }
    fallback_factory = arm._AimdoComponentFactory(
        "on", aimdo_factory, eager_factory, component_by_module, frozenset()
    )

    def enroll(
        assembled: object,
        *,
        load_device: object,
        offload_device: object,
        mechanism_factory: Any,
    ) -> dict[str, FakeMechanism]:
        enrolled = {}
        for component in ("diffusion", "clip_l", "vae"):
            module = getattr(assembled, component)
            enrolled[component] = mechanism_factory(
                SimpleNamespace(module=module),
                load_device=load_device,
                offload_device=offload_device,
            )
        return enrolled

    with pytest.raises(RuntimeError, match="VBAR allocation failed"):
        arm.NativeRuntimeHandle(
            runtime,
            FakeDevice("cuda:0"),
            recipe=_recipe(),
            coordinator=_coordinator(arm),
            mechanism_factory=fallback_factory,
            _torch_module=FakeTorch(cuda=True),
            _enroll_assembled=enroll,
        )
    assert aimdo_calls == [modules.diffusion, modules.clip_l]
    assert eager_calls == []
    assert len(caplog.records) == 1
    assert "component 'clip_l'" in caplog.text


def test_failed_aimdo_factory_does_not_poison_fresh_handle_factory() -> None:
    arm = _native_arm()
    first_error = RuntimeError("VBAR allocation failed")

    def aimdo_factory(_weights: object, **_kwargs: Any) -> object:
        raise first_error

    failed_factory = arm._AimdoComponentFactory("on", aimdo_factory, pytest.fail, {}, frozenset())
    with pytest.raises(RuntimeError) as caught:
        failed_factory(SimpleNamespace(module=FakeModule(1)))
    assert caught.value is first_error

    sentinel = object()
    fresh_factory = arm._AimdoComponentFactory(
        "on", lambda _weights, **_kwargs: sentinel, pytest.fail, {}, frozenset()
    )
    assert fresh_factory(SimpleNamespace(module=FakeModule(1))) is sentinel
    assert fresh_factory.route_facts().mechanism == "aimdo"


def test_cancelled_aimdo_construction_can_retry_without_eager_fallback() -> None:
    arm = _native_arm()
    cancellation = asyncio.CancelledError()
    sentinel = object()
    calls = 0

    def mechanism_factory(_weights: object, **_kwargs: object) -> object:
        nonlocal calls
        calls += 1
        if calls == 1:
            raise cancellation
        return sentinel

    factory = arm._AimdoComponentFactory("on", mechanism_factory, pytest.fail, {}, frozenset())
    weights = SimpleNamespace(module=FakeModule(1))
    with pytest.raises(asyncio.CancelledError) as caught:
        factory(weights)
    assert caught.value is cancellation
    assert factory(weights) is sentinel
    assert factory.route_facts().dynamic_components == ("<unknown>",)


def test_aimdo_factories_isolate_concurrent_requests_and_retry_transient_failure() -> None:
    arm = _native_arm()
    modules = {name: FakeModule(1) for name in ("first", "second")}
    barrier = threading.Barrier(2, timeout=10)
    attempts: dict[str, int] = {"first": 0, "second": 0}
    calls: list[tuple[str, object, object]] = []

    def mechanism_factory(weights: object, **kwargs: object) -> object:
        component = next(
            name for name, module in modules.items() if cast(Any, weights).module is module
        )
        attempts[component] += 1
        calls.append((component, kwargs["load_device"], kwargs["dtype"]))
        if str(kwargs["load_device"]).startswith("cuda"):
            barrier.wait()
        if component == "first" and attempts[component] == 1:
            raise LookupError("transient selection failure")
        return component

    factories = {
        name: arm._AimdoComponentFactory(
            "on", mechanism_factory, pytest.fail, {id(module): name}, frozenset()
        )
        for name, module in modules.items()
    }

    async def requests() -> list[object]:
        return await asyncio.gather(
            *(
                asyncio.to_thread(
                    factories[name],
                    SimpleNamespace(module=modules[name]),
                    load_device=device,
                    dtype=dtype,
                )
                for name, device, dtype in (
                    ("first", "cuda:0", "float16"),
                    ("second", "cuda:1", "bfloat16"),
                )
            ),
            return_exceptions=True,
        )

    first, second = asyncio.run(requests())
    assert isinstance(first, LookupError)
    assert second == "second"
    assert factories["first"].route_facts().mechanism == "eager"
    assert factories["second"].route_facts().dynamic_components == ("second",)

    assert (
        factories["first"](
            SimpleNamespace(module=modules["first"]), load_device="cpu", dtype="float32"
        )
        == "first"
    )
    assert factories["first"].route_facts().dynamic_components == ("first",)
    assert sorted(calls[:2]) == [
        ("first", "cuda:0", "float16"),
        ("second", "cuda:1", "bfloat16"),
    ]
    assert calls[2:] == [("first", "cpu", "float32")]


