def test_aimdo_factory_keeps_runtime_declared_components_resident() -> None:
    arm = _native_arm()
    components = {
        component: FakeModule(1)
        for component in ("fl2va_dit", "ref2va_dit", "conditioner", "video_vae", "audio_vae")
    }
    aimdo_calls: list[FakeModule] = []
    eager_calls: list[FakeModule] = []

    def aimdo_factory(weights: object, **kwargs: Any) -> FakeMechanism:
        module = cast(Any, weights).module
        aimdo_calls.append(module)
        return FakeMechanism(module, demand_paged=True, **kwargs)

    def eager_factory(weights: object, **kwargs: Any) -> FakeMechanism:
        module = cast(Any, weights).module
        eager_calls.append(module)
        return FakeMechanism(module, **kwargs)

    resident_components = frozenset({"video_vae", "audio_vae"})
    factory = arm._AimdoComponentFactory(
        "auto",
        aimdo_factory,
        eager_factory,
        {id(module): component for component, module in components.items()},
        resident_components,
    )

    mechanisms = {
        component: factory(
            SimpleNamespace(module=module),
            load_device=FakeDevice("cuda:0"),
            offload_device=FakeDevice("cpu"),
        )
        for component, module in components.items()
    }

    assert [component for component, value in mechanisms.items() if value.demand_paged] == [
        "fl2va_dit",
        "ref2va_dit",
        "conditioner",
    ]
    assert aimdo_calls == [
        components["fl2va_dit"],
        components["ref2va_dit"],
        components["conditioner"],
    ]
    assert eager_calls == [components["video_vae"], components["audio_vae"]]


