def test_enrolled_mechanisms_map_to_roles_once_and_refuse_unknown_keys() -> None:
    arm = _native_arm()
    runtime = _runtime()
    runtime.assembled.clip_g = FakeModule(15)
    runtime.assembled.t5xxl = FakeModule(25)
    manager = FakeManager()
    enrolled = _fake_enroll_assembled(
        runtime.assembled,
        load_device=FakeDevice("cuda:0"),
        offload_device=FakeDevice("cpu"),
    )
    handle = arm.NativeRuntimeHandle(
        runtime,
        FakeDevice("cuda:0"),
        recipe=_recipe(),
        coordinator=_coordinator(arm, manager),
        _torch_module=FakeTorch(cuda=True),
        _enroll_assembled=lambda *_args, **_kwargs: enrolled,
    )

    for role, expected in (
        ("diffusion", (enrolled["diffusion"],)),
        (
            "text",
            (
                enrolled["clip_l"],
                enrolled["clip_g"],
                enrolled["t5xxl"],
            ),
        ),
        ("vae", (enrolled["vae"],)),
    ):
        with handle.stage(role):
            pass
        assert manager.loads[-1][0] == expected
        for mechanism in expected:
            assert mechanism.working_set_events == (["enter", "exit"] if role == "vae" else [])
            if role == "vae":
                assert mechanism.loaded_bytes() > 0
                assert mechanism.unload_calls == 0
    consumed = [
        mechanism for mechanisms, _memory, _force in manager.loads for mechanism in mechanisms
    ]
    assert consumed == [
        enrolled["diffusion"],
        enrolled["clip_l"],
        enrolled["clip_g"],
        enrolled["t5xxl"],
        enrolled["vae"],
    ]
    assert len({id(mechanism) for mechanism in handle.mechanisms}) == len(handle.mechanisms)

    unknown = dict(enrolled)
    unknown["surprise"] = FakeMechanism(FakeModule(), load_device="cuda:0", offload_device="cpu")
    with pytest.raises(ValueError, match="unknown component 'surprise'"):
        arm.NativeRuntimeHandle(
            runtime,
            FakeDevice("cuda:0"),
            recipe=_recipe(),
            coordinator=_coordinator(arm),
            _torch_module=FakeTorch(cuda=True),
            _enroll_assembled=lambda *_args, **_kwargs: unknown,
        )


def test_h3_codecs_stay_resident_until_conditioning_stage_exit(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    _install_fake_residency_policy_module(monkeypatch)
    manager = FakeManager()
    names = ("fl2va_dit", "ref2va_dit", "conditioner", "video_vae", "audio_vae")
    modules = {name: FakeModule(index) for index, name in enumerate(names, 1)}
    mechanisms = {
        name: FakeMechanism(module, load_device="cuda:0", offload_device="cpu")
        for name, module in modules.items()
    }
    recipe = _recipe()
    runtime = SimpleNamespace(
        runtime_identity=recipe.runtime_identity,
        assembled=SimpleNamespace(**modules),
        residency_policy=_h3_residency_policy(),
    )
    handle = arm.NativeRuntimeHandle(
        runtime,
        FakeDevice("cuda:0"),
        recipe=recipe,
        coordinator=_coordinator(arm, manager),
        _torch_module=FakeTorch(cuda=True),
        _enroll_assembled=lambda *_args, **_kwargs: mechanisms,
    )

    with handle.stage("text"):
        pass
    with handle.stage("vae"):
        assert mechanisms["video_vae"].loaded_bytes() > 0
        assert mechanisms["audio_vae"].loaded_bytes() > 0
    assert mechanisms["video_vae"].loaded_bytes() > 0
    assert mechanisms["audio_vae"].loaded_bytes() > 0
    assert mechanisms["video_vae"].unload_calls == 0
    assert mechanisms["audio_vae"].unload_calls == 0

    with handle.stage("vae"):
        assert mechanisms["video_vae"].loaded_bytes() > 0
        assert mechanisms["audio_vae"].loaded_bytes() > 0
    assert mechanisms["video_vae"].loaded_bytes() > 0
    assert mechanisms["audio_vae"].loaded_bytes() > 0
    assert mechanisms["video_vae"].unload_calls == 0
    assert mechanisms["audio_vae"].unload_calls == 0

    with handle.stage("vae", observer_stage="condition"):
        pass
    assert mechanisms["conditioner"].loaded_bytes() > 0
    assert mechanisms["conditioner"].unload_calls == 0
    assert mechanisms["video_vae"].loaded_bytes() == 0
    assert mechanisms["audio_vae"].loaded_bytes() == 0
    assert mechanisms["video_vae"].unload_calls == 1
    assert mechanisms["audio_vae"].unload_calls == 1
    assert manager.empty_cache_calls == [FakeDevice("cuda:0")] * 4

    with pytest.raises(RuntimeError, match="conditioning failed"):
        with handle.stage("vae", observer_stage="condition"):
            raise RuntimeError("conditioning failed")
    assert mechanisms["video_vae"].loaded_bytes() == 0
    assert mechanisms["audio_vae"].loaded_bytes() == 0
    assert mechanisms["video_vae"].unload_calls == 2
    assert mechanisms["audio_vae"].unload_calls == 2


