def test_select_load_device_honors_explicit_selection_and_environment() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    select = residency.select_load_device
    environ = {"DINKSTER_ACCELERATOR": "xpu"}
    assert select(FakeTorch(cuda=True, xpu=True), environ=environ).name == "xpu:0"
    # An explicit argument beats the environment pin.
    assert select(FakeTorch(cuda=True, xpu=True), selection="cuda", environ=environ).name == (
        "cuda:0"
    )
    assert select(FakeTorch(cuda=True, xpu=True), selection="cpu", environ={}).name == "cpu"
    assert select(FakeTorch(mps=True), selection="mps", environ={}).name == "mps"
    # Blank environment values mean auto, matching resolve_accelerator.
    assert select(FakeTorch(), environ={"DINKSTER_ACCELERATOR": "  "}).name == "cpu"


def test_select_load_device_translates_rocm_to_cuda_device() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    torch = FakeTorch(cuda=True, cuda_version=None, hip_version="7.1")
    device = residency.select_load_device(torch, selection="rocm", environ={})
    assert device.name == "cuda:0"
    environ = {"DINKSTER_ACCELERATOR": "rocm"}
    assert residency.select_load_device(torch, environ=environ).name == "cuda:0"


def test_select_load_device_refuses_missing_or_mismatched_backends() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    select = residency.select_load_device
    with pytest.raises(ValueError, match="no available CUDA-namespace device"):
        select(FakeTorch(xpu=True), selection="cuda", environ={})
    with pytest.raises(ValueError, match="no available XPU device"):
        select(FakeTorch(cuda=True), selection="xpu", environ={})
    with pytest.raises(ValueError, match="no available MPS backend"):
        select(FakeTorch(cuda=True), selection="mps", environ={})
    # The two CUDA-namespace families refuse each other's torch build.
    rocm_torch = FakeTorch(cuda=True, cuda_version=None, hip_version="7.1")
    with pytest.raises(ValueError, match="select 'rocm' instead"):
        select(rocm_torch, selection="cuda", environ={})
    with pytest.raises(ValueError, match="no HIP runtime"):
        select(FakeTorch(cuda=True), selection="rocm", environ={})
    with pytest.raises(residency.AcceleratorError, match="unknown accelerator 'npu'"):
        select(FakeTorch(cuda=True), selection="npu", environ={})
    with pytest.raises(residency.AcceleratorError, match="unknown accelerator 'npu'"):
        select(FakeTorch(cuda=True), environ={"DINKSTER_ACCELERATOR": "npu"})


def test_native_accelerator_family_distinguishes_rocm_from_cuda() -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    family = residency.native_accelerator_family
    cuda_torch = FakeTorch(cuda=True)
    rocm_torch = FakeTorch(cuda=True, cuda_version=None, hip_version="7.1")
    assert family(cuda_torch, FakeDevice("cuda:0")) == "cuda"
    assert family(rocm_torch, FakeDevice("cuda:0")) == "rocm"
    assert family(cuda_torch, FakeDevice("xpu:0")) == "xpu"
    assert family(cuda_torch, FakeDevice("mps")) == "mps"
    assert family(cuda_torch, FakeDevice("cpu")) == "cpu"
    # Plain device strings work the same as device objects.
    assert family(rocm_torch, "cuda:1") == "rocm"


@pytest.mark.parametrize(
    ("roles", "family_id", "embedding_free"),
    (
        (("checkpoint",), "dinkster.sd15", False),
        (("checkpoint", "vae"), "dinkster.sdxl", False),
        (("clip_l", "diffusion", "t5xxl", "vae"), "dinkster.flux_dev", False),
        (("clip_vision", "diffusion", "t5xxl", "vae"), "dinkster.wan21", True),
        (("diffusion", "qwen3_4b", "vae"), "dinkster.z_image", True),
        (("diffusion", "t5xxl", "vae"), "dinkster.wan21", True),
    ),
)
def test_native_runtime_factory_derives_identity_and_uses_production_handle(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    roles: tuple[str, ...],
    family_id: str,
    embedding_free: bool,
) -> None:
    arm = _native_arm()
    assets = _split_assets(tmp_path, roles)
    if embedding_free:
        assets = dict(reversed(tuple(assets.items())))
    events: list[tuple[str, object]] = []
    plan = SimpleNamespace(
        family=SimpleNamespace(id=family_id),
        identity_components=() if embedding_free else (_clip_text_plan(),),
    )
    inference = SimpleNamespace(
        Lumina2AssemblyPlan=importlib.import_module("dinkster_inference").Lumina2AssemblyPlan,
        load_safetensors_header=lambda path: events.append(("header", path.name)) or path.name,
        plan_native=lambda **sources: events.append(("plan", dict(sources))) or plan,
    )
    real_import = importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: inference if name == "dinkster_inference" else real_import(name),
    )
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch())
    monkeypatch.setattr(arm, "select_load_device", lambda _torch: FakeDevice("cpu"))
    embedding_reads = 0

    def freeze_embedding_resource() -> tuple[None, None]:
        nonlocal embedding_reads
        embedding_reads += 1
        return None, None

    monkeypatch.setattr(arm, "_freeze_embedding_resource", freeze_embedding_resource)
    recipe = SimpleNamespace(runtime_identity="derived-identity")
    monkeypatch.setattr(
        arm,
        "_runtime_recipe",
        lambda *_args, **_kwargs: events.append(("recipe", _kwargs)) or recipe,
    )
    runtime = object()
    monkeypatch.setattr(
        arm,
        "_load_runtime",
        lambda *args, **kwargs: events.append(("load", (args, kwargs))) or runtime,
    )

    class Handle:
        def attach_pool(self, pool: object) -> None:
            self.pool = pool

    handle = Handle()
    built: list[dict[str, object]] = []
    monkeypatch.setattr(
        arm,
        "_build_runtime_handle",
        lambda loaded, _torch, **kwargs: built.append({"runtime": loaded, **kwargs}) or handle,
    )
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    with use_execution_context(ExecutionContext("native", None)):
        result = arm.load_native_runtime_handle(assets)

    assert result is handle
    load_index = len(roles) + 2
    assert [name for name, _ in events[:load_index]] == ["header"] * len(roles) + [
        "plan",
        "recipe",
    ]
    planned_sources = cast("dict[str, object]", events[len(roles)][1])
    assert tuple(planned_sources) == (*roles, "fp8_matmul")
    assert planned_sources["fp8_matmul"] is False
    load_args, load_kwargs = cast(
        "tuple[tuple[object, ...], dict[str, object]]", events[load_index][1]
    )
    assert load_args[1] == "derived-identity"
    assert load_kwargs == {"source_assets": assets}
    assert built[0]["runtime"] is runtime
    assert built[0]["recipe"] is recipe
    primary = "diffusion" if "diffusion" in assets else "checkpoint"
    assert pool.labels == [(handle, assets[primary].name)]
    assert handle.pool is pool
    assert embedding_reads == (0 if embedding_free else 1)


def test_native_mesh_operations_bridge_cancellation_and_model_eviction(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    calls: list[tuple[str, dict[str, object]]] = []
    result = object()

    def run(operation: str, **inputs: object) -> object:
        calls.append((operation, inputs))
        return (result, result, result) if operation == "bake_texture_from_voxel" else result

    def cancelled() -> bool:
        return False

    monkeypatch.setattr(arm, "_native_mesh_operation", run)
    monkeypatch.setattr(arm, "_triangle_mesh_batch", lambda value: value)
    with use_execution_context(ExecutionContext("native", None, cancelled=cancelled)):
        arm.GenerationRemeshMesh.execute(mesh=object())
    assert calls[-1][0] == "remesh_mesh"
    assert calls[-1][1]["offload_models"] is True
    assert calls[-1][1]["cancelled"] is cancelled

    arm.GenerationBakeTextureFromVoxel.execute(mesh=object(), voxel_colors=object())
    assert calls[-1][0] == "bake_texture_from_voxel"
    assert calls[-1][1]["offload_models"] is True


