@pytest.mark.parametrize(
    "signature",
    (
        "attention_pooler.query_tokens",
        "duration_head.attention_pooler.query_tokens",
        "model.diffusion_model.duration_head.attention_pooler.query_tokens",
    ),
)
def test_load_model_patch_routes_ltx_duration_component(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, signature: str
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "duration.safetensors"))
    source = SimpleNamespace(keys=lambda: (signature,))
    handle = object()
    calls: list[tuple[object, ...]] = []
    inference = SimpleNamespace(load_safetensors_header=lambda path: source)
    inference_torch = SimpleNamespace()
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            inference
            if name == "dinkster_inference"
            else inference_torch
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    monkeypatch.setattr(
        arm,
        "_ltxav_component_identity",
        lambda *args: calls.append(("identity", *args)) or ("duration:identity", object()),
    )
    monkeypatch.setattr(
        arm,
        "_build_component_runtime_handle",
        lambda descriptor, *args, **kwargs: (
            calls.append(("build", *args, kwargs)) or handle
            if descriptor.id == "dinkster.ltxav"
            else pytest.fail("wrong component descriptor")
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: "torch")

    with use_execution_context(ExecutionContext("native", "duration:identity")):
        result = arm.NativeLoadZImageControlPatch.execute(model_patch=asset)

    assert result["model_patch"] is handle
    assert calls[0][0] == "identity"
    assert calls[0][2:] == (asset, "duration_head", "float32")
    assert calls[1] == (
        "build",
        asset,
        "duration_head",
        "duration:identity",
        "torch",
        {"compute_dtype": "float32"},
    )


def test_native_z_image_control_patch_loads_strict_plan_into_residency(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "control.safetensors"))

    class Source:
        @staticmethod
        def keys() -> tuple[str, ...]:
            return ()

    source = Source()
    plan = object()
    control = object()
    mechanism = object()
    events: list[tuple[object, ...]] = []

    class Coordinator:
        @staticmethod
        def enroll_component(module: object, *, enroller: Any, **kwargs: object) -> object:
            return enroller(module, **kwargs)

    coordinator = Coordinator()
    inference = SimpleNamespace(
        load_safetensors_header=lambda path: events.append(("header", path)) or source,
        plan_z_image_control=lambda value, **kwargs: events.append(("plan", value, kwargs)) or plan,
    )
    inference_torch = SimpleNamespace(
        assemble_z_image_control=lambda value, **kwargs: (
            events.append(("assemble", value, kwargs))
            or SimpleNamespace(control=control, resource_digest="resource-identity")
        ),
        enroll_component=lambda module, **kwargs: (
            events.append(("enroll", module, kwargs)) or mechanism
        ),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            inference
            if name == "dinkster_inference"
            else inference_torch
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    torch = FakeTorch(cuda=True)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "default_native_residency", lambda: coordinator)

    class ComponentHandle:
        def __init__(self, *args: object, **kwargs: object) -> None:
            self.args = args
            self.kwargs = kwargs

        def attach_pool(self, pool: object) -> None:
            self.pool = pool

    monkeypatch.setattr(arm, "NativeComponentHandle", ComponentHandle)
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    with use_execution_context(ExecutionContext("native", "expected")):
        result = arm.NativeLoadZImageControlPatch.execute(model_patch=asset)

    component_handle = result["model_patch"]
    assert isinstance(component_handle, ComponentHandle)
    assert component_handle.args[:2] == (control, mechanism)
    assert component_handle.kwargs == {
        "resource_identity": "resource-identity",
        "coordinator": coordinator,
    }
    assert component_handle.pool is pool
    assert pool.labels == [(component_handle, asset.name)]
    assert events[0] == ("header", asset.local_path())
    assert events[1] == ("plan", source, {"asset_digest": asset.digest})
    assert events[2][0:2] == ("assemble", plan)
    assert events[3][0:2] == ("enroll", control)


def test_native_model_patch_loader_dispatches_multitalk_with_bound_identity(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "multitalk.safetensors"))

    class Source:
        @staticmethod
        def keys() -> tuple[str, ...]:
            return ("audio_proj.proj1.weight",)

    source = Source()
    patch_plan = SimpleNamespace(runtime_facts=("patch=multitalk",))
    plan = SimpleNamespace(patch=patch_plan)
    patch = object()
    mechanism = object()
    events: list[tuple[object, ...]] = []

    class Coordinator:
        @staticmethod
        def enroll_component(module: object, *, enroller: Any, **kwargs: object) -> object:
            return enroller(module, **kwargs)

    coordinator = Coordinator()
    inference = SimpleNamespace(
        BFLOAT16=SimpleNamespace(name="bfloat16"),
        load_safetensors_header=lambda path: events.append(("header", path)) or source,
        plan_wan21_multitalk=lambda value, **kwargs: events.append(("plan", value, kwargs)) or plan,
        plan_z_image_control=lambda *_args, **_kwargs: pytest.fail(
            "MultiTalk must not use the Z-Image planner"
        ),
        runtime_component_identity=lambda family, components: (
            events.append(("component_identity", family, components)) or "component"
        ),
        build_runtime_identity_from_facts=lambda family, component, **kwargs: (
            events.append(("runtime_identity", family, component, kwargs)) or "runtime"
        ),
        extend_runtime_identity=lambda identity, facts: (
            events.append(("extend_identity", identity, facts)) or "bound-resource-identity"
        ),
    )
    inference_torch = SimpleNamespace(
        assemble_wan21_multitalk=lambda value, **kwargs: (
            events.append(("assemble", value, kwargs))
            or SimpleNamespace(patch=patch, resource_digest="patch-resource")
        ),
        assemble_z_image_control=lambda *_args, **_kwargs: pytest.fail(
            "MultiTalk must not use the Z-Image assembler"
        ),
        enroll_component=lambda module, **kwargs: (
            events.append(("enroll", module, kwargs)) or mechanism
        ),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            inference
            if name == "dinkster_inference"
            else inference_torch
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    torch = FakeTorch(cuda=True)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "default_native_residency", lambda: coordinator)

    class ComponentHandle:
        def __init__(self, *args: object, **kwargs: object) -> None:
            self.args = args
            self.kwargs = kwargs

        def attach_pool(self, pool: object) -> None:
            self.pool = pool

    monkeypatch.setattr(arm, "NativeComponentHandle", ComponentHandle)
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    with use_execution_context(ExecutionContext("native", "expected")):
        result = arm.NativeLoadZImageControlPatch.execute(model_patch=asset)

    component_handle = result["model_patch"]
    assert isinstance(component_handle, ComponentHandle)
    assert component_handle.args[:2] == (patch, mechanism)
    assert component_handle.kwargs == {
        "resource_identity": "bound-resource-identity",
        "coordinator": coordinator,
    }
    assert pool.labels == [(component_handle, asset.name)]
    assert ("plan", source, {"asset_digest": asset.digest}) in events
    assert ("component_identity", "dinkster.wan21", (patch_plan,)) in events
    assert (
        "extend_identity",
        "runtime",
        ("resource=patch-resource",),
    ) in events
    assert any(event[:2] == ("enroll", patch) for event in events)


def test_native_z_image_control_patch_binding_validates_and_survives_lora_clone(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    runtime = _runtime()
    runtime.family = SimpleNamespace(id="future.z_image")
    runtime.accepts_z_image_control = True
    handle = _handle(arm, runtime)

    class ZImageControl:
        accepts_z_image_control_binding = True

    class ComponentHandle:
        def __init__(self) -> None:
            self.module: object = ZImageControl()
            self.active_checks = 0
            self.dependents: list[object] = []

        def require_active(self) -> None:
            self.active_checks += 1

        def register_dependent(self, dependent: object) -> None:
            self.dependents.append(dependent)

    monkeypatch.setattr(arm, "NativeComponentHandle", ComponentHandle)
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch())
    patch = ComponentHandle()
    image = FakeTensor((1, 64, 96, 4), "control")
    runtime.accepts_z_image_control = False
    with pytest.raises(TypeError, match="requires a native Z-Image model"):
        arm.NativeApplyZImageControlPatch.execute(
            model=handle,
            model_patch=patch,
            vae=handle,
            image=image,
            strength=0.75,
        )
    runtime.accepts_z_image_control = "true"
    with pytest.raises(TypeError, match="requires a native Z-Image model"):
        arm.NativeApplyZImageControlPatch.execute(
            model=handle,
            model_patch=patch,
            vae=handle,
            image=image,
            strength=0.75,
        )
    runtime.accepts_z_image_control = True
    patch.module = object()
    with pytest.raises(TypeError, match="must be a native Z-Image control patch"):
        arm.NativeApplyZImageControlPatch.execute(
            model=handle,
            model_patch=patch,
            vae=handle,
            image=image,
            strength=0.75,
        )
    patch.module = SimpleNamespace(accepts_z_image_control_binding="true")
    with pytest.raises(TypeError, match="must be a native Z-Image control patch"):
        arm.NativeApplyZImageControlPatch.execute(
            model=handle,
            model_patch=patch,
            vae=handle,
            image=image,
            strength=0.75,
        )
    patch.module = ZImageControl()
    model = arm.NativeApplyZImageControlPatch.execute(
        model=handle,
        model_patch=patch,
        vae=handle,
        image=image,
        strength=0.75,
    )["model"]

    assert isinstance(model, arm._NativeModelOverlay)
    assert model.z_image_control is not None
    assert model.z_image_control.handle is patch
    assert model.z_image_control.image.ndim == 4
    assert model.z_image_control.strength == 0.75
    assert patch.active_checks == 3
    assert patch.dependents == [model]

    lora = _asset(_safetensors(tmp_path / "control-lora.safetensors"))
    overlay = SimpleNamespace(patches=(SimpleNamespace(component="diffusion"),))
    clone = _handle(arm, runtime)
    monkeypatch.setattr(arm, "_native_lora_overlay", lambda *_args: overlay)
    monkeypatch.setattr(handle, "clone", lambda *_args, **_kwargs: clone)
    monkeypatch.setattr(arm, "default_pool", lambda: FakePool())
    cloned = arm.NativeLoadLoraModelOnly.execute(
        model=model,
        lora=lora,
        strength_model=0.5,
    )["model"]
    assert isinstance(cloned, arm._NativeModelOverlay)
    assert cloned.handle is clone
    assert cloned.z_image_control is model.z_image_control


