def test_native_wan22_first_frame_matches_reference_latent_and_mask_geometry(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    fake_torch = FakeTorch()
    encoded = FakeTensor((1, 48, 1, 2, 4), "encoded", device="cuda:0", dtype="float16")
    encoded_inputs: list[FakeTensor] = []
    normalized_inputs: list[FakeTensor] = []
    stages: list[str] = []

    class Runtime:
        family = SimpleNamespace(id="future.video")
        assembled = SimpleNamespace(
            diffusion=SimpleNamespace(config=SimpleNamespace(model_type="ti2v")),
            vae=SimpleNamespace(
                process_out=lambda latent: (
                    normalized_inputs.append(latent)
                    or FakeTensor(
                        latent.shape, "external", device=latent.device, dtype=latent.dtype
                    )
                )
            ),
        )

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            encoded_inputs.append(content)
            return encoded

    class Handle:
        runtime = Runtime()
        load_device = FakeDevice("cuda:0")

        @contextmanager
        def stage(self, role: str):  # noqa: ANN201
            stages.append(role)
            yield

    handle = Handle()
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch.resize":

            def common_upscale(
                image: FakeTensor,
                width: int,
                height: int,
                _method: str,
                _crop: str,
            ) -> FakeTensor:
                return FakeTensor(
                    (image.shape[0], image.shape[1], height, width),
                    "resized",
                    device=image.device,
                    dtype=image.dtype,
                )

            return SimpleNamespace(common_upscale=common_upscale)
        return real_import(name)

    monkeypatch.setattr(arm, "_native_handle", lambda _value, _name: handle)
    monkeypatch.setattr(arm, "_torch", lambda: fake_torch)
    monkeypatch.setattr(arm.importlib, "import_module", import_module)

    output = arm.NativeWan22ImageToVideoLatent.execute(
        vae=handle,
        width=64,
        height=32,
        length=5,
        batch_size=2,
        start_image=FakeTensor((2, 20, 40, 3), "image"),
    )["latent"]

    latent = cast("Mapping[str, FakeTensor]", output)
    assert latent["samples"].shape == (2, 48, 2, 2, 4)
    assert latent["noise_mask"].shape == (2, 1, 2, 2, 4)
    assert latent["samples"].device == latent["noise_mask"].device == FakeDevice("cpu")
    assert [value.shape for value in encoded_inputs] == [(1, 3, 2, 32, 64)]
    assert [value.shape for value in normalized_inputs] == [(1, 48, 2, 2, 4)]
    assert stages == ["vae"]
    assert fake_torch.inference_entries == 1


