def test_native_h3_model_only_peft_lora_precalculates_and_composes_identity(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    model_asset = _asset(_safetensors(tmp_path / "fl2va.safetensors"))
    recipe_seed = SimpleNamespace(model_role="fl2va-dit", runtime_facts=("provider=test",))
    base_recipe = arm._component_descriptor("dinkster.minimax_h3").recipe(
        arm._weight_source_ref(inference, model_asset),
        SimpleNamespace(role="diffusion", runtime=recipe_seed),
        inference.BFLOAT16.name,
    )

    class MiniMaxH3Model:
        __module__ = "dinkster_inference_torch.minimax_h3_assembly"

        def __init__(self, runtime_identity: str) -> None:
            self.assembled = SimpleNamespace(diffusion=FakeModule())
            self.runtime_identity = runtime_identity
            self.model_role = "fl2va-dit"
            self.runtime_facts = ("provider=test",)
            self.receipt_identity = "guidance-receipt"

    torch = FakeTorch()
    patch_set = object()
    patch_sets_seen: list[object] = []
    materialized: list[tuple[object, object]] = []

    def enroll(
        assembled: object,
        *,
        load_device: object,
        offload_device: object,
        patch_sets: object = None,
        patch_weight_dtype: object = None,
        patch_key_prefixes: object = None,
        mechanism_factory: object = None,
    ) -> object:
        assert patch_weight_dtype is None
        assert patch_key_prefixes is None
        patch_sets_seen.append(patch_sets)
        return _fake_enroll_assembled(
            assembled,
            load_device=load_device,
            offload_device=offload_device,
            mechanism_factory=mechanism_factory,
        )

    def materializer(next_recipe: object, next_resolvers: object) -> object:
        materialized.append((next_recipe, next_resolvers))
        recipe = cast("Any", next_recipe)
        return arm.NativeRuntimeHandle(
            MiniMaxH3Model(recipe.runtime_identity),
            torch.device("cuda:0"),
            recipe=recipe,
            patch_sets={"diffusion": patch_set},
            materializer=materializer,
            source_resolvers=cast("Mapping[str, object]", next_resolvers),
            coordinator=_coordinator(arm),
            _torch_module=torch,
            _enroll_assembled=enroll,
        )

    base = arm.NativeRuntimeHandle(
        MiniMaxH3Model(base_recipe.runtime_identity),
        torch.device("cuda:0"),
        recipe=base_recipe,
        materializer=materializer,
        source_resolvers={model_asset.digest: model_asset.resolver},
        coordinator=_coordinator(arm),
        _torch_module=torch,
        _enroll_assembled=enroll,
    )
    lora = _asset(
        _safetensors_shapes(
            tmp_path / "h3-peft.safetensors",
            {
                "diffusion_model.layer.lora_A.weight": (1, 1),
                "diffusion_model.layer.lora_B.weight": (1, 1),
                "diffusion_model.layer.alpha": (),
            },
        )
    )
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    result = arm.NativeLoadLoraModelOnly.execute(
        model=base,
        lora=lora,
        strength_model=0.25,
    )["model"]

    assert len(materialized) == 1
    patched_recipe, resolvers = materialized[0]
    overlay = cast("Any", patched_recipe).overlays[0]
    assert overlay.patches[0].component == "diffusion"
    assert overlay.patches[0].target == inference.PatchTarget("layer.weight")
    assert overlay.patches[0].decoded.variant == "peft"
    assert float(overlay.strength_model) == 0.25
    assert resolvers == {
        model_asset.digest: model_asset.resolver,
        lora.digest: lora.resolver,
    }
    assert patch_sets_seen == [None, {"diffusion": patch_set}]
    patched_handle = cast("Any", result)
    assert patched_handle.recipe.runtime_identity != base.recipe.runtime_identity
    assert patched_handle.runtime.runtime_identity == patched_handle.recipe.runtime_identity
    assert patched_handle.runtime.receipt_identity == base.runtime.receipt_identity
    base_composition = inference.compose_execution(
        inference.MINIMAX_H3_CONFIG.family_id,
        {
            "fl2va_dit": base.recipe.runtime_identity,
            "conditioner": base.recipe.runtime_identity,
        },
    )
    patched_composition = inference.compose_execution(
        inference.MINIMAX_H3_CONFIG.family_id,
        {
            "fl2va_dit": patched_handle.recipe.runtime_identity,
            "conditioner": base.recipe.runtime_identity,
        },
    )
    assert patched_composition.execution_identity != base_composition.execution_identity

    real_import = arm.importlib.import_module
    fake_torch_module = SimpleNamespace(MiniMaxH3Model=MiniMaxH3Model)
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: fake_torch_module if name == "dinkster_inference_torch" else real_import(name),
    )
    assert arm._minimax_h3_model_handle(patched_handle, inference) is patched_handle


def test_native_h3_lora_entry_modes_and_refusals(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    model_asset = _asset(_safetensors(tmp_path / "fl2va.safetensors"))
    recipe = arm._component_descriptor("dinkster.minimax_h3").recipe(
        arm._weight_source_ref(inference, model_asset),
        SimpleNamespace(
            role="diffusion",
            runtime=SimpleNamespace(model_role="fl2va-dit", runtime_facts=("provider=test",)),
        ),
        inference.BFLOAT16.name,
    )
    handle = SimpleNamespace(
        recipe=recipe,
        runtime=SimpleNamespace(assembled=SimpleNamespace(diffusion=FakeModule())),
    )
    lora = _asset(
        _safetensors_shapes(
            tmp_path / "h3-peft.safetensors",
            {
                "diffusion_model.layer.lora_A.weight": (1, 1),
                "diffusion_model.layer.lora_B.weight": (1, 1),
            },
        )
    )
    real_overlay = arm._native_lora_overlay
    overlay = real_overlay(handle, lora, 0.5, 0.0)
    clone = object()
    clone_calls: list[object] = []
    cast(Any, handle).clone = lambda overlays, *, source_resolvers: (
        clone_calls.append((overlays, source_resolvers)) or clone
    )
    monkeypatch.setattr(
        arm,
        "_native_model",
        lambda _model, _name: (handle, (), {}, None, None, (), None, ()),
    )
    monkeypatch.setattr(arm, "_native_lora_overlay", lambda *_args: overlay)
    monkeypatch.setattr(arm, "default_pool", lambda: FakePool())

    assert arm.NativeLoadLoraModelOnly.execute(
        model=handle,
        lora=lora,
        strength_model=0.5,
    ) == {"model": clone}
    assert len(clone_calls) == 1
    assert arm.NativeLoadLoraModelOnly.execute(
        model=handle,
        lora=lora,
        strength_model=0.5,
        execution_mode="attach",
    ) == {"model": clone}
    assert len(clone_calls) == 2
    assert arm.NativeLoadLoraModelOnly.execute(
        model=handle,
        lora=lora,
        strength_model=0.0,
    ) == {"model": handle}
    with pytest.raises(
        ValueError,
        match="^MiniMax H3 LoRAs require Load LoRA$",
    ):
        arm.NativeLoadLora.execute(
            model=handle,
            clip=object(),
            lora=lora,
            strength_model=0.5,
            strength_clip=0.0,
        )

    unmatched = _asset(
        _safetensors_shapes(tmp_path / "unmatched.safetensors", {"other.tensor": (1,)})
    )
    monkeypatch.setattr(arm, "_native_lora_overlay", real_overlay)
    with pytest.raises(
        RuntimeError,
        match="has no patch keys matching this model",
    ):
        arm.NativeLoadLoraModelOnly.execute(
            model=handle,
            lora=unmatched,
            strength_model=0.5,
        )


def _h3_decomposed_handle(arm, tmp_path: Path, monkeypatch: pytest.MonkeyPatch):  # noqa: ANN001, ANN201
    inference = importlib.import_module("dinkster_inference")
    asset = _asset(_safetensors(tmp_path / "fl2va.safetensors"))
    recipe = arm._component_descriptor("dinkster.minimax_h3").recipe(
        arm._weight_source_ref(inference, asset),
        SimpleNamespace(
            role="diffusion",
            runtime=SimpleNamespace(model_role="fl2va-dit", runtime_facts=("provider=test",)),
        ),
        inference.BFLOAT16.name,
    )

    class MiniMaxH3Model:
        __module__ = "dinkster_inference_torch.minimax_h3_assembly"

        def __init__(self, runtime_identity: str) -> None:
            self.assembled = SimpleNamespace(diffusion=FakeModule())
            self.runtime_identity = runtime_identity
            self.model_role = "fl2va-dit"
            self.runtime_facts = ("provider=test",)
            self.receipt_identity = "h3-receipt"

        def sample_multistream(self) -> None: ...

    class MiniMaxH3DiTRuntime:
        sample_calls: ClassVar[list[dict[str, object]]] = []

        def __init__(
            self,
            diffusion: object,
            *,
            model_role: str,
            runtime_identity: str,
            receipt_identity: str,
            compute_dtype: object,
            conditioning_identity: str | None = None,
        ) -> None:
            self.diffusion = diffusion
            self.model_role = model_role
            self.runtime_identity = runtime_identity
            self.receipt_identity = receipt_identity
            self.compute_dtype = compute_dtype
            self.conditioning_identity = conditioning_identity
            self.family = importlib.import_module("dinkster_inference").MINIMAX_H3

        def custom_sampling_sigmas(
            self,
            scheduler_id: str,
            steps: int,
            denoise: float,
            *,
            device: object | None = None,
        ) -> tuple[float, ...]:
            del scheduler_id, steps, denoise, device
            return (1.0, 0.5, 0.0)

        def custom_sampling_beta_sigmas(self, steps: int, alpha: float, beta: float) -> None: ...

        def custom_sampling_sd_turbo_sigmas(self, steps: int, denoise: float) -> None: ...

        def custom_sampling_percent_to_sigma(
            self, percent: float, *, return_actual_sigma: bool
        ) -> None: ...

        def check_custom_sampling(self, request: object, **_kwargs: object) -> None: ...

        def sample_custom(self, latent: object, **kwargs: object) -> object:
            type(self).sample_calls.append({"latent": latent, **kwargs})
            return inference.CustomSamplingResult(cast("Any", latent), None)

    fake_module = SimpleNamespace(
        MiniMaxH3Model=MiniMaxH3Model,
        MiniMaxH3DiTRuntime=MiniMaxH3DiTRuntime,
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: fake_module if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(arm, "_torch", lambda: FakeTorch())
    handle = _handle(arm, MiniMaxH3Model(recipe.runtime_identity), recipe=recipe)
    return inference, recipe, handle, MiniMaxH3DiTRuntime


def _h3_prepared_conditioning(inference, recipe, digest_digit: str):  # noqa: ANN001, ANN201
    identity = f"native:{inference.MINIMAX_H3_CONFIG.family_id}:{digest_digit * 64}"
    return [[inference.PreparedMultiStreamConditioning(identity, "payload"), {}]]


def test_native_h3_decomposed_sampling_resolves_dit_runtime(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference, recipe, handle, dit_type = _h3_decomposed_handle(arm, tmp_path, monkeypatch)
    positive = _h3_prepared_conditioning(inference, recipe, "7")
    conditioner_identity = positive[0][0].runtime_identity

    runtime = arm._minimax_h3_custom_sampling_runtime(handle, positive, [], inference)

    composition = inference.compose_execution(
        inference.MINIMAX_H3_CONFIG.family_id,
        {"fl2va_dit": recipe.runtime_identity, "conditioner": conditioner_identity},
    )
    assert type(runtime) is dit_type
    assert runtime.runtime_identity == composition.execution_identity
    assert runtime.conditioning_identity == conditioner_identity
    assert runtime.model_role == "fl2va_dit"
    assert runtime.receipt_identity == "h3-receipt"
    assert runtime.compute_dtype == "bfloat16"
    assert runtime.diffusion is handle.runtime.assembled.diffusion

    matching_negative = _h3_prepared_conditioning(inference, recipe, "7")
    with_negative = arm._minimax_h3_custom_sampling_runtime(
        handle, positive, matching_negative, inference
    )
    assert with_negative.runtime_identity == composition.execution_identity

    registered = arm.resolve_component_execution(handle, positive, matching_negative, inference)
    assert registered is not None
    registered_runtime, registered_positive, registered_negative = registered
    assert registered_runtime.runtime_identity == composition.execution_identity
    assert registered_runtime.diffusion is handle.runtime.assembled.diffusion
    assert registered_positive is positive
    assert registered_negative is matching_negative

    schedule_runtime = arm._minimax_h3_schedule_runtime(handle, inference)
    assert type(schedule_runtime) is dit_type
    assert schedule_runtime.runtime_identity == recipe.runtime_identity

    sigmas = arm.GenerationBasicScheduler.execute(
        model=handle,
        scheduler="normal",
        steps=2,
        denoise=0.75,
    )["sigmas"]
    assert cast("Any", sigmas).values == (1.0, 0.5, 0.0)


def test_native_h3_decomposed_sampling_executes_with_empty_negative(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference, recipe, handle, dit_type = _h3_decomposed_handle(arm, tmp_path, monkeypatch)
    monkeypatch.setattr(arm, "multistream_sampling_preview_emitter", lambda _handle: None)
    positive = _h3_prepared_conditioning(inference, recipe, "7")
    video = FakeTensor((1, 24, 6, 4, 5), "video")
    audio = FakeTensor((1, 32, 97), "audio")
    streams = inference.MultiStreamLatent.from_pairs((("video", video), ("audio", audio)))
    sampler = arm.GenerationKSamplerSelect.execute(sampler_name="euler")["sampler"]

    output, denoised = arm._execute_generation_custom_sampling(
        model=handle,
        noise=arm._CustomNoiseValue(None),
        sampler=sampler,
        sigmas=arm._CustomSigmasValue((1.0, 0.5, 0.0)),
        positive=positive,
        negative=[],
        cfg=3.0,
        latent_image={"samples": streams},
    )

    assert len(dit_type.sample_calls) == 1
    call = dit_type.sample_calls[0]
    assert call["cfg"] == inference.SamplingGuidance(None, 3.0)
    assert call["cond"] is positive[0][0]
    assert call["seed"] == 0
    moved = cast("Any", call["latent"])
    assert type(moved) is inference.MultiStreamLatent
    assert moved.roles == ("video", "audio")
    result = cast("Any", output["samples"])
    assert type(result) is inference.MultiStreamLatent
    assert result.roles == ("video", "audio")
    assert type(denoised["samples"]) is inference.MultiStreamLatent


def test_native_h3_decomposed_sampling_refusals_and_non_h3_passthrough(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference, recipe, handle, _ = _h3_decomposed_handle(arm, tmp_path, monkeypatch)
    positive = _h3_prepared_conditioning(inference, recipe, "7")

    with pytest.raises(TypeError, match="positive must contain prepared MiniMax H3 conditioning"):
        arm._minimax_h3_custom_sampling_runtime(handle, [], [], inference)
    with pytest.raises(ValueError, match="different MiniMax H3 conditioner component"):
        arm._minimax_h3_custom_sampling_runtime(
            handle, positive, _h3_prepared_conditioning(inference, recipe, "8"), inference
        )
    foreign_identity = f"native:dinkster.sd15:{'7' * 64}"
    foreign = [[inference.PreparedMultiStreamConditioning(foreign_identity, "payload"), {}]]
    with pytest.raises(ValueError, match="official MiniMax H3 conditioner component"):
        arm._minimax_h3_custom_sampling_runtime(handle, foreign, [], inference)

    other = _handle(arm, _runtime())
    assert arm._minimax_h3_custom_sampling_runtime(other, positive, [], inference) is None
    assert arm._minimax_h3_schedule_runtime(other, inference) is None


def test_h3_model_materializer_applies_only_diffusion_patch_sets(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    asset = _asset(_safetensors(tmp_path / "fl2va.safetensors"))

    @dataclass(frozen=True)
    class Model:
        assembled: object
        runtime_identity: str
        model_role: str = "fl2va-dit"
        runtime_facts: tuple[str, ...] = ("provider=test",)
        receipt_identity: str | None = "guidance-receipt"

    seed = Model(SimpleNamespace(diffusion=FakeModule()), "pending")
    descriptor = replace(
        arm._component_descriptor("dinkster.minimax_h3"),
        loader="load_h3_component",
        runtime_factory="h3_runtime",
    )
    base_recipe = descriptor.recipe(
        arm._weight_source_ref(inference, asset),
        SimpleNamespace(role="diffusion", runtime=seed),
        inference.BFLOAT16.name,
    )
    overlay = _overlay("9")
    patched_recipe = base_recipe.append_overlays((overlay,))
    loaded = replace(seed, runtime_identity=base_recipe.runtime_identity)
    patch_set = object()
    builds: list[dict[str, object]] = []

    def load_model(_path: Path, **kwargs: object) -> object:
        assert kwargs["expected_identity"] == base_recipe.runtime_identity
        assert kwargs["expected_role"] == "diffusion"
        return SimpleNamespace(role="diffusion", runtime=loaded)

    fake_torch_module = SimpleNamespace(
        load_h3_component=load_model,
        MiniMaxH3Model=Model,
        h3_runtime=lambda component, identity, _dtype: replace(
            component.runtime, runtime_identity=identity
        ),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: fake_torch_module if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(
        arm,
        "_materialize_patch_sets",
        lambda *_args: {"diffusion": patch_set},
    )
    handle = SimpleNamespace(attach_pool=lambda pool: setattr(handle, "pool", pool))
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    monkeypatch.setattr(
        arm,
        "_build_runtime_handle",
        lambda runtime, _torch, **kwargs: builds.append({"runtime": runtime, **kwargs}) or handle,
    )

    arm._build_component_runtime_handle(
        descriptor,
        asset,
        "diffusion",
        patched_recipe.runtime_identity,
        FakeTorch(),
        compute_dtype="bfloat16",
        as_model=True,
        required_recipe=patched_recipe,
        source_resolvers={asset.digest: asset.resolver},
    )

    assert len(builds) == 1
    assert builds[0]["recipe"] == patched_recipe
    assert builds[0]["patch_sets"] == {"diffusion": patch_set}
    rebuilt = cast("Model", builds[0]["runtime"])
    assert rebuilt.runtime_identity == patched_recipe.runtime_identity
    assert rebuilt.receipt_identity == loaded.receipt_identity
    assert pool.labels == [(handle, asset.name)]
    assert handle.pool is pool

    with pytest.raises(
        RuntimeError,
        match="^MiniMax H3 component overlay identity differs from dispatch identity$",
    ):
        arm._build_component_runtime_handle(
            descriptor,
            asset,
            "diffusion",
            "wrong-dispatch-identity",
            FakeTorch(),
            compute_dtype="bfloat16",
            as_model=True,
            required_recipe=patched_recipe,
            source_resolvers={asset.digest: asset.resolver},
        )
    renamed_source = replace(patched_recipe.sources[0].source, name="retained-name.safetensors")
    renamed_recipe = replace(
        patched_recipe,
        sources=(inference.WeightSourceBinding("diffusion", renamed_source),),
    )
    assert renamed_recipe.runtime_identity == patched_recipe.runtime_identity
    with pytest.raises(
        RuntimeError,
        match="^rebuilt MiniMax H3 component recipe differs from retained recipe$",
    ):
        arm._build_component_runtime_handle(
            descriptor,
            asset,
            "diffusion",
            renamed_recipe.runtime_identity,
            FakeTorch(),
            compute_dtype="bfloat16",
            as_model=True,
            required_recipe=renamed_recipe,
            source_resolvers={asset.digest: asset.resolver},
        )

    monkeypatch.setattr(
        arm,
        "_materialize_patch_sets",
        lambda *_args: {"conditioner": patch_set},
    )
    with pytest.raises(
        RuntimeError,
        match="^MiniMax H3 component overlays must target only diffusion$",
    ):
        arm._build_component_runtime_handle(
            descriptor,
            asset,
            "diffusion",
            patched_recipe.runtime_identity,
            FakeTorch(),
            compute_dtype="bfloat16",
            as_model=True,
            required_recipe=patched_recipe,
            source_resolvers={asset.digest: asset.resolver},
        )


@pytest.mark.parametrize("causal", (False, True))
def test_wan21_split_model_materializer_reloads_base_then_applies_diffusion_overlay(
    causal: bool, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    asset = _asset(_safetensors(tmp_path / "wan21-diffusion.safetensors"))
    plan = inference.ComponentPlan(
        "diffusion",
        asset.local_path(),
        inference.WAN21_T2V_14B,
        {},
        {},
        {},
        identity_facts=(f"asset_digest={asset.digest}", f"asset_size={asset.size}"),
    )

    class CausalModel(FakeModule):
        pass

    module = CausalModel() if causal else FakeModule()
    loaded = SimpleNamespace(role="diffusion", module=module, plan=plan)
    descriptor = replace(
        arm._component_descriptor("dinkster.wan21"),
        runtime_factory=None,
        runtime_class="Wan21CausalDiffusionRuntime" if causal else "Wan21DiffusionRuntime",
    )
    base_recipe = descriptor.recipe(
        arm._weight_source_ref(inference, asset), loaded, inference.BFLOAT16.name
    )
    overlay = replace(_overlay("8"), strength_clip="0", structural_digest="")
    patched_recipe = base_recipe.append_overlays((overlay,))
    patch_set = object()
    load_identities: list[str] = []
    materialized: list[tuple[object, object]] = []
    builds: list[dict[str, object]] = []

    class Runtime:
        def __init__(
            self,
            diffusion: object,
            family: object,
            *,
            runtime_identity: str,
        ) -> None:
            self.assembled = SimpleNamespace(diffusion=diffusion)
            self.family = family
            self.runtime_identity = runtime_identity

    class CausalRuntime(Runtime):
        pass

    def load_component(_path: Path, **kwargs: object) -> object:
        load_identities.append(cast("str", kwargs["expected_identity"]))
        return loaded

    def materialize_patch_sets(
        _inference: object,
        _inference_torch: object,
        recipe: object,
        resolvers: object,
    ) -> object:
        materialized.append((recipe, resolvers))
        return {"diffusion": patch_set}

    fake_torch_module = SimpleNamespace(
        load_wan21_component=load_component,
        Wan21DiffusionRuntime=Runtime,
        Wan21CausalModel=CausalModel,
        Wan21CausalDiffusionRuntime=CausalRuntime,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: fake_torch_module if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(arm, "_materialize_patch_sets", materialize_patch_sets)
    monkeypatch.setattr(
        arm,
        "_build_runtime_handle",
        lambda runtime, _torch, **kwargs: builds.append({"runtime": runtime, **kwargs}) or object(),
    )

    arm._build_component_runtime_handle(
        descriptor,
        asset,
        "diffusion",
        patched_recipe.runtime_identity,
        FakeTorch(),
        compute_dtype=inference.BFLOAT16.name,
        as_model=True,
        required_recipe=patched_recipe,
        source_resolvers={asset.digest: asset.resolver},
    )

    assert load_identities == [base_recipe.runtime_identity]
    assert materialized == [
        (patched_recipe, {asset.digest: asset.resolver}),
    ]
    assert len(builds) == 1
    assert builds[0]["recipe"] == patched_recipe
    assert builds[0]["patch_sets"] == {"diffusion": patch_set}
    rebuilt = cast("Runtime", builds[0]["runtime"])
    assert type(rebuilt) is (CausalRuntime if causal else Runtime)
    assert rebuilt.assembled.diffusion is module
    assert rebuilt.runtime_identity == patched_recipe.runtime_identity
    assert rebuilt.runtime_identity != base_recipe.runtime_identity


