def test_private_nvfp4_status_relay_is_exact_runtime_scoped_and_lifecycle_loud(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    runtime_a, runtime_b, rebuilt_runtime = object(), object(), object()
    snapshots = {
        runtime_a: ("immutable", "a"),
        runtime_b: ("immutable", "b"),
        rebuilt_runtime: ("immutable", "rebuilt"),
    }
    calls: list[object] = []
    diagnostics = SimpleNamespace(
        nvfp4_runtime_status=lambda runtime: calls.append(runtime) or snapshots[runtime]
    )
    real_import = importlib.import_module

    def fake_import(name: str) -> object:
        if name == "dinkster_inference_torch._nvfp4_diagnostics":
            return diagnostics
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", fake_import)
    handle_a = SimpleNamespace(runtime=runtime_a)
    handle_b = SimpleNamespace(runtime=runtime_b)
    rebuilt = SimpleNamespace(runtime=rebuilt_runtime)
    assert arm._nvfp4_runtime_status(handle_a) is snapshots[runtime_a]
    assert arm._nvfp4_runtime_status(handle_b) is snapshots[runtime_b]
    assert arm._nvfp4_runtime_status(rebuilt) is snapshots[rebuilt_runtime]
    assert calls == [runtime_a, runtime_b, rebuilt_runtime]

    class Released:
        @property
        def runtime(self) -> object:
            raise RuntimeError("native runtime handle was terminally released")

    with pytest.raises(RuntimeError, match="terminally released"):
        arm._nvfp4_runtime_status(cast("Any", Released()))


def test_legacy_sidecar_loads_and_enables_compute_following_storage(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from dinkster_compat_comfy.legacy_sources import LegacyCheckpointError

    arm = _native_arm()
    path = tmp_path / ("a" * 64)
    path.write_bytes(b"synthetic legacy checkpoint")
    asset = AssetRef(
        digest=digest_file(path),
        name="model.ckpt",
        size=path.stat().st_size,
        resolver=FixedResolver(path),
    )
    source_sha256 = hashlib.sha256(path.read_bytes()).hexdigest()
    sidecar = _safetensors(path.with_name(f"{path.stem}.{source_sha256[:16]}.dinkster.safetensors"))
    with pytest.raises(LegacyCheckpointError, match="unsupported-weight-source-format"):
        arm.resolve_weight_source(path)
    plan = SimpleNamespace(family=SimpleNamespace(id="dinkster.sd15"), identity_components=())
    monkeypatch.setattr(native_policy_module, "plan_native", lambda _source: plan)
    monkeypatch.setattr(
        importlib.import_module("dinkster_inference"),
        "plan_native",
        lambda **_sources: plan,
    )
    policy = NativeDispatchPolicy(
        lambda _digest: path,
        lambda _diagnostic: None,
        fp8_matmul=lambda: True,
        dtype_policy=lambda: {
            "diffusion": "bfloat16",
            "textEncoder": "float16",
            "vae": "float32",
        },
    )
    verdict = policy._probe_transaction(asset.digest, True, None, asset.name)
    assert verdict.kind == "native"
    assert verdict.cache_tag is not None
    assert (
        verdict.diffusion_dtype,
        verdict.text_dtype,
        verdict.vae_dtype,
    ) == ("bfloat16", "float16", "float32")
    extension_verdict = policy._probe_transaction(asset.digest, True, "a" * 64, asset.name)
    assert extension_verdict.kind == "native"
    assert extension_verdict.cache_tag != verdict.cache_tag

    runtime = _runtime()
    runtime.runtime_identity = verdict.cache_tag
    torch = FakeTorch(cuda=True)
    manager = FakeManager()
    coordinator = _coordinator(arm, manager)
    pool = FakePool()
    calls: list[dict[str, object]] = []
    real_import = importlib.import_module

    def load_runtime(
        **kwargs: object,
    ) -> object:
        calls.append(dict(kwargs))
        assert kwargs["expected_identity"] == runtime.runtime_identity
        assert kwargs["storage_dtype_follows_compute"] is True
        assert kwargs["fp8_matmul"] is True
        assert kwargs["diffusion_dtype"] == torch.bfloat16
        assert kwargs["text_dtype"] == torch.float16
        assert kwargs["vae_dtype"] == torch.float32
        return runtime

    def fake_import(name: str):
        if name == "torch":
            return torch
        if name == "dinkster_inference_torch":
            return SimpleNamespace(
                enroll_assembled=_fake_enroll_assembled,
                supports_fp8_matmul=lambda _device: True,
                torch_sampler_registry=_fake_torch_sampler_registry,
            )
        if name == "dinkster_inference_torch.wiring":
            return SimpleNamespace(load_runtime=load_runtime)
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", fake_import)
    resolved_sources: list[tuple[Path, str | None]] = []
    real_resolve = arm.resolve_weight_source

    def resolve_source(source_path: Path, logical_name: str | None = None) -> Path:
        resolved_sources.append((source_path, logical_name))
        return real_resolve(source_path, logical_name)

    monkeypatch.setattr(arm, "resolve_weight_source", resolve_source)
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    monkeypatch.setattr(arm, "default_native_residency", lambda: coordinator)
    with use_execution_context(
        ExecutionContext(
            "native",
            verdict.cache_tag,
            True,
            diffusion_dtype="bfloat16",
            text_dtype="float16",
            vae_dtype="float32",
        )
    ):
        outputs = arm.NativeLoadCheckpoint.execute(checkpoint=asset)

    assert len(calls) == 1
    assert cast(Any, calls[0]["checkpoint"]).path == sidecar
    assert resolved_sources == [(path, asset.name), (sidecar, None)]
    model, clip, vae = outputs["model"], outputs["clip"], outputs["vae"]
    assert model is clip is vae
    assert model.runtime is runtime
    checkpoint_source = model.recipe.sources[0].source
    assert checkpoint_source.digest == asset.digest
    assert checkpoint_source.name == asset.name
    assert str(model.load_device) == "cuda:0"
    assert model.model_size() == 70
    assert runtime.assembled.diffusion.moves == []
    assert runtime.assembled.clip_l.moves == []
    assert runtime.assembled.vae.moves == []
    assert pool.labels == [(model, "model.ckpt")]
    assert pool.loaded[-1] == (model, False)
    assert manager.registered() == ()


