def test_stage_accepts_partial_placement_and_accounts_conservatively() -> None:
    from dinkster_compat_comfy import ResidentPool, comfy_resident_meta
    from dinkster_compat_comfy.pool import resident_advisory_unload

    arm = _native_arm()
    manager = FakeManager(partial_load_bytes=5)
    handle = _handle(
        arm,
        _runtime(),
        coordinator=_coordinator(arm, manager),
    )
    pool = ResidentPool(
        cost_of=comfy_resident_meta,
        unload=resident_advisory_unload,
    )
    pool.label(handle, "native.safetensors")
    handle.attach_pool(pool)
    diffusion = cast(FakeMechanism, handle.mechanisms[0])

    with handle.stage("diffusion"):
        assert manager.loads[-1] == ((diffusion,), 0, False)
        assert 0 < diffusion.loaded_bytes() < diffusion.total_bytes()
        assert pool.footprint("vram:cuda:0") == 70
    assert pool.footprint("vram:cuda:0") == 70

    handle.advisory_unload()
    assert pool.footprint("vram:cuda:0") == 0
    for mechanism in handle.mechanisms:
        fake = cast(FakeMechanism, mechanism)
        assert fake.unload_calls == 1
        assert fake.partially_unload_calls == []


def test_failed_native_advisory_unload_claims_zero_and_stays_accounted(
    caplog: pytest.LogCaptureFixture,
) -> None:
    from dinkster_compat_comfy import ResidentPool, comfy_resident_meta
    from dinkster_compat_comfy.pool import resident_advisory_unload
    from dinkster_memory import PressureSignal

    arm = _native_arm()
    handle = _handle(arm, _runtime())
    pool = ResidentPool(
        cost_of=comfy_resident_meta,
        unload=resident_advisory_unload,
    )
    pool.label(handle, "native.safetensors")
    handle.attach_pool(pool)
    with handle.stage("diffusion"):
        pass
    diffusion = cast(FakeMechanism, handle.mechanisms[0])
    failing = cast(FakeMechanism, handle.mechanisms[1])
    failing.fail_unload = True

    with caplog.at_level("WARNING"):
        freed = asyncio.run(pool.shed(PressureSignal(device="vram:cuda:0", bytes_needed=70)))
    assert freed == 0
    assert pool.footprint("vram:cuda:0") == 70
    assert diffusion.loaded_bytes() == 0
    assert failing.unload_calls == 1


def test_native_advisory_unload_refuses_active_stage_then_succeeds() -> None:
    from dinkster_compat_comfy import ResidentPool, comfy_resident_meta
    from dinkster_compat_comfy.pool import (
        native_terminal_release,
        resident_advisory_unload,
    )
    from dinkster_memory import PressureSignal

    arm = _native_arm()
    torch = FakeTorch(cuda=True)
    manager = FakeManager()
    handle = _handle(
        arm,
        _runtime(),
        torch,
        coordinator=_coordinator(arm, manager),
    )
    pool = ResidentPool(
        cost_of=comfy_resident_meta,
        unload=resident_advisory_unload,
        terminal_release=native_terminal_release,
    )
    rid = pool.label(handle, "native.safetensors")
    handle.attach_pool(pool)
    assert pool.footprint("vram:cuda:0") == 0

    entered = threading.Event()
    finish = threading.Event()
    errors: list[BaseException] = []

    def run_stage() -> None:
        try:
            with handle.stage("diffusion"):
                entered.set()
                assert finish.wait(timeout=5)
        except BaseException as error:  # pragma: no cover - surfaced below
            errors.append(error)

    thread = threading.Thread(target=run_stage)
    thread.start()
    assert entered.wait(timeout=5)
    assert pool.footprint("vram:cuda:0") == 70
    diffusion = handle.runtime.assembled.diffusion
    assert [str(device) for device in diffusion.moves] == ["cuda:0"]

    freed_busy = asyncio.run(pool.shed(PressureSignal(device="vram:cuda:0", bytes_needed=70)))
    assert freed_busy == 0
    assert pool.footprint("vram:cuda:0") == 70
    assert [str(device) for device in diffusion.moves] == ["cuda:0"]

    finish.set()
    thread.join(timeout=5)
    assert not thread.is_alive()
    assert errors == []
    freed_idle = asyncio.run(pool.shed(PressureSignal(device="vram:cuda:0", bytes_needed=70)))
    assert freed_idle == 70
    assert pool.footprint("vram:cuda:0") == 0
    assert [str(device) for device in diffusion.moves] == ["cuda:0", "cpu"]
    assert manager.registered()  # advisory unload is not deregistration
    assert pool.get(rid) is handle
    assert pool.footprint("vram:cuda:0") == 0  # resolution alone does not reload
    for mechanism in handle.mechanisms:
        fake = cast(FakeMechanism, mechanism)
        assert fake.unload_calls == 1
        assert fake.partially_unload_calls == []


def test_one_native_identity_has_one_cost_and_terminal_release_is_atomic() -> None:
    from dinkster_compat_comfy import (
        ResidentLookupError,
        ResidentPool,
        comfy_resident_meta,
    )
    from dinkster_compat_comfy.pool import (
        native_terminal_release,
        resident_advisory_unload,
    )
    from dinkster_memory import PressureSignal

    arm = _native_arm()
    manager = FakeManager()
    handle = _handle(
        arm,
        _runtime(),
        coordinator=_coordinator(arm, manager),
    )
    model = clip = vae = handle
    pool = ResidentPool(
        cost_of=comfy_resident_meta,
        unload=resident_advisory_unload,
        terminal_release=native_terminal_release,
    )
    rid = pool.label(handle, "native.safetensors")
    handle.attach_pool(pool)
    assert pool.rid_for(model) == pool.rid_for(clip) == pool.rid_for(vae) == rid
    assert len(pool) == 1
    assert pool.footprint("ram") == 70
    assert pool.footprint("vram:cuda:0") == 0
    (item,) = pool.details()
    assert item.bytes_by_residency == {"ram": 70}

    for role in ("text", "diffusion", "vae"):
        with handle.stage(role):
            pass
    assert set(manager.registered()) == set(handle.mechanisms)
    assert pool.footprint("vram:cuda:0") == 70

    enrolled = handle.mechanisms
    freed = asyncio.run(pool.shed(PressureSignal(device="ram", bytes_needed=70)))
    assert freed == 70
    assert handle.released
    assert model.released and clip.released and vae.released
    assert manager.registered() == ()
    assert manager.removes[-1] == enrolled
    assert handle.mechanisms == ()
    assert pool.footprint("ram") == 0
    with pytest.raises(ResidentLookupError):
        pool.get(rid)
    for reference in (model, clip, vae):
        with pytest.raises(RuntimeError, match="terminally released"):
            reference.require_active()


