@pytest.mark.parametrize("probe_fails", (False, True), ids=("unsupported", "probe-error"))
def test_native_checkpoint_fp8_request_clears_unsupported_effective_binding(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    caplog: pytest.LogCaptureFixture,
    probe_fails: bool,
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    torch = FakeTorch()
    asset = _asset(_safetensors(tmp_path / "model.safetensors"))
    source = inference.load_safetensors_header(asset.local_path())
    plan = SimpleNamespace(family=SimpleNamespace(id="dinkster.sd15"), identity_components=())
    recipe = arm._runtime_recipe(
        inference,
        {"checkpoint": asset},
        {"checkpoint": source},
        fp8_matmul=True,
        extension_snapshot_digest=None,
        plan=plan,
    )
    events: list[str] = []

    class Fp8Module(FakeModule):
        fp8_matmul = True

        def modules(self):  # noqa: ANN201
            return iter((self,))

        def bind_fp8_matmul(self, enabled: bool) -> None:
            self.fp8_matmul = enabled
            events.append("bind-default")

        def to(self, device: object) -> FakeModule:
            assert not self.fp8_matmul, "unsupported hardware binding survived enrollment"
            return super().to(device)

    runtime = _runtime()
    runtime.runtime_identity = recipe.runtime_identity
    runtime.assembled.diffusion = Fp8Module(40)

    def supports_fp8_matmul(device: object) -> bool:
        assert device == torch.device("cpu")
        events.append("probe")
        if probe_fails:
            raise RuntimeError("driver query failed")
        return False

    def plan_native(**kwargs: object) -> object:
        assert kwargs["fp8_matmul"] is True
        events.append("plan")
        return plan

    def load_runtime(**kwargs: Any) -> object:
        assert kwargs["checkpoint"].path == asset.local_path()
        assert kwargs["expected_identity"] == recipe.runtime_identity
        assert kwargs["fp8_matmul"] is True
        assert kwargs["storage_dtype_follows_compute"] is True
        events.append("load")
        return runtime

    def enroll(assembled: Any, **kwargs: Any) -> dict[str, FakeMechanism]:
        assert assembled is runtime.assembled
        assert kwargs["load_device"] == torch.device("cpu")
        assert assembled.diffusion.fp8_matmul is False
        events.append("enroll")
        return _fake_enroll_assembled(assembled, **kwargs)

    real_import = importlib.import_module

    def fake_import(name: str) -> Any:
        if name == "dinkster_inference_torch":
            return SimpleNamespace(
                supports_fp8_matmul=supports_fp8_matmul,
                enroll_assembled=enroll,
                torch_sampler_registry=_fake_torch_sampler_registry,
            )
        if name == "dinkster_inference_torch.wiring":
            return SimpleNamespace(load_runtime=load_runtime)
        return real_import(name)

    manager = FakeManager()
    coordinator = _coordinator(arm, manager)
    pool = FakePool()
    monkeypatch.setenv("DINKSTER_AIMDO_ARM", "off")
    monkeypatch.setattr(inference, "plan_native", plan_native)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm.importlib, "import_module", fake_import)
    monkeypatch.setattr(arm, "default_native_residency", lambda: coordinator)
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    with use_execution_context(
        ExecutionContext("native", recipe.runtime_identity, fp8_matmul=True)
    ):
        outputs = arm.NativeLoadCheckpoint.execute(checkpoint=asset)

    assert events == ["plan", "load", "probe", "bind-default", "enroll"]
    probe_diagnostic = "; probeError=RuntimeError: driver query failed" if probe_fails else ""
    assert (
        "fp8-matmul-unsupported: device=cpu; capability=unavailable; torch=2.13.0"
        f"{probe_diagnostic}; falling back to the default matmul path"
    ) in caplog.text
    handle = outputs["model"]
    assert outputs["clip"] is outputs["vae"] is handle
    assert handle.runtime is runtime
    assert handle.recipe == recipe
    assert handle.recipe.knobs.fp8_matmul is True
    assert handle.runtime.runtime_identity == recipe.runtime_identity
    assert pool.labels == [(handle, asset.name)]
    with handle.stage("diffusion"):
        assert not runtime.assembled.diffusion.fp8_matmul
    assert runtime.assembled.diffusion.moves == [torch.device("cpu")]
    assert manager.loads[-1][0] == (handle.mechanisms[0],)
    handle.terminal_release()


def test_native_fp8_fallback_matches_real_cpu_default_matmul() -> None:
    torch = pytest.importorskip("torch")
    inference_torch = importlib.import_module("dinkster_inference_torch")
    arm = _native_arm()
    generator = torch.Generator().manual_seed(1349)
    state = {
        "weight": torch.randn((32, 32), generator=generator).to(torch.float8_e4m3fn),
        "weight_scale": torch.tensor(0.75, dtype=torch.float32),
        "input_scale": torch.ones((), dtype=torch.float32),
    }
    default = inference_torch.Fp8Linear(32, 32, bias=False, compute_dtype=torch.float32)
    requested = inference_torch.Fp8Linear(32, 32, bias=False, compute_dtype=torch.float32)
    default.load_state_dict(state)
    requested.load_state_dict(state)
    requested.bind_fp8_matmul(True)
    assert requested.fp8_matmul

    arm._disable_runtime_fp8_matmul(SimpleNamespace(assembled=SimpleNamespace(diffusion=requested)))

    assert not requested.fp8_matmul
    inputs = torch.randn((2, 32), generator=generator)
    torch.testing.assert_close(requested(inputs), default(inputs), rtol=0, atol=0)


