def test_z_image_sampler_encodes_and_stages_bound_control(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    control_latent = FakeTensor((1, 16, 8, 8), "control-latent")
    sample_result = FakeTensor((1, 16, 8, 8), "sampled")
    events: list[object] = []

    class Runtime:
        family = SimpleNamespace(id="dinkster.z_image", latent=object())

