def test_wan_clip_and_sampler_use_plain_5d_video_latent(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    positive = Conditioning(FakeTensor((1, 16, 4096), "positive"), None)
    negative = Conditioning(FakeTensor((1, 16, 4096), "negative"), None)
    sampled = FakeTensor((1, 16, 3, 8, 12), "sampled")

    class Runtime(_PlainVideoLatentAdapter):
        family = SimpleNamespace(id="dinkster.wan21")
        conditioning_identity = "dinkster.wan.conditioning:test:t2v"
        check_custom_sampling = staticmethod(_accept_custom_sampling)

        def __init__(self) -> None:
            self.sample_input: object | None = None
            self.sample_kwargs: dict[str, object] | None = None
            self.prepared: dict[str, object] = {}

        def encode_text(self, text: str) -> Conditioning[FakeTensor]:
            return positive if text == "moving clouds" else negative

        def prepare_text_conditioning(self, conditioning: Conditioning[FakeTensor]) -> object:
            prepared = object()
            self.prepared[conditioning.embeddings.name] = prepared
            return prepared

        def sample_multistream(self, latent: object, **kwargs: object) -> object:
            from dinkster_inference import MultiStreamLatent

            self.sample_input = latent
            self.sample_kwargs = kwargs
            assert type(latent) is MultiStreamLatent
            streams = cast("Any", latent)
            assert streams.roles == ("video",)
            assert streams.by_role("video").shape == (1, 16, 3, 8, 12)
            return streams.replace("video", sampled)

        run_ksampler_as_custom = sample_multistream

    runtime = Runtime()
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    handle = _handle(arm, runtime, torch)
    positive_wire = arm.NativeClipTextEncode.execute(text="moving clouds", clip=handle)
    negative_wire = arm.NativeClipTextEncode.execute(text="static", clip=handle)
    positive_value = cast("Any", positive_wire["conditioning"])[0][0]
    assert type(positive_value) is PreparedMultiStreamConditioning
    assert positive_value.runtime_identity == runtime.conditioning_identity
    latent = {
        "samples": FakeTensor((1, 16, 3, 8, 12), "video"),
        "custom": "preserved",
    }

    with pytest.raises(ValueError, match="prepared by a different runtime"):
        arm.NativeKSampler.execute(
            model=handle,
            seed=7,
            steps=2,
            cfg=5.0,
            sampler_name="euler",
            scheduler="simple",
            positive=[[PreparedMultiStreamConditioning("other", positive_value.payload), {}]],
            negative=negative_wire["conditioning"],
            latent_image=latent,
            denoise=1.0,
        )

    output = arm.NativeKSampler.execute(
        model=handle,
        seed=7,
        steps=2,
        cfg=5.0,
        sampler_name="euler",
        scheduler="simple",
        positive=positive_wire["conditioning"],
        negative=negative_wire["conditioning"],
        latent_image=latent,
        denoise=1.0,
    )

    assert output["latent"] == {"samples": sampled, "custom": "preserved"}
    assert runtime.sample_kwargs is not None
    assert runtime.sample_kwargs["conditioning"] is runtime.prepared["positive"]
    assert cast("Any", runtime.sample_kwargs["cfg"]).uncond is runtime.prepared["negative"]
    assert cast("Any", runtime.sample_kwargs["cfg"]).scale == 5.0
    assert runtime.sample_kwargs["sampler_id"] == "dinkster.euler"
    assert runtime.sample_kwargs["scheduler_id"] == "dinkster.simple"
    assert torch.inference_entries == 3
    diffusion, text, vae = cast("tuple[FakeMechanism, ...]", handle.mechanisms)
    assert diffusion.loaded_bytes() > 0
    assert diffusion.unload_calls == 0
    assert text.loaded_bytes() == 0
    assert text.unload_calls == 1
    assert vae.unload_calls == 0


