@pytest.mark.parametrize("family_id", ("dinkster.ltxv", "dinkster.uncatalogued"))
@pytest.mark.parametrize("latent_form", ("structural", "adapted", "missing_adapter"))
@pytest.mark.parametrize("shift", (None, 4.0))
def test_native_ksampler_adapts_declared_multistream_families(
    monkeypatch: pytest.MonkeyPatch, family_id: str, latent_form: str, shift: float | None
) -> None:
    from dinkster_inference import (
        LTX_SIGMAS,
        LTXV,
        CustomSamplingRuntime,
        FlowSigmas,
        FluxFlowSigmas,
        MultiStreamLatent,
    )

    arm = _native_arm()
    torch = FakeTorch()
    recipe = replace(_recipe(), family_id=family_id, component_identity=(f"family={family_id}",))
    video = FakeTensor((1, 128, 13, 16, 24), "video")
    streams = MultiStreamLatent.from_pairs((("video", video),))
    sampled = FakeTensor((1, 128, 13, 16, 24), "sampled")
    adapter_calls: list[object] = []
    preflight_calls: list[tuple[object, dict[str, object]]] = []
    sample_calls: list[tuple[object, object, float | None, dict[str, object]]] = []
    admitted_shifts: list[float | None] = []

    def run_ksampler_as_custom(
        latent: object, *, sampling_shift: float | None = None, **kwargs: object
    ) -> object:
        space = LTX_SIGMAS if sampling_shift is None else FluxFlowSigmas(shift=sampling_shift)
        sample_calls.append((latent, space, sampling_shift, kwargs))
        return cast("Any", latent).replace("video", sampled)

    def unexpected_multistream(*_args: object, **_kwargs: object) -> Any:
        pytest.fail("NativeKSampler must compose the custom seam instead of sample_multistream")

    def check_custom_sampling(request: object, **kwargs: object) -> None:
        preflight_calls.append((request, kwargs))

    def unexpected_custom(*_args: object, **_kwargs: object) -> Any:
        pytest.fail("declared multi-stream sampling must not use the dense custom-only route")

    diffusion = SimpleNamespace(sample_multistream=unexpected_multistream)
    wrapper = SimpleNamespace(
        family=replace(LTXV, id=family_id),
        runtime_identity=recipe.runtime_identity,
        diffusion=diffusion,
        sample_multistream=diffusion.sample_multistream,
        run_ksampler_as_custom=run_ksampler_as_custom,
        conditioning_identity="ltx-test-conditioning",
        custom_sampling_sigmas=unexpected_custom,
        custom_sampling_beta_sigmas=unexpected_custom,
        custom_sampling_sd_turbo_sigmas=unexpected_custom,
        custom_sampling_percent_to_sigma=unexpected_custom,
        check_custom_sampling=check_custom_sampling,
        sample_custom=unexpected_custom,
    )
    if latent_form != "missing_adapter":

        def adapt_multistream_latent(latent: object, **_kwargs: object) -> object:
            adapter_calls.append(latent)
            return streams

        wrapper.adapt_multistream_latent = adapt_multistream_latent
    assert isinstance(wrapper, CustomSamplingRuntime)
    handle = _handle(arm, wrapper, torch, recipe=recipe)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    if shift is not None:
        # Scalar-shift admission is separate from latent adaptation and forwarding.
        def admit_sampling_shift(runtime: object, requested: float | None) -> float | None:
            assert runtime is wrapper
            admitted_shifts.append(requested)
            return requested

        monkeypatch.setattr(arm, "_runtime_sampling_shift", admit_sampling_shift)
    latent_samples = streams if latent_form == "structural" else video

    def lane(value: object) -> list[list[object]]:
        return [[PreparedMultiStreamConditioning(wrapper.conditioning_identity, value), {}]]

    inputs = {
        "model": arm._NativeModelOverlay(handle, (), {}, sampling_shift=shift),
        "seed": 7,
        "steps": 4,
        "cfg": 5.0,
        "sampler_name": "euler",
        "scheduler": "simple",
        "positive": lane(object()),
        "negative": lane(object()),
        "latent_image": {"samples": latent_samples},
        "denoise": 1.0,
    }
    if latent_form == "missing_adapter":
        with pytest.raises(TypeError, match="cannot be adapted to the model's latent streams"):
            arm.NativeKSampler.execute(**inputs)
        assert admitted_shifts == []
        assert preflight_calls == []
        assert sample_calls == []
        return

    result = cast("Mapping[str, object]", arm.NativeKSampler.execute(**inputs)["latent"])["samples"]
    assert admitted_shifts == ([] if shift is None else [shift])
    expected_space = LTX_SIGMAS if shift is None else FluxFlowSigmas(shift=shift)
    assert type(expected_space) is FluxFlowSigmas
    assert expected_space != FlowSigmas(shift=expected_space.shift)
    assert len(preflight_calls) == 1
    preflight_request = cast("Any", preflight_calls[0][0])
    assert preflight_request.sampler.id == "dinkster.euler"
    assert tuple(name for name, _value in preflight_request.options) == (
        "s_churn",
        "s_tmin",
        "s_tmax",
        "s_noise",
    )
    assert preflight_request.sigmas == ()
    assert preflight_calls[0][1] == {
        "has_denoise_mask": False,
        "has_inpaint": False,
        "has_context_windows": False,
        "guidance": None,
    }
    assert len(sample_calls) == 1
    sampled_latent, sampled_space, sampled_shift, sample_kwargs = sample_calls[0]
    assert type(sampled_latent) is MultiStreamLatent
    assert sampled_space == expected_space
    assert sampled_shift == shift
    assert sample_kwargs["scheduler_id"] == "dinkster.simple"
    if latent_form == "structural":
        assert adapter_calls == []
        assert type(result) is MultiStreamLatent
        assert cast("Any", result).by_role("video") is sampled
    else:
        assert adapter_calls == [video]
        assert result is sampled


def test_ltxv_clip_text_encode_wraps_prepared_multistream_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    embeddings = Conditioning(FakeTensor((1, 16, 4096), "positive"), None)

    class Runtime:
        family = SimpleNamespace(id="dinkster.ltxv")
        conditioning_identity = "dinkster.ltxv.conditioning:test"

        def __init__(self) -> None:
            self.prepared: dict[str, object] = {}

        def encode_text(self, text: str) -> Conditioning[FakeTensor]:
            del text
            return embeddings

        def prepare_text_conditioning(self, conditioning: Conditioning[FakeTensor]) -> object:
            prepared = object()
            self.prepared[conditioning.embeddings.name] = prepared
            return prepared

    runtime = Runtime()
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    handle = _handle(arm, runtime, torch)

    wire = arm.NativeClipTextEncode.execute(text="moving clouds", clip=handle)

    value = cast("Any", wire["conditioning"])[0][0]
    assert type(value) is PreparedMultiStreamConditioning
    assert value.runtime_identity == runtime.conditioning_identity
    assert value.payload is runtime.prepared["positive"]


