def test_empty_ltxav_latent_builds_model_derived_streams(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import MultiStreamLatent

    arm = _native_arm()
    torch = FakeTorch()
    handle = _ltxav_geometry_handle()
    monkeypatch.setattr(arm, "_native_handle", lambda _value, _name: handle)
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    output = arm.NativeEmptyLTXAVLatent.execute(
        model=handle, width=768, height=512, length=97, frame_rate=25, batch_size=2
    )

    streams = cast("Mapping[str, object]", output["latent"])["samples"]
    assert type(streams) is MultiStreamLatent
    assert cast("Any", streams).roles == ("video", "audio")
    video = cast("Any", streams).by_role("video")
