def test_ltxv_component_builder_enrolls_with_selected_coordinator(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "ltxv-component.safetensors"))
    inference = importlib.import_module("dinkster_inference")
    module = object()
    plan = inference.ComponentPlan("t5xxl", asset.local_path(), "synthetic", {}, {}, {})
    loaded = SimpleNamespace(module=module, role="t5xxl", plan=plan)
    descriptor = arm._component_descriptor("dinkster.ltxv")
    recipe = descriptor.recipe(arm._weight_source_ref(inference, asset), loaded, "bfloat16")
    identity = recipe.runtime_identity
    enroller = object()
    mechanism = object()
    enrollment_calls: list[tuple[object, object, dict[str, object]]] = []

    class Coordinator:
        def enroll_component(
            self, module_arg: object, *, enroller: object, **kwargs: object
        ) -> object:
            enrollment_calls.append((module_arg, enroller, kwargs))
            return mechanism

    coordinator = Coordinator()
    inference_torch = SimpleNamespace(
        enroll_component=enroller,
        load_ltxv_component=lambda *_args, **_kwargs: loaded,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: inference_torch if name == "dinkster_inference_torch" else real_import(name),
    )
    monkeypatch.setattr(arm, "default_native_residency", lambda: coordinator)
    monkeypatch.setattr(arm, "default_pool", FakePool)

    class Handle:
        def __init__(self, *args: object, **kwargs: object) -> None:
            self.args = args
            self.kwargs = kwargs

        def attach_pool(self, _pool: object) -> None:
            pass

    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)

    result = arm._build_component_runtime_handle(
        descriptor,
        asset,
        "t5xxl",
        identity,
        FakeTorch(cuda=True),
        compute_dtype="bfloat16",
        load_device=FakeDevice("cuda:0"),
    )

    assert isinstance(result, Handle)
    assert enrollment_calls == [
        (
            module,
            enroller,
            {
                "load_device": FakeDevice("cuda:0"),
                "offload_device": FakeDevice("cpu"),
            },
        )
    ]
    assert result.args[:3] == (module, mechanism, FakeDevice("cuda:0"))
    assert result.kwargs["coordinator"] is coordinator


