@pytest.mark.parametrize(
    ("text_role", "projection_config", "projection_from_text", "expected_roles"),
    (
        ("gemma3_12b", "single_linear", False, ("gemma3_12b", "text_projection", "connectors")),
        ("gemma3_12b", "dual_linear", False, ("gemma3_12b", "text_projection")),
        ("gemma4_12b", "dual_linear_gemma4", True, ("gemma4_12b", "text_projection")),
    ),
)
def test_build_ltxav_text_handle_composes_profile_components(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    text_role: str,
    projection_config: str,
    projection_from_text: bool,
    expected_roles: tuple[str, ...],
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    text_encoder = _asset(_safetensors(tmp_path / "gemma.safetensors"))
    checkpoint = _asset(_safetensors(tmp_path / "ltx.safetensors"))
    expected_identity = "native:dinkster.ltxav:" + "1" * 64
    roles: list[str] = []
    attention: list[tuple[object, object]] = []
    built: list[tuple[object, str, str, object, dict[str, object]]] = []
    composed: list[tuple[tuple[object, ...], str]] = []
    result = object()
    token = AttentionRouteToken(
        1,
        tuple(AttentionRoute(role, "sdpa") for role in ATTENTION_ROLES),
        (("torch", "2.13.0"),),
        "dinkster.attention-kernel.v1",
        "cpu",
        None,
        "2.13.0",
        "auto",
    )

    def identity(
        _inference: object,
        _asset_value: object,
        role: str,
        _compute_dtype: str,
        _attention_policy: object,
        _attention_route_token: object,
    ) -> tuple[str, object]:
        roles.append(role)
        attention.append((_attention_policy, _attention_route_token))
        if role == "text_projection" and projection_from_text and _asset_value is checkpoint:
            raise inference.LTXAVComponentAssemblyError("checkpoint has no projection")
        planned = SimpleNamespace(component=SimpleNamespace(config=projection_config))
        return f"identity:{role}", planned

    def build(
        descriptor: Any,
        asset: object,
        role: str,
        identity: str,
        torch: object,
        **kwargs: object,
    ) -> object:
        assert descriptor.id == "dinkster.ltxav"
        built.append((asset, role, identity, torch, kwargs))
        return SimpleNamespace(terminal_release=lambda: None)

    def text_handle(handles: tuple[object, ...], identity: str) -> object:
        composed.append((handles, identity))
        return result

    monkeypatch.setattr(arm, "_ltxav_component_identity", identity)
    monkeypatch.setattr(arm, "_build_component_runtime_handle", build)
    monkeypatch.setattr(inference, "identify_ltxav_text_source", lambda _source: text_role)
    monkeypatch.setattr(
        inference,
        "compose_execution",
        lambda family_id, components: SimpleNamespace(
            family_id=family_id,
            components=components,
            execution_identity=expected_identity,
        ),
    )
    monkeypatch.setattr(arm, "_LTXAVTextHandle", text_handle)

    with use_execution_context(
        ExecutionContext(
            "native",
            expected_identity,
            diffusion_dtype="unloaded",
            text_dtype="bfloat16",
            vae_dtype="unloaded",
            attention_route_token=token,
        )
    ):
        loaded = arm._build_ltxav_text_handle(
            text_encoder,
            checkpoint,
            expected_identity,
            FakeTorch(),
            compute_dtype="bfloat16",
            load_device=FakeDevice("cpu"),
        )

    assert loaded is result
    expected_attempts = (
        (text_role, "text_projection", "text_projection")
        if projection_from_text
        else expected_roles
    )
    assert tuple(roles) == expected_attempts
    assert attention == [("auto", token)] * len(expected_attempts)
    assert tuple(call[1] for call in built) == expected_roles
    projection_asset = text_encoder if projection_from_text else checkpoint
    expected_assets = [text_encoder, projection_asset]
    if "connectors" in expected_roles:
        expected_assets.append(checkpoint)
    assert [call[0] for call in built] == expected_assets
    assert len(composed) == 1
    assert len(composed[0][0]) == len(expected_roles)
    assert composed[0][1] == expected_identity


def test_ltxav_text_handle_encodes_a_component_bound_carrier(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    calls: list[tuple[object, object, bytes, object]] = []
    stages: list[str] = []

    class GemmaComponent:
        model = object()
        tokenizer_model = b"tokenizer"

    class Runtime:
        def __init__(
            self,
            gemma: object,
            projection: object,
            tokenizer: bytes,
            *,
            connectors: object,
        ) -> None:
            calls.append((gemma, projection, tokenizer, connectors))

        @staticmethod
        def encode_text(text: str) -> object:
            return "conditioning", text

        @staticmethod
        def text_conditioning_carrier(conditioning: object) -> object:
            return "carrier", conditioning

    fake_inference_torch = SimpleNamespace(
        LTXAVGemmaComponent=GemmaComponent,
        LTXAVTextRuntime=Runtime,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )

    @contextmanager
    def stage() -> Iterator[None]:
        stages.append("enter")
        try:
            yield
        finally:
            stages.append("exit")

    projection = object()
    connectors = object()
    handles = (
        SimpleNamespace(
            component=GemmaComponent(),
            load_device=FakeDevice("cpu"),
            require_active=lambda: None,
            stage=stage,
        ),
        SimpleNamespace(component=projection, require_active=lambda: None, stage=stage),
        SimpleNamespace(component=connectors, require_active=lambda: None, stage=stage),
    )
    handle = arm._LTXAVTextHandle(cast("Any", handles), "text-composition")

    with handle.stage():
        carrier = handle.encode_text("prompt")

    assert calls == [(GemmaComponent.model, projection, b"tokenizer", connectors)]
    assert carrier == ("carrier", ("conditioning", "prompt"))
    assert stages == ["enter", "enter", "enter", "exit", "exit", "exit"]
    assert handle._dinkster_resident_owner is handles[0]
    assert handle._dinkster_resident_refs == handles[1:]


