def test_ltxav_audio_vae_decode_uses_standalone_codec_and_refuses_other_streams(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    torch = FakeTorch(cuda=True)
    stages: list[str] = []
    decoded: list[FakeTensor] = []

    class Codec(_FakeLTXAudioCodec):
        pass

    class Runtime:
        def __init__(self, component: object) -> None:
            assert type(component) is Codec

        def decode_audio_latent(self, latent: FakeTensor) -> object:
            decoded.append(latent)
            return inference.AudioPreview(
                FakeTensor((latent.shape[0], 2, 48000), "waveform", device=latent.device),
                48000,
            )

    class Component:
        component = Codec()
        load_device = FakeDevice("cuda:0")
        recipe = _ltx_component_recipe("audio_vae")
        resource_identity = recipe.runtime_identity

        def require_active(self) -> None:
            pass

        @contextmanager
        def stage(self) -> Iterator[None]:
            stages.append("enter")
            try:
                yield
            finally:
                stages.append("exit")

    fake_inference_torch = SimpleNamespace(
        LTXAVAudioCodec=Codec,
        LTXAVAudioCodecRuntime=Runtime,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "NativeComponentHandle", Component)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    latent = FakeTensor((2, 8, 3, 16), "audio-latent")

    result = arm.GenerationLTXAVAudioVAEDecode.execute(
        samples={"samples": inference.MultiStreamLatent.from_pairs((("audio", latent),))},
        audio_vae=Component(),
    )

    assert stages == ["enter", "exit"]
    assert decoded == [latent]
    assert latent.moves == [FakeDevice("cuda:0")]
    assert cast("Any", result["audio"])["waveform"].shape == (2, 2, 48000)
    assert cast("Any", result["audio"])["sample_rate"] == 48000

    with pytest.raises(TypeError, match="exactly one audio stream"):
        arm.GenerationLTXAVAudioVAEDecode.execute(
            samples={
                "samples": inference.MultiStreamLatent.from_pairs(
                    (("video", FakeTensor((1, 128, 1, 1, 1))),)
                )
            },
            audio_vae=Component(),
        )
    with pytest.raises(ValueError, match=r"\[batch,8,time,16\]"):
        arm.GenerationLTXAVAudioVAEDecode.execute(
            samples={"samples": FakeTensor((1, 4, 3, 16))},
            audio_vae=Component(),
        )


