def test_wan_i2v_nodes_encode_vision_and_build_exact_native_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    vision = FakeTensor((1, 257, 1280), "vision", device="cuda:0")
    reference = FakeTensor((1, 16, 2, 2, 2), "reference", device="cuda:0")
    prepared_calls: list[tuple[object, FakeTensor, FakeTensor]] = []
    stages: list[str] = []

    class Runtime:
        family = SimpleNamespace(id="future.video")
        conditioning_identity = "dinkster.wan.conditioning:test:i2v"
        assembled = SimpleNamespace(
            diffusion=SimpleNamespace(config=SimpleNamespace(model_type="i2v")),
            clip_vision=object(),
        )

        def encode_vision(self, image: FakeTensor) -> FakeTensor:
            assert image.shape == (1, 8, 12, 3)
            assert str(image.device) == "cuda:0"
            return vision

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            assert content.shape == (1, 3, 5, 16, 16)
            assert str(content.device) == "cuda:0"
            return reference

        def prepare_i2v_conditioning(
            self,
            text: object,
            concat_latent: FakeTensor,
            vision_embedding: FakeTensor,
        ) -> object:
            prepared_calls.append((text, concat_latent, vision_embedding))
            return ("i2v", text)

    class Handle:
        runtime = Runtime()
        load_device = FakeDevice("cuda:0")
        recipe = SimpleNamespace(runtime_identity="wan-i2v-runtime")

        @contextmanager
        def stage(self, role: str):  # noqa: ANN201
            stages.append(role)
            yield

    handle = Handle()
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch.resize":

            def common_upscale(
                image: FakeTensor,
                width: int,
                height: int,
                _method: str,
                _crop: str,
            ) -> FakeTensor:
                return FakeTensor(
                    (image.shape[0], image.shape[1], height, width),
                    "resized",
                    device=image.device,
                    dtype=image.dtype,
                )

            return SimpleNamespace(common_upscale=common_upscale)
        return real_import(name)

    monkeypatch.setattr(arm, "_native_handle", lambda _value, _name: handle)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    image = FakeTensor((1, 8, 12, 3), "image")

    encoded = arm.NativeWan21ClipVisionEncode.execute(model=handle, image=image)
    clip_output = cast("Any", encoded["clip_vision_output"])
    assert clip_output.conditioning_identity == handle.runtime.conditioning_identity
    assert clip_output.embedding is vision

    with pytest.raises(ValueError, match="incompatible with the native Wan profile"):
        arm.NativeWan21ImageToVideo.execute(
            positive=[],
            negative=[],
            model=handle,
            start_image=image,
            clip_vision_output=replace(clip_output, conditioning_identity="other"),
            width=16,
            height=16,
            length=5,
            batch_size=2,
        )
    with pytest.raises(ValueError, match=r"\[frames,H,W,C>=3\]"):
        arm.NativeWan21ImageToVideo.execute(
            positive=[],
            negative=[],
            model=handle,
            start_image=FakeTensor((0, 8, 12, 3), "empty-image"),
            clip_vision_output=clip_output,
            width=16,
            height=16,
            length=5,
            batch_size=2,
        )
    with pytest.raises(TypeError, match="embedding must be an exact torch.Tensor"):
        arm.NativeWan21ImageToVideo.execute(
            positive=[],
            negative=[],
            model=handle,
            start_image=image,
            clip_vision_output=replace(clip_output, embedding=object()),
            width=16,
            height=16,
            length=5,
            batch_size=2,
        )

    positive_text = object()
    negative_text = object()
    positive = [
        [PreparedMultiStreamConditioning(handle.runtime.conditioning_identity, positive_text), {}]
    ]
    negative = [
        [PreparedMultiStreamConditioning(handle.runtime.conditioning_identity, negative_text), {}]
    ]

    output = arm.NativeWan21ImageToVideo.execute(
        positive=positive,
        negative=negative,
        model=handle,
        start_image=image,
        clip_vision_output=clip_output,
        width=16,
        height=16,
        length=5,
        batch_size=2,
    )

    assert stages == ["vision", "vae"]
    assert len(prepared_calls) == 2
    assert [call[0] for call in prepared_calls] == [positive_text, negative_text]
    assert all(call[1].shape == (1, 20, 2, 2, 2) for call in prepared_calls)
    assert all(call[2] is vision for call in prepared_calls)
    for name, text in (("positive", positive_text), ("negative", negative_text)):
        prepared = cast("Any", output[name])[0][0]
        assert prepared.runtime_identity == handle.runtime.conditioning_identity
        assert prepared.payload == ("i2v", text)
    latent = cast("Any", output["latent"])["samples"]
    assert latent.shape == (2, 16, 2, 2, 2)
    assert str(latent.device) == "cpu"


@pytest.mark.parametrize("with_vision", (False, True))
def test_wan_track_to_video_builds_model_mask_and_motion_conditioning(
    monkeypatch: pytest.MonkeyPatch,
    with_vision: bool,
) -> None:
    torch = pytest.importorskip("torch")
    arm = _native_arm()
    prepared_calls: list[tuple[object, object, object]] = []
    encoded_inputs: list[object] = []
    stages: list[str] = []

    class Runtime:
        family = SimpleNamespace(id="future.video")
        conditioning_identity = "dinkster.wan.conditioning:test:ati"
        assembled = SimpleNamespace(
            diffusion=SimpleNamespace(
                config=SimpleNamespace(model_type="i2v", in_channels=36, out_channels=16)
            ),
            clip_vision=object(),
            vae=SimpleNamespace(
                process_in=lambda value: value + 100.0,
                process_out=lambda value: value - 100.0,
            ),
        )

        def encode_content(self, content: object) -> object:
            encoded_inputs.append(cast("Any", content).detach().clone())
            return torch.ones((1, 16, 2, 2, 2))

        def prepare_i2v_conditioning(
            self,
            text: object,
            concat_latent: object,
            vision: object,
        ) -> object:
            prepared_calls.append((text, concat_latent, vision))
            return ("ati", text)

    class Handle:
        runtime = Runtime()
        load_device = torch.device("cpu")

        @contextmanager
        def stage(self, role: str):  # noqa: ANN201
            stages.append(role)
            yield

    handle = Handle()
    real_import = arm.importlib.import_module

    def resize_to_batch_size(value: object, batch_size: int) -> object:
        tensor = cast("Any", value)
        return tensor.repeat(batch_size, 1, 1, 1, 1)

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch.resize":
            return SimpleNamespace(
                common_upscale=lambda value, width, height, _method, _crop: value,
                resize_to_batch_size=resize_to_batch_size,
            )
        return real_import(name)

    monkeypatch.setattr(arm, "_native_handle", lambda _value, _name: handle)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "importlib", SimpleNamespace(import_module=import_module))
    vision = torch.zeros((1, 257, 1280))
    monkeypatch.setattr(arm, "_wan21_clip_embedding", lambda *_args, **_kwargs: vision)
    positive_text = object()
    negative_text = object()
    positive = [
        [PreparedMultiStreamConditioning(handle.runtime.conditioning_identity, positive_text), {}]
    ]
    negative = [
        [PreparedMultiStreamConditioning(handle.runtime.conditioning_identity, negative_text), {}]
    ]
    tracks = json.dumps(
        [[{"x": 2.0 + index * 0.05, "y": 3.0 + index * 0.03} for index in range(121)]]
    )

    output = arm.NativeWanTrackToVideo.execute(
        positive=positive,
        negative=negative,
        vae=handle,
        tracks=tracks,
        width=16,
        height=16,
        length=5,
        batch_size=2,
        temperature=220.0,
        topk=2,
        start_image=torch.full((1, 16, 16, 3), 0.75),
        clip_vision_output=object() if with_vision else None,
    )

    assert stages == ["vae"]
    assert len(encoded_inputs) == 2
    assert all(cast("Any", value).shape == (1, 3, 5, 16, 16) for value in encoded_inputs)
    assert len(prepared_calls) == 2
    assert [call[0] for call in prepared_calls] == [positive_text, negative_text]
    concat = cast("Any", prepared_calls[0][1])
    assert concat is prepared_calls[1][1]
    assert concat.shape == (2, 20, 2, 2, 2)
    assert torch.equal(concat[:, :4, :1], torch.ones_like(concat[:, :4, :1]))
    assert torch.equal(concat[:, 4:, :1], torch.ones_like(concat[:, 4:, :1]))
    expected_vision = vision if with_vision else None
    assert all(call[2] is expected_vision for call in prepared_calls)
    for name, text in (("positive", positive_text), ("negative", negative_text)):
        prepared = cast("Any", output[name])[0][0]
        assert prepared.runtime_identity == handle.runtime.conditioning_identity
        assert prepared.payload == ("ati", text)
    latent = cast("Any", output["latent"])["samples"]
    assert latent.shape == (2, 16, 2, 2, 2)
    assert latent.device == torch.device("cpu")


