def test_wan_move_position_replacement_matches_pinned_comfyui_rng_order() -> None:
    torch = pytest.importorskip("torch")
    arm = _native_arm()
    tracks = torch.tensor(
        [
            [[2.0, 3.0], [5.0, 7.0]],
            [[4.0, 4.0], [6.0, 8.0]],
            [[7.0, 5.0], [-1.0, 8.0]],
            [[9.0, 6.0], [8.0, 8.0]],
            [[10.0, 7.0], [9.0, 9.0]],
        ]
    )
    visibility = torch.tensor(
        [[True, True], [True, True], [True, False], [True, True], [True, True]]
    )
    torch.manual_seed(345)
    positions = arm._wan_move_positions(
        tracks,
        visibility,
        height=16,
        width=24,
        torch=torch,
    )
    assert torch.equal(
        positions,
        torch.tensor([[[0, 0], [0, 1]], [[0, 0], [1, 1]]]),
    )

    feature = torch.arange(1 * 4 * 2 * 2 * 3, dtype=torch.float32).reshape(1, 4, 2, 2, 3)
    torch.manual_seed(999)
    output = arm._wan_move_replace_feature(feature, positions.unsqueeze(0), 0.7, torch)
    assert hashlib.sha256(output.numpy().tobytes()).hexdigest() == (
        "6e4d6a66f9267209233348bf46f1203c6706a6bd7e3ca3ff3475bb2c418f7820"
    )


def test_wan_move_track_to_video_builds_reference_exact_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    torch = pytest.importorskip("torch")
    arm = _native_arm()
    prepared_calls: list[tuple[object, object, object]] = []
    stages: list[str] = []
