    assert concat is prepared_calls[1][1]
    assert concat.shape == (1, 20, 2, 2, 2)
    assert torch.equal(concat[:, :4, 0], torch.ones((1, 4, 2, 2)))
    assert torch.equal(concat[:, :4, 1], torch.zeros((1, 4, 2, 2)))
    expected_reference = encoded.clone()
    expected_reference[:, :, 1, 1, 1] = expected_reference[:, :, 0, 0, 0]
    assert torch.equal(concat[:, 4:], expected_reference)
    assert all(call[2] is None for call in prepared_calls)
    for name, text in (("positive", positive_text), ("negative", negative_text)):
        prepared = cast("Any", output[name])[0][0]
        assert prepared.runtime_identity == handle.runtime.conditioning_identity
        assert prepared.payload == ("move", text)
    latent = cast("Any", output["latent"])["samples"]
    assert latent.shape == (1, 16, 2, 2, 2)
    assert latent.device == torch.device("cpu")


