def test_classic_control_materialization_builds_ordered_runtime_chain(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import ControlApplication, PayloadReference, PercentRange

    arm = _native_arm()
    resource, _mechanism = _control_resource(arm)
    pool = ControlPool()
    resident_id = "resident:" + pool.rid_for(resource)
    first_hint = arm._ControlHintSnapshot((1, 3, 8, 8), b"\x01" * 768, "b" * 64)
    second_hint = arm._ControlHintSnapshot((1, 3, 8, 8), b"\x02" * 768, "c" * 64)
    first_application = ControlApplication(
        "first", PayloadReference(first_hint.digest), 1.0, PercentRange(0.0, 1.0)
    )
    second_application = ControlApplication(
        "second",
        PayloadReference(second_hint.digest),
        0.5,
        PercentRange(0.25, 0.75),
        first_application,
    )
    binding = arm._ClassicControlBinding(
        second_application,
        (
            arm._ClassicControlEntry("first", resident_id, resource.resource_digest, first_hint),
            arm._ClassicControlEntry("second", resident_id, resource.resource_digest, second_hint),
        ),
        False,
    )
    controls: list[SimpleNamespace] = []

    def resolved_control(
        application: object,
        model: object,
        hint: object,
        model_digest: str,
        hint_digest: str,
        *,
        previous: object,
    ) -> SimpleNamespace:
        result = SimpleNamespace(
            application=application,
            model=model,
            hint=hint,
            model_digest=model_digest,
            hint_digest=hint_digest,
            previous=previous,
        )
        controls.append(result)
        return result

    inference_torch = SimpleNamespace(
        sd_control_hint_digest=lambda hint: (  # noqa: ARG005
            first_hint.digest if len(controls) == 0 else second_hint.digest
        ),
        SDControlConditioning=resolved_control,
    )
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    resolved, handles = arm._materialize_classic_control(
        binding,
        latent_batch=1,
        torch=FakeTorch(),
        inference=importlib.import_module("dinkster_inference"),
        inference_torch=inference_torch,
    )

    assert resolved is controls[1]
    assert controls[0].application is first_application
    assert controls[0].previous is None
    assert controls[1].application is second_application
    assert controls[1].previous is controls[0]
    assert handles == (resource.handle,)


@pytest.mark.parametrize("invalid_hint", (False, True))
def test_deferred_control_materialization_is_shared_and_released_on_exit(
    monkeypatch: pytest.MonkeyPatch, invalid_hint: bool
) -> None:
    from dinkster_inference import component_registry

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    original, _mechanism = _control_resource(arm, discard_on_release=True)
    handle = original.handle
    resource = replace(
        original,
        handle=None,
        descriptor=SimpleNamespace(loader="test.control:load", runtime_class="test.control:bind"),
        plan=object(),
    )
    pool = ControlPool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)
    hint = arm._ControlHintSnapshot((1, 3, 8, 8), bytes(768), "b" * 64)
    binding = None
    for _ in range(2):
        binding = arm._extend_control_binding(
            binding,
            resource=resource,
            hint=hint,
            strength=1.0,
            start_percent=0.0,
            end_percent=1.0,
            apply_to_uncond=False,
            inference=inference,
        )
    base = SimpleNamespace(compute_dtype=lambda _role: "float16")
    base_handle = SimpleNamespace(
        runtime=SimpleNamespace(assembled=base),
        recipe=SimpleNamespace(
            sources=(
                SimpleNamespace(
                    role="diffusion", source=SimpleNamespace(digest="blake3:" + "c" * 64)
                ),
            )
        ),
    )
    loads: list[object] = []

    def load(plan: object, dtype: str, **kwargs: object) -> object:
        loads.append(plan)
        assert plan is resource.plan
        assert dtype == "float16"
        assert kwargs == {"base": base, "base_asset_digest": "blake3:" + "c" * 64}
        return handle.module

    monkeypatch.setattr(
        component_registry,
        "execution_symbol",
        lambda symbol: load if symbol == "test.control:load" else lambda *args, **kwargs: args,
    )

    def enroll(*_args: object, discard_on_release: bool = False) -> object:
        assert discard_on_release
        return handle

    monkeypatch.setattr(arm, "_enroll_control_module", enroll)
    inference_torch = SimpleNamespace(
        sd_control_hint_digest=lambda _hint: "d" * 64 if invalid_hint else hint.digest,
    )
    with pytest.raises(ValueError, match="snapshot digest" if invalid_hint else "sampling failed"):
        with arm._classic_control_context(
            binding,
            latent_batch=1,
            torch=FakeTorch(),
            inference=inference,
            inference_torch=inference_torch,
            base_handle=base_handle,
        ) as (_control, handles):
            assert handles == (handle,)
            assert not handle.released
            raise ValueError("sampling failed")
    assert len(loads) == 1
    assert handle.released
    assert resource.handle is None


@pytest.mark.parametrize("receiver_kind", ["legacy", "flux"])
@pytest.mark.parametrize("resident_carrier", [False, True])
def test_native_sampler_stages_and_passes_classic_control(
    monkeypatch: pytest.MonkeyPatch,
    receiver_kind: str,
    resident_carrier: bool,
) -> None:
    from dinkster_inference import (
        ControlApplication,
        PayloadReference,
        PercentRange,
        ResidentConditioningCarrier,
    )

    arm = _native_arm()
    torch = FakeTorch()
    resource, mechanism = _control_resource(arm)
    application = ControlApplication(
        "canny", PayloadReference("b" * 64), 1.0, PercentRange(0.0, 1.0)
    )
    snapshot = arm._ControlHintSnapshot((1, 3, 8, 8), b"\0" * 768, "b" * 64)
    binding = arm._ClassicControlBinding(
        application,
        (
            arm._ClassicControlEntry(
                "canny", "resident:control", resource.resource_digest, snapshot
            ),
        ),
        False,
    )
    sampled = FakeTensor((1, 4, 8, 8), "sampled")
    seen: dict[str, object] = {}

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def sample(self, _latent: object, **kwargs: object) -> FakeTensor:
            seen.update(kwargs)
            return sampled

    runtime = Runtime()
    if receiver_kind == "flux":
        pytest.importorskip("torch")
        from dinkster_inference_torch.wiring import FluxRuntime

        receiver = object.__new__(FluxRuntime).sample_custom
        assert receiver.__func__ is FluxRuntime.sample_custom
        monkeypatch.setattr(runtime, "sample_custom", receiver, raising=False)

    real_import_module = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            SimpleNamespace(torch_sampler_registry=_fake_torch_sampler_registry)
            if name == "dinkster_inference_torch"
            else real_import_module(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    def materialize(candidate: object, **kwargs: object) -> tuple[str, tuple[object, ...]]:
        assert candidate is binding
        assert kwargs["latent_batch"] == 1
        return "resolved-control", (resource.handle,)

    monkeypatch.setattr(arm, "_materialize_classic_control", materialize)
    inputs = _ksampler_inputs(arm, runtime, torch)
    for name in ("positive", "negative"):
        conditioning = cast("list[list[object]]", inputs[name])
        metadata = cast("dict[str, object]", conditioning[0][1])
        metadata["control"] = binding
        metadata["control_apply_to_uncond"] = False
        if resident_carrier:
            inputs[name] = ResidentConditioningCarrier(
                arm._ControlledConditioning(conditioning, binding, (resource,))
            )

    if receiver_kind == "flux":
        events: list[str] = []

        def unexpected_materialize(*_args: object, **_kwargs: object) -> None:
            events.append("materialize")
            pytest.fail("receiver admission must precede control materialization")

        def unexpected_stage(*_args: object, **_kwargs: object) -> None:
            events.append("stage")
            pytest.fail("receiver admission must precede residency staging")

        monkeypatch.setattr(arm, "_materialize_classic_control", unexpected_materialize)
        monkeypatch.setattr(arm.NativeRuntimeHandle, "stage", unexpected_stage)
        monkeypatch.setattr(arm.NativeComponentHandle, "stage", unexpected_stage)
        with pytest.raises(TypeError, match="selected sampler to accept the 'control' keyword"):
            arm.NativeKSampler.execute(**inputs)
        assert events == []
        assert seen == {}
        assert mechanism.partially_load_calls == []
        return

    output = arm.NativeKSampler.execute(**inputs)

    assert output["latent"]["samples"] is sampled
    assert seen["control"] == "resolved-control"
    assert mechanism.partially_load_calls == [None]


@pytest.mark.parametrize(
    "receiver_kind", ["kwargs", "explicit", "partial", "missing", "positional", "flux"]
)
def test_generation_custom_sampler_stages_and_passes_classic_control(
    monkeypatch: pytest.MonkeyPatch,
    receiver_kind: str,
) -> None:
    from dinkster_inference import CustomSamplingRequest, CustomSamplingResult

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    torch = FakeTorch()
    resource, mechanism = _control_resource(arm)
    binding = arm._ClassicControlBinding(object(), (), False)
    inherited_binding = arm._ClassicControlBinding(object(), (), True)
    controlled = [
        [
            FakeTensor((1, 77, 4), "controlled"),
            {"control": binding, "control_apply_to_uncond": False},
        ]
    ]
    inherited = [
        [
            FakeTensor((1, 77, 4), "inherited"),
            {"control": inherited_binding, "control_apply_to_uncond": True},
        ]
    ]
    sampled = FakeTensor((1, 4, 8, 8), "sampled")
    generated_noise = FakeTensor((1, 4, 8, 8), "noise")
    resolved_control = object()
    calls: list[dict[str, object]] = []

    class Cache:
        @staticmethod
        def wrap_denoiser(denoiser: object, sigmas: object, info: object) -> object:
            del sigmas, info
            return denoiser

    cache = Cache()

    class Runtime:
        family = inference.SD15

        @staticmethod
        def custom_sampling_sigmas(
            _scheduler_id: str, _steps: int, _denoise: float
        ) -> tuple[float, ...]:
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_beta_sigmas(
            _steps: int, _alpha: float, _beta: float
        ) -> tuple[float, ...]:
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_sd_turbo_sigmas(_steps: int, _denoise: float) -> tuple[float, ...]:
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_percent_to_sigma(
            _percent: float, *, return_actual_sigma: bool
        ) -> float:
            del return_actual_sigma
            return 0.0

        @staticmethod
        def check_custom_sampling(request: object, **_kwargs: object) -> None:
            assert isinstance(request, CustomSamplingRequest)

        @staticmethod
        def sample_custom(latent: object, **kwargs: object) -> CustomSamplingResult[Any]:
            calls.append({"latent": latent, **kwargs})
            return CustomSamplingResult(cast("Any", sampled), None)

    runtime = Runtime()
    original_sample_custom = runtime.sample_custom

    def explicit_control(
        latent: object, *, control: object = None, **kwargs: object
    ) -> CustomSamplingResult[Any]:
        return original_sample_custom(latent, control=control, **kwargs)

    def missing_control(latent: object) -> CustomSamplingResult[Any]:
        pytest.fail("unsupported receiver must not execute")

    def positional_control(latent: object, control: object = None, /) -> CustomSamplingResult[Any]:
        pytest.fail("positional-only receiver must not execute")

    if receiver_kind == "explicit":
        monkeypatch.setattr(runtime, "sample_custom", explicit_control)
    elif receiver_kind == "partial":
        monkeypatch.setattr(runtime, "sample_custom", partial(explicit_control, control=None))
    elif receiver_kind == "missing":
        monkeypatch.setattr(runtime, "sample_custom", missing_control)
    elif receiver_kind == "positional":
        monkeypatch.setattr(runtime, "sample_custom", positional_control)
    elif receiver_kind == "flux":
        pytest.importorskip("torch")
        from dinkster_inference_torch.wiring import FluxRuntime

        receiver = object.__new__(FluxRuntime).sample_custom
        assert receiver.__func__ is FluxRuntime.sample_custom
        monkeypatch.setattr(runtime, "sample_custom", receiver)
    handle = _handle(arm, runtime, torch)
    fake_inference_torch = SimpleNamespace(
        prepare_noise=lambda samples, seed, noise_inds: (
            generated_noise
            if (samples.shape, seed, noise_inds) == ((1, 4, 8, 8), 17, None)
            else pytest.fail("unexpected noise request")
        ),
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "sampling_preview_emitter", lambda _handle: None)
    monkeypatch.setattr(
        arm,
        "_custom_sampling_conditioning",
        lambda *_args: (object(), None),
    )

    def materialize(candidate: object, **kwargs: object) -> tuple[object, tuple[object, ...]]:
        assert candidate is binding or candidate is inherited_binding
        assert kwargs["latent_batch"] == 1
        return resolved_control, (resource.handle,)

    monkeypatch.setattr(arm, "_materialize_classic_control", materialize)
    sampler = arm.GenerationKSamplerSelect.execute(sampler_name="euler")["sampler"]
    if receiver_kind in ("missing", "positional", "flux"):
        events: list[str] = []

        def unexpected_materialize(*_args: object, **_kwargs: object) -> None:
            events.append("materialize")
            pytest.fail("receiver admission must precede control materialization")

        def unexpected_stage(*_args: object, **_kwargs: object) -> None:
            events.append("stage")
            pytest.fail("receiver admission must precede residency staging")

        monkeypatch.setattr(arm, "_materialize_classic_control", unexpected_materialize)
        monkeypatch.setattr(arm.NativeRuntimeHandle, "stage", unexpected_stage)
        monkeypatch.setattr(arm.NativeComponentHandle, "stage", unexpected_stage)
        with pytest.raises(TypeError, match="selected sampler to accept the 'control' keyword"):
            arm._execute_generation_custom_sampling(
                model=handle,
                noise=arm._CustomNoiseValue(17),
                sampler=sampler,
                sigmas=arm._CustomSigmasValue((1.0, 0.0)),
                positive=controlled,
                negative=controlled,
                cfg=6.5,
                latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
            )
        assert events == []
        assert calls == []
        assert mechanism.partially_load_calls == []
        return
    output, _denoised = arm._execute_generation_custom_sampling(
        model=arm._NativeModelOverlay(handle, (), {}, sampling_cache=cache),
        noise=arm._CustomNoiseValue(17),
        sampler=sampler,
        sigmas=arm._CustomSigmasValue((1.0, 0.0)),
        positive=controlled,
        negative=controlled,
        cfg=6.5,
        latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
    )

    assert output["samples"] is sampled
    assert len(calls) == 1
    assert calls[0]["control"] is resolved_control
    assert cast("CustomSamplingRequest[Any]", calls[0]["request"]).cache is cache
    assert mechanism.partially_load_calls == [None]

    plain = [[FakeTensor((1, 77, 4), "plain"), {}]]
    with pytest.raises(ValueError, match="must cover empty conditioning"):
        arm._execute_generation_custom_sampling(
            model=handle,
            noise=arm._CustomNoiseValue(17),
            sampler=sampler,
            sigmas=arm._CustomSigmasValue((1.0, 0.0)),
            positive=controlled,
            negative=controlled,
            empty=plain,
            cfg=6.5,
            latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
        )
    with pytest.raises(ValueError, match="cannot be attached only to empty"):
        arm._execute_generation_custom_sampling(
            model=handle,
            noise=arm._CustomNoiseValue(17),
            sampler=sampler,
            sigmas=arm._CustomSigmasValue((1.0, 0.0)),
            positive=plain,
            negative=plain,
            empty=controlled,
            cfg=6.5,
            latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
        )
    arm._execute_generation_custom_sampling(
        model=handle,
        noise=arm._CustomNoiseValue(17),
        sampler=sampler,
        sigmas=arm._CustomSigmasValue((1.0, 0.0)),
        positive=controlled,
        negative=controlled,
        empty=controlled,
        cfg=6.5,
        latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
    )
    assert len(calls) == 2
    assert calls[1]["control"] is resolved_control
    with pytest.raises(ValueError, match="must match the positive control"):
        arm._execute_generation_custom_sampling(
            model=handle,
            noise=arm._CustomNoiseValue(17),
            sampler=sampler,
            sigmas=arm._CustomSigmasValue((1.0, 0.0)),
            positive=inherited,
            negative=plain,
            empty=controlled,
            cfg=6.5,
            latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
        )
    arm._execute_generation_custom_sampling(
        model=handle,
        noise=arm._CustomNoiseValue(17),
        sampler=sampler,
        sigmas=arm._CustomSigmasValue((1.0, 0.0)),
        positive=inherited,
        negative=plain,
        empty=plain,
        cfg=6.5,
        latent_image={"samples": FakeTensor((1, 4, 8, 8), "latent")},
    )
    assert len(calls) == 3
    assert calls[2]["control"] is resolved_control


