def test_extension_sampler_executes_through_native_ksampler_and_differs_from_euler(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        Parameterization,
        SamplerInfo,
        builtin_sampler_registry,
    )
    from s1_sampler_pack_a import SCALED_EULER

    arm = _native_arm()
    registry = _fake_torch_sampler_registry(builtin_sampler_registry())
    registry.register(SCALED_EULER)
    torch = FakeTorch()
    info = SamplerInfo(Parameterization.EPS, seed=7)
    sigmas = (2.0, 1.0, 0.0)

    def denoiser(x: float, sigma: float) -> float:
        del x, sigma
        return 0.0

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def sample(self, _latent: object, **kwargs: object) -> float:
            sampler = registry.get(cast(str, kwargs["sampler_id"]))
            assert sampler is not None
            return sampler.build()(denoiser, 8.0, sigmas, info)

    runtime = Runtime()
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(
        arm,
        "_sampler_registry",
        lambda _inference, _digest: (registry, ("proof_a",), "proof-token"),
    )
    inputs = _ksampler_inputs(arm, runtime, torch)
    inputs["sampler_name"] = "s1_scaled_euler"
    output = arm.NativeKSampler.execute(**inputs)

    euler = registry.get("euler")
    assert euler is not None
    builtin = euler.build()(denoiser, 8.0, sigmas, info)
    latent = cast("dict[str, object]", output["latent"])
    assert latent["samples"] != builtin
    assert latent["samples"] == SCALED_EULER.build()(denoiser, 8.0, sigmas, info)


