def test_vae_boundaries_permute_nchw_and_nhwc(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    decoded = FakeTensor((1, 3, 16, 24), "decoded")
    encoded = FakeTensor((1, 4, 2, 3), "encoded")

    class Codec:
        @staticmethod
        def decode_tiled(_latent: FakeTensor, **_kwargs: object) -> FakeTensor:
            pytest.fail("the no-OOM decode path must not engage tiled fallback")

        @staticmethod
        def encode_tiled(_content: FakeTensor, **_kwargs: object) -> FakeTensor:
            pytest.fail("the no-OOM encode path must not engage tiled fallback")

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def __init__(self) -> None:
            self.codec = Codec()
            self.decode_input: FakeTensor | None = None
            self.encode_input: FakeTensor | None = None

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            self.decode_input = latent
            return decoded

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            self.encode_input = content
            return encoded

    runtime = Runtime()
    handle = _handle(arm, runtime, torch)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    latent = FakeTensor((1, 4, 2, 3), "latent")
    image = arm.NativeVAEDecode.execute(samples={"samples": latent}, vae=handle)["image"]
    assert image.shape == (1, 16, 24, 3)
    assert image.name == decoded.name
    assert image.dtype == decoded.dtype
    assert [str(device) for device in latent.moves] == ["cuda:0"]

    pixels = FakeTensor((1, 16, 24, 3), "pixels")
    result = arm.NativeVAEEncode.execute(pixels=pixels, vae=handle)
    assert result == {"latent": {"samples": encoded}}
    assert runtime.encode_input is not None
    assert runtime.encode_input.shape == (1, 3, 16, 24)
    assert [str(device) for device in runtime.encode_input.moves] == ["cuda:0"]
    assert torch.inference_entries == 2


