def test_raw_vae_nodes_batch_direct_encode_and_decode_from_live_memory(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    descriptor = CodecDescriptor(
        id="dinkster.test_batched_codec",
        display_name="Test Batched Codec",
        kind="image",
        latent=LatentDescriptor(channels=4, dimensions=2, spatial_downscale=8),
        supported_dtypes=frozenset({FLOAT32}),
    )
    geometries: list[tuple[str, tuple[int, ...], object]] = []

    class Memory:
        @staticmethod
        def encode_bytes(geometry: object) -> int:
            geometries.append(("encode", cast(Any, geometry).shape, cast(Any, geometry).dtype))
            return 100

        @staticmethod
        def decode_bytes(geometry: object) -> int:
            geometries.append(("decode", cast(Any, geometry).shape, cast(Any, geometry).dtype))
            return 100

    class Codec:
        memory = Memory()
        compute_dtype = torch.float32

        def __init__(self) -> None:
            self.descriptor = descriptor

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def __init__(self) -> None:
            self.codec = Codec()
            self.decode_batches: list[int] = []
            self.encode_batches: list[int] = []

        def sample_multistream(self, *_args: object, **_kwargs: object) -> object:
            raise AssertionError("codec execution must not sample")

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            self.decode_batches.append(latent.shape[0])
            return FakeTensor(
                (latent.shape[0], 3, 16, 24),
                f"decode-{len(self.decode_batches)}",
                device=latent.device,
            )

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            self.encode_batches.append(content.shape[0])
            return FakeTensor(
                (content.shape[0], 4, 2, 3),
                f"encode-{len(self.encode_batches)}",
                device=content.device,
            )

    concatenated: list[tuple[str, ...]] = []
    original_cat = torch.cat

    def cat(tensors: tuple[FakeTensor, ...], dim: int = 0) -> FakeTensor:
        concatenated.append(tuple(tensor.name for tensor in tensors))
        return original_cat(tensors, dim)

    torch.cat = cat
    real_import_module = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return SimpleNamespace(get_free_memory=lambda _device: SimpleNamespace(free_total=250))
        return real_import_module(name)

    runtime = Runtime()
    handle = _handle(arm, runtime, torch)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm.importlib, "import_module", import_module)

    decoded = arm.NativeVAEDecode.execute(
        samples={"samples": FakeTensor((5, 4, 2, 3), device="cuda:0")},
        vae=handle,
    )["image"]
    encoded = arm.NativeVAEEncode.execute(
        pixels=FakeTensor((5, 16, 24, 3), device="cuda:0"),
        vae=handle,
    )["latent"]["samples"]

    assert decoded.shape == (5, 16, 24, 3)
    assert encoded.shape == (5, 4, 2, 3)
    assert runtime.decode_batches == [2, 2, 1]
    assert runtime.encode_batches == [2, 2, 1]
    assert concatenated == [
        ("decode-1", "decode-2", "decode-3"),
        ("encode-1", "encode-2", "encode-3"),
    ]
    assert geometries == [
        ("decode", (1, 4, 2, 3), FLOAT32),
        ("encode", (1, 3, 16, 24), FLOAT32),
    ]


def test_split_direct_vae_moves_successful_batches_to_cpu_after_tiled_fallback(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()

    class Memory:
        @staticmethod
        def decode_bytes(_geometry: object) -> int:
            return 100

    codec = SimpleNamespace(memory=Memory(), compute_dtype=torch.float32)
    handle = SimpleNamespace(load_device=FakeDevice("cuda:0"))
    calls = 0

    def decode(batch: FakeTensor) -> FakeTensor:
        nonlocal calls
        calls += 1
        if calls == 2:
            raise FakeCUDAOutOfMemoryError("second batch OOM")
        return FakeTensor((batch.shape[0], 3, 16, 24), "direct", device="cuda:0")

    real_import_module = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return SimpleNamespace(get_free_memory=lambda _device: SimpleNamespace(free_total=200))
        return real_import_module(name)

    concatenated_devices: list[tuple[str, ...]] = []
    original_cat = torch.cat

    def cat(tensors: tuple[FakeTensor, ...], dim: int = 0) -> FakeTensor:
        concatenated_devices.append(tuple(str(tensor.device) for tensor in tensors))
        return original_cat(tensors, dim)

    torch.cat = cat
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    monkeypatch.setattr(
        arm,
        "_retry_tiled_vae_after_oom",
        lambda **_kwargs: FakeTensor((1, 3, 16, 24), "tiled", device="cpu"),
    )

    output = arm._run_direct_vae(
        handle=handle,
        value=FakeTensor((3, 4, 2, 3), device="cuda:0"),
        direction="decode",
        operation=decode,
        codec=codec,
    )

    assert concatenated_devices == [("cpu", "cpu")]
    assert output.shape == (3, 3, 16, 24)
    assert str(output.device) == "cpu"


def test_codec_handle_cuda_batches_match_single_item_execution(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    if importlib.util.find_spec("torch") is None:
        pytest.skip("CUDA VAE batching requires the GPU validation environment")
    torch = importlib.import_module("torch")
    if not torch.cuda.is_available():
        pytest.skip("CUDA VAE batching requires an available CUDA device")
    arm = _native_arm()
    descriptor = CodecDescriptor(
        id="dinkster.test_cuda_batched_codec",
        display_name="Test CUDA Batched Codec",
        kind="image",
        latent=LatentDescriptor(channels=3, dimensions=2, spatial_downscale=1),
        supported_dtypes=frozenset({FLOAT32}),
    )

    class Memory:
        @staticmethod
        def encode_bytes(_geometry: object) -> int:
            return 100

        @staticmethod
        def decode_bytes(_geometry: object) -> int:
            return 100

    class Codec:
        memory = Memory()
        compute_dtype = torch.float32

        def __init__(self) -> None:
            self.descriptor = descriptor

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def __init__(self) -> None:
            self.codec = Codec()
            self.encode_batches: list[int] = []
            self.decode_batches: list[int] = []

        def sample_multistream(self, *_args: object, **_kwargs: object) -> object:
            raise AssertionError("codec execution must not sample")

        def encode_content(self, content: Any) -> Any:
            self.encode_batches.append(content.shape[0])
            return content.mul(2.0)

        def decode_latent(self, latent: Any) -> Any:
            self.decode_batches.append(latent.shape[0])
            return latent.add(3.0)

    real_import_module = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return SimpleNamespace(get_free_memory=lambda _device: SimpleNamespace(free_total=200))
        return real_import_module(name)

    runtime = Runtime()
    handle = _handle(arm, runtime, load_device="cuda:0")
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    published = arm._NativeCodecHandle(handle)
    value = torch.arange(5 * 3 * 4 * 4, device="cuda:0", dtype=torch.float32).reshape(5, 3, 4, 4)

    encoded = published.encode_content(value)
    decoded = published.decode_latent(value)
    expected_encoded = torch.cat(tuple(runtime.encode_content(item) for item in value.split(1)))
    expected_decoded = torch.cat(tuple(runtime.decode_latent(item) for item in value.split(1)))

    assert runtime.encode_batches[:3] == [2, 2, 1]
    assert runtime.decode_batches[:3] == [2, 2, 1]
    torch.testing.assert_close(encoded, expected_encoded, rtol=0, atol=0)
    torch.testing.assert_close(decoded, expected_decoded, rtol=0, atol=0)


def test_generation_codec_handle_supports_multistream_runtime_and_tiled_fallback(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        FLOAT32,
        CodecDescriptor,
        LatentDescriptor,
        require_inference_codec_handle,
        require_inference_tiled_codec_handle,
    )

    arm = _native_arm()
    torch = FakeTorch()
    cache_devices = _capture_soft_empty_cache(arm, monkeypatch)
    tiled = FakeTensor((1, 3, 5, 16, 24), "tiled", device="cuda:0")
    descriptor = CodecDescriptor(
        id="dinkster.test_video_codec",
        display_name="Test Video Codec",
        kind="video",
        latent=LatentDescriptor(
            channels=16,
            dimensions=3,
            spatial_downscale=8,
            temporal_downscale=4,
            temporal_causal=True,
        ),
        supported_dtypes=frozenset({FLOAT32}),
    )

    class Codec:
        def __init__(self) -> None:
            self.descriptor = descriptor
            self.decode_calls: list[tuple[FakeTensor, dict[str, object]]] = []
            self.encode_calls: list[tuple[FakeTensor, dict[str, object]]] = []

        def decode_tiled(self, latent: FakeTensor, **kwargs: object) -> FakeTensor:
            assert handle.coordinator._placement_depth == 1
            self.decode_calls.append((latent, kwargs))
            return tiled

        def encode_tiled(self, content: FakeTensor, **kwargs: object) -> FakeTensor:
            assert handle.coordinator._placement_depth == 1
            self.encode_calls.append((content, kwargs))
            return content

    codec = Codec()

    class Runtime:
        def __init__(self) -> None:
            self.codec = codec

        def sample_multistream(self, *_args: object, **_kwargs: object) -> object:
            raise AssertionError("codec execution must not sample")

        def decode_latent(self, _latent: FakeTensor) -> FakeTensor:
            raise FakeCUDAOutOfMemoryError("direct decode OOM")

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            return content

    handle = _handle(arm, Runtime(), torch)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    published = arm._NativeCodecHandle(handle)

    assert require_inference_codec_handle(published, "vae") is published
    assert require_inference_tiled_codec_handle(published, "vae") is published
    assert published._dinkster_resident_owner is handle
    latent = FakeTensor((1, 16, 2, 2, 3), "latent", dtype="float16")
    with published.stage():
        with torch.inference_mode():
            decoded = published.decode_latent(latent)
            encoded = published.encode_content(latent)
            tiled_decoded = published.decode_latent_tiled(
                latent,
                tile=(4, 8, 12),
                overlap=(1, 2, 3),
            )
            tiled_encoded = published.encode_content_tiled(
                latent,
                tile=(16, 64, 96),
                overlap=(4, 8, 12),
            )

    assert decoded is tiled
    assert encoded is latent
    assert tiled_decoded is tiled
    assert tiled_encoded is latent
    assert codec.decode_calls == [
        (
            latent,
            {"output_device": "cpu", "dtype": "float32"},
        ),
        (latent, {"tile": (4, 8, 12), "overlap": (1, 2, 3)}),
    ]
    assert codec.encode_calls == [(latent, {"tile": (16, 64, 96), "overlap": (4, 8, 12)})]
    assert [str(device) for device in cache_devices] == ["cuda:0"]


def test_codec_handle_tiled_retry_runs_outside_the_exception_handler(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The OOM traceback holds the direct decode/encode frames while the
    handler runs, so the tiled retry must execute with no active exception."""
    from dinkster_inference import FLOAT32, CodecDescriptor, LatentDescriptor

    arm = _native_arm()
    torch = FakeTorch()
    _capture_soft_empty_cache(arm, monkeypatch)
    tiled = FakeTensor((1, 3, 5, 16, 24), "tiled", device="cuda:0")
    descriptor = CodecDescriptor(
        id="dinkster.test_video_codec",
        display_name="Test Video Codec",
        kind="video",
        latent=LatentDescriptor(
            channels=16,
            dimensions=3,
            spatial_downscale=8,
            temporal_downscale=4,
            temporal_causal=True,
        ),
        supported_dtypes=frozenset({FLOAT32}),
    )
    active_exceptions: list[BaseException | None] = []

    class Codec:
        def __init__(self) -> None:
            self.descriptor = descriptor

        def decode_tiled(self, latent: FakeTensor, **_kwargs: object) -> FakeTensor:
            del latent
            active_exceptions.append(sys.exc_info()[1])
            return tiled

        def encode_tiled(self, content: FakeTensor, **_kwargs: object) -> FakeTensor:
            del content
            active_exceptions.append(sys.exc_info()[1])
            return tiled

    class Runtime:
        def __init__(self) -> None:
            self.codec = Codec()

        def sample_multistream(self, *_args: object, **_kwargs: object) -> object:
            raise AssertionError("codec execution must not sample")

        def decode_latent(self, _latent: FakeTensor) -> FakeTensor:
            raise FakeCUDAOutOfMemoryError("direct decode OOM")

        def encode_content(self, _content: FakeTensor) -> FakeTensor:
            raise FakeCUDAOutOfMemoryError("direct encode OOM")

    handle = _handle(arm, Runtime(), torch)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    published = arm._NativeCodecHandle(handle)
    latent = FakeTensor((1, 16, 2, 2, 3), "latent", dtype="float16")

    with published.stage():
        with torch.inference_mode():
            assert published.decode_latent(latent) is tiled
            assert published.encode_content(latent) is tiled
    assert active_exceptions == [None, None]


@pytest.mark.parametrize("custom_sampling", [False, True])
def test_generation_sampler_keeps_basic_single_stream_materialization(
    monkeypatch: pytest.MonkeyPatch, custom_sampling: bool
) -> None:
    from dinkster_inference import CustomSamplingRuntime

    arm = _native_arm()
    runtime = _runtime()

    def encode_text(_text: str) -> object:
        return object()

    def sample(_latent: object, **_kwargs: object) -> object:
        return object()

    def decode_latent(value: object) -> object:
        return value

    def encode_content(value: object) -> object:
        return value

    runtime.encode_text = encode_text
    runtime.sample = sample
    runtime.decode_latent = decode_latent
    runtime.encode_content = encode_content
    if custom_sampling:
        runtime.custom_sampling_sigmas = sample
        runtime.custom_sampling_beta_sigmas = sample
        runtime.custom_sampling_sd_turbo_sigmas = sample
        runtime.custom_sampling_percent_to_sigma = sample
        runtime.check_custom_sampling = sample
        runtime.sample_custom = sample
    assert isinstance(runtime, CustomSamplingRuntime) is custom_sampling
    handle = _handle(arm, runtime)
    identity = handle.recipe.runtime_identity

    class ComponentHandle:
        resource_identity = identity
        load_device = handle.load_device
        component = object()

        def require_active(self) -> None:
            pass

        @contextmanager
        def stage(self, *, memory_required: int = 0):  # noqa: ANN201
            del memory_required
            yield

        @contextmanager
        def stage_with(self, runtime_handle: object, role: str):  # noqa: ANN201
            del runtime_handle, role
            yield

    chain = ApplicationChain(
        handle,
        (
            ComponentApplication(
                "dinkster.sd15",
                "diffusion",
                ComponentHandle(),
                extend_runtime_identity(identity, ("application=control",)),
                lambda _runtime, _component, _latent: {"control": object()},
            ),
        ),
    )
    calls: list[tuple[object, str, object]] = []

    def materialize(value: object, input_id: str, actual_handle: object) -> list[list[object]]:
        calls.append((value, input_id, actual_handle))
        return [[f"materialized-{input_id}", {}]]

    forwarded: dict[str, object] = {}

    def execute(**kwargs: object) -> Mapping[str, object]:
        forwarded.update(kwargs)
        return {"latent": "sampled"}

    monkeypatch.setattr(arm, "_materialize_provider_conditioning", materialize)
    monkeypatch.setattr(arm.NativeKSampler, "execute", execute)
    positive = _component_conditioning_carrier("positive")
    negative = _component_conditioning_carrier("negative")

    output = arm.GenerationKSampler.execute(
        model=chain,
        seed=7,
        steps=2,
        cfg=5.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=positive,
        negative=negative,
        latent_image={"samples": object()},
        denoise=1.0,
    )

    assert output == {"latent": "sampled"}
    inference = importlib.import_module("dinkster_inference")
    assert forwarded["positive"] is positive
    assert forwarded["negative"] is negative
    assert arm._prepare_ksampler_conditioning(
        positive, "positive", handle.runtime, handle, inference
    ) == [["materialized-positive", {}]]
    assert arm._prepare_ksampler_conditioning(
        negative, "negative", handle.runtime, handle, inference
    ) == [["materialized-negative", {}]]
    assert calls == [
        (positive, "positive", handle),
        (negative, "negative", handle),
    ]
    assert forwarded["model"] is chain


def test_generation_sampler_routes_conditioning_through_single_stream_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import Conditioning, ConditioningCarrier

    arm = _native_arm()
    runtime = _runtime()
    runtime.conditioning_identity = "dinkster.qwen-image.conditioning:test"
    prepared: list[ConditioningCarrier] = []
    prepared_values: list[Conditioning[FakeTensor]] = []

    def encode_text(_text: str) -> Conditioning[FakeTensor]:
        return Conditioning(FakeTensor((1, 2, 8), "text"))

    def sample(_latent: FakeTensor, **_kwargs: object) -> FakeTensor:
        return FakeTensor((1, 16, 1, 2, 2), "sampled")

    def decode_latent(value: FakeTensor) -> FakeTensor:
        return value

    def encode_content(value: FakeTensor) -> FakeTensor:
        return value

    def prepare_single_stream_conditioning(
        value: ConditioningCarrier,
    ) -> Conditioning[FakeTensor]:
        prepared.append(value)
        conditioning = Conditioning(
            FakeTensor((1, 2, 8), f"prepared-{len(prepared)}"),
            FakeTensor((1, 8), f"pooled-{len(prepared)}"),
        )
        prepared_values.append(conditioning)
        return conditioning

    runtime.encode_text = encode_text
    runtime.sample = sample
    runtime.decode_latent = decode_latent
    runtime.encode_content = encode_content
    runtime.prepare_single_stream_conditioning = prepare_single_stream_conditioning
    handle = _handle(arm, runtime)
    forwarded: dict[str, object] = {}

    def execute(**kwargs: object) -> Mapping[str, object]:
        forwarded.update(kwargs)
        return {"latent": "sampled"}

    monkeypatch.setattr(arm.NativeKSampler, "execute", execute)
    positive = _component_conditioning_carrier("positive")
    negative = _component_conditioning_carrier("negative")

    output = arm.GenerationKSampler.execute(
        model=handle,
        seed=7,
        steps=2,
        cfg=5.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=positive,
        negative=negative,
        latent_image={"samples": object()},
        denoise=1.0,
    )

    assert output == {"latent": "sampled"}
    inference = importlib.import_module("dinkster_inference")
    assert forwarded["positive"] is positive
    assert forwarded["negative"] is negative
    positive_rows = cast(
        "list[list[object]]",
        arm._prepare_ksampler_conditioning(positive, "positive", runtime, handle, inference),
    )
    negative_rows = cast(
        "list[list[object]]",
        arm._prepare_ksampler_conditioning(negative, "negative", runtime, handle, inference),
    )
    assert prepared == [positive, negative]
    assert cast("FakeTensor", positive_rows[0][0]).name == "prepared-1"
    assert cast("FakeTensor", negative_rows[0][0]).name == "prepared-2"
    metadata = cast("dict[str, object]", positive_rows[0][1])
    expected_metadata: dict[str, object] = {
        arm._NATIVE_PREPARED_CONDITIONING_KEY: prepared_values[0]
    }
    assert metadata == expected_metadata
    materialized, inpaint = arm._conditioning(
        positive_rows,
        "positive",
        FakeTorch(),
        importlib.import_module("dinkster_inference"),
    )
    assert materialized is prepared_values[0]
    assert inpaint is None
    metadata["pooled_output"] = FakeTensor((1, 8), "legacy-pooled")
    with pytest.raises(ValueError, match="prepared conditioning cannot carry legacy metadata"):
        arm._conditioning(
            positive_rows, "positive", FakeTorch(), importlib.import_module("dinkster_inference")
        )


