def test_generation_sampler_option_nodes_publish_catalog_descriptors() -> None:
    arm = _native_arm()
    cases = (
        (
            arm.GenerationSamplerDPMPP3MSDE.execute(
                eta=0.75,
                s_noise=0.8,
                noise_device="gpu",
            )["sampler"],
            "dinkster.dpmpp_3m_sde_gpu",
            {"eta": 0.75, "s_noise": 0.8},
        ),
        (
            arm.GenerationSamplerDPMPP2MSDE.execute(
                solver_type="heun",
                eta=0.6,
                s_noise=0.7,
                noise_device="cpu",
            )["sampler"],
            "dinkster.dpmpp_2m_sde",
            {"eta": 0.6, "s_noise": 0.7, "solver_type": "heun"},
        ),
        (
            arm.GenerationSamplerDPMPPSDE.execute(
                eta=0.5,
                s_noise=0.9,
                r=2.0,
                noise_device="cpu",
            )["sampler"],
            "dinkster.dpmpp_sde",
            {"eta": 0.5, "s_noise": 0.9, "r": 2.0},
        ),
        (
            arm.GenerationSamplerDPMPP2SAncestral.execute(eta=0.4, s_noise=0.6)["sampler"],
            "dinkster.dpmpp_2s_ancestral",
            {"eta": 0.4, "s_noise": 0.6},
        ),
        (
            arm.GenerationSamplerEulerAncestral.execute(eta=0.3, s_noise=0.5)["sampler"],
            "dinkster.euler_ancestral",
            {"eta": 0.3, "s_noise": 0.5},
        ),
        (
            arm.GenerationSamplerEulerAncestralCFGPP.execute(eta=0.2, s_noise=0.4)["sampler"],
            "dinkster.euler_ancestral_cfg_pp",
            {"eta": 0.2, "s_noise": 0.4},
        ),
        (
            arm.GenerationSamplerLMS.execute(order=6)["sampler"],
            "dinkster.lms",
            {"order": 6},
        ),
        (
            arm.GenerationSamplerDPMAdaptative.execute(
                order=2,
                rtol=0.03,
                atol=0.005,
                h_init=0.08,
                pcoeff=0.1,
                icoeff=0.9,
                dcoeff=0.05,
                accept_safety=0.85,
                eta=2.0,
                s_noise=0.7,
            )["sampler"],
            "dinkster.dpm_adaptive",
            {
                "order": 2,
                "rtol": 0.03,
                "atol": 0.005,
                "h_init": 0.08,
                "pcoeff": 0.1,
                "icoeff": 0.9,
                "dcoeff": 0.05,
                "accept_safety": 0.85,
                "eta": 2.0,
                "s_noise": 0.7,
            },
        ),
        (
            arm.GenerationSamplerERSDE.execute(
                solver_type="ER-SDE",
                max_stage=3,
                eta=12.0,
                s_noise=0.75,
            )["sampler"],
            "dinkster.er_sde",
            {"solver_type": "ER-SDE", "max_stage": 3, "eta": 12.0, "s_noise": 0.75},
        ),
        (
            arm.GenerationSamplerSEEDS2.execute(
                solver_type="phi_2",
                eta=0.2,
                s_noise=0.3,
                r=0.75,
            )["sampler"],
            "dinkster.seeds_2",
            {"eta": 0.2, "s_noise": 0.3, "r": 0.75, "solver_type": "phi_2"},
        ),
    )
    for value, descriptor_id, options in cases:
        assert type(value) is arm._CustomSamplerValue
        assert value.descriptor.id == descriptor_id
        assert dict(value.options) == options

    with pytest.raises(ValueError, match="noise_device"):
        arm.GenerationSamplerDPMPP3MSDE.execute(
            eta=1.0,
            s_noise=1.0,
            noise_device="unknown",
        )
    with pytest.raises(ValueError, match="must be >="):
        arm.GenerationSamplerDPMPPSDE.execute(
            eta=1.0,
            s_noise=1.0,
            r=0.0,
            noise_device="cpu",
        )


def test_sa_solver_node_binds_percentages_and_all_options(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    percentages: list[tuple[float, bool]] = []

    class Runtime:
        @staticmethod
        def custom_sampling_percent_to_sigma(percent: float, *, return_actual_sigma: bool) -> float:
            percentages.append((percent, return_actual_sigma))
            return 10.0 - percent

    monkeypatch.setattr(
        arm,
        "_require_base_custom_sampling_runtime",
        lambda model, name: (Runtime(), None, None),
    )

    sampler = arm.GenerationSamplerSASolver.execute(
        model=object(),
        eta=0.35,
        sde_start_percent=0.2,
        sde_end_percent=0.85,
        s_noise=1.25,
        predictor_order=6,
        corrector_order=0,
        use_pece=True,
        simple_order_2=True,
    )["sampler"]

    assert sampler.descriptor.id == "dinkster.configured_sa_solver"
    assert dict(sampler.options) == {
        "eta": 0.35,
        "sde_start_sigma": 9.8,
        "sde_end_sigma": 9.15,
        "s_noise": 1.25,
        "predictor_order": 6,
        "corrector_order": 0,
        "use_pece": True,
        "simple_order_2": True,
    }
    assert percentages == [(0.2, False), (0.85, False)]


