def test_add_noise_uses_sigma_span_noise_indices_and_preserves_latent_metadata(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch_module = FakeTorch()
    samples = FakeTensor((2, 4, 2, 2), "samples")
    generated = FakeTensor((2, 4, 2, 2), "generated")
    output_samples = FakeTensor((2, 4, 2, 2), "output")
    calls: list[tuple[object, object, float]] = []

    class Runtime:
        @staticmethod
        def custom_sampling_add_noise(latent: object, noise: object, sigma: float) -> FakeTensor:
            calls.append((latent, noise, sigma))
            return output_samples

    monkeypatch.setattr(arm, "_torch", lambda: torch_module)
    monkeypatch.setattr(
        arm,
        "_require_base_custom_sampling_runtime",
        lambda model, name: (Runtime(), None, None),
    )
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: SimpleNamespace(
            prepare_noise=lambda latent, seed, noise_inds: (
                generated
                if (latent is samples and seed == 17 and noise_inds == (1, 0))
                else pytest.fail("unexpected noise request")
            )
        ),
    )
    latent = {"samples": samples, "batch_index": [1, 0], "keep": "metadata"}

    output = arm.GenerationAddNoise.execute(
        model=object(),
        noise=arm._CustomNoiseValue(17),
        sigmas=arm._CustomSigmasValue((3.5, 2.0, 0.5)),
        latent_image=latent,
    )["latent"]

    assert calls == [(samples, generated, 3.0)]
    assert output["keep"] == "metadata"
    assert output["samples"] is output_samples
    assert (
        arm.GenerationAddNoise.execute(
            model=object(),
            noise=arm._CustomNoiseValue(None),
            sigmas=arm._CustomSigmasValue(()),
            latent_image=latent,
        )["latent"]
        is latent
    )


def test_sampling_supplier_nodes_use_application_chain_base_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    torch_module = FakeTorch()
    recipe = _recipe()
    percentages: list[tuple[float, bool]] = []
    add_noise_calls: list[tuple[object, object, float]] = []
    output_samples = FakeTensor((1, 4, 2, 2), "noisy")

    class Runtime:
        family = inference.SD15
        runtime_identity = recipe.runtime_identity

        @staticmethod
        def custom_sampling_sigmas(*_args: object, **_kwargs: object) -> tuple[float, ...]:
            return (1.0, 0.0)

        custom_sampling_beta_sigmas = custom_sampling_sigmas
        custom_sampling_sd_turbo_sigmas = custom_sampling_sigmas

        @staticmethod
        def custom_sampling_percent_to_sigma(percent: float, *, return_actual_sigma: bool) -> float:
            percentages.append((percent, return_actual_sigma))
            return 1.0 - percent

        @staticmethod
        def check_custom_sampling(*_args: object, **_kwargs: object) -> None:
            pass

        @staticmethod
        def sample_custom(*_args: object, **_kwargs: object) -> object:
            raise NotImplementedError

        @staticmethod
        def custom_sampling_add_noise(latent: object, noise: object, sigma: float) -> object:
            add_noise_calls.append((latent, noise, sigma))
            return output_samples

    runtime = Runtime()
    handle = _handle(arm, runtime, torch_module, recipe=recipe)
    identity = handle.recipe.runtime_identity

    class ComponentHandle:
        resource_identity = identity
        load_device = handle.load_device
        component = object()

        def require_active(self) -> None:
            pass

        @contextmanager
        def stage(self):  # noqa: ANN201
            yield

        @contextmanager
        def stage_with(self, runtime_handle: object, role: str):  # noqa: ANN201
            del runtime_handle, role
            pytest.fail("supplier nodes must not stage model applications")

    application = ComponentApplication(
        "dinkster.sd15",
        "diffusion",
        cast("InferenceComponentHandle", ComponentHandle()),
        extend_runtime_identity(identity, ("application=lora",)),
        lambda *_args: pytest.fail("supplier nodes must not materialize model applications"),
    )
    model = ApplicationChain(handle, (application,))
    monkeypatch.setattr(arm, "_torch", lambda: torch_module)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            SimpleNamespace(
                prepare_noise=lambda samples, seed, noise_inds: samples,
                torch_sampler_registry=_fake_torch_sampler_registry,
            )
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )

    sampler = arm.GenerationSamplerSASolver.execute(
        model=model,
        eta=0.5,
        sde_start_percent=0.2,
        sde_end_percent=0.8,
        s_noise=0.75,
        predictor_order=5,
        corrector_order=2,
        use_pece=True,
        simple_order_2=False,
    )["sampler"]
    latent = {"samples": FakeTensor((1, 4, 2, 2), "latent")}
    noisy = arm.GenerationAddNoise.execute(
        model=model,
        noise=arm._CustomNoiseValue(7),
        sigmas=arm._CustomSigmasValue((1.0, 0.0)),
        latent_image=latent,
    )["latent"]

    assert sampler.descriptor.id == "dinkster.configured_sa_solver"
    assert noisy["samples"] is output_samples
    assert percentages == [(0.2, False), (0.8, False)]
    assert add_noise_calls == [(latent["samples"], latent["samples"], 1.0)]


def test_scheduled_cfg_guider_carries_a_per_run_guidance_extension(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    contribution = object()
    factory_calls: list[tuple[object, ...]] = []

    def factory(*args: object) -> object:
        factory_calls.append(args)
        return contribution

    monkeypatch.setattr(arm, "_guidance_transform_factory", factory)
    sigmas = arm._CustomSigmasValue((1.0, 0.5, 0.0))
    model = object()
    positive = object()
    negative = object()
    result = arm.GenerationScheduledCFGGuider.execute(
        model=model,
        positive=positive,
        negative=negative,
        sigmas=sigmas,
        from_cfg=1.0,
        to_cfg=4.0,
        schedule="log",
    )
    guider = result["guider"]
    assert type(guider) is arm._CustomGuiderValue
    assert guider.model is model
    assert guider.positive is positive
    assert guider.negative is negative
    assert guider.cfg == 4.0
    assert guider.transforms == (("dinkster.scheduled_cfg_guider", contribution),)
    assert result["sigmas"] is sigmas
    assert factory_calls == [("scheduled_cfg", sigmas.values, 1.0, 4.0, "log")]

    sample_calls: list[dict[str, object]] = []

    def sample(**kwargs: object) -> tuple[dict[object, object], dict[object, object]]:
        sample_calls.append(kwargs)
        return {}, {}

    monkeypatch.setattr(arm, "_execute_generation_custom_sampling", sample)
    arm.GenerationSamplerCustomAdvanced.execute(
        noise=arm._CustomNoiseValue(7),
        guider=guider,
        sampler=object(),
        sigmas=sigmas,
        latent_image={},
    )
    assert sample_calls[0]["guider_transforms"] == guider.transforms

    with pytest.raises(ValueError, match="unknown scheduled CFG interpolation"):
        arm.GenerationScheduledCFGGuider.execute(
            model=model,
            positive=positive,
            negative=negative,
            sigmas=sigmas,
            from_cfg=6.5,
            to_cfg=1.0,
            schedule="unknown",
        )


def test_generation_custom_samplers_execute_the_public_runtime_contract(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ConditioningCarrier,
        ConditioningSet,
        CustomSamplingRequest,
        CustomSamplingResult,
        GuidanceContribution,
        GuidancePostCFGDescriptor,
        InpaintConditioning,
        LatentDescriptor,
        PerpNegSamplingGuidance,
        SamplingGuidance,
    )

    arm = _native_arm()
    torch = FakeTorch()
    calls: list[dict[str, object]] = []
    schedule_devices: list[object | None] = []
    generated_noise = FakeTensor((1, 16, 8, 8), "generated-noise")
    sampled = FakeTensor((1, 16, 8, 8), "sampled", device="cuda:0")
    denoised = FakeTensor((1, 16, 8, 8), "denoised", device="cuda:0")
    runtime_recipe = replace(
        _recipe(),
        family_id="dinkster.flux_dev",
        component_identity=("family=dinkster.flux_dev",),
    )

    class Runtime:
        family = SimpleNamespace(
            id="dinkster.flux_dev",
            latent=LatentDescriptor(channels=16),
            single_stream_latent=lambda: SimpleNamespace(channels=16, dimensions=2),
        )
        runtime_identity = runtime_recipe.runtime_identity
        denoised_result: FakeTensor | None = denoised

        @staticmethod
        def encode_text(_text: str) -> Conditioning[FakeTensor]:
            return Conditioning(FakeTensor((1, 2, 8), "encoded"))

        @staticmethod
        def sample(latent: FakeTensor, **_kwargs: object) -> FakeTensor:
            return latent

        @staticmethod
        def decode_latent(latent: FakeTensor) -> FakeTensor:
            return latent

        @staticmethod
        def encode_content(content: FakeTensor) -> FakeTensor:
            return content

        @staticmethod
        def custom_sampling_sigmas(
            scheduler_id: str,
            steps: int,
            denoise: float,
            *,
            device: object | None = None,
        ) -> tuple[float, ...]:
            assert (scheduler_id, steps, denoise) == ("dinkster.normal", 2, 0.75)
            schedule_devices.append(device)
            return (1.0, 0.5, 0.0)

        @staticmethod
        def custom_sampling_beta_sigmas(
            steps: int,
            alpha: float,
            beta: float,
            *,
            device: object | None = None,
        ) -> tuple[float, ...]:
            assert (steps, alpha, beta) == (13, 2.0, 5.0)
            schedule_devices.append(device)
            return (1.0, 0.25, 0.0)

        @staticmethod
        def custom_sampling_sd_turbo_sigmas(
            steps: int,
            denoise: float,
            *,
            device: object | None = None,
        ) -> tuple[float, ...]:
            assert (steps, denoise) == (4, 0.65)
            schedule_devices.append(device)
            return (2.0, 1.0, 0.0)

        @staticmethod
        def custom_sampling_percent_to_sigma(
            percent: float,
            *,
            return_actual_sigma: bool,
        ) -> float:
            assert (percent, return_actual_sigma) == (1.0, True)
            return 0.001

        @staticmethod
        def check_custom_sampling(
            request: object,
            *,
            has_denoise_mask: bool,
            has_inpaint: bool,
            has_context_windows: bool,
            guidance: float | None = None,
        ) -> None:
            assert isinstance(request, CustomSamplingRequest)
            assert guidance is None
            assert type(has_denoise_mask) is bool
            assert type(has_inpaint) is bool

        @staticmethod
        def sample_custom(latent: object, **kwargs: object) -> Any:
            calls.append({"latent": latent, **kwargs})
            return CustomSamplingResult(cast("Any", sampled), cast("Any", Runtime.denoised_result))

    runtime = Runtime()
    handle = _handle(arm, runtime, torch, recipe=runtime_recipe)
    real_import = arm.importlib.import_module
    materialized_carriers: list[object] = []

    def materialize_basic_conditioning(value: object, *, device: object) -> object:
        assert device == handle.load_device
        materialized_carriers.append(value)
        return Conditioning(FakeTensor((1, 2, 8), "carrier"))

    fake_inference_torch = SimpleNamespace(
        materialize_basic_conditioning=materialize_basic_conditioning,
        prepare_noise=lambda samples, seed, noise_inds: (
            generated_noise
            if (samples.shape, seed, noise_inds) == ((1, 16, 8, 8), 17, (0,))
            else pytest.fail("unexpected noise request")
        ),
        torch_sampler_registry=_fake_torch_sampler_registry,
    )

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return fake_inference_torch
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "sampling_preview_emitter", lambda _handle: None)
    real_custom_sampling_conditioning = arm._custom_sampling_conditioning
    positive = [[FakeTensor((1, 2, 8), "positive"), {}]]
    negative = [[FakeTensor((1, 2, 8), "negative"), {}]]
    empty = [[FakeTensor((1, 2, 8), "empty"), {}]]
    prepared = {
        "positive": object(),
        "negative": object(),
        "empty_conditioning": object(),
    }
    mask = FakeTensor((1, 8, 8), "mask")
    inpaint = InpaintConditioning(
        cast("Any", mask),
        cast("Any", FakeTensor((1, 16, 8, 8), "masked-image")),
    )
    use_inpaint = False

    def prepare_conditioning(_value: object, input_id: str, *_args: object) -> object:
        return prepared[input_id], inpaint if use_inpaint else None

    monkeypatch.setattr(
        arm,
        "_custom_sampling_conditioning",
        prepare_conditioning,
    )
    latent = FakeTensor((1, 4, 8, 8), "latent")
    latent_value = {
        "samples": latent,
        "custom": "preserved",
        "batch_index": [0],
        "downscale_ratio_spacial": 8,
        "downscale_ratio_temporal": 1,
    }

    sampler = arm.GenerationKSamplerSelect.execute(sampler_name="euler")["sampler"]
    sigmas = arm.GenerationBasicScheduler.execute(
        model=handle,
        scheduler="normal",
        steps=2,
        denoise=0.75,
    )["sigmas"]
    beta_sigmas = arm.GenerationBetaSamplingScheduler.execute(
        model=handle,
        steps=13,
        alpha=2.0,
        beta=5.0,
    )["sigmas"]
    turbo_sigmas = arm.GenerationSDTurboScheduler.execute(
        model=handle,
        steps=4,
        denoise=0.65,
    )["sigmas"]
    sigma_value = arm.GenerationSamplingPercentToSigma.execute(
        model=handle,
        sampling_percent=1.0,
        return_actual_sigma=True,
    )["sigma_value"]
    assert beta_sigmas == arm._CustomSigmasValue((1.0, 0.25, 0.0))
    assert turbo_sigmas == arm._CustomSigmasValue((2.0, 1.0, 0.0))
    assert sigma_value == 0.001
    assert schedule_devices == [handle.load_device] * 3
    with pytest.raises(ValueError, match="steps must be in"):
        arm.GenerationBetaSamplingScheduler.execute(
            model=handle,
            steps=0,
            alpha=2.0,
            beta=5.0,
        )
    with pytest.raises(ValueError, match="steps must be in"):
        arm.GenerationSDTurboScheduler.execute(model=handle, steps=11, denoise=0.65)
    with pytest.raises(ValueError, match="denoise must be in"):
        arm.GenerationSDTurboScheduler.execute(model=handle, steps=4, denoise=1.01)
    with pytest.raises(ValueError, match="sampling_percent must be in"):
        arm.GenerationSamplingPercentToSigma.execute(
            model=handle,
            sampling_percent=-0.01,
            return_actual_sigma=False,
        )
    contribution = GuidanceContribution(
        post_cfg=(GuidancePostCFGDescriptor("test.transform", lambda context: context.reduced),)
    )
    factory_calls: list[tuple[tuple[object, ...], dict[str, object]]] = []

    def _fake_factory(*args: object, **kwargs: object) -> object:
        factory_calls.append((args, kwargs))
        return contribution

    monkeypatch.setattr(arm, "_guidance_transform_factory", _fake_factory)
    guided_model = arm.GenerationEpsilonScaling.execute(model=handle, scaling_factor=1.005)["model"]
    chained_model = arm.GenerationEpsilonScaling.execute(model=guided_model, scaling_factor=1.005)[
        "model"
    ]
    assert chained_model.guidance_transforms == (
        ("dinkster.epsilon_scaling:0", contribution),
        ("dinkster.epsilon_scaling:1", contribution),
    )
    disabled_model = arm.GenerationDisableCFG1Optimization.execute(model=guided_model)["model"]
    assert (
        arm.GenerationDisableCFG1Optimization.execute(model=disabled_model)["model"]
        is disabled_model
    )
    assert disabled_model.handle is guided_model.handle
    assert disabled_model.guidance_transforms[:-1] == guided_model.guidance_transforms
    assert disabled_model.guidance_transforms[-1][0] == "dinkster.disable_cfg1_optimization"
    with pytest.raises(ValueError, match="scaling_factor must be in"):
        arm.GenerationEpsilonScaling.execute(model=handle, scaling_factor=float("nan"))
    with pytest.raises(ValueError, match="scaling_factor must be in"):
        arm.GenerationEpsilonScaling.execute(model=handle, scaling_factor=2.0)
    rescaled_model = arm.GenerationRescaleCfg.execute(model=handle, multiplier=0.7)["model"]
    assert rescaled_model.guidance_transforms == (("dinkster.rescale_cfg:0", contribution),)
    assert factory_calls[-1] == (("rescale_cfg", 0.7), {"flow": True})
    with pytest.raises(ValueError, match="multiplier must be in"):
        arm.GenerationRescaleCfg.execute(model=handle, multiplier=1.5)
    renormed_model = arm.GenerationRenormCfg.execute(model=handle, cfg_trunc=7.0, renorm_cfg=1.0)[
        "model"
    ]
    assert renormed_model.guidance_transforms == (("dinkster.renorm_cfg:0", contribution),)
    assert factory_calls[-1] == (("renorm_cfg", 7.0, 1.0), {})
    with pytest.raises(ValueError, match="cfg_trunc must be in"):
        arm.GenerationRenormCfg.execute(model=handle, cfg_trunc=-1.0, renorm_cfg=1.0)
    with pytest.raises(ValueError, match="renorm_cfg must be in"):
        arm.GenerationRenormCfg.execute(model=handle, cfg_trunc=7.0, renorm_cfg=101.0)
    tsr_model = arm.GenerationTemporalScoreRescaling.execute(
        model=handle, tsr_k=0.95, tsr_sigma=1.0
    )["model"]
    assert tsr_model.guidance_transforms == (("dinkster.temporal_score_rescaling:0", contribution),)
    assert factory_calls[-1] == (("temporal_score_rescaling", 0.95, 1.0), {"flow": True})
    with pytest.raises(ValueError, match="tsr_k must be in"):
        arm.GenerationTemporalScoreRescaling.execute(model=handle, tsr_k=0.0, tsr_sigma=1.0)
    with pytest.raises(ValueError, match="tsr_sigma must be in"):
        arm.GenerationTemporalScoreRescaling.execute(model=handle, tsr_k=0.95, tsr_sigma=0.0)
    nag_model = arm.GenerationNormalizedAttentionGuidance.execute(
        model=handle, nag_scale=5.0, nag_alpha=0.5, nag_tau=1.5
    )["model"]
    assert nag_model.guidance_transforms == (("dinkster.nag:0", contribution),)
    assert factory_calls[-1] == (("nag", 5.0, 0.5, 1.5), {})
    with pytest.raises(ValueError, match="nag_scale must be in"):
        arm.GenerationNormalizedAttentionGuidance.execute(
            model=handle, nag_scale=51.0, nag_alpha=0.5, nag_tau=1.5
        )
    with pytest.raises(ValueError, match="nag_alpha must be in"):
        arm.GenerationNormalizedAttentionGuidance.execute(
            model=handle, nag_scale=5.0, nag_alpha=1.5, nag_tau=1.5
        )
    with pytest.raises(ValueError, match="nag_tau must be in"):
        arm.GenerationNormalizedAttentionGuidance.execute(
            model=handle, nag_scale=5.0, nag_alpha=0.5, nag_tau=0.5
        )
    first = arm.GenerationSamplerCustom.execute(
        model=guided_model,
        add_noise=True,
        noise_seed=17,
        cfg=6.5,
        positive=positive,
        negative=negative,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    guider = arm.GenerationCFGGuider.execute(
        model=disabled_model,
        positive=positive,
        negative=negative,
        cfg=1.0,
    )["guider"]
    noise = arm.GenerationRandomNoise.execute(noise_seed=17)["noise"]
    second = arm.GenerationSamplerCustomAdvanced.execute(
        noise=noise,
        guider=guider,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    basic_guider = arm.GenerationBasicGuider.execute(
        model=handle,
        conditioning=positive,
    )["guider"]
    third = arm.GenerationSamplerCustomAdvanced.execute(
        noise=noise,
        guider=basic_guider,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    carrier = ConditioningCarrier(ConditioningSet(()), ())
    with monkeypatch.context() as context:
        context.setattr(arm, "_custom_sampling_conditioning", real_custom_sampling_conditioning)
        carrier_output = arm.GenerationSamplerCustom.execute(
            model=handle,
            add_noise=True,
            noise_seed=17,
            cfg=6.5,
            positive=carrier,
            negative=carrier,
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )

    assert len(calls) == 4
    for call in calls[:2]:
        assert cast("FakeTensor", call["latent"]).shape == (1, 16, 8, 8)
        assert call["noise"] is generated_noise
        assert call["cond"] is prepared["positive"]
        guidance = call["cfg"]
        assert isinstance(guidance, SamplingGuidance)
        assert guidance.uncond is prepared["negative"]
        request = call["request"]
        assert isinstance(request, CustomSamplingRequest)
        assert request.sampler.id == "dinkster.euler"
        assert request.sigmas == (1.0, 0.5, 0.0)
    first_guidance = cast("SamplingGuidance", calls[0]["cfg"])
    assert first_guidance.scale == 6.5
    assert first_guidance.transforms == (("dinkster.epsilon_scaling:0", contribution),)
    assert not first_guidance.disable_cfg1_optimization
    advanced_guidance = cast("SamplingGuidance", calls[1]["cfg"])
    assert advanced_guidance.scale == 1.0
    assert advanced_guidance.transforms == (("dinkster.epsilon_scaling:0", contribution),)
    assert advanced_guidance.disable_cfg1_optimization
    assert calls[2]["cond"] is prepared["positive"]
    assert calls[2]["cfg"] == SamplingGuidance(None, 1.0)
    assert isinstance(calls[3]["cond"], Conditioning)
    assert materialized_carriers == [carrier, carrier]
    for output in (first, second, third, carrier_output):
        assert output["output"] == {
            "samples": sampled,
            "custom": "preserved",
            "batch_index": [0],
        }
        assert output["denoised_output"] == {
            "samples": denoised,
            "custom": "preserved",
            "batch_index": [0],
            "downscale_ratio_spacial": 8,
            "downscale_ratio_temporal": 1,
        }
    assert sampled.device == denoised.device == FakeDevice("cpu")
    guided_basic = arm.GenerationBasicGuider.execute(
        model=guided_model,
        conditioning=positive,
    )["guider"]
    arm.GenerationSamplerCustomAdvanced.execute(
        noise=noise,
        guider=guided_basic,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    bare_guidance = cast("SamplingGuidance", calls[-1]["cfg"])
    assert bare_guidance.uncond is None
    assert bare_guidance.transforms == (("dinkster.epsilon_scaling:0", contribution),)
    use_inpaint = True
    inpaint_output = arm.GenerationSamplerCustom.execute(
        model=handle,
        add_noise=True,
        noise_seed=17,
        cfg=6.5,
        positive=positive,
        negative=negative,
        sampler=sampler,
        sigmas=sigmas,
        latent_image={**latent_value, "noise_mask": mask},
    )
    assert calls[-1]["denoise_mask"] is mask
    assert calls[-1]["inpaint"] is inpaint
    assert inpaint_output["output"]["noise_mask"] is mask
    use_inpaint = False
    Runtime.denoised_result = None
    disabled_noise = arm.GenerationDisableNoise.execute()["noise"]
    fallback = arm.GenerationSamplerCustomAdvanced.execute(
        noise=disabled_noise,
        guider=guider,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    assert fallback["denoised_output"] == fallback["output"]
    assert cast("FakeTensor", calls[-1]["noise"]).name == "zeros"
    assert cast("FakeTensor", calls[-1]["noise"]).shape == (1, 16, 8, 8)
    assert cast("FakeTensor", calls[-1]["noise"]).device == FakeDevice("cpu")
    assert torch.inference_entries == 7
    with pytest.raises(ValueError, match="latent channels must match"):
        arm.GenerationSamplerCustom.execute(
            model=handle,
            add_noise=True,
            noise_seed=17,
            cfg=6.5,
            positive=positive,
            negative=negative,
            sampler=sampler,
            sigmas=sigmas,
            latent_image={"samples": FakeTensor((1, 4, 8, 8), "nonzero")},
        )
    with pytest.raises(ValueError, match="extension snapshot changed"):
        arm.GenerationSamplerCustom.execute(
            model=handle,
            add_noise=True,
            noise_seed=17,
            cfg=6.5,
            positive=positive,
            negative=negative,
            sampler=replace(sampler, extension_snapshot_digest="changed"),
            sigmas=sigmas,
            latent_image=latent_value,
        )
    overlay = arm._NativeModelOverlay(handle, (object(),), {})
    with pytest.raises(ValueError, match="model overlay"):
        arm.GenerationBasicScheduler.execute(
            model=overlay,
            scheduler="normal",
            steps=2,
            denoise=0.75,
        )
    with pytest.raises(ValueError, match="model overlays"):
        arm.GenerationSamplerCustom.execute(
            model=overlay,
            add_noise=True,
            noise_seed=17,
            cfg=6.5,
            positive=positive,
            negative=negative,
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )
    control = arm._ClassicControlBinding(object(), (), False)
    controlled = [
        [
            FakeTensor((1, 2, 8), "controlled"),
            {"control": control, "control_apply_to_uncond": False},
        ]
    ]
    with pytest.raises(TypeError, match="application metadata is malformed"):
        arm.GenerationSamplerCustom.execute(
            model=handle,
            add_noise=True,
            noise_seed=17,
            cfg=6.5,
            positive=controlled,
            negative=controlled,
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )

    class RefusingRuntime(Runtime):
        @staticmethod
        def check_custom_sampling(
            request: object,
            *,
            has_denoise_mask: bool,
            has_inpaint: bool,
            has_context_windows: bool,
            guidance: float | None = None,
        ) -> None:
            del request, has_denoise_mask, has_inpaint, guidance
            raise ValueError("custom sampling preflight refused")

    refusing_handle = _handle(arm, RefusingRuntime(), torch, recipe=runtime_recipe)
    with monkeypatch.context() as context:
        context.setattr(arm, "_torch", lambda: pytest.fail("torch used before preflight"))
        with pytest.raises(ValueError, match="preflight refused"):
            arm.GenerationSamplerCustom.execute(
                model=refusing_handle,
                add_noise=True,
                noise_seed=17,
                cfg=6.5,
                positive=positive,
                negative=negative,
                sampler=sampler,
                sigmas=sigmas,
                latent_image=latent_value,
            )

    class InpaintRefusingRuntime(Runtime):
        @staticmethod
        def check_custom_sampling(
            request: object,
            *,
            has_denoise_mask: bool,
            has_inpaint: bool,
            has_context_windows: bool,
            guidance: float | None = None,
        ) -> None:
            del request, has_denoise_mask, guidance
            if has_inpaint:
                raise ValueError("custom sampling inpaint preflight refused")

    inpaint_refusing_handle = _handle(
        arm,
        InpaintRefusingRuntime(),
        torch,
        recipe=runtime_recipe,
    )
    raw_inpaint = [
        [
            FakeTensor((1, 2, 8), "inpaint-positive"),
            {"concat_mask": object(), "concat_latent_image": object()},
        ]
    ]
    with monkeypatch.context() as context:
        context.setattr(arm, "_torch", lambda: pytest.fail("torch used before inpaint preflight"))
        with pytest.raises(ValueError, match="inpaint preflight refused"):
            arm.GenerationSamplerCustom.execute(
                model=inpaint_refusing_handle,
                add_noise=True,
                noise_seed=17,
                cfg=6.5,
                positive=raw_inpaint,
                negative=negative,
                sampler=sampler,
                sigmas=sigmas,
                latent_image=latent_value,
            )
    with pytest.raises(ValueError, match="cfg must be in"):
        arm.GenerationPerpNegGuider.execute(
            model=handle,
            positive=positive,
            negative=negative,
            empty_conditioning=empty,
            cfg=101.0,
            neg_scale=1.0,
        )
    with pytest.raises(ValueError, match="neg_scale must be in"):
        arm.GenerationPerpNegGuider.execute(
            model=handle,
            positive=positive,
            negative=negative,
            empty_conditioning=empty,
            cfg=8.0,
            neg_scale=-0.5,
        )
    perp_guider = arm.GenerationPerpNegGuider.execute(
        model=guided_model,
        positive=positive,
        negative=negative,
        empty_conditioning=empty,
        cfg=6.5,
        neg_scale=0.75,
    )["guider"]
    perp_output = arm.GenerationSamplerCustomAdvanced.execute(
        noise=noise,
        guider=perp_guider,
        sampler=sampler,
        sigmas=sigmas,
        latent_image=latent_value,
    )
    assert perp_output["output"] == {
        "samples": sampled,
        "custom": "preserved",
        "batch_index": [0],
    }
    perp_guidance = calls[-1]["cfg"]
    assert isinstance(perp_guidance, PerpNegSamplingGuidance)
    assert perp_guidance.uncond is prepared["negative"]
    assert perp_guidance.empty is prepared["empty_conditioning"]
    assert perp_guidance.scale == 6.5
    assert perp_guidance.neg_scale == 0.75
    assert perp_guidance.transforms == (("dinkster.epsilon_scaling:0", contribution),)
    assert calls[-1]["cond"] is prepared["positive"]
    with pytest.raises(ValueError, match="requires negative conditioning"):
        arm.GenerationSamplerCustomAdvanced.execute(
            noise=noise,
            guider=arm._PerpNegGuiderValue(handle, positive, None, empty, 6.5, 1.0),
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )
    with pytest.raises(ValueError, match="does not accept FluxGuidance"):
        arm.GenerationSamplerCustomAdvanced.execute(
            noise=noise,
            guider=arm._PerpNegGuiderValue(
                handle, positive, negative, arm._GuidedRows(empty, 3.5), 6.5, 1.0
            ),
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )
    with pytest.raises(TypeError, match="same conditioning representation"):
        arm.GenerationSamplerCustomAdvanced.execute(
            noise=noise,
            guider=arm._PerpNegGuiderValue(handle, positive, negative, carrier, 6.5, 1.0),
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )
    with pytest.raises(ValueError, match="cannot be attached only to empty"):
        arm.GenerationSamplerCustomAdvanced.execute(
            noise=noise,
            guider=arm._PerpNegGuiderValue(handle, positive, negative, controlled, 6.5, 1.0),
            sampler=sampler,
            sigmas=sigmas,
            latent_image=latent_value,
        )

    patched_calls: list[object] = []

    def derive(space: object) -> Runtime:
        derived = Runtime()
        cast(Any, derived).assembled = cast(Any, runtime).assembled

        def patched_sample(latent: object, **kwargs: object) -> object:
            patched_calls.append(space)
            return Runtime.sample_custom(latent, **kwargs)

        cast(Any, derived).sample_custom = patched_sample
        return derived

    cast(Any, runtime).with_sampling_space = derive
    patched = arm.GenerationModelSamplingFlux.execute(model=handle, width=768)["model"]
    patched_sigmas = arm.GenerationBasicScheduler.execute(
        model=patched,
        scheduler="normal",
        steps=2,
        denoise=0.75,
    )["sigmas"]
    arm.GenerationSamplerCustom.execute(
        model=patched,
        add_noise=True,
        noise_seed=17,
        cfg=6.5,
        positive=positive,
        negative=negative,
        sampler=sampler,
        sigmas=patched_sigmas,
        latent_image=latent_value,
    )
    patched_guider = arm.GenerationCFGGuider.execute(
        model=patched,
        positive=positive,
        negative=negative,
        cfg=6.5,
    )["guider"]
    arm.GenerationSamplerCustomAdvanced.execute(
        noise=noise,
        guider=patched_guider,
        sampler=sampler,
        sigmas=patched_sigmas,
        latent_image=latent_value,
    )
    assert patched_calls == [patched.sampling_space, patched.sampling_space]


def test_impact_regional_pass_uses_the_custom_sampling_engine(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    sampler = arm._CustomSamplerValue(object())
    provider = arm._ImpactRegionalProvider(
        "model",
        "positive",
        "negative",
        6.5,
        sampler,
        (3.0, 2.0, 1.0),
    )
    calls: list[dict[str, object]] = []

    def execute(**kwargs: object) -> tuple[dict[str, object], dict[str, object]]:
        calls.append(kwargs)
        return ({"samples": "sampled", "noise_mask": "mask"}, {"samples": "denoised"})

    monkeypatch.setattr(arm, "_execute_generation_custom_sampling", execute)
    output = arm._run_impact_regional_pass(
        provider,
        {"samples": "latent", "metadata": "preserved"},
        (2.0, 1.0),
        seed=17,
        add_noise=True,
        mask="mask",
    )

    assert output == {"samples": "sampled"}
