def test_native_sampler_uses_family_runtime_call_contract_for_prepared_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import Conditioning

    arm = _native_arm()
    torch = FakeTorch()
    runtime = _runtime()
    runtime.conditioning_identity = "dinkster.qwen-image.conditioning:test"
    runtime.prepare_single_stream_conditioning = lambda _carrier: Conditioning(
        FakeTensor((1, 2, 8), "unused")
    )
    runtime.encode_text = lambda _text: Conditioning(FakeTensor((1, 2, 8), "text"))
    runtime.decode_latent = lambda value: value
    runtime.encode_content = lambda value: value
    sampled = FakeTensor((1, 16, 1, 2, 2), "sampled")
