def test_native_sampler_uses_seedvr2_component_runtime_call_contract(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import WeightSourceBinding

    arm = _native_arm()
    torch = FakeTorch()
    base_recipe = _recipe()
    recipe = replace(
        base_recipe,
        sources=(WeightSourceBinding("diffusion", base_recipe.sources[0].source),),
        family_id="dinkster.seedvr2",
        component_identity=("family=dinkster.seedvr2", "role=diffusion"),
    )
    sampled = FakeTensor((1, 16, 1, 2, 2), "sampled", device="cuda:0")
    sample_kwargs: dict[str, object] = {}

    class Runtime:
        family = SimpleNamespace(id="dinkster.seedvr2")
        runtime_identity: str
        assembled = SimpleNamespace(
            diffusion=FakeModule(),
            compute_dtype=lambda _role: "bfloat16",
        )

        def sample(self, latent: FakeTensor, **kwargs: object) -> FakeTensor:
            assert latent.name == "latent"
            sample_kwargs.update(kwargs)
            return sampled

    runtime = Runtime()
    runtime.runtime_identity = recipe.runtime_identity
    handle = _handle(arm, runtime, torch, recipe=recipe)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    resolutions: list[tuple[object, ...]] = []
    real_resolve = arm._resolve_sampling_model

    def resolve(*args: Any, **kwargs: Any) -> Any:
        result = real_resolve(*args, **kwargs)
        resolutions.append(result)
        return result

    def prepare(*_args: object) -> object:
        raise AssertionError("callback-prepared conditioning must not be prepared again")

    monkeypatch.setattr(arm, "_resolve_sampling_model", resolve)
    monkeypatch.setattr(arm, "_prepare_ksampler_conditioning", prepare)
    monkeypatch.setattr(
        arm,
        "resolve_seedvr2_component_execution",
        lambda candidate, positive, negative, _inference, **_options: (
            (runtime, positive, negative) if candidate is handle else None
        ),
    )
    embeddings = FakeTensor((1, 16, 1, 2, 2), "embeddings")
    inputs = {
        "model": handle,
        "seed": 7,
        "steps": 2,
        "cfg": 1.0,
        "sampler_name": "euler",
        "scheduler": "simple",
        "positive": [[embeddings, {}]],
        "negative": [[embeddings, {}]],
        "latent_image": {"samples": FakeTensor((1, 16, 1, 2, 2), "latent")},
        "denoise": 1.0,
    }

    output = arm.NativeKSampler.execute(**inputs)

    assert cast("Mapping[str, object]", output["latent"])["samples"] is sampled
    assert sampled.device == FakeDevice("cuda:0")
    assert sample_kwargs["device"] == FakeDevice("cuda:0")
    assert sample_kwargs["compute_dtype"] == "bfloat16"
    assert resolutions == [(runtime, inputs["positive"], inputs["negative"], True, True)]


