def test_generation_clip_options_chain_without_mutating_sources() -> None:
    arm = _native_arm()
    source = object()

    layered = arm.GenerationClipSetLastLayer.execute(
        clip=source,
        stop_at_clip_layer=-3,
    )["clip"]
    configured = arm.GenerationT5TokenizerOptions.execute(
        clip=layered,
        min_padding=5,
        min_length=32,
    )["clip"]
    relayered = arm.GenerationClipSetLastLayer.execute(
        clip=configured,
        stop_at_clip_layer=-2,
    )["clip"]

    assert layered.source is source
    assert (layered.hidden_layer, layered.t5_min_padding, layered.t5_min_length) == (-3, None, None)
    assert (configured.hidden_layer, configured.t5_min_padding, configured.t5_min_length) == (
        -3,
        5,
        32,
    )
    assert (relayered.hidden_layer, relayered.t5_min_padding, relayered.t5_min_length) == (
        -2,
        5,
        32,
    )
    assert relayered._dinkster_resident_refs == (source,)
    with pytest.raises(ValueError, match=r"\[-24, -1\]"):
        arm.GenerationClipSetLastLayer.execute(clip=source, stop_at_clip_layer=0)
    with pytest.raises(ValueError, match=r"\[0, 10000\]"):
        arm.GenerationT5TokenizerOptions.execute(clip=source, min_padding=-1, min_length=0)


