def test_generation_clip_text_encode_controlnet_stamps_control_payloads(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ConditioningChannel,
        ConditioningRecord,
        ConditioningSet,
        ExtensionInputValue,
        PayloadBinding,
        PayloadDescriptor,
        PayloadReference,
        make_conditioning_carrier,
    )

    arm = _native_arm()

    def carrier(
        text_id: str,
        pooled_id: str | None = None,
        *,
        metadata: tuple[tuple[str, ExtensionInputValue], ...] = (),
    ) -> Any:
        text_binding = PayloadBinding(text_id, (1, 2, 8), "F32", "conditioning-text", bytes(64))
        channels = [
            (
                ConditioningChannel.TEXT,
                PayloadDescriptor(
                    PayloadReference(text_id),
                    text_binding.shape,
                    text_binding.dtype,
                    text_binding.space,
                ),
            )
        ]
        bindings = [text_binding]
        if pooled_id is not None:
            pooled_binding = PayloadBinding(
                pooled_id, (1, 8), "F32", "conditioning-pooled", bytes(32)
            )
            bindings.append(pooled_binding)
            channels.append(
                (
                    ConditioningChannel.POOLED,
                    PayloadDescriptor(
                        PayloadReference(pooled_id),
                        pooled_binding.shape,
                        pooled_binding.dtype,
                        pooled_binding.space,
                    ),
                )
            )
        return make_conditioning_carrier(
            ConditioningSet(
                (
                    ConditioningRecord(
                        channels=tuple(channels),
                        extension_metadata=metadata,
                    ),
                )
            ),
            tuple(bindings),
        )

    target = carrier("target", metadata=(("dinkster.test/preserved", 1),))
    first_control = carrier("control-1", "pooled-1")
    second_control = carrier("control-2")
    controls = iter((first_control, second_control))
    target_id = target.conditioning.records[0].channels[0][1].reference.id
    first_channels = dict(first_control.conditioning.records[0].channels)
    first_text_id = first_channels[ConditioningChannel.TEXT].reference.id
    first_pooled_id = first_channels[ConditioningChannel.POOLED].reference.id
    second_text_id = second_control.conditioning.records[0].channels[0][1].reference.id

    def encode(_cls: type[Any], **_inputs: object) -> Mapping[str, object]:
        return {"conditioning": next(controls)}

    monkeypatch.setattr(arm.GenerationClipTextEncode, "execute", classmethod(encode))

    first = cast(
        "Any",
        arm.GenerationClipTextEncodeControlnet.execute(
            clip=object(), conditioning=target, text="first"
        )["conditioning"],
    )
    first_record = first.conditioning.records[0]
    first_metadata = dict(first_record.extension_metadata)
    assert dict(first_record.channels) == dict(target.conditioning.records[0].channels)
    assert first_metadata == {
        "dinkster.test/preserved": 1,
        "dinkster-compat-comfy/cross-attn-controlnet": PayloadReference(first_text_id),
        "dinkster-compat-comfy/pooled-output-controlnet": PayloadReference(first_pooled_id),
    }
    assert {binding.reference_id for binding in first.bindings} == {
        target_id,
        first_text_id,
        first_pooled_id,
    }

    second = cast(
        "Any",
        arm.GenerationClipTextEncodeControlnet.execute(
            clip=object(), conditioning=first, text="second"
        )["conditioning"],
    )
    second_metadata = dict(second.conditioning.records[0].extension_metadata)
    assert second_metadata["dinkster-compat-comfy/cross-attn-controlnet"] == PayloadReference(
        second_text_id
    )
    assert second_metadata["dinkster-compat-comfy/pooled-output-controlnet"] is None
    assert {binding.reference_id for binding in second.bindings} == {target_id, second_text_id}


def test_generation_qwen_vae_uses_image_semantics_and_decodes_layers(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    events: list[object] = []

    class Handle:
        recipe = SimpleNamespace(family_id="dinkster.qwen_image")

    class Codec:
        descriptor = SimpleNamespace(kind="video", content_channels=3)
        load_device = FakeDevice("cuda:0")

        def __init__(self, _value: object) -> None:
            pass

        @contextmanager
        def stage(self):
            events.append("stage")
            yield

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            events.append(("encode", content.shape))
            return FakeTensor((content.shape[0], 16, 1, 2, 2), "encoded")

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            events.append(("decode", latent.shape))
            if latent.shape[2] == 1:
                return FakeTensor((latent.shape[0], 3, 16, 16), "decoded")
            return FakeTensor((latent.shape[0], 3, latent.shape[2], 16, 16), "layers")

    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_native_component_codec", lambda value: Codec(value))
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    handle = Handle()

    encoded = arm.GenerationVAEEncode.execute(
        pixels=FakeTensor((2, 16, 16, 3), "pixels"),
        vae=handle,
    )
    decoded = arm.GenerationVAEDecode.execute(
        samples={"samples": FakeTensor((2, 16, 1, 2, 2), "latent")},
        vae=handle,
    )
    layered = arm.GenerationVAEDecode.execute(
        samples={"samples": FakeTensor((2, 16, 4, 2, 2), "layered-latent")},
        vae=handle,
    )

    assert cast("Mapping[str, FakeTensor]", encoded["latent"])["samples"].shape == (
        2,
        16,
        1,
        2,
        2,
    )
    assert cast("FakeTensor", decoded["image"]).shape == (2, 16, 16, 3)
    assert cast("FakeTensor", layered["image"]).shape == (8, 16, 16, 3)
    assert events == [
        "stage",
        ("encode", (2, 3, 16, 16)),
        "stage",
        ("decode", (2, 16, 1, 2, 2)),
        "stage",
        ("decode", (2, 16, 4, 2, 2)),
    ]


def test_chroma_radiance_pixel_codec_runs_the_load_encode_decode_path(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    torch = FakeTorch()
    events: list[tuple[str, tuple[int, ...]]] = []

    class Codec:
        def __init__(self, *, compute_dtype: object) -> None:
            assert compute_dtype == "bfloat16"

        def encode(self, content: FakeTensor) -> FakeTensor:
            events.append(("encode", content.shape))
            return FakeTensor(content.shape, "encoded", device=content.device)

        def decode(self, latent: FakeTensor) -> FakeTensor:
            events.append(("decode", latent.shape))
            return FakeTensor(latent.shape, "decoded", device=latent.device)

    real_import = importlib.import_module
    fake_inference_torch = SimpleNamespace(PixelSpaceCodec=Codec)
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    identity = "native:dinkster.chroma_radiance:" + "a" * 64
    with use_execution_context(
        ExecutionContext(
            "native",
            identity,
            diffusion_dtype="unloaded",
            text_dtype="unloaded",
            vae_dtype="bfloat16",
        )
    ):
        vae = arm.NativeLoadVae.execute(pixel_space=True)["vae"]

    pixels = FakeTensor((2, 16, 24, 3), "pixels")
    encoded = arm.GenerationVAEEncode.execute(pixels=pixels, vae=vae)["latent"]
    latent = cast("Mapping[str, FakeTensor]", encoded)["samples"]
    decoded = arm.GenerationVAEDecode.execute(samples=encoded, vae=vae)["image"]

    assert vae.descriptor.latent == inference.CHROMA_RADIANCE.single_stream_latent()
    assert vae.descriptor.id == "dinkster.chroma_radiance_pixel_space"
    assert vae.resource_identity == identity
    assert latent.shape == (2, 3, 16, 24)
    assert cast("FakeTensor", decoded).shape == pixels.shape
    assert events == [("encode", (2, 3, 16, 24)), ("decode", (2, 3, 16, 24))]


