def test_generation_vae_decode_unwraps_only_one_video_stream(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import MultiStreamLatent

    arm = _native_arm()
    decoded: list[FakeTensor] = []

    class Handle:
        recipe = SimpleNamespace(family_id="dinkster.qwen_image")

    class Codec:
        descriptor = SimpleNamespace(kind="video", content_channels=3)
        load_device = FakeDevice("cuda:0")

        def __init__(self, _value: object) -> None:
            pass

        @contextmanager
        def stage(self):
            yield

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            decoded.append(latent)
            return FakeTensor((1, 3, 1, 16, 16), "decoded")

    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_native_component_codec", lambda value: Codec(value))
