def test_flux2_component_execution_composes_diffusion_and_text_identities(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        FLUX2_DEV,
        ComponentBinding,
        ConditioningCarrier,
        bind_component_conditioning,
        compose_execution,
    )

    arm = _native_arm()
    diffusion_identity = "native:dinkster.flux2_dev:" + "1" * 64
    text_identity = "native:dinkster.flux2_dev:" + "2" * 64
    constructed: list[str] = []

    class Runtime:
        conditioning_identity = "flux2-conditioning"

        def __init__(
            self,
            diffusion: object = "diffusion",
            family: object = FLUX2_DEV,
            *,
            runtime_identity: str = diffusion_identity,
        ) -> None:
            self.assembled = SimpleNamespace(diffusion=diffusion)
            self.family = family
            self.runtime_identity = runtime_identity
            constructed.append(runtime_identity)

        def prepare_flux2_conditioning(self, _carrier: ConditioningCarrier) -> object:
            return Conditioning(FakeTensor((1, 2, 8), "prepared"))

    fake_torch_inference = SimpleNamespace(Flux2DiffusionRuntime=Runtime)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    base = Runtime()
    handle = SimpleNamespace(
        runtime=base,
        recipe=SimpleNamespace(
            family_id=FLUX2_DEV.id,
            runtime_identity=diffusion_identity,
            sources=(SimpleNamespace(role="diffusion"),),
        ),
    )
    positive = bind_component_conditioning(
        _component_conditioning_carrier(),
        ComponentBinding("mistral3_24b", FLUX2_DEV.id, text_identity),
    )

    execution = arm.resolve_component_execution(
        cast("Any", handle), positive, [], real_import("dinkster_inference")
    )

    assert execution is not None
    runtime, rows, negative = execution
    expected = compose_execution(
        FLUX2_DEV.id,
        {"diffusion": diffusion_identity, "mistral3_24b": text_identity},
    )
    assert runtime.runtime_identity == expected.execution_identity
    assert cast("FakeTensor", cast("Any", rows)[0][0]).name == "prepared"
    assert negative == []
    assert constructed == [diffusion_identity, expected.execution_identity]


def test_flux2_component_execution_refuses_wrong_binding_and_lane_identity(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        FLUX2_DEV,
        ComponentBinding,
        bind_component_conditioning,
    )

    arm = _native_arm()
    diffusion_identity = "native:dinkster.flux2_dev:" + "1" * 64

    class Runtime:
        def __init__(self) -> None:
            self.assembled = SimpleNamespace(diffusion=object())
            self.family = FLUX2_DEV
            self.runtime_identity = diffusion_identity

    fake_torch_inference = SimpleNamespace(
        Flux2DiffusionRuntime=Runtime,
        QwenImageDiffusionRuntime=type("OtherRuntime", (), {}),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    handle = SimpleNamespace(
        runtime=Runtime(),
        recipe=SimpleNamespace(
            family_id=FLUX2_DEV.id,
            runtime_identity=diffusion_identity,
            sources=(SimpleNamespace(role="diffusion"),),
        ),
    )
    carrier = _component_conditioning_carrier()

    def bound(role: str, digit: str, family: str = FLUX2_DEV.id) -> object:
        return bind_component_conditioning(
            carrier,
            ComponentBinding(role, family, f"native:{family}:" + digit * 64),
        )

    inference = real_import("dinkster_inference")
    with pytest.raises(ValueError, match="wrong component family"):
        arm.resolve_component_execution(
            cast("Any", handle), bound("qwen3_8b", "2", "dinkster.flux2_klein_9b"), [], inference
        )
    with pytest.raises(ValueError, match="wrong component role"):
        arm.resolve_component_execution(cast("Any", handle), bound("qwen3_4b", "2"), [], inference)
    with pytest.raises(ValueError, match="lanes must share"):
        arm.resolve_component_execution(
            cast("Any", handle),
            bound("mistral3_24b", "2"),
            bound("mistral3_24b", "3"),
            inference,
        )
    with pytest.raises(TypeError, match="positive must be Flux2 Dev component-bound"):
        arm.resolve_component_execution(cast("Any", handle), carrier, [], inference)
    foreign = SimpleNamespace(
        runtime=Runtime(),
        recipe=SimpleNamespace(
            family_id="dinkster.qwen_image",
            runtime_identity=diffusion_identity,
            sources=(SimpleNamespace(role="diffusion"),),
        ),
    )
    with pytest.raises(TypeError, match="native Qwen Image diffusion component"):
        arm.resolve_component_execution(
            cast("Any", foreign), bound("mistral3_24b", "2"), [], inference
        )
    bundled = SimpleNamespace(
        runtime=object(),
        recipe=SimpleNamespace(
            family_id=FLUX2_DEV.id,
            runtime_identity=diffusion_identity,
            sources=(SimpleNamespace(role="checkpoint"),),
        ),
    )
    bundled_positive = bound("mistral3_24b", "2")
    assert arm.resolve_component_execution(
        cast("Any", bundled), bundled_positive, [], inference
    ) == (
        bundled.runtime,
        bundled_positive,
        [],
    )
    assert arm._resolve_sampling_model(cast("Any", bundled), bundled_positive, [], inference) == (
        bundled.runtime,
        bundled_positive,
        [],
        True,
        False,
    )


