@pytest.mark.parametrize("sampling_consumer", [False, True])
def test_component_execution_propagates_callback_exceptions(
    monkeypatch: pytest.MonkeyPatch,
    sampling_consumer: bool,
) -> None:
    arm = _native_arm()
    handle = SimpleNamespace(
        runtime=object(),
        recipe=SimpleNamespace(family_id="dinkster.seedvr2"),
    )
    failure = RuntimeError("callback reconstruction failed")

    def fail(*_args: object, **_kwargs: object) -> None:
        raise failure

    monkeypatch.setattr(arm, "resolve_seedvr2_component_execution", fail)
    inference = importlib.import_module("dinkster_inference")
