def test_generation_empty_latent_image_runs_standalone_without_comfy(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Latent creation must not require a ComfyUI install (issue #846)."""
    import importlib.util

    arm = _native_arm()
    monkeypatch.setitem(sys.modules, "torch", cast("Any", FakeTorch))
    # Nothing may satisfy the comfy import: drop any leaked stub so the
    # import reaches the real finders, then prove no install exists.
    monkeypatch.delitem(sys.modules, "comfy", raising=False)
    monkeypatch.delitem(sys.modules, "comfy.model_management", raising=False)
    assert importlib.util.find_spec("comfy") is None

    output = arm.GenerationEmptyLatentImage.execute(width=1024, height=1024, batch_size=1)

    latent = cast("Mapping[str, Any]", output["latent"])
    samples = cast("FakeTensor", latent["samples"])
    assert samples.shape == [1, 4, 128, 128]
    assert samples.name == "zeros"
    assert samples.device == FakeDevice("cpu")
    assert samples.dtype == "float32"
    assert latent["downscale_ratio_spacial"] == 8


def test_generation_empty_latent_image_ignores_broken_comfy_install(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """Native device selection must not inspect an installed ComfyUI."""
    (tmp_path / "comfy").mkdir()
    (tmp_path / "comfy" / "__init__.py").write_text("")
    (tmp_path / "comfy" / "model_management.py").write_text(
        "import missing_transitive_dependency_846\n"
    )

    arm = _native_arm()
    monkeypatch.setitem(sys.modules, "torch", cast("Any", FakeTorch))
    monkeypatch.delitem(sys.modules, "comfy", raising=False)
    monkeypatch.delitem(sys.modules, "comfy.model_management", raising=False)
    monkeypatch.syspath_prepend(str(tmp_path))

    output = arm.GenerationEmptyLatentImage.execute(width=1024, height=1024, batch_size=1)

    latent = cast("Mapping[str, Any]", output["latent"])
    samples = cast("FakeTensor", latent["samples"])
    assert samples.device == FakeDevice("cpu")
    assert samples.dtype == "float32"
    assert "comfy" not in sys.modules
    assert "comfy.model_management" not in sys.modules


def test_generation_flux_guidance_stamps_dinkster_conditioning_and_last_wins() -> None:
    from dinkster_inference import (
        FLUX2_DEV,
        ComponentBinding,
        ConditioningCarrier,
        ConditioningSet,
        bind_component_conditioning,
        split_component_conditioning,
    )

    arm = _native_arm()
    carrier = _component_conditioning_carrier()
    bound = bind_component_conditioning(
        carrier,
        ComponentBinding("mistral3_24b", FLUX2_DEV.id, "native:dinkster.flux2_dev:" + "2" * 64),
    )

    wrapped = cast(
        "Any", arm.GenerationFluxGuidance.execute(conditioning=carrier, guidance=4)["conditioning"]
    )
    assert type(wrapped) is ConditioningCarrier
    inner, guidance = arm._split_flux_guidance(wrapped)
    assert guidance == 4.0
    assert cast("Any", inner).conditioning == carrier.conditioning
    rewrapped = cast(
        "Any",
        arm.GenerationFluxGuidance.execute(conditioning=wrapped, guidance=2.5)["conditioning"],
    )
    inner, guidance = arm._split_flux_guidance(rewrapped)
    assert guidance == 2.5
    assert cast("Any", inner).conditioning == carrier.conditioning
    bound_wrapped = cast(
        "Any", arm.GenerationFluxGuidance.execute(conditioning=bound, guidance=3.5)["conditioning"]
    )
    inner, guidance = arm._split_flux_guidance(bound_wrapped)
    assert guidance == 3.5
    assert split_component_conditioning(cast("Any", inner))[1] is not None
    with pytest.raises(ValueError, match=r"guidance must be in"):
        arm.GenerationFluxGuidance.execute(conditioning=carrier, guidance=100.5)
    with pytest.raises(TypeError, match="text-encoding node"):
        arm.GenerationFluxGuidance.execute(conditioning=[[object(), {}]], guidance=3.5)
    with pytest.raises(ValueError, match="empty conditioning"):
        arm.GenerationFluxGuidance.execute(
            conditioning=ConditioningCarrier(ConditioningSet(()), ()), guidance=3.5
        )
    assert arm._effective_flux_guidance(None, None) is None
    assert arm._effective_flux_guidance(3.5, None) == 3.5
    assert arm._effective_flux_guidance(None, 4.0) == 4.0
    assert arm._effective_flux_guidance(3.5, 3.5) == 3.5
    with pytest.raises(ValueError, match="strengths must match"):
        arm._effective_flux_guidance(3.5, 4.0)


def test_generation_flux_disable_guidance_stamps_explicit_null_and_last_wins() -> None:
    arm = _native_arm()
    carrier = _component_conditioning_carrier()

    disabled = cast(
        "Any",
        arm.GenerationFluxDisableGuidance.execute(conditioning=carrier)["conditioning"],
    )
    inner, guidance = arm._split_flux_guidance(disabled)
    assert guidance == arm._FLUX_GUIDANCE_DISABLED
    assert cast("Any", inner).conditioning == carrier.conditioning
    restored = cast(
        "Any",
        arm.GenerationFluxGuidance.execute(conditioning=disabled, guidance=2.5)["conditioning"],
    )
    assert arm._split_flux_guidance(restored)[1] == 2.5
    redisabled = arm.GenerationFluxDisableGuidance.execute(conditioning=restored)["conditioning"]
    assert arm._split_flux_guidance(redisabled)[1] == arm._FLUX_GUIDANCE_DISABLED
    with pytest.raises(ValueError, match="strengths must match"):
        arm._effective_flux_guidance(arm._FLUX_GUIDANCE_DISABLED, 3.5)
    with pytest.raises(TypeError, match="text-encoding node"):
        arm.GenerationFluxDisableGuidance.execute(conditioning=[[object(), {}]])


def test_generation_reference_latent_is_optional_and_appends_ordered_payloads(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import PayloadBinding, PayloadReference

    arm = _native_arm()
    carrier = _component_conditioning_carrier()
    assert arm.GenerationReferenceLatent.execute(conditioning=carrier)["conditioning"] is carrier
    calls: list[tuple[str, FakeTensor, str]] = []

    def bind(reference_id: str, tensor: FakeTensor, *, space: str) -> PayloadBinding:
        calls.append((reference_id, tensor, space))
        value = len(calls)
        return PayloadBinding(
            reference_id,
            tuple(tensor.shape),
            "F32",
            space,
            bytes((value,)) * tensor.nbytes,
        )

    fake_torch = FakeTorch()
    fake_inference_torch = SimpleNamespace(tensor_to_payload_binding=bind)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(arm, "_torch", lambda: fake_torch)
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    first = FakeTensor((1, 128, 2, 3), "first")
    second = FakeTensor((1, 128, 3, 2), "second")

    once = cast(
        "Any",
        arm.GenerationReferenceLatent.execute(
            conditioning=carrier,
            latent={"samples": first},
        )["conditioning"],
    )
    twice = cast(
        "Any",
        arm.GenerationReferenceLatent.execute(
            conditioning=once,
            latent={"samples": second},
        )["conditioning"],
    )

    references = dict(twice.conditioning.records[0].extension_metadata)[
        arm._FLUX2_REFERENCE_LATENTS_KEY
    ]
    assert isinstance(references, tuple)
    assert all(type(item) is PayloadReference for item in references)
    assert len(references) == 2
    assert [call[1] for call in calls] == [first, second]
    assert [call[2] for call in calls] == ["flux2-reference-latent"] * 2
    assert len(twice.bindings) == len(carrier.bindings) + 2

    with pytest.raises(TypeError, match="mapping"):
        arm.GenerationReferenceLatent.execute(conditioning=carrier, latent=object())
    with pytest.raises(TypeError, match="exact torch.Tensor"):
        arm.GenerationReferenceLatent.execute(
            conditioning=carrier,
            latent={"samples": object()},
        )


