def test_generation_ltxav_reference_audio_encodes_and_attaches_prepared_rows(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch(cuda=True)
    stages: list[str] = []
    encode_calls: list[tuple[object, int]] = []

    class AudioVAE(_FakeLTXAudioVAE):
        def encode(self, waveform: object, sample_rate: int) -> FakeTensor:
            assert stages == ["enter"]
            encode_calls.append((waveform, sample_rate))
            return FakeTensor((2, 8, 3, 16), "audio-latent", device="cuda:0")

    class Codec(_FakeLTXAudioCodec):
        def __init__(self) -> None:
            super().__init__()
            self.audio_vae = AudioVAE()

    class Component:
        def __init__(self) -> None:
            self.component = Codec()
            self.load_device = FakeDevice("cuda:0")
            self.recipe = _ltx_component_recipe("audio_vae")
            self.resource_identity = self.recipe.runtime_identity

        def require_active(self) -> None:
            pass

        @contextmanager
        def stage(self) -> Iterator[None]:
            stages.append("enter")
            try:
                yield
            finally:
                stages.append("exit")

    fake_inference_torch = SimpleNamespace(
        LTXAVAudioCodec=Codec,
        LTXAVPreparedConditioning=_FakeLTXAVPrepared,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "NativeComponentHandle", Component)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    positive_text = object()
    negative_text = object()
    positive = [
        [PreparedMultiStreamConditioning("runtime:ltxav", _FakeLTXAVPrepared(positive_text)), {}]
    ]
    negative = [
        [PreparedMultiStreamConditioning("runtime:ltxav", _FakeLTXAVPrepared(negative_text)), {}]
    ]
    waveform = FakeTensor((2, 1, 16000), "waveform")

    result = arm.GenerationLTXAVReferenceAudio.execute(
        positive=positive,
        negative=negative,
        reference_audio={"waveform": waveform, "sample_rate": 16000},
        audio_vae=Component(),
    )

    assert stages == ["enter", "exit"]
    assert encode_calls == [(waveform, 16000)]
    assert waveform.moves == [FakeDevice("cuda:0")]
    for name, text in (("positive", positive_text), ("negative", negative_text)):
        carrier = cast("Any", result[name])[0][0]
        assert type(carrier) is PreparedMultiStreamConditioning
        assert carrier.runtime_identity == "runtime:ltxav"
        payload = cast("_FakeLTXAVPrepared", carrier.payload)
        assert payload.text is text
        assert cast("FakeTensor", payload.reference_audio).shape == (2, 3, 128)


