@pytest.mark.parametrize("advanced", [False, True])
def test_native_ksamplers_consume_flux_sampling_space(
    monkeypatch: pytest.MonkeyPatch, advanced: bool
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    sampled_spaces: list[object] = []

    class Runtime:
        family = SimpleNamespace(id="dinkster.flux_dev")
        space: object = None

        def encode_text(self, text: str) -> object:
            raise AssertionError("sampling must not encode text")

        def decode_latent(self, latent: object) -> object:
            raise AssertionError("sampling must not decode latents")

        def encode_content(self, content: object) -> object:
            raise AssertionError("sampling must not encode content")

        def with_sampling_space(self, space: object) -> Runtime:
            derived = Runtime()
            derived.space = space
            cast(Any, derived).runtime_identity = cast(Any, self).runtime_identity
            return derived

        def sample(self, latent: object, **kwargs: object) -> object:
            sampled_spaces.append(self.space)
            return latent

    runtime = Runtime()
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "_materialize_provider_conditioning", lambda value, *_args: value)
    inputs = _ksampler_inputs(arm, runtime, torch)
    original = inputs["model"]
    patched = arm.GenerationModelSamplingFlux.execute(model=original, width=768)["model"]
    inputs["model"] = patched
    if advanced:
        inputs.pop("denoise")
        inputs["noise_seed"] = inputs.pop("seed")
        inputs.update(
            add_noise="enable", start_at_step=0, end_at_step=2, return_with_leftover_noise="disable"
        )
        arm.GenerationKSamplerAdvanced.execute(**inputs)
    else:
        arm.GenerationKSampler.execute(**inputs)
    assert sampled_spaces == [patched.sampling_space]
    assert runtime.space is None
    assert patched.handle is original


