def test_generation_ksampler_unwraps_flux_guidance_before_materialization(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    runtime = _runtime()
    runtime.encode_text = lambda _text: object()
    runtime.sample = lambda _latent, **_kwargs: object()
    runtime.decode_latent = lambda value: value
    runtime.encode_content = lambda value: value
    handle = _handle(arm, runtime)

    calls: list[tuple[object, str]] = []

    def materialize(value: object, input_id: str, actual_handle: object) -> list[list[object]]:
        del actual_handle
        calls.append((value, input_id))
        return [[f"materialized-{input_id}", {}]]

    forwarded: dict[str, object] = {}

    def execute(**kwargs: object) -> Mapping[str, object]:
        forwarded.update(kwargs)
        return {"latent": "sampled"}

    monkeypatch.setattr(arm, "_materialize_provider_conditioning", materialize)
    monkeypatch.setattr(arm.NativeKSampler, "execute", execute)
    positive = _component_conditioning_carrier("positive")
    negative = _component_conditioning_carrier("negative")

    output = arm.GenerationKSampler.execute(
        model=handle,
        seed=7,
        steps=2,
        cfg=5.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=arm._GuidedRows(positive, 3.5),
        negative=arm._GuidedRows(negative, 3.5),
        latent_image={"samples": object()},
        denoise=1.0,
    )

    assert output == {"latent": "sampled"}
    wrapped_positive = cast("Any", forwarded["positive"])
    assert type(wrapped_positive) is arm._GuidedRows
    assert wrapped_positive.rows is positive
    assert wrapped_positive.guidance == 3.5
    wrapped_negative = cast("Any", forwarded["negative"])
    assert type(wrapped_negative) is arm._GuidedRows
    assert wrapped_negative.rows is negative
    assert wrapped_negative.guidance == 3.5
    inference = importlib.import_module("dinkster_inference")
    for value, name in ((wrapped_positive, "positive"), (wrapped_negative, "negative")):
        inner, guidance = arm._split_flux_guidance(value)
        assert guidance == 3.5
        assert arm._prepare_ksampler_conditioning(
            inner, name, handle.runtime, handle, inference
        ) == [[f"materialized-{name}", {}]]
    assert calls == [(positive, "positive"), (negative, "negative")]


