def test_lumina2_model_sampling_overlay_reaches_custom_scheduler() -> None:
    from dinkster_inference import (
        BFLOAT16,
        LUMINA2,
        FlowSigmas,
        ReconstructionRecipe,
        RuntimeKnobs,
        WeightSourceBinding,
        WeightSourceRef,
    )

    arm = _native_arm()
    recipe = ReconstructionRecipe(
        sources=(
            WeightSourceBinding(
                "diffusion",
                WeightSourceRef("blake3:" + "6" * 64, "lumina2.safetensors", 1),
            ),
        ),
        family_id="dinkster.lumina2",
        component_identity=("family=dinkster.lumina2", "role=diffusion"),
        knobs=RuntimeKnobs(
            diffusion_dtype=BFLOAT16.name,
            text_dtype="unloaded",
            vae_dtype="unloaded",
            fp8_matmul=False,
        ),
    )
    calls: list[tuple[str, int, float, float | None, object | None]] = []
    spaces: list[object] = []

    class Runtime:
        family = LUMINA2
        runtime_identity = recipe.runtime_identity

        def with_sampling_space(self, space: object) -> Runtime:
            spaces.append(space)
            return self

        @staticmethod
        def encode_text(_text: str) -> object:
            raise AssertionError("diffusion component must not encode text")

        @staticmethod
        def sample(_latent: object, **_kwargs: object) -> object:
            raise AssertionError("scheduler test must not execute sampling")

        @staticmethod
        def decode_latent(_latent: object) -> object:
            raise AssertionError("diffusion component must not decode latents")

        @staticmethod
        def encode_content(_content: object) -> object:
            raise AssertionError("diffusion component must not encode content")

        @staticmethod
        def custom_sampling_sigmas(
            scheduler_id: str,
            steps: int,
            denoise: float,
            *,
            sampling_shift: float | None = None,
            device: object | None = None,
        ) -> tuple[float, ...]:
            calls.append((scheduler_id, steps, denoise, sampling_shift, device))
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_beta_sigmas(*_args: object, **_kwargs: object) -> tuple[float, ...]:
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_sd_turbo_sigmas(*_args: object, **_kwargs: object) -> tuple[float, ...]:
            return (1.0, 0.0)

        @staticmethod
        def custom_sampling_percent_to_sigma(*_args: object, **_kwargs: object) -> float:
            return 0.0

        @staticmethod
        def check_custom_sampling(*_args: object, **_kwargs: object) -> None:
            return None

        @staticmethod
        def sample_custom(*_args: object, **_kwargs: object) -> object:
            raise AssertionError("scheduler test must not execute sampling")

    handle = _handle(arm, Runtime(), recipe=recipe)
    shifted = arm.GenerationModelSamplingAuraFlow.execute(model=handle, shift=4.0)["model"]
    sigmas = arm.GenerationBasicScheduler.execute(
        model=shifted,
        scheduler="normal",
        steps=12,
        denoise=0.75,
    )["sigmas"]

    assert sigmas == arm._CustomSigmasValue((1.0, 0.0))
    assert calls == [("dinkster.normal", 12, 0.75, None, handle.load_device)]
    assert spaces == [FlowSigmas(shift=4.0, multiplier=1.0)] * 2
    with pytest.raises(TypeError, match="sampling-space override"):
        arm.GenerationModelSamplingAuraFlow.execute(model=_handle(arm, _runtime()), shift=4.0)


def test_aura_flow_preserves_overlay_state_without_family_selection() -> None:
    from dinkster_inference import FlowSigmas

    arm = _native_arm()
    runtime = _runtime()
    accepted: list[object] = []

    def derive(space: object) -> object:
        accepted.append(space)
        return runtime

    runtime.with_sampling_space = derive
    handle = _handle(arm, runtime)
    original = arm._NativeModelOverlay(
        handle,
        (_overlay(),),
        {"retained": object()},
        sampling_shift=6.0,
        guidance_transforms=(("test", object()),),
        context_windows=object(),
        chroma_radiance_options=(object(),),
        sampling_cache=object(),
        sampling_timeline=object(),
    )
    patched = arm.GenerationModelSamplingAuraFlow.execute(model=original, shift=3.1)["model"]
    assert accepted == [FlowSigmas(shift=3.1, multiplier=1.0, timesteps=1000)]
    assert patched.sampling_space == accepted[0] and patched.sampling_shift is None
    for name in (
        "handle",
        "overlays",
        "source_resolvers",
        "guidance_transforms",
        "context_windows",
        "chroma_radiance_options",
        "sampling_cache",
        "sampling_timeline",
    ):
        assert getattr(patched, name) is getattr(original, name)
    assert original.sampling_shift == 6.0 and original.sampling_space is None
    chained = arm.GenerationModelSamplingAuraFlow.execute(model=patched, shift=4.0)["model"]
    assert chained.sampling_space == FlowSigmas(shift=4.0, multiplier=1.0)
    assert patched.sampling_space == accepted[0]


