def test_generation_clip_text_encode_binds_flux2_component_identity(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import ConditioningCarrier, split_component_conditioning

    arm = _native_arm()
    events: list[str] = []
    identity = "native:dinkster.flux2_klein_4b:" + "2" * 64

    class Handle:
        resource_identity = identity
        recipe = SimpleNamespace(
            family_id="dinkster.flux2_klein_4b",
            sources=(SimpleNamespace(role="qwen3_4b"),),
            runtime_identity=identity,
        )

        def require_active(self) -> None:
            pass

        @property
        def component(self) -> object:
            assert events == ["stage"]
            return "text-module"

        @contextmanager
        def stage(self):  # noqa: ANN201
            events.append("stage")
            yield

    class TextRuntime:
        def __init__(self, component: object) -> None:
            assert component == "text-module"

        def encode_text(self, text: str) -> object:
            assert text == "a lighthouse"
            events.append("encode")
            return object()

    carrier = _component_conditioning_carrier()
    fake_torch_inference = SimpleNamespace(
        Flux2TextRuntime=TextRuntime,
        basic_conditioning_to_carrier=lambda _value: carrier,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
