def test_anima_component_execution_composes_diffusion_and_text_identities(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ANIMA,
        ComponentBinding,
        ConditioningCarrier,
        bind_component_conditioning,
        compose_execution,
    )

    arm = _native_arm()
    diffusion_identity = "native:dinkster.anima:" + "1" * 64
    text_identity = "native:dinkster.anima:" + "2" * 64
    constructed: list[str] = []
    materialized: list[ConditioningCarrier] = []

    class Runtime:
        def __init__(
            self,
            diffusion: object = "diffusion",
            *,
            runtime_identity: str = diffusion_identity,
            compute_dtype: object = "bfloat16",
        ) -> None:
            del compute_dtype
            self.assembled = SimpleNamespace(diffusion=diffusion)
            self.family = ANIMA
            self.runtime_identity = runtime_identity
            constructed.append(runtime_identity)

    prepared = SimpleNamespace(embeddings=FakeTensor((1, 2, 12), "prepared"))

    def materialize(carrier: ConditioningCarrier, *, device: object) -> object:
        assert device == FakeDevice("cuda:0")
        materialized.append(carrier)
        return prepared

    fake_torch_inference = SimpleNamespace(
        AnimaDiffusionRuntime=Runtime,
        materialize_anima_conditioning=materialize,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", FakeTorch)
    base = Runtime()
    handle = SimpleNamespace(
        runtime=base,
        load_device=FakeDevice("cuda:0"),
        recipe=SimpleNamespace(
            family_id="dinkster.anima",
            runtime_identity=diffusion_identity,
            sources=(SimpleNamespace(role="diffusion"),),
            knobs=SimpleNamespace(diffusion_dtype="bfloat16"),
        ),
    )
    carrier = _component_conditioning_carrier()
    positive = bind_component_conditioning(
        carrier,
        ComponentBinding("qwen3_06b", "dinkster.anima", text_identity),
    )

    execution = arm.resolve_component_execution(
        cast("Any", handle), positive, [], real_import("dinkster_inference")
    )

    assert execution is not None
    runtime, rows, negative = execution
    expected = compose_execution(
        "dinkster.anima",
        {"diffusion": diffusion_identity, "qwen3_06b": text_identity},
    )
    assert runtime.runtime_identity == expected.execution_identity
    assert cast("FakeTensor", cast("Any", rows)[0][0]).name == "prepared"
    assert negative == []
    assert materialized == [carrier]
    assert constructed == [diffusion_identity, expected.execution_identity]


