def test_generation_custom_sampling_routes_triposplat_components_and_wraps_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        TRIPOSPLAT,
        CustomSamplingRequest,
        CustomSamplingResult,
        MultiStreamLatent,
        SamplingGuidance,
    )

    arm = _native_arm()
    torch = FakeTorch(cuda=True)
    recipe = replace(
        _recipe(),
        family_id="dinkster.triposplat",
        component_identity=("family=dinkster.triposplat", "role=dit"),
    )
    checks: list[dict[str, object]] = []
    calls: list[dict[str, object]] = []
    sample_devices: list[tuple[object, object]] = []

    class Runtime:
        family = TRIPOSPLAT
        runtime_identity = recipe.runtime_identity
        conditioning_identity = "dinkster.triposplat.conditioning:test"

        @staticmethod
        def encode_text(_text: str) -> object:
            raise AssertionError("component sampling must not encode text")

        @staticmethod
        def sample(latent: FakeTensor, **_kwargs: object) -> FakeTensor:
            raise AssertionError("custom sampling must not use the generic sample path")

        @staticmethod
        def sample_multistream(latent: Any, **kwargs: object) -> Any:
            calls.append({"latent": latent, **kwargs})
            return latent

        run_ksampler_as_custom = sample_multistream

        @staticmethod
        def decode_latent(latent: FakeTensor) -> FakeTensor:
            return latent

        @staticmethod
        def encode_content(content: FakeTensor) -> FakeTensor:
            return content

        @staticmethod
        def custom_sampling_sigmas(
            scheduler_id: str, steps: int, denoise: float
        ) -> tuple[float, ...]:
            raise AssertionError("unused")

        @staticmethod
        def custom_sampling_beta_sigmas(steps: int, alpha: float, beta: float) -> tuple[float, ...]:
            raise AssertionError("unused")

        @staticmethod
        def custom_sampling_sd_turbo_sigmas(steps: int, denoise: float) -> tuple[float, ...]:
            raise AssertionError("unused")

        @staticmethod
        def custom_sampling_percent_to_sigma(percent: float, *, return_actual_sigma: bool) -> float:
            raise AssertionError("unused")

        @staticmethod
        def check_custom_sampling(
            request: object,
            *,
            has_denoise_mask: bool,
            has_inpaint: bool,
            has_context_windows: bool,
            guidance: float | None = None,
        ) -> None:
            assert isinstance(request, CustomSamplingRequest)
            assert not has_inpaint
            if guidance is not None:
                raise ValueError("runtime does not support distilled-guidance")
            checks.append({"has_denoise_mask": has_denoise_mask})

        @staticmethod
        def sample_custom(latent: Any, **kwargs: object) -> Any:
            calls.append({"latent": latent, **kwargs})
            sample_devices.append(
                (latent.by_role("latent").device, latent.by_role("camera").device)
            )
            return CustomSamplingResult(cast("Any", latent), None)

    runtime = Runtime()
    handle = _handle(arm, runtime, torch, recipe=recipe)
    positive_payload = object()
    negative_payload = object()
    executions: list[tuple[object, object, object]] = []
    negatives: list[object | None] = [negative_payload]

    def fake_execution(
        handle_arg: object,
        positive_arg: object,
        negative_arg: object,
        _inference: object,
        **_options: object,
    ) -> object:
        executions.append((handle_arg, positive_arg, negative_arg))
        return arm._ResolvedComponentExecution(runtime, positive_payload, negatives[0], True)

    monkeypatch.setattr(arm, "_resolve_component_execution", fake_execution)
    latent_stream = FakeTensor((1, 8192, 16), "latent-stream")
    camera_stream = FakeTensor((1, 1, 5), "camera-stream")
    streams = MultiStreamLatent.from_pairs((("latent", latent_stream), ("camera", camera_stream)))
    generated_noise = MultiStreamLatent.from_pairs(
        (
            ("latent", FakeTensor((1, 8192, 16), "latent-noise")),
            ("camera", FakeTensor((1, 1, 5), "camera-noise")),
        )
    )
    prepare_calls: list[tuple[object, int, object]] = []

    def prepare_multistream_noise(samples: object, seed: int, noise_inds: object) -> object:
        prepare_calls.append((samples, seed, noise_inds))
        return generated_noise

    fake_inference_torch = SimpleNamespace(
        prepare_multistream_noise=prepare_multistream_noise,
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "multistream_sampling_preview_emitter", lambda _handle: None)
    sampler = arm.GenerationKSamplerSelect.execute(sampler_name="euler")["sampler"]
    sigmas = arm._CustomSigmasValue((1.0, 0.5, 0.0))
    raw_positive = [["raw-positive", {}]]
    raw_negative = [["raw-negative", {}]]

    output, _ = arm._execute_generation_custom_sampling(
        model=handle,
        noise=arm._CustomNoiseValue(23),
        sampler=sampler,
        sigmas=sigmas,
        positive=raw_positive,
        negative=raw_negative,
        cfg=6.5,
        latent_image={"samples": streams, "custom": "preserved"},
    )

    assert executions == [(handle, raw_positive, raw_negative)]
    assert len(checks) == 2
    assert all(not check["has_denoise_mask"] for check in checks)
    assert len(calls) == 1
    call = calls[0]
    cond = cast("Any", call["cond"])
    assert type(cond) is PreparedMultiStreamConditioning
    assert cond.runtime_identity == runtime.conditioning_identity
    assert cond.payload is positive_payload
    guidance = cast("Any", call["cfg"])
    assert type(guidance) is SamplingGuidance
    uncond = guidance.uncond
    assert type(uncond) is PreparedMultiStreamConditioning
    assert uncond.runtime_identity == runtime.conditioning_identity
    assert uncond.payload is negative_payload
    assert guidance.scale == 6.5
    assert call["noise"] is generated_noise
    assert prepare_calls == [(streams, 23, None)]
    assert call["seed"] == 23
    assert call["denoise_mask"] is None
    assert call["inpaint"] is None
    moved = cast("Any", call["latent"])
    assert type(moved) is MultiStreamLatent
    assert moved.roles == ("latent", "camera")
    assert sample_devices == [(FakeDevice("cuda:0"), FakeDevice("cuda:0"))]
    result = cast("Any", output["samples"])
    assert type(result) is MultiStreamLatent
    assert result.roles == ("latent", "camera")
    assert result.by_role("latent").device == FakeDevice("cpu")
    assert result.by_role("camera").device == FakeDevice("cpu")
    assert output["custom"] == "preserved"

    negatives[0] = None
    arm._execute_generation_custom_sampling(
        model=handle,
        noise=arm._CustomNoiseValue(23),
        sampler=sampler,
        sigmas=sigmas,
        positive=raw_positive,
        negative=None,
        cfg=6.5,
        latent_image={"samples": streams},
    )
    assert calls[-1]["cfg"] == SamplingGuidance(None, 6.5)
    assert cast("Any", calls[-1]["cond"]).payload is positive_payload

    with pytest.raises(ValueError, match="perp-neg guidance requires negative conditioning"):
        arm._execute_generation_custom_sampling(
            model=handle,
            noise=arm._CustomNoiseValue(23),
            sampler=sampler,
            sigmas=sigmas,
            positive=raw_positive,
            negative=raw_negative,
            cfg=6.5,
            latent_image={"samples": streams},
            empty=raw_positive,
        )
    assert len(calls) == 2

    composed_inputs = {
        "model": handle,
        "positive": raw_positive,
        "negative": [],
        "cfg": 1.0,
        "seed": 23,
        "steps": 2,
        "denoise": 1.0,
        "sampler_name": "euler",
        "scheduler": "simple",
        "latent_image": {"samples": streams},
    }
    arm.NativeKSampler.execute(**composed_inputs)
    assert calls[-1]["cfg"] == SamplingGuidance(None, 1.0)
    composed_inputs["positive"] = arm.GenerationFluxGuidance.execute(
        conditioning=_component_conditioning_carrier(), guidance=3.5
    )["conditioning"]
    with pytest.raises(ValueError, match="does not support distilled-guidance"):
        arm.NativeKSampler.execute(**composed_inputs)
    assert len(calls) == 3


def test_flux2_component_codec_pins_module_dtype_and_requires_image_batches(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    family = importlib.import_module("dinkster_native.families.flux2")
    torch = FakeTorch()

    @dataclass
    class FakePlugin:
        descriptor: object
        compute_dtype: object = None

        def decode(self, latent: object) -> object:
            return ("decoded", latent, self.compute_dtype)

        def encode(self, content: object) -> object:
            return ("encoded", content, self.compute_dtype)

    descriptor = SimpleNamespace(kind="image")
    module = SimpleNamespace(parameters=lambda: iter([SimpleNamespace(dtype="float32")]))
    handle = SimpleNamespace(
        component=module,
        resource_identity="native:dinkster.flux2:" + "f" * 64,
        load_device="cuda:0",
        require_active=lambda: None,
        stage=lambda: None,
    )
    monkeypatch.setattr(family, "load_component", lambda _value, _name, _role: handle)
    fake_torch_inference = SimpleNamespace(
        kl_codec_plugin=lambda candidate: FakePlugin(descriptor) if candidate is module else None
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    codec = family.CodecAdapter(object())

    assert codec.descriptor is descriptor
    assert codec.resource_identity == handle.resource_identity
    assert codec._dinkster_resident_owner is handle
    assert codec.load_device == "cuda:0"
    latent = FakeTensor((1, 4, 2, 3), "latent")
    assert codec.decode_latent(latent) == ("decoded", latent, "float32")
    content = FakeTensor((1, 3, 16, 24), "content")
    assert codec.encode_content(content) == ("encoded", content, "float32")
    with pytest.raises(ValueError, match=r"\[batch,3,height,width\]"):
        codec.encode_content(SimpleNamespace(ndim=3))


