def test_kl_component_codec_batches_direct_calls_from_live_memory(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    codec_type = importlib.import_module("dinkster_native.families.kl").CodecAdapter
    torch = FakeTorch()
    module = SimpleNamespace(parameters=lambda: iter([SimpleNamespace(dtype="float32")]))
    handle = SimpleNamespace(
        component=module,
        resource_identity="native:dinkster.flux2:" + "f" * 64,
        load_device=FakeDevice("cuda:0"),
        require_active=lambda: None,
    )
    geometries: list[tuple[str, tuple[int, ...]]] = []
    decode_batches: list[int] = []
    encode_batches: list[int] = []

    class Memory:
        @staticmethod
        def decode_bytes(geometry: object) -> int:
            geometries.append(("decode", cast(Any, geometry).shape))
            return 100

        @staticmethod
        def encode_bytes(geometry: object) -> int:
            geometries.append(("encode", cast(Any, geometry).shape))
            return 100

    @dataclass
    class Plugin:
        descriptor: object
        compute_dtype: object = None
        memory: object = Memory()

        @staticmethod
        def decode(latent: FakeTensor) -> FakeTensor:
            decode_batches.append(latent.shape[0])
            return FakeTensor((latent.shape[0], 3, 16, 24), device=latent.device)

        @staticmethod
        def encode(content: FakeTensor) -> FakeTensor:
            encode_batches.append(content.shape[0])
            return FakeTensor((content.shape[0], 4, 2, 3), device=content.device)

    plugin = Plugin(SimpleNamespace(kind="image"))
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return SimpleNamespace(
                kl_codec_plugin=lambda candidate: plugin if candidate is module else None,
                get_free_memory=lambda _device: SimpleNamespace(free_total=250),
            )
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    codec = codec_type(handle, "Flux2")

    decoded = codec.decode_latent(FakeTensor((5, 4, 2, 3), device="cuda:0"))
    encoded = codec.encode_content(FakeTensor((5, 3, 16, 24), device="cuda:0"))

    assert decoded.shape == (5, 3, 16, 24)
    assert encoded.shape == (5, 4, 2, 3)
    assert decode_batches == [2, 2, 1]
    assert encode_batches == [2, 2, 1]
    assert geometries == [
        ("decode", (1, 4, 2, 3)),
        ("encode", (1, 3, 16, 24)),
    ]


def test_generation_kl_component_codec_stages_with_estimated_working_memory(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    codec_type = importlib.import_module("dinkster_native.families.kl").CodecAdapter
    inference = importlib.import_module("dinkster_inference")
    torch = FakeTorch()
    stages: list[tuple[int, bool]] = []
    estimates: list[tuple[str, Any]] = []

    class Handle:
        pass

    class Estimator:
        def decode_bytes(self, geometry: Any) -> int:
            estimates.append(("decode", geometry))
            return 456

        def encode_bytes(self, geometry: Any) -> int:
            estimates.append(("encode", geometry))
            return 123

    @contextmanager
    def stage(*, memory_required: int = 0, clear_cache_after: bool = False):
        stages.append((memory_required, clear_cache_after))
        yield

    codec = object.__new__(codec_type)
    codec._handle = SimpleNamespace(stage=stage)
    codec._plugin = SimpleNamespace(memory=Estimator(), compute_dtype="bfloat16")
    codec.descriptor = SimpleNamespace(kind="image", content_channels=3)
    codec.load_device = FakeDevice("cuda:0")
    codec.decode_latent = lambda _latent: FakeTensor((1, 3, 1024, 1024), "decoded")
    codec.encode_content = lambda _content: FakeTensor((1, 16, 64, 64), "encoded")
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_native_component_codec", lambda _value: codec)
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    arm.GenerationVAEDecode.execute(
        samples={"samples": FakeTensor((1, 16, 64, 64), "latent")},
        vae=Handle(),
    )
    arm.GenerationVAEEncode.execute(
        pixels=FakeTensor((1, 1024, 1024, 3), "pixels"),
        vae=Handle(),
    )

    assert stages == [(456, True), (123, True)]
    assert [(name, geometry.shape, geometry.dtype) for name, geometry in estimates] == [
        ("decode", (1, 16, 64, 64), inference.BFLOAT16),
        ("encode", (1, 3, 1024, 1024), inference.BFLOAT16),
    ]


@pytest.mark.parametrize("family_id", ["dinkster.ltxv", "dinkster.ltxav"])
@pytest.mark.parametrize("alternate", [False, True])
def test_ltxv_component_codec_uses_selected_compute_dtype_and_video_semantics(
    monkeypatch: pytest.MonkeyPatch, family_id: str, alternate: bool
) -> None:
    from dinkster_inference import (
        LTXAV_VIDEO_CODEC,
        LTXV_CODEC,
        Registry,
        component_catalog,
    )

    arm = _native_arm()
    codec_type = importlib.import_module("dinkster_native.families.ltx").CodecAdapter
    descriptor = LTXV_CODEC if family_id == "dinkster.ltxv" else LTXAV_VIDEO_CODEC
    registration = component_catalog.default_component_registry().get(family_id)
    assert registration is not None
    if alternate:
        family_id = "example.compatible"
        registration = replace(registration, family=replace(registration.family, id=family_id))
    registry = Registry()
    registry.register(registration)
    monkeypatch.setattr(component_catalog, "default_component_registry", lambda: registry)
    module = SimpleNamespace(
        config=SimpleNamespace(latent_channels=128, spatial_ratio=32, temporal_ratio=8),
        parameters=lambda: iter([SimpleNamespace(dtype="float8_e4m3fn")]),
        encode=lambda value: value,
        decode=lambda value: value,
    )
    recipe = _ltx_component_recipe("vae", family_id)
    handle = arm.NativeComponentHandle(
        module,
        FakeMechanism(FakeModule(1), load_device="cuda:0", offload_device="cpu"),
        "cuda:0",
        recipe=recipe,
        resource_identity=recipe.runtime_identity,
        coordinator=_coordinator(arm),
    )

    class Runtime:
        def __init__(self, candidate: object, *, compute_dtype: object) -> None:
            assert candidate is module
            assert compute_dtype == "bfloat16"
            self.codec = SimpleNamespace(descriptor=descriptor)

        @staticmethod
        def decode_latent(latent: object) -> object:
            return "decoded", latent

        @staticmethod
        def encode_content(content: object) -> object:
            return "encoded", content

    monkeypatch.setattr(arm, "_torch", FakeTorch)
    runtime_name = "LTXVVideoCodecRuntime" if descriptor is LTXV_CODEC else "LTXAVVideoCodecRuntime"
    fake_torch_inference = SimpleNamespace(**{runtime_name: Runtime})
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )

    codec = arm._native_component_codec(handle)

    assert codec.descriptor is descriptor
    assert codec.resource_identity == handle.resource_identity
    assert codec._dinkster_resident_owner is handle
    assert codec.load_device == "cuda:0"
    assert codec.sequence_content
    assert codec.decode_latent("latent") == ("decoded", "latent")
    assert codec.encode_content("content") == ("encoded", "content")

    module.config.spatial_ratio = 16
    with pytest.raises(TypeError, match="config.spatial_ratio"):
        codec_type(handle)
    module.config.spatial_ratio = 32
    module.decode = None
    with pytest.raises(TypeError, match="callable decode"):
        codec_type(handle)
    module.decode = lambda value: value
    descriptor = replace(descriptor, latent=replace(descriptor.latent, spatial_downscale=16))
    with pytest.raises(TypeError, match="matching declared latent.spatial_downscale"):
        codec_type(handle)


