def test_ltxv_media_codec_accepts_component_codec_and_full_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import LTXV_CODEC

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    codecs = [
        SimpleNamespace(
            descriptor=LTXV_CODEC,
            resource_identity="test:codec",
            load_device="cpu",
            require_active=lambda: None,
            stage=lambda: None,
            encode_content=lambda value: value,
            decode_latent=lambda value: value,
        )
        for _ in range(2)
    ]
    component_codec, runtime_codec = codecs

    class Component:
        pass

    class Runtime:
        def __init__(self, family_id: str = "dinkster.ltxv") -> None:
            self.recipe = SimpleNamespace(family_id=family_id)
            self.runtime = SimpleNamespace(
                codec=SimpleNamespace(descriptor=LTXV_CODEC),
                encode_content=lambda value: value,
                decode_latent=lambda value: value,
            )

        def require_active(self) -> None:
            return None

    component = Component()
    runtime = Runtime()
    adapted: list[tuple[object, object]] = []
    monkeypatch.setattr(arm, "NativeComponentHandle", Component)
    monkeypatch.setattr(arm, "NativeRuntimeHandle", Runtime)
    monkeypatch.setattr(arm, "_native_component_codec", lambda value: component_codec)
    monkeypatch.setattr(
        inference,
        "RuntimeCodecAdapter",
        lambda value, *, descriptor: adapted.append((value, descriptor)) or runtime_codec,
    )

    assert arm._ltxv_media_codec(component) is component_codec
    assert arm._ltxv_media_codec(runtime) is runtime_codec
    assert adapted == [(runtime, LTXV_CODEC)]
    alternate = Runtime("example.video")
    assert arm._ltxv_media_codec(alternate) is runtime_codec
    alternate.runtime.codec = None
    with pytest.raises(TypeError, match="codec descriptor"):
        arm._ltxv_media_codec(alternate)


def test_ltxv_media_codec_accepts_descriptor_identity_not_allowlist() -> None:
    from dinkster_inference import LTXV_CODEC

    class Codec:
        descriptor = replace(LTXV_CODEC, id="example.video", display_name="Alternate video")
        resource_identity = "example:codec"
        load_device = "cpu"

        def require_active(self) -> None:
            pass

        @contextmanager
        def stage(self) -> Iterator[None]:
            yield

        def encode_content(self, value: object) -> object:
            return value

        def decode_latent(self, value: object) -> object:
            return value

    arm = _native_arm()
    codec = Codec()
    assert arm._ltxv_media_codec(codec) is codec
    codec.descriptor = replace(
        codec.descriptor, latent=replace(codec.descriptor.latent, temporal_causal=False)
    )
    with pytest.raises(TypeError, match="causal video codec"):
        arm._ltxv_media_codec(codec)
    codec.descriptor = LTXV_CODEC
    cast("Any", codec).encode_content = None
    with pytest.raises(TypeError, match="encode_content must be callable"):
        arm._ltxv_media_codec(codec)


def test_generation_flux2_vae_uses_image_semantics(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    events: list[object] = []

    class Handle:
        recipe = SimpleNamespace(family_id="dinkster.flux2")

    class Codec:
        descriptor = SimpleNamespace(kind="image", content_channels=3)
        load_device = FakeDevice("cuda:0")

        def __init__(self, _value: object) -> None:
            pass

        @contextmanager
        def stage(self):  # noqa: ANN201
            events.append("stage")
            yield

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            events.append(("encode", content.shape))
            return FakeTensor((content.shape[0], 128, 1, 1), "encoded")

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            events.append(("decode", latent.shape))
            return FakeTensor((latent.shape[0], 3, 16, 16), "decoded")

    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_native_component_codec", lambda value: Codec(value))
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    handle = Handle()

    encoded = arm.GenerationVAEEncode.execute(
        pixels=FakeTensor((2, 16, 16, 3), "pixels"),
        vae=handle,
    )
    decoded = arm.GenerationVAEDecode.execute(
        samples={"samples": FakeTensor((2, 128, 1, 1), "latent")},
        vae=handle,
    )

    assert cast("Mapping[str, FakeTensor]", encoded["latent"])["samples"].shape == (2, 128, 1, 1)
    assert cast("FakeTensor", decoded["image"]).shape == (2, 16, 16, 3)
    assert events == [
        "stage",
        ("encode", (2, 3, 16, 16)),
        "stage",
        ("decode", (2, 128, 1, 1)),
    ]


def test_generation_seedvr2_tiled_vae_uses_comfyui_geometry(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import SEEDVR2_CODEC

    arm = _native_arm()
    torch = FakeTorch()
    events: list[object] = []

    class Handle:
        pass

    class Codec:
        descriptor = SEEDVR2_CODEC
        load_device = FakeDevice("cuda:0")
        resource_identity = "native:dinkster.seedvr2:" + "1" * 64
        accepts_batched_video = True
        accepts_image_batch_latent = True
        manages_input_device = True

        def require_active(self) -> None:
            return None

        @contextmanager
        def stage(self):  # noqa: ANN201
            events.append("stage")
            yield

        def encode_content(self, content: FakeTensor) -> FakeTensor:
            return content

        def decode_latent(self, latent: FakeTensor) -> FakeTensor:
            return latent

        def encode_content_tiled(
            self,
            content: FakeTensor,
            *,
            tile: tuple[int, ...],
            overlap: tuple[int, ...],
        ) -> FakeTensor:
            events.append(("encode", content.shape, tile, overlap))
            return FakeTensor((content.shape[0], 16, 2, 4, 6), "encoded")

        def decode_latent_tiled(
            self,
            latent: FakeTensor,
            *,
            tile: tuple[int, ...],
            overlap: tuple[int, ...],
        ) -> FakeTensor:
            events.append(("decode", latent.shape, tile, overlap))
            if len(latent.shape) == 4:
                return FakeTensor((latent.shape[0], 3, 32, 48), "decoded")
            return FakeTensor((latent.shape[0], 3, 2, 32, 48), "decoded")

    codec = Codec()
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_native_component_codec", lambda _value: codec)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    handle = Handle()

    encoded = arm.GenerationVAEEncodeTiled.execute(
        pixels=FakeTensor((1, 5, 32, 48, 3), "pixels"),
        vae=handle,
        tile_size=512,
        overlap=128,
        temporal_size=64,
        temporal_overlap=8,
    )
    decoded = arm.GenerationVAEDecodeTiled.execute(
        samples={"samples": FakeTensor((1, 16, 2, 4, 6), "latent")},
        vae=handle,
        tile_size=512,
        overlap=200,
        temporal_size=8,
        temporal_overlap=8,
    )
    decoded_image_batch = arm.GenerationVAEDecodeTiled.execute(
        samples={"samples": FakeTensor((2, 16, 4, 6), "latent")},
        vae=handle,
        tile_size=512,
        overlap=200,
        temporal_size=8,
        temporal_overlap=8,
    )

    assert cast("Mapping[str, FakeTensor]", encoded["latent"])["samples"].shape == (1, 16, 2, 4, 6)
    assert cast("FakeTensor", decoded["image"]).shape == (2, 32, 48, 3)
    assert cast("FakeTensor", decoded_image_batch["image"]).shape == (2, 32, 48, 3)
    assert events == [
        "stage",
        ("encode", (1, 3, 5, 32, 48), (64, 512, 512), (8, 128, 128)),
        "stage",
        ("decode", (1, 16, 2, 4, 6), (2, 64, 64), (1, 16, 16)),
        "stage",
        ("decode", (2, 16, 4, 6), (2, 64, 64), (1, 16, 16)),
    ]


@pytest.mark.parametrize(
    ("mode", "role", "outcome"),
    (
        ("on", "mistral3_24b", "dynamic"),
        ("on", "qwen3_4b", "construction-failure"),
        ("auto", "qwen3_8b", "gate-fallback"),
        ("on", "vae", "resident"),
    ),
)
def test_flux2_component_builder_routes_only_text_through_aimdo(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mode: str,
    role: str,
    outcome: str,
) -> None:
    from dinkster_inference.component_catalog import default_component_registry

    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "flux2-component.safetensors"))
    inference = importlib.import_module("dinkster_inference")
    descriptor = next(
        item
        for item in default_component_registry()
        if item.id.startswith("dinkster.flux2") and role in item.roles
    )
    module = object()
    plan = inference.ComponentPlan(role, asset.local_path(), "synthetic", {}, {}, {})
    loaded = SimpleNamespace(
        module=module,
        role=role,
        family_id=descriptor.id,
        plan=plan,
    )
    recipe = descriptor.recipe(arm._weight_source_ref(inference, asset), loaded, "bfloat16")
    identity = recipe.runtime_identity
    patch_set = object()
    eager_mechanism = object()
    dynamic_mechanism = object()
    dynamic_free_memory = object()
    enrollment_calls: list[dict[str, object]] = []
    selection_calls: list[str] = []
    handle_calls: list[tuple[object, object, object, dict[str, object]]] = []
    coordinator_calls: list[dict[str, object]] = []

    def dynamic_factory(weights: object, **_kwargs: object) -> object:
        assert cast(Any, weights).module is module
        if outcome == "construction-failure":
            raise RuntimeError("allocation failed")
        return dynamic_mechanism

    def enroll(module_arg: object, **kwargs: object) -> object:
        assert module_arg is module
        enrollment_calls.append(kwargs)
        factory = kwargs.get("mechanism_factory")
        if factory is None:
            return eager_mechanism
        return cast(Any, factory)(SimpleNamespace(module=module_arg))

    inference_torch = SimpleNamespace(
        ResidentWeights=lambda _weights, **_kwargs: eager_mechanism,
        dynamic_free_memory=dynamic_free_memory,
        enroll_component=enroll,
        lora_compute_dtype=lambda _device: "float32",
        load_flux2_component=lambda *_args, **_kwargs: loaded,
    )

    def fake_import(name: str) -> object:
        if name == "dinkster_inference":
            return inference
        if name == "dinkster_inference_torch":
            return inference_torch
        raise AssertionError(name)

    def select_factory(
        selected: str, _device: object, _torch: object
    ) -> tuple[object | None, str | None]:
        selection_calls.append(selected)
        if outcome == "gate-fallback":
            return None, "aimdo device activation gate failed"
        return dynamic_factory, None

    class Coordinator:
        def __init__(self, **kwargs: object) -> None:
            self.__dict__.update(kwargs)

        @staticmethod
        def enroll_component(module: object, *, enroller: Any, **kwargs: object) -> object:
            return enroller(module, **kwargs)

    def coordinator(**kwargs: object) -> object:
        coordinator_calls.append(kwargs)
        return Coordinator(**kwargs)

    class Handle:
        def __init__(
            self,
            module_arg: object,
            mechanism_arg: object,
            device_arg: object,
            **kwargs: object,
        ) -> None:
            handle_calls.append((module_arg, mechanism_arg, device_arg, kwargs))

        def attach_pool(self, _pool: object) -> None:
            pass

    monkeypatch.setenv("DINKSTER_AIMDO_ARM", mode)
    monkeypatch.setattr(arm.importlib, "import_module", fake_import)
    monkeypatch.setattr(arm, "_component_candidate_path", lambda _asset: asset.local_path())
    monkeypatch.setattr(
        arm,
        "_materialize_patch_sets",
        lambda *_args: {role: patch_set},
    )
    monkeypatch.setattr(arm, "_aimdo_mechanism_factory", select_factory)
    monkeypatch.setattr(arm, "default_native_residency", coordinator)
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "default_pool", FakePool)

    if outcome == "construction-failure":
        with pytest.raises(RuntimeError, match="allocation failed"):
            arm._build_component_runtime_handle(
                descriptor,
                asset,
                role,
                identity,
                FakeTorch(cuda=True),
                compute_dtype="bfloat16",
                load_device=FakeDevice("cuda:0"),
            )
        assert selection_calls == [mode]
        assert len(enrollment_calls) == 1
        assert isinstance(enrollment_calls[0]["mechanism_factory"], arm._AimdoComponentFactory)
        assert coordinator_calls == [{"free_memory": dynamic_free_memory}]
        assert handle_calls == []
        return

    result = arm._build_component_runtime_handle(
        descriptor,
        asset,
        role,
        identity,
        FakeTorch(cuda=True),
        compute_dtype="bfloat16",
        load_device=FakeDevice("cuda:0"),
    )

    assert isinstance(result, Handle)
    assert len(enrollment_calls) == 1
    assert enrollment_calls[0]["load_device"] == FakeDevice("cuda:0")
    assert enrollment_calls[0]["offload_device"] == FakeDevice("cpu")
    assert enrollment_calls[0]["patch_set"] is patch_set
    assert enrollment_calls[0]["patch_weight_dtype"] == "float32"
    dynamic = outcome == "dynamic"
    assert ("mechanism_factory" in enrollment_calls[0]) is dynamic
    assert selection_calls == ([mode] if role != "vae" else [])
    assert coordinator_calls == ([{"free_memory": dynamic_free_memory}] if dynamic else [{}])
    assert len(handle_calls) == 1
    assert handle_calls[0][:3] == (
        module,
        dynamic_mechanism if outcome == "dynamic" else eager_mechanism,
        FakeDevice("cuda:0"),
    )
    facts = cast(Any, handle_calls[0][3]["residency_route_facts"])()
    if outcome == "dynamic":
        assert facts == arm.ResidencyRouteFacts(
            requested=mode, mechanism="aimdo", dynamic_components=(role,)
        )
    elif outcome == "resident":
        assert facts == arm.ResidencyRouteFacts(
            requested=mode, mechanism="eager", resident_components=(role,)
        )
    else:
        assert facts.mechanism == "eager"
        assert facts.fallback_reason is not None
        assert facts.fallback_components == (role,)


def test_native_generic_flux2_loaders_publish_components_and_a_diffusion_runtime(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "component.safetensors"))
    handle = SimpleNamespace(attach_pool=lambda pool: setattr(handle, "pool", pool))
    calls: list[tuple[object, ...]] = []
    torch = FakeTorch(cuda=True)

    def build(
        candidate: object,
        role: str,
        expected_identity: str,
        torch_module: object,
        **kwargs: object,
    ) -> object:
        calls.append((candidate, role, expected_identity, torch_module, kwargs))
        return handle

    def build_model(
        candidate: object,
        expected_identity: str,
        torch_module: object,
        **kwargs: object,
    ) -> object:
        calls.append((candidate, "runtime", expected_identity, torch_module, kwargs))
        return handle

    _mock_component_builders(monkeypatch, "dinkster.flux2_dev", build, build_model)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    pool = FakePool()
    monkeypatch.setattr(arm, "default_pool", lambda: pool)

    with use_execution_context(
        ExecutionContext(
            "native",
            "text-identity",
            diffusion_dtype="unloaded",
            text_dtype="bfloat16",
            vae_dtype="unloaded",
        )
    ):
        clip = arm.NativeLoadClip.execute(
            text_encoder=asset,
            type="flux2",
            device="default",
        )["clip"]
    with use_execution_context(
        ExecutionContext(
            "native",
            "vae-identity",
            diffusion_dtype="unloaded",
            text_dtype="unloaded",
            vae_dtype="float32",
        )
    ):
        vae = arm.NativeLoadVae.execute(vae=asset)["vae"]
    with use_execution_context(
        ExecutionContext(
            "native",
            "diffusion-identity",
            diffusion_dtype="bfloat16",
            text_dtype="unloaded",
            vae_dtype="unloaded",
        )
    ):
        model = arm.NativeLoadDiffusionModel.execute(diffusion_model=asset, weight_dtype="default")[
            "model"
        ]

    assert clip is vae is model is handle
    assert calls == [
        (
            asset,
            "mistral3_24b",
            "text-identity",
            torch,
            {"compute_dtype": "bfloat16", "load_device": None},
        ),
        (asset, "vae", "vae-identity", torch, {"compute_dtype": "float32"}),
        (
            asset,
            "runtime",
            "diffusion-identity",
            torch,
            {"compute_dtype": "bfloat16"},
        ),
    ]
    assert pool.labels == []


