def test_native_sampler_passes_sampling_shift_to_composed_flux2_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        FLOAT16,
        FLUX2_DEV,
        ComponentBinding,
        ConditioningCarrier,
        ReconstructionRecipe,
        RuntimeKnobs,
        WeightSourceBinding,
        WeightSourceRef,
        bind_component_conditioning,
        compose_execution,
    )

    arm = _native_arm()
    torch = FakeTorch(cuda=True)
    source = WeightSourceRef("blake3:" + "1" * 64, "flux2-dit.safetensors", 1)
    recipe = ReconstructionRecipe(
        sources=(WeightSourceBinding("diffusion", source),),
        family_id=FLUX2_DEV.id,
        component_identity=("family=dinkster.flux2_dev", "role=diffusion"),
        knobs=RuntimeKnobs(
            diffusion_dtype=FLOAT16.name,
            text_dtype="unloaded",
            vae_dtype="unloaded",
            fp8_matmul=False,
        ),
    )
    text_identity = f"native:{FLUX2_DEV.id}:" + "2" * 64
    prepared: list[ConditioningCarrier] = []
    samples: list[tuple[str, dict[str, object]]] = []

    class Runtime:
        conditioning_identity = "flux2-conditioning"
        supports_sampling_shift = True

        def __init__(
            self,
            diffusion: object,
            family: object = FLUX2_DEV,
            *,
            runtime_identity: str = recipe.runtime_identity,
        ) -> None:
            self.assembled = SimpleNamespace(
                diffusion=diffusion,
                compute_dtype=lambda _role: "float16",
            )
            self.family = family
            self.runtime_identity = runtime_identity

        def prepare_flux2_conditioning(self, carrier: ConditioningCarrier) -> object:
            prepared.append(carrier)
            return Conditioning(FakeTensor((1, 2, 8), f"prepared-{len(prepared)}"))

        def prepare_single_stream_conditioning(
            self, _carrier: ConditioningCarrier
        ) -> Conditioning[FakeTensor]:
            raise AssertionError("component sampling must retain Flux2 reference conditioning")

        def sample(self, latent: FakeTensor, **kwargs: object) -> FakeTensor:
            samples.append((self.runtime_identity, dict(kwargs)))
            assert latent.name == "latent"
            return FakeTensor(latent.shape, "sampled")

    base_runtime = Runtime(FakeModule(40))
    handle = _handle(arm, base_runtime, torch, recipe=recipe)
    model = arm._NativeModelOverlay(handle, (), {}, None, 3.25)
    carrier = _component_conditioning_carrier()
    binding = ComponentBinding("mistral3_24b", FLUX2_DEV.id, text_identity)
    positive = bind_component_conditioning(carrier, binding)
    negative = bind_component_conditioning(carrier, binding)
    fake_torch_inference = SimpleNamespace(
        Flux2DiffusionRuntime=Runtime,
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    output = arm.NativeKSampler.execute(
        model=model,
        seed=7,
        steps=2,
        cfg=2.5,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=positive,
        negative=negative,
        latent_image={"samples": FakeTensor((1, 128, 2, 2), "latent")},
        denoise=1.0,
    )

    expected = compose_execution(
        FLUX2_DEV.id,
        {"diffusion": recipe.runtime_identity, "mistral3_24b": text_identity},
    )
    assert cast("Mapping[str, FakeTensor]", output["latent"])["samples"].name == "sampled"
    assert prepared == [carrier, carrier]
    assert len(samples) == 1
    runtime_identity, sample_kwargs = samples[0]
    assert runtime_identity == expected.execution_identity
    assert sample_kwargs["sampling_shift"] == 3.25
    assert cast("Conditioning[FakeTensor]", sample_kwargs["cond"]).embeddings.name == "prepared-1"
    guidance = cast("Any", sample_kwargs["cfg"])
    assert guidance.uncond.embeddings.name == "prepared-2"
    assert guidance.scale == 2.5
    assert "device" not in sample_kwargs
    assert "compute_dtype" not in sample_kwargs


