def test_generation_sampler_prepares_rich_multistream_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ConditioningCarrier,
        ConditioningChannel,
        ConditioningRecord,
        ConditioningSet,
        MultiStreamLatent,
        PayloadBinding,
        PayloadDescriptor,
        PayloadReference,
        TokenLayoutDescriptor,
        TokenSegmentDescriptor,
        encode_conditioning_carrier,
        make_conditioning_carrier,
    )

    arm = _native_arm()
    torch = FakeTorch()
    sampled = FakeTensor((1, 16, 3, 2, 2), "sampled")

    def carrier(name: str) -> ConditioningCarrier:
        text = PayloadBinding(
            f"{name}-text",
            (1, 2, 8),
            "F32",
            "conditioning-text",
            bytes(64),
        )
        pose = PayloadBinding(
            f"{name}-pose",
            (1, 16, 2, 2, 2),
            "F32",
            "conditioning-pose-latent",
            bytes(512),
        )

        def descriptor(binding: PayloadBinding) -> PayloadDescriptor:
            return PayloadDescriptor(
                PayloadReference(binding.reference_id),
                binding.shape,
                binding.dtype,
                binding.space,
            )

        return make_conditioning_carrier(
            ConditioningSet(
                (
                    ConditioningRecord(
                        channels=(
                            (ConditioningChannel.TEXT, descriptor(text)),
                            (ConditioningChannel.POSE_LATENT, descriptor(pose)),
                        ),
                        token_layout=TokenLayoutDescriptor(
                            "dinkster.wan21",
                            1,
                            ("umt5",),
                            (TokenSegmentDescriptor("umt5", "umt5", 0, 2),),
                        ),
                    ),
                )
            ),
            (text, pose),
        )

    positive = carrier("positive")
    negative = carrier("negative")

    class Runtime(_PlainVideoLatentAdapter):
        family = SimpleNamespace(id="dinkster.wan21")
        conditioning_identity = "dinkster.wan.conditioning:test:animate"
        check_custom_sampling = staticmethod(_accept_custom_sampling)

        def __init__(self) -> None:
            self.prepared: list[ConditioningCarrier] = []
            self.sample_kwargs: dict[str, object] | None = None

        def prepare_conditioning(self, value: ConditioningCarrier) -> object:
            assert type(value) is ConditioningCarrier
            encode_conditioning_carrier(value)
            self.prepared.append(value)
            return ("prepared", value)

        def sample_multistream(self, latent: object, **kwargs: object) -> object:
            assert type(latent) is MultiStreamLatent
            self.sample_kwargs = kwargs
            return cast("Any", latent).replace("video", sampled)

        run_ksampler_as_custom = sample_multistream

    runtime = Runtime()
    handle = _handle(arm, runtime, torch)
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    output = arm.GenerationKSampler.execute(
        model=handle,
        seed=7,
        steps=2,
        cfg=5.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=positive,
        negative=negative,
        latent_image={"samples": FakeTensor((1, 16, 3, 2, 2), "latent")},
        denoise=1.0,
    )

    assert cast("Mapping[str, object]", output["latent"])["samples"] is sampled
    assert runtime.prepared == [positive, negative]
    assert runtime.sample_kwargs is not None
    assert runtime.sample_kwargs["conditioning"] == ("prepared", positive)
    guidance = cast("Any", runtime.sample_kwargs["cfg"])
    assert guidance.uncond == ("prepared", negative)
    assert guidance.scale == 5.0


