def test_generation_context_windows_nodes_attach_validated_specs() -> None:
    from dinkster_inference import ContextFuseMethod, ContextWindowSchedule, ContextWindowsSpec

    arm = _native_arm()
    handle = _handle(arm, _runtime())

    generic = arm.GenerationContextWindowsManual.execute(
        model=handle,
        context_length=16,
        context_overlap=4,
        context_schedule="standard_static",
        context_stride=1,
        closed_loop=False,
        fuse_method="pyramid",
        dim=0,
        freenoise=False,
        causal_window_fix=True,
    )["model"]
    assert type(generic) is arm._NativeModelOverlay
    assert generic.handle is handle
    assert generic.overlays == ()
    assert generic.context_windows == ContextWindowsSpec(
        ContextWindowSchedule.STATIC_STANDARD,
        ContextFuseMethod.PYRAMID,
        16,
        4,
        causal_anchor=True,
    )

    wan = arm.GenerationWanContextWindowsManual.execute(
        model=handle,
        context_length=81,
        context_overlap=30,
        context_schedule="standard_uniform",
        context_stride=1,
        closed_loop=False,
        fuse_method="pyramid",
        freenoise=True,
    )["model"]
    assert type(wan) is arm._NativeModelOverlay
    assert wan.context_windows == ContextWindowsSpec(
        ContextWindowSchedule.UNIFORM_STANDARD,
        ContextFuseMethod.PYRAMID,
        21,
        7,
        dim=2,
        freenoise=True,
        causal_anchor=True,
    )

    ltxv = arm.GenerationLTXVContextWindows.execute(
        model=handle,
        context_length=17,
        context_overlap=8,
        context_schedule="standard_uniform",
        context_stride=1,
        closed_loop=False,
        fuse_method="pyramid",
        freenoise=True,
        retain_first_frame=True,
    )["model"]
    assert type(ltxv) is arm._NativeModelOverlay
    assert ltxv.context_windows == ContextWindowsSpec(
        ContextWindowSchedule.UNIFORM_STANDARD,
        ContextFuseMethod.PYRAMID,
        3,
        1,
        dim=2,
        freenoise=True,
        causal_anchor=True,
        cond_retain_indices=(),
        latent_retain_indices=(0,),
    )

    base: dict[str, object] = {
        "model": handle,
        "context_length": 16,
        "context_overlap": 4,
        "context_schedule": "standard_static",
        "context_stride": 1,
        "closed_loop": False,
        "fuse_method": "pyramid",
        "dim": 0,
        "freenoise": False,
        "causal_window_fix": True,
    }

    def execute_generic(**changed: object) -> object:
        return arm.GenerationContextWindowsManual.execute(
            **cast("dict[str, Any]", {**base, **changed})
        )

    with pytest.raises(ValueError, match="unknown context schedule"):
        execute_generic(context_schedule="bogus")
    with pytest.raises(ValueError, match="unknown fuse method"):
        execute_generic(fuse_method="bogus")
    with pytest.raises(ValueError, match="relative fusing is not supported"):
        execute_generic(fuse_method="relative")
    with pytest.raises(ValueError, match="overlap must be nonnegative and less than length"):
        execute_generic(context_overlap=16)
    with pytest.raises(ValueError, match="only one context-windows configuration"):
        execute_generic(model=generic)
    with pytest.raises(ValueError, match="only one context-windows configuration"):
        arm.GenerationLTXVContextWindows.execute(
            model=ltxv,
            context_length=17,
            context_overlap=8,
            context_schedule="standard_uniform",
            context_stride=1,
            closed_loop=False,
            fuse_method="pyramid",
            freenoise=True,
            retain_first_frame=False,
        )
    with pytest.raises(TypeError, match="context_length and context_overlap must be ints"):
        arm.GenerationWanContextWindowsManual.execute(
            model=handle,
            context_length=cast("Any", True),
            context_overlap=30,
            context_schedule="standard_uniform",
            context_stride=1,
            closed_loop=False,
            fuse_method="pyramid",
            freenoise=True,
        )


def test_generation_sampling_caches_compose_and_reach_ksampler(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ContextFuseMethod,
        ContextWindowSchedule,
        ContextWindowsSpec,
        CustomSamplingRequest,
        builtin_sampler_registry,
    )

    arm = _native_arm()
    handle = _handle(arm, _runtime())
    created: list[tuple[float, float, float]] = []
    easy_created: list[tuple[float, float, float]] = []

    class Cache:
        def wrap_denoiser(self, denoiser: object, sigmas: object, info: object) -> object:
            del sigmas, info
            return denoiser

    cache = Cache()

    def lazy_cache_config(threshold: float, start: float, end: float) -> Cache:
        created.append((threshold, start, end))
        return cache

    easy_cache = Cache()

    def easy_cache_config(threshold: float, start: float, end: float) -> Cache:
        easy_created.append((threshold, start, end))
        return easy_cache

    fake_torch_inference = SimpleNamespace(
        EasyCacheConfig=easy_cache_config,
        LazyCacheConfig=lazy_cache_config,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_torch_inference if name == "dinkster_inference_torch" else real_import(name)
        ),
    )

    cached = arm.GenerationLazyCache.execute(
        model=handle,
        reuse_threshold=0.25,
        start_percent=0.1,
        end_percent=0.9,
    )["model"]

    assert type(cached) is arm._NativeModelOverlay
    assert cached.sampling_cache is cache
    assert created == [(0.25, 0.1, 0.9)]
    easy = arm.GenerationEasyCache.execute(
        model=handle,
        reuse_threshold=0.3,
        start_percent=0.2,
        end_percent=0.8,
    )["model"]
    assert type(easy) is arm._NativeModelOverlay
    assert easy.sampling_cache is easy_cache
    assert easy_created == [(0.3, 0.2, 0.8)]
    spec = ContextWindowsSpec(
        ContextWindowSchedule.STATIC_STANDARD,
        ContextFuseMethod.PYRAMID,
        16,
        4,
    )
    windowed = arm._model_with_context_windows(easy, spec)
    assert windowed.context_windows is spec
    assert windowed.sampling_cache is easy_cache
    reverse = arm.GenerationLazyCache.execute(
        model=arm._NativeModelOverlay(handle, (), {}, context_windows=spec),
        reuse_threshold=0.25,
        start_percent=0.1,
        end_percent=0.9,
    )["model"]
    assert reverse.context_windows is spec
    assert reverse.sampling_cache is cache
    with pytest.raises(ValueError, match="only one sampling cache"):
        arm.GenerationLazyCache.execute(
            model=cached,
            reuse_threshold=0.25,
            start_percent=0.1,
            end_percent=0.9,
        )
    with pytest.raises(ValueError, match="only one sampling cache"):
        arm.GenerationEasyCache.execute(
            model=easy,
            reuse_threshold=0.25,
            start_percent=0.1,
            end_percent=0.9,
        )

    observed: list[object] = []
    descriptor = builtin_sampler_registry().get("dinkster.euler")
    assert descriptor is not None

    def execute(**_kwargs: object) -> Mapping[str, object]:
        observed.append(CustomSamplingRequest(descriptor, (), (1.0, 0.0)).cache)
        return {"latent": object()}

    monkeypatch.setattr(arm.NativeKSampler, "execute", execute)
    monkeypatch.setattr(arm, "_minimax_h3_model_handle", lambda model, _inference: model)
    arm.GenerationKSampler.execute(
        model=easy,
        seed=0,
        steps=1,
        cfg=1.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=object(),
        negative=object(),
        latent_image={"samples": object()},
        denoise=1.0,
    )
    assert observed == [easy_cache]


def test_generation_attention_schedule_binds_curve_and_reaches_ksampler(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import CustomSamplingRequest, builtin_sampler_registry
    from dinkster_nodes_foundation import Curve

    arm = _native_arm()
    runtime = _runtime()
    runtime.assembled.attention_status = {
        "unet": SimpleNamespace(primary="sol", authenticated=True)
    }
    handle = _handle(arm, runtime)
    scheduled = arm.GenerationAttentionSchedule.execute(
        model=handle,
        approximate_provider="sol",
        start_percent=0.25,
        end_percent=0.75,
        conditioning_sink="exact_kv",
        sol_tau=Curve(((0.0, 1.0), (1.0, 2.0)), "monotone_cubic"),
    )["model"]

    assert type(scheduled) is arm._NativeModelOverlay
    assert scheduled.sampling_timeline.approximate_provider == "sol"
    assert scheduled.sampling_timeline.sol_tau.evaluate(0.5) == 1.5
    assert tuple(
        modifier.modifier for modifier in scheduled.sampling_timeline.attention_modifiers
    ) == ("sol_conditioning_exact_kv",)
    runtime.assembled.attention_status = {
        "unet": SimpleNamespace(primary="sage", authenticated=True)
    }
    with pytest.raises(ValueError, match="conditioning sink requires the Sol provider"):
        arm.GenerationAttentionSchedule.execute(
            model=handle,
            approximate_provider="sage",
            start_percent=0.0,
            end_percent=1.0,
            conditioning_sink="exact_kv",
        )
    runtime.assembled.attention_status = {
        "unet": SimpleNamespace(primary="sol", authenticated=True)
    }
    with pytest.raises(ValueError, match="conditioning sink is unsupported"):
        arm.GenerationAttentionSchedule.execute(
            model=handle,
            approximate_provider="sol",
            start_percent=0.0,
            end_percent=1.0,
            conditioning_sink="invented",
        )
    with pytest.raises(ValueError, match="only one sampling timeline"):
        arm.GenerationAttentionSchedule.execute(
            model=scheduled,
            approximate_provider="sol",
            start_percent=0.0,
            end_percent=1.0,
        )
    with pytest.raises(ValueError, match="selected diffusion provider"):
        arm.GenerationAttentionSchedule.execute(
            model=handle,
            approximate_provider="sage",
            start_percent=0.0,
            end_percent=1.0,
        )
    runtime.assembled.attention_status = {
        "unet": SimpleNamespace(primary="sol", authenticated=True),
        "flux": SimpleNamespace(primary="sage", authenticated=True),
    }
    with pytest.raises(ValueError, match="selected diffusion provider"):
        arm.GenerationAttentionSchedule.execute(
            model=handle,
            approximate_provider="sol",
            start_percent=0.0,
            end_percent=1.0,
        )
    runtime.assembled.attention_status = {
        "unet": SimpleNamespace(primary="sol", authenticated=False)
    }
    with pytest.raises(ValueError, match="authenticated provider route"):
        arm.GenerationAttentionSchedule.execute(
            model=handle,
            approximate_provider="sol",
            start_percent=0.0,
            end_percent=1.0,
        )

    observed: list[object] = []
    descriptor = builtin_sampler_registry().get("dinkster.euler")
    assert descriptor is not None

    def execute(**_kwargs: object) -> Mapping[str, object]:
        observed.append(CustomSamplingRequest(descriptor, (), (1.0, 0.0)).timeline)
        return {"latent": object()}

    monkeypatch.setattr(arm.NativeKSampler, "execute", execute)
    monkeypatch.setattr(arm, "_minimax_h3_model_handle", lambda model, _inference: model)
    arm.GenerationKSampler.execute(
        model=scheduled,
        seed=0,
        steps=1,
        cfg=1.0,
        sampler_name="dinkster.euler",
        scheduler="dinkster.simple",
        positive=object(),
        negative=object(),
        latent_image={"samples": object()},
        denoise=1.0,
    )
    assert observed == [scheduled.sampling_timeline]


def test_wan_sampler_forwards_context_windows_to_opted_in_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ContextFuseMethod,
        ContextWindowSchedule,
        ContextWindowsSpec,
        MultiStreamLatent,
    )

    arm = _native_arm()
    torch = FakeTorch()
