    spec = ContextWindowsSpec(
        ContextWindowSchedule.UNIFORM_STANDARD,
        ContextFuseMethod.PYRAMID,
        21,
        7,
        dim=2,
        causal_anchor=True,
    )

    class Runtime(_PlainVideoLatentAdapter):
        family = SimpleNamespace(id="dinkster.wan21")
