def _dependency_recipe(
    arm: Any,
    asset: AssetRef,
    *,
    dependencies: tuple[object, ...] = (),
    embedding_binding_digest: str | None = None,
    attention_route_token: AttentionRouteToken | None = None,
) -> object:
    from dinkster_inference import WeightSourceBinding

    inference = importlib.import_module("dinkster_inference")
    base = _recipe()
    return replace(
        base,
        sources=(WeightSourceBinding("checkpoint", arm._weight_source_ref(inference, asset)),),
        knobs=replace(
            base.knobs,
            embedding_binding_digest=embedding_binding_digest,
            attention_route_token=attention_route_token,
        ),
        dependencies=dependencies,
    )


def _dependency_edge(
    child_id: str,
    child: object,
    *,
    group: str = "models",
    scope: Any = "model",
    clone_mode: Any = "with-parent",
    owner: str = "parent",
) -> object:
    from dinkster_inference import DependencyRef

    return DependencyRef(
        child_id=child_id,
        child=child,
        residency_group=group,
        scope=scope,
        clone_mode=clone_mode,
        accounting_owner=owner,
    )


def _dependency_materialization_fakes(
    arm: Any,
    monkeypatch: pytest.MonkeyPatch,
) -> tuple[object, Any, list[tuple[str, ...]], list[object]]:
    inference = importlib.import_module("dinkster_inference")
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    resource = (SimpleNamespace(binding_digest=None), None)
    pool = residency.NativeResidencyPool()
    assembled_paths: list[tuple[str, ...]] = []
    assembled_resources: list[object] = []
    torch = FakeTorch(cuda=True)
    coordinator = _coordinator(arm)

    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            SimpleNamespace(
                torch_sampler_registry=_fake_torch_sampler_registry,
                worker_planning_context=lambda: pytest.fail(
                    "generic native prevalidation must not request MiniMax H3 planning context"
                ),
            )
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_embedding_resource", lambda _torch: resource)
    monkeypatch.setattr(arm, "default_dependency_residency_pool", lambda: pool)
    monkeypatch.setattr(
        inference,
        "plan_native",
        lambda **_sources: SimpleNamespace(
            family=SimpleNamespace(id="dinkster.sd15"), identity_components=()
        ),
    )
    monkeypatch.setattr(
        inference,
        "runtime_component_identity",
        lambda family, _components: (f"family={family}",),
    )

    def assemble(
        prepared: object,
        source_resolvers: Mapping[str, object],
        supplied_torch: object,
        supplied_resource: object,
    ) -> object:
        assert supplied_torch is torch
        assembled_paths.append(cast(Any, prepared).path)
        assembled_resources.append(supplied_resource)
        recipe = cast(Any, prepared).recipe
        runtime = _runtime()
        runtime.runtime_identity = recipe.runtime_identity

        def materializer(next_recipe: object, next_resolvers: Mapping[str, object]) -> object:
            return arm._materialize_recipe_handle(
                next_recipe,
                next_resolvers,
                torch,
                cast(Any, supplied_resource),
            )

        return arm.NativeRuntimeHandle(
            runtime,
            FakeDevice("cuda:0"),
            recipe=recipe,
            materializer=materializer,
            source_resolvers=source_resolvers,
            coordinator=coordinator,
            _torch_module=torch,
            _enroll_assembled=_fake_enroll_assembled,
        )

    monkeypatch.setattr(arm, "_assemble_prevalidated_handle", assemble)
    return torch, pool, assembled_paths, assembled_resources


def test_dependency_materialization_orders_stage_accounts_conditionals_and_release(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "dependency.safetensors"))
    child = _dependency_recipe(arm, asset)
    conditional = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(
            _dependency_edge("model-child", child),
            _dependency_edge("conditional-child", conditional, scope="conditional"),
        ),
    )
    torch, pool, assembled, resources = _dependency_materialization_fakes(arm, monkeypatch)
    resolvers = {asset.digest: asset.resolver}

    handle = arm._materialize_recipe_handle(recipe, resolvers, torch)

    assert assembled == [("model-child",), ()]
    assert len({id(resource) for resource in resources}) == 1
    assert tuple(handle.owned_dependencies) == (("model-child",),)
    assert len(pool.active_tokens()) == 2
    assert sum(pool.account_costs().values()) == asset.size * 2

    stage_events: list[str] = []
    cleanup_events: list[str] = []

    def observe(path: tuple[str, ...], dependency: object) -> None:
        label = "root" if not path else path[-1]
        cast(Any, dependency).register_lifecycle_callback(
            "pre-run", label, lambda _event, value=label: stage_events.append(value)
        )
        cast(Any, dependency).register_lifecycle_callback(
            "cleanup", label, lambda _event, value=label: cleanup_events.append(value)
        )

    observe((), handle)
    for path, dependency in handle.owned_dependencies.items():
        observe(path, dependency)

    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    observer_events: list[Any] = []
    with residency.observe_native_stages(observer_events.append):
        with handle.stage("diffusion"):
            pass
    assert stage_events == ["model-child", "root"]
    lease_begins = [
        event for event in observer_events if event.operation == "lease" and event.phase == "begin"
    ]
    assert len(lease_begins) == 2
    assert lease_begins[0].parent_span_id is None
    assert lease_begins[1].parent_span_id == lease_begins[0].span_id

    stage_events.clear()
    active = frozenset({("conditional-child",)})
    with handle.stage("diffusion", active_conditional=active):
        pass
    conditional_handle = handle.owned_dependencies[("conditional-child",)]
    observe(("conditional-child",), conditional_handle)
    assert assembled == [("model-child",), (), ("conditional-child",)]
    assert len(pool.active_tokens()) == 3
    assert len(pool.account_costs()) == 2
    assert sum(pool.account_costs().values()) == asset.size * 3

    stage_events.clear()
    with handle.stage("diffusion", active_conditional=active):
        pass
    assert stage_events == ["model-child", "conditional-child", "root"]
    assert assembled == [("model-child",), (), ("conditional-child",)]

    handle.terminal_release()
    assert cleanup_events == ["root", "conditional-child", "model-child"]
    assert pool.active_tokens() == ()


