def test_dependency_construction_failure_rolls_back_every_unique_lease(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "rollback.safetensors"))
    child = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("child", child),),
    )
    torch, pool, assembled, _resources = _dependency_materialization_fakes(arm, monkeypatch)
    original = arm._assemble_prevalidated_handle
    built: list[object] = []

    def fail_root(*args: object, **kwargs: object) -> object:
        prepared = cast(Any, args[0])
        if prepared.path == ():
            raise RuntimeError("root construction failed")
        handle = original(*args, **kwargs)
        built.append(handle)
        return handle

    monkeypatch.setattr(arm, "_assemble_prevalidated_handle", fail_root)

    with pytest.raises(RuntimeError, match="root construction failed"):
        arm._materialize_recipe_handle(recipe, {asset.digest: asset.resolver}, torch)

    assert assembled == [("child",)]
    assert len(built) == 1 and cast(Any, built[0]).released
    assert pool.active_tokens() == ()


def test_dependency_complete_prevalidation_finishes_before_first_lease(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "late-prevalidation.safetensors"))
    child = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("child", child),),
    )
    torch, pool, assembled, _resources = _dependency_materialization_fakes(arm, monkeypatch)
    validated: list[object] = []

    def materialize_patch_sets(
        _inference: object,
        _inference_torch: object,
        current: object,
        _source_resolvers: object,
    ) -> object:
        validated.append(current)
        if current is child:
            raise RuntimeError("late child overlay validation failed")
        return {}

    monkeypatch.setattr(arm, "_materialize_patch_sets", materialize_patch_sets)

    with pytest.raises(RuntimeError, match="late child overlay validation failed"):
        arm._materialize_recipe_handle(recipe, {asset.digest: asset.resolver}, torch)

    assert validated == [recipe, child]
    assert assembled == []
    assert pool.active_tokens() == ()

    acquired: list[object] = []
    real_acquire = pool.acquire

    def acquire(*args: object, **kwargs: object) -> object:
        acquired.append((args, kwargs))
        return real_acquire(*args, **kwargs)

    monkeypatch.setattr(pool, "acquire", acquire)
    typed_child = cast(Any, child)
    invalid_child = replace(
        typed_child,
        knobs=replace(typed_child.knobs, diffusion_dtype="float64"),
    )
    invalid_recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("child", invalid_child),),
    )
    monkeypatch.setattr(arm, "_materialize_patch_sets", lambda *_args: {})

    with pytest.raises(RuntimeError, match="unsupported runtime dtype"):
        arm._materialize_recipe_handle(invalid_recipe, {asset.digest: asset.resolver}, torch)

    assert acquired == []
    assert assembled == []
    assert pool.active_tokens() == ()


