def test_dependency_stage_failure_releases_graph_once_in_reverse_order(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    residency = importlib.import_module("dinkster_compat_comfy.native_residency")
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "stage-failure.safetensors"))
    child = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("child", child),),
    )
    torch, pool, _assembled, _resources = _dependency_materialization_fakes(arm, monkeypatch)
    handle = arm._materialize_recipe_handle(recipe, {asset.digest: asset.resolver}, torch)
    dependency = handle.owned_dependencies[("child",)]
    cleanup: list[str] = []
    handle.register_lifecycle_callback("cleanup", "root", lambda _event: cleanup.append("root"))
    dependency.register_lifecycle_callback(
        "inject", "fail", lambda _event: (_ for _ in ()).throw(RuntimeError("stage failed"))
    )
    dependency.register_lifecycle_callback(
        "cleanup", "child", lambda _event: cleanup.append("child")
    )

    with pytest.raises(RuntimeError, match="stage failed") as caught:
        with handle.stage("diffusion"):
            pytest.fail("failed child stage must not enter the parent body")

    lifecycle_error = cast(Any, caught.value)
    assert isinstance(lifecycle_error, residency.NativeLifecycleCallbackError)
    assert str(lifecycle_error.failures[0]) == "stage failed"
    assert cleanup == ["root", "child"]
    assert handle.released and dependency.released
    assert pool.active_tokens() == ()
    with pytest.raises(residency.NativeRuntimeReleasedError):
        handle.terminal_release()
    assert pool.active_tokens() == ()


def test_dependency_conditional_first_activation_is_serialized(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "conditional-race.safetensors"))
    conditional = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("conditional", conditional, scope="conditional"),),
    )
    torch, pool, assembled, _resources = _dependency_materialization_fakes(arm, monkeypatch)
    handle = arm._materialize_recipe_handle(recipe, {asset.digest: asset.resolver}, torch)
    start = threading.Barrier(3)
    failures: list[BaseException] = []

    def stage() -> None:
        try:
            start.wait()
            with handle.stage("diffusion", active_conditional=frozenset({("conditional",)})):
                pass
        except BaseException as exc:
            failures.append(exc)

    threads = [threading.Thread(target=stage) for _ in range(2)]
    for thread in threads:
        thread.start()
    start.wait()
    for thread in threads:
        thread.join(timeout=5)

    assert not failures
    assert all(not thread.is_alive() for thread in threads)
    assert assembled == [(), ("conditional",)]
    assert len(pool.active_tokens()) == 2
    handle.terminal_release()
    assert pool.active_tokens() == ()


def test_dependency_clone_and_rebuild_keep_frozen_resource_and_fresh_ownership(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "clone-rebuild.safetensors"))
    child = _dependency_recipe(arm, asset)
    recipe = _dependency_recipe(
        arm,
        asset,
        dependencies=(_dependency_edge("child", child),),
    )
    torch, pool, assembled, resources = _dependency_materialization_fakes(arm, monkeypatch)
    resolvers = {asset.digest: asset.resolver}
    base = arm._materialize_recipe_handle(recipe, resolvers, torch)
    base_key = base.materialization_key

    clone = base.clone()
    assert clone is not base
    assert clone.materialization_key == base_key
    assert clone.owned_dependencies[("child",)] is not base.owned_dependencies[("child",)]
    assert len(pool.active_tokens()) == 4
    assert len({token.serial for token in pool.active_tokens()}) == 4
    clone.terminal_release()
    assert len(pool.active_tokens()) == 2

    base.terminal_release()
    assert pool.active_tokens() == ()
    rebuilt = base.rebuild()
    assert rebuilt.materialization_key == base_key
    assert len(pool.active_tokens()) == 2
    rebuilt.terminal_release()
    assert pool.active_tokens() == ()
    assert assembled == [("child",), ()] * 3
    assert len({id(resource) for resource in resources}) == 1


