def test_native_hook_graph_routes_sampler_through_scheduled_runtime(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    sample_result = FakeTensor((1, 4, 8, 8), "scheduled")

    class Runtime:
        family = SimpleNamespace(id="dinkster.sd15")

        def __init__(self) -> None:
            self.sample_kwargs: dict[str, object] | None = None

        def sample_scheduled(self, _latent: object, **kwargs: object) -> FakeTensor:
            self.sample_kwargs = kwargs
            return sample_result

    runtime = Runtime()
    handle = _handle(arm, runtime, torch)
    lora_path = tmp_path / "style.safetensors"
    lora_path.write_bytes(b"lora")
    hooks = arm.NativeCreateHookLora.execute(
        lora_name=_asset(lora_path), strength_model=1.0, strength_clip=1.0
    )["hooks"]
    keyframes = arm.NativeCreateHookKeyframe.execute(strength_mult=0.0, start_percent=0.0)[
        "HOOK_KF"
    ]
    keyframes = arm.NativeCreateHookKeyframe.execute(
        strength_mult=1.0, start_percent=0.5, prev_hook_kf=keyframes
    )["HOOK_KF"]
    hooks = arm.NativeSetHookKeyframes.execute(hooks=hooks, hook_kf=keyframes)["hooks"]
    concat_mask = FakeTensor((1, 8, 8), "mask")
    concat_image = FakeTensor((1, 4, 8, 8), "image")
    prompt = [
        [
            FakeTensor((1, 77, 4), "prompt"),
            {
                "dinkster.native/prompt": ("a cat", handle.recipe.runtime_identity),
                "concat_mask": concat_mask,
                "concat_latent_image": concat_image,
            },
        ]
    ]
    scheduled = arm.NativePairConditioningSetProperties.execute(
        positive_NEW=prompt,
        negative_NEW=prompt,
        strength=1.0,
        set_cond_area="default",
        hooks=hooks,
    )
    positive = scheduled["positive"]
    assert "hooks" not in positive[0][1]
    assert "dinkster.native/hooks" in positive[0][1]

    carriers = iter((object(), object()))
    states: list[Any] = []

    def scheduled_carrier(*args: object) -> object:
        states.append(args[-1])
        return next(carriers)

    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "_scheduled_carrier", scheduled_carrier)
    monkeypatch.setattr(arm._NativeScheduleState, "close", lambda _self: None)
    monkeypatch.setattr(
        arm,
        "sampling_preview_emitter",
        lambda _handle: pytest.fail("scheduled sampling has no on_state seam"),
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            SimpleNamespace(
                PatchProviderSnapshot=lambda providers: providers,
                torch_sampler_registry=_fake_torch_sampler_registry,
            )
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )
    inputs = _ksampler_inputs(arm, runtime, torch)
    ordinary_overlay = object()
    model = arm._NativeModelOverlay(handle, (ordinary_overlay,), {"digest": object()})
    inputs.update(model=model, positive=positive, negative=scheduled["negative"])
    output = arm.NativeKSampler.execute(**inputs)

    assert output["latent"]["samples"] is sample_result
    assert runtime.sample_kwargs is not None
    assert callable(runtime.sample_kwargs["resolver"])
    assert "on_state" not in runtime.sample_kwargs
    assert len(states) == 2
    assert all(state.ordinary_overlays == (ordinary_overlay,) for state in states)
    assert all(set(state.resolvers) == {"digest"} for state in states)
    inpaint = cast("Any", runtime.sample_kwargs["inpaint"])
    assert inpaint.mask is concat_mask
    assert inpaint.masked_image is concat_image


def test_native_hook_mask_materializes_canonical_regional_metadata(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import SD15, EncoderStream

    arm = _native_arm()

    class MaskTensor(FakeTensor):
        @property
        def ndim(self) -> int:
            return len(self.shape)

        def unsqueeze(self, dim: int) -> MaskTensor:
            shape = list(self.shape)
            shape.insert(dim, 1)
            return MaskTensor(tuple(shape), self.name, dtype=self.dtype)

    @dataclass(frozen=True)
    class Record:
        mask: object | None = None
        schedule: object = "encoded-schedule"
        extension_metadata: tuple[tuple[str, object], ...] = (("dinkster.test/value", 1),)

    empty = object()

    def intersect_ranges(left: tuple[float, float], right: tuple[float, float]) -> object:
        start = max(left[0], right[0])
        end = min(left[1], right[1])
        return empty if start > end else (start, end)

    inference = SimpleNamespace(
        EMPTY_RANGE=empty,
        PercentRange=lambda start, end: (start, end),
        intersect_ranges=intersect_ranges,
        EncoderStream=EncoderStream,
        ScheduledPromptRoute=lambda stream, text: (stream, text),
        ScheduledPrompt=lambda schedule, routes: SimpleNamespace(schedule=schedule, routes=routes),
        ScheduledPatchStack=lambda schedule, overlays: SimpleNamespace(
            schedule=schedule, overlays=overlays
        ),
        ScheduledEncodeRequest=lambda prompts, **kwargs: SimpleNamespace(prompts=prompts, **kwargs),
        ScheduledVariantOwner=lambda builder: builder,
        ScheduledExecution=lambda owner: SimpleNamespace(owner=owner),
        InferenceTypeRegistry=lambda: object(),
        ConditioningSet=lambda records: SimpleNamespace(records=records),
        MaskDescriptor=lambda payload, strength, bounds: SimpleNamespace(
            payload=payload, strength=strength, set_area_to_bounds=bounds
        ),
        PayloadReference=lambda reference_id: SimpleNamespace(id=reference_id),
        make_conditioning_carrier=lambda conditioning, bindings: SimpleNamespace(
            conditioning=conditioning,
            bindings=tuple({binding.reference_id: binding for binding in bindings}.values()),
        ),
    )
    seen_masks: list[MaskTensor] = []
    text_binding = SimpleNamespace(reference_id="text", shape=(1, 77, 4))
    inference_torch = SimpleNamespace(
        MASK_PAYLOAD_SPACE="conditioning-mask",
        tensor_to_payload_binding=lambda reference_id, mask, **_kwargs: (
            seen_masks.append(mask) or SimpleNamespace(reference_id=reference_id, shape=mask.shape)
        ),
    )

    class Runtime:
        family = SD15

        def encode_text_scheduled(self, _request: object, **_kwargs: object) -> object:
            return SimpleNamespace(
                conditioning=SimpleNamespace(records=(Record(),)),
                bindings=(text_binding,),
            )

    runtime = Runtime()
    handle = SimpleNamespace(recipe=SimpleNamespace(runtime_identity="runtime"), runtime=runtime)
    state = SimpleNamespace(
        inference=inference,
        inference_torch=inference_torch,
        add_hooks=lambda _hooks: None,
        register=lambda _overlays: None,
        builder=object(),
        executions=[],
        ordinary_overlays=(),
    )
    mask = MaskTensor((8, 8), "mask")
    conditioning = [[object(), {"dinkster.native/prompt": ("a cat", "runtime")}]]
    hooks = arm._NativeHooks(
        (
            arm._NativeLoraHook(
                object(),
                1.0,
                0.0,
                arm._NativeHookKeyframes(((0.0, 0.0), (0.5, 1.0))),
            ),
        )
    )
    overlay = SimpleNamespace(strength_model=1.0, strength_clip=0.0)
    monkeypatch.setattr(arm, "_native_lora_overlay", lambda *_args: overlay)
    conditioned = arm.NativePairConditioningSetProperties.execute(
        positive_NEW=conditioning,
        negative_NEW=conditioning,
        strength=0.65,
        set_cond_area="mask bounds",
        mask=mask,
        hooks=hooks,
    )["positive"]

    monkeypatch.setattr(arm, "_torch", FakeTorch)
    carrier = arm._scheduled_carrier(conditioned, "positive", handle, state)

    assert arm._uses_native_scheduling(conditioned)
    assert seen_masks[0].shape == (1, 8, 8)
    assert len(carrier.conditioning.records) == 2
    for record in carrier.conditioning.records:
        assert record.mask.strength == 0.65
        assert record.mask.set_area_to_bounds is True
        assert record.mask.payload.id == "positive-mask-0"
        assert record.schedule == "encoded-schedule"
        assert record.extension_metadata == (("dinkster.test/value", 1),)
    assert carrier.bindings[0] is text_binding
    assert carrier.bindings[1].shape == (1, 8, 8)
    assert len(carrier.bindings) == 2
    assert conditioning[0][1] == {"dinkster.native/prompt": ("a cat", "runtime")}


