def test_native_scheduled_sampler_closes_state_when_second_carrier_fails(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    runtime = SimpleNamespace(family=SimpleNamespace(id="dinkster.sd15"))
    handle = _handle(arm, runtime, torch)
    prompt = [[FakeTensor((1, 77, 4), "prompt"), {"start_percent": 0.0}]]
    inputs = _ksampler_inputs(arm, runtime, torch)
    inputs.update(model=handle, positive=prompt, negative=prompt)
    closed: list[object] = []
    calls = 0

    def carrier(*args: object) -> object:
        nonlocal calls
        calls += 1
        if calls == 2:
            raise RuntimeError("negative carrier failed")
        return object()

    real_import = arm.importlib.import_module
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "_scheduled_carrier", carrier)
    monkeypatch.setattr(arm._NativeScheduleState, "close", lambda self: closed.append(self))
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            SimpleNamespace(
                PatchProviderSnapshot=lambda providers: providers,
                torch_sampler_registry=_fake_torch_sampler_registry,
            )
            if name == "dinkster_inference_torch"
            else real_import(name)
        ),
    )

    with pytest.raises(RuntimeError, match="negative carrier failed"):
        arm.NativeKSampler.execute(**inputs)

    assert len(closed) == 1


