@pytest.mark.parametrize("node", ("ksampler", "custom", "custom_advanced"))
@pytest.mark.parametrize("multistream", (False, True))
@pytest.mark.parametrize("outcome", ("success", "cancel", "preview_error", "runtime_error"))
def test_native_sampling_forwards_callbacks_and_live_cancellation(
    monkeypatch: pytest.MonkeyPatch, node: str, multistream: bool, outcome: str
) -> None:
    from dinkster_inference import (
        SD15,
        CustomSamplingResult,
        MultiStreamLatent,
        MultiStreamLatentDescriptor,
        sampling_environment_cancellation,
    )

    arm = _native_arm()
    torch = FakeTorch()
    events: list[object] = []
    cancelled = False
    failure = RuntimeError(outcome)
    state = object()

    def is_cancelled() -> bool:
        return cancelled

    @contextmanager
    def preview_stage() -> Iterator[None]:
        events.append("preview_enter")
        try:
            yield
        finally:
            events.append("preview_exit")

    def on_state(event: object) -> None:
        assert event is state
        events.append("state")
        if outcome == "preview_error":
            raise failure

    preview = SimpleNamespace(stage=preview_stage, on_state=on_state)

    def sample(latent: Any, **kwargs: Any) -> Any:
        nonlocal cancelled
        events.append("sample")
        ambient = sampling_environment_cancellation()
        assert ambient is is_cancelled
        assert not ambient()
        if node == "ksampler" and multistream:
            assert kwargs["cancelled"] is is_cancelled
        if node != "ksampler" or multistream:
            kwargs["on_step"](SimpleNamespace(step=0, total=2))
        assert kwargs["on_state"] is on_state
        kwargs["on_state"](state)
        cancelled = True
        assert ambient(), "node must not latch cancellation before execution"
        if outcome == "cancel":
            raise SamplingCancelled()
        if outcome == "runtime_error":
            raise failure
        if node != "ksampler":
            assert kwargs["request"].sigmas == (1.0, 0.375, 0.0)
            return CustomSamplingResult(latent, latent)
        return latent

    runtime = _runtime()
    runtime.family = SD15
    runtime.sample = sample
    runtime.sample_custom = sample
    runtime.encode_text = lambda text: Conditioning(FakeTensor((1, 2, 4), text))
    runtime.encode_content = lambda value: value
    runtime.decode_latent = lambda value: value
    runtime.custom_sampling_sigmas = lambda *_args: (1.0, 0.0)
    runtime.custom_sampling_beta_sigmas = lambda *_args: (1.0, 0.0)
    runtime.custom_sampling_sd_turbo_sigmas = lambda *_args: (1.0, 0.0)
    runtime.custom_sampling_percent_to_sigma = lambda *_args, **_kwargs: 0.0
    runtime.check_custom_sampling = _accept_custom_sampling
    runtime.conditioning_identity = "test.multistream"
    inputs = _ksampler_inputs(arm, runtime, torch)
    if multistream:
        runtime.sample_multistream = sample
        runtime.run_ksampler_as_custom = sample
        runtime.family = SimpleNamespace(
            id="dinkster.testav",
            latent=MultiStreamLatentDescriptor(
                (
                    ("video", LatentDescriptor(channels=4, dimensions=3)),
                    ("audio", LatentDescriptor(channels=8, dimensions=1)),
                )
            ),
        )
        inputs["latent_image"] = {
            "samples": MultiStreamLatent.from_pairs(
                (
                    ("video", FakeTensor((1, 4, 2, 8, 8), "video")),
                    ("audio", FakeTensor((1, 8, 16), "audio")),
                )
            ),
            "custom": "preserved",
        }
        inputs["positive"] = inputs["negative"] = [
            [PreparedMultiStreamConditioning(runtime.conditioning_identity, object()), {}]
        ]

    def unexpected_config() -> object:
        pytest.fail("nodes must not query distributed configuration")

    monkeypatch.setitem(
        sys.modules,
        "dinkster_inference_torch.distributed",
        SimpleNamespace(distributed_sampling_config=unexpected_config),
    )
    monkeypatch.setattr(
        arm,
        "_resolve_sampling_model",
        lambda _handle, positive, negative, _inference, **_kwargs: (
            runtime,
            positive,
            negative,
            False,
            False,
        ),
    )
    real_import = arm.importlib.import_module
    fake_inference_torch = SimpleNamespace(
        prepare_noise=lambda samples, *_args: samples,
        prepare_multistream_noise=lambda samples, *_args: samples,
        materialize_basic_conditioning=lambda value, **_kwargs: Conditioning(
            FakeTensor((1, 77, 4), "materialized")
        ),
        torch_sampler_registry=_fake_torch_sampler_registry,
    )
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch", lambda: torch)
    monkeypatch.setattr(arm, "sampling_preview_emitter", lambda _handle: preview)
    monkeypatch.setattr(arm, "multistream_sampling_preview_emitter", lambda _handle: preview)
    monkeypatch.setattr(arm, "report_progress", lambda step, total: events.append((step, total)))
    prior_cancellation = sampling_environment_cancellation()

    def execute() -> Any:
        if node == "ksampler":
            return arm.NativeKSampler.execute(**inputs)["latent"]
        sampler = arm.GenerationKSamplerSelect.execute(sampler_name="euler")["sampler"]
        sigmas = arm._CustomSigmasValue((1.0, 0.375, 0.0))
        if node == "custom":
            return arm.GenerationSamplerCustom.execute(
                model=inputs["model"],
                add_noise=True,
                noise_seed=7,
                cfg=6.5,
                positive=inputs["positive"],
                negative=inputs["negative"],
                sampler=sampler,
                sigmas=sigmas,
                latent_image=inputs["latent_image"],
            )["output"]
        guider = arm.GenerationCFGGuider.execute(
            model=inputs["model"],
            positive=inputs["positive"],
            negative=inputs["negative"],
            cfg=6.5,
        )["guider"]
        return arm.GenerationSamplerCustomAdvanced.execute(
            noise=arm.GenerationRandomNoise.execute(noise_seed=7)["noise"],
            guider=guider,
            sampler=sampler,
            sigmas=sigmas,
            latent_image=inputs["latent_image"],
        )["output"]

    with use_execution_context(ExecutionContext("native", None, cancelled=is_cancelled)):
        if outcome == "success":
            assert execute()["custom"] == "preserved"
        elif outcome == "cancel":
            with pytest.raises(SamplingCancelled):
                execute()
        else:
            with pytest.raises(RuntimeError) as caught:
                execute()
            assert caught.value is failure
    assert sampling_environment_cancellation() is prior_cancellation
    assert "sample" in events
    assert "state" in events
    assert events[0] == "preview_enter"
    assert events[-1] == "preview_exit"
    if node != "ksampler" or multistream:
        assert (1, 2) in events


def _conditioning_value_carrier(
    text: Any,
    pooled: Any = None,
    *,
    with_mask: bool = False,
    scale: Any = None,
) -> Any:
    """One-record carrier holding real numpy payload bytes."""
    import numpy as np
    from dinkster_inference import (
        ConditioningChannel,
        ConditioningRecord,
        ConditioningSet,
        ConditionScaleVector,
        MaskDescriptor,
        PayloadBinding,
        PayloadDescriptor,
        PayloadReference,
        make_conditioning_carrier,
    )

    def bound(tag: str, array: Any, space: str) -> tuple[Any, Any]:
        data = np.ascontiguousarray(array)
        wire = {2: "F16", 4: "F32", 8: "F64"}[int(data.dtype.itemsize)]
        binding = PayloadBinding(tag, tuple(data.shape), wire, space, data.tobytes())
        descriptor = PayloadDescriptor(PayloadReference(tag), binding.shape, wire, space)
        return binding, descriptor

    bindings = []
    text_binding, text_descriptor = bound("value:text", text, "conditioning-text")
    bindings.append(text_binding)
    channels = [(ConditioningChannel.TEXT, text_descriptor)]
    if pooled is not None:
        pooled_binding, pooled_descriptor = bound("value:pooled", pooled, "conditioning-pooled")
        bindings.append(pooled_binding)
        channels.append((ConditioningChannel.POOLED, pooled_descriptor))
    scale_vector = None
    if scale is not None:
        scale_binding, scale_descriptor = bound("value:scale", scale, "conditioning-scale")
        bindings.append(scale_binding)
        scale_vector = ConditionScaleVector(scale_descriptor)
    mask_descriptor = None
    if with_mask:
        mask_binding, _ = bound(
            "value:mask", np.ones((1, 4, 4), dtype=np.float32), "conditioning-mask"
        )
        bindings.append(mask_binding)
        mask_descriptor = MaskDescriptor(PayloadReference(mask_binding.reference_id), 0.8, True)
    record = ConditioningRecord(
        channels=tuple(channels), mask=mask_descriptor, scale_vector=scale_vector
    )
    return make_conditioning_carrier(ConditioningSet((record,)), tuple(bindings))


def _record_channel_binding(carrier: Any, record_index: int, channel: Any) -> Any:
    record = carrier.conditioning.records[record_index]
    payload = dict(record.channels)[channel]
    return next(
        binding for binding in carrier.bindings if binding.reference_id == payload.reference.id
    )


def test_generation_conditioning_merge_combine_concatenates_records() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    first = _conditioning_value_carrier(np.arange(16, dtype=np.float32).reshape(1, 2, 8))
    second = _conditioning_value_carrier(np.full((1, 3, 8), 2.0, dtype=np.float32))

    merged = arm.GenerationConditioningMerge.execute(
        **{
            "mode": "combine",
            "mode.inputs.conditioning_1": first,
            "mode.inputs.conditioning_2": second,
        }
    )["conditioning"]

    assert type(merged) is inference.ConditioningCarrier
    assert merged.conditioning.records == (
        *first.conditioning.records,
        *second.conditioning.records,
    )
    assert {binding.reference_id for binding in merged.bindings} == {
        binding.reference_id for binding in (*first.bindings, *second.bindings)
    }


def test_generation_conditioning_merge_refuses_bad_inputs() -> None:
    import numpy as np

    arm = _native_arm()
    carrier = _conditioning_value_carrier(np.ones((1, 2, 8), dtype=np.float32))

    with pytest.raises(ValueError, match="at least two"):
        arm.GenerationConditioningMerge.execute(
            **{"mode": "combine", "mode.inputs.conditioning_1": carrier}
        )
    with pytest.raises(TypeError, match="conditioning_2 must come from"):
        arm.GenerationConditioningMerge.execute(
            **{
                "mode": "combine",
                "mode.inputs.conditioning_1": carrier,
                "mode.inputs.conditioning_2": object(),
            }
        )
    with pytest.raises(TypeError, match="conditioning_from must come from"):
        arm.GenerationConditioningMerge.execute(
            **{"mode": "concat", "mode.conditioning_to": carrier}
        )
    with pytest.raises(ValueError, match="conditioning_to_strength must be in"):
        arm.GenerationConditioningMerge.execute(
            **{
                "mode": "average",
                "mode.conditioning_to": carrier,
                "mode.conditioning_from": carrier,
                "mode.conditioning_to_strength": 1.5,
            }
        )
    with pytest.raises(ValueError, match="unknown conditioning merge mode"):
        arm.GenerationConditioningMerge.execute(**{"mode": "blend"})


def test_generation_conditioning_merge_average_matches_pinned_math() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    to_text = np.arange(16, dtype=np.float32).reshape(1, 2, 8)
    to_pooled = np.ones((1, 8), dtype=np.float32)
    from_text = np.full((1, 4, 8), 2.0, dtype=np.float32)
    from_pooled = np.full((1, 8), 3.0, dtype=np.float32)

    merged = arm.GenerationConditioningMerge.execute(
        **{
            "mode": "average",
            "mode.conditioning_to": _conditioning_value_carrier(to_text, to_pooled),
            "mode.conditioning_from": _conditioning_value_carrier(from_text, from_pooled),
            "mode.conditioning_to_strength": 0.25,
        }
    )["conditioning"]

    text_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.TEXT)
    expected_text = to_text * 0.25 + from_text[:, :2] * (1.0 - 0.25)
    assert expected_text.dtype == np.float32
    assert text_binding.dtype == "F32"
    assert text_binding.shape == (1, 2, 8)
    assert text_binding.data == expected_text.tobytes()
    pooled_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.POOLED)
    expected_pooled = to_pooled * 0.25 + from_pooled * (1.0 - 0.25)
    assert pooled_binding.data == expected_pooled.tobytes()


def test_generation_conditioning_merge_average_pads_and_inherits_pooled() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    to_text = np.full((1, 3, 4), 4.0, dtype=np.float32)
    from_text = np.full((1, 1, 4), 2.0, dtype=np.float32)
    from_pooled = np.full((1, 4), 3.0, dtype=np.float32)

    merged = arm.GenerationConditioningMerge.execute(
        **{
            "mode": "average",
            "mode.conditioning_to": _conditioning_value_carrier(to_text),
            "mode.conditioning_from": _conditioning_value_carrier(from_text, from_pooled),
            "mode.conditioning_to_strength": 0.5,
        }
    )["conditioning"]

    padded = np.concatenate((from_text, np.zeros((1, 2, 4), dtype=np.float32)), axis=1)
    expected_text = to_text * 0.5 + padded * 0.5
    text_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.TEXT)
    assert text_binding.data == expected_text.tobytes()
    # A to-record without a pooled payload inherits the from-side one.
    pooled_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.POOLED)
    expected_pooled = from_pooled * 0.5 + from_pooled * 0.5
    assert pooled_binding.data == expected_pooled.tobytes()
    assert pooled_binding.space == "conditioning-pooled"


def test_generation_conditioning_merge_concat_appends_from_tokens() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    to_text = np.arange(16, dtype=np.float32).reshape(1, 2, 8)
    to_pooled = np.ones((1, 8), dtype=np.float32)
    from_text = np.full((1, 3, 8), 2.0, dtype=np.float32)

    merged = arm.GenerationConditioningMerge.execute(
        **{
            "mode": "concat",
            "mode.conditioning_to": _conditioning_value_carrier(to_text, to_pooled),
            "mode.conditioning_from": _conditioning_value_carrier(from_text),
        }
    )["conditioning"]

    text_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.TEXT)
    assert text_binding.shape == (1, 5, 8)
    assert text_binding.data == np.concatenate((to_text, from_text), axis=1).tobytes()
    pooled_binding = _record_channel_binding(merged, 0, inference.ConditioningChannel.POOLED)
    assert pooled_binding.data == to_pooled.tobytes()

    with pytest.raises(ValueError, match="cannot be joined along the token axis"):
        arm.GenerationConditioningMerge.execute(
            **{
                "mode": "concat",
                "mode.conditioning_to": _conditioning_value_carrier(to_text),
                "mode.conditioning_from": _conditioning_value_carrier(
                    np.ones((1, 3, 4), dtype=np.float32)
                ),
            }
        )


def test_generation_conditioning_scale_multiplies_text_and_pooled() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    text = np.arange(16, dtype=np.float32).reshape(1, 2, 8)
    pooled = np.arange(8, dtype=np.float16).reshape(1, 8)
    carrier = _conditioning_value_carrier(text, pooled)

    scaled = arm.GenerationConditioningScale.execute(conditioning=carrier, multiplier=2.5)[
        "conditioning"
    ]

    text_binding = _record_channel_binding(scaled, 0, inference.ConditioningChannel.TEXT)
    assert text_binding.dtype == "F32"
    assert text_binding.data == (text * 2.5).tobytes()
    pooled_binding = _record_channel_binding(scaled, 0, inference.ConditioningChannel.POOLED)
    expected_pooled = pooled * 2.5
    assert expected_pooled.dtype == np.float16
    assert pooled_binding.dtype == "F16"
    assert pooled_binding.data == expected_pooled.tobytes()

    with pytest.raises(ValueError, match="multiplier must be in"):
        arm.GenerationConditioningScale.execute(conditioning=carrier, multiplier=1000.0)
    with pytest.raises(TypeError, match="conditioning must come from"):
        arm.GenerationConditioningScale.execute(conditioning=object(), multiplier=1.0)


def test_generation_conditioning_zero_out_zeroes_payloads_and_scale_vector() -> None:
    import numpy as np

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    carrier = _conditioning_value_carrier(
        np.arange(16, dtype=np.float16).reshape(1, 2, 8),
        np.ones((1, 8), dtype=np.float32),
        scale=np.full((8,), 2.0, dtype=np.float32),
    )

    zeroed = arm.GenerationConditioningZeroOut.execute(conditioning=carrier)["conditioning"]

    text_binding = _record_channel_binding(zeroed, 0, inference.ConditioningChannel.TEXT)
    assert text_binding.dtype == "F16"
    assert text_binding.shape == (1, 2, 8)
    assert text_binding.data == bytes(32)
    pooled_binding = _record_channel_binding(zeroed, 0, inference.ConditioningChannel.POOLED)
    assert pooled_binding.dtype == "F32"
    assert pooled_binding.data == bytes(32)
    scale_vector = zeroed.conditioning.records[0].scale_vector
    assert scale_vector is not None
    scale_binding = next(
        binding
        for binding in zeroed.bindings
        if binding.reference_id == scale_vector.values.reference.id
    )
    assert scale_binding.data == bytes(32)


def test_generation_conditioning_set_area_pixels_percent_and_video_match_pin() -> None:
    import numpy as np

