@pytest.mark.parametrize("outcome", ("dynamic", "gate-fallback", "construction-failure"))
def test_chroma_builders_select_device_before_component_loading(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, outcome: str
) -> None:
    arm = _native_arm()
    asset = _asset(_safetensors(tmp_path / "chroma.safetensors"))
    inference = importlib.import_module("dinkster_inference")
    descriptor = replace(
        arm._component_descriptor("dinkster.chroma"), runtime_factory=None, plan_family=None
    )
    plans = {
        role: inference.ComponentPlan(role, asset.local_path(), None, {}, {}, {})
        for role in ("t5xxl", "diffusion")
    }
    torch = FakeTorch(cuda=True)
    selected = FakeDevice("cuda:0")
    load_calls: list[dict[str, object]] = []
    enrollment_calls: list[dict[str, object]] = []
    mechanism_calls: list[dict[str, object]] = []
    runtime_builds: list[dict[str, object]] = []
    coordinator_calls: list[dict[str, object]] = []
    route_providers: list[Callable[[], object]] = []

    def load_component(_path: Path, **kwargs: object) -> object:
        load_calls.append(dict(kwargs))
        return SimpleNamespace(
            role=kwargs["expected_role"],
            module=object(),
            plan=plans[cast("str", kwargs["expected_role"])],
            runtime_identity=kwargs["expected_identity"],
            attention_status="attention",
        )

    fake_inference_torch = SimpleNamespace(
        ResidentWeights=lambda _weights, **_kwargs: object(),
        dynamic_free_memory=object(),
        load_chroma_component=load_component,
        ChromaDiffusionRuntime=lambda module, **kwargs: SimpleNamespace(
            assembled=SimpleNamespace(diffusion=module), **kwargs
        ),
        enroll_component=lambda *_args, **_kwargs: None,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "select_load_device", lambda _torch: selected)

    class Coordinator:
        def __init__(self, **kwargs: object) -> None:
            coordinator_calls.append(kwargs)

        def enroll_component(self, module: object, **kwargs: object) -> object:
            enrollment_calls.append({"module": module, **kwargs})
            mechanism_factory = kwargs.get("mechanism_factory")
            if mechanism_factory is not None:
                cast("Any", mechanism_factory)(
                    SimpleNamespace(module=module),
                    load_device=kwargs["load_device"],
                    offload_device=kwargs["offload_device"],
                )
            return object()

    class Handle:
        def __init__(self, *_args: object, **kwargs: object) -> None:
            route_providers.append(cast(Any, kwargs["residency_route_facts"]))

        def attach_pool(self, _pool: object) -> None:
            pass

    monkeypatch.setenv("DINKSTER_AIMDO_ARM", "auto")

    def aimdo_factory(_weights: object, **kwargs: object) -> object:
        mechanism_calls.append(kwargs)
        if outcome == "construction-failure":
            raise RuntimeError("allocation failed")
        return object()

    monkeypatch.setattr(
        arm,
        "_aimdo_mechanism_factory",
        lambda *_args: (
            (None, "aimdo device activation gate failed")
            if outcome == "gate-fallback"
            else (aimdo_factory, None)
        ),
    )
    monkeypatch.setattr(arm, "default_native_residency", Coordinator)
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "default_pool", FakePool)
    monkeypatch.setattr(
        arm,
        "_build_runtime_handle",
        lambda runtime, _torch, **kwargs: (
            runtime_builds.append({"runtime": runtime, **kwargs}) or object()
        ),
    )

    if outcome == "construction-failure":
        with pytest.raises(RuntimeError, match="allocation failed"):
            arm._build_component_runtime_handle(
                descriptor,
                asset,
                "t5xxl",
                descriptor.component_identity("t5xxl", plans["t5xxl"], "float32"),
                torch,
                compute_dtype="float32",
            )
        assert len(load_calls) == 1
        assert len(enrollment_calls) == 1
        assert isinstance(enrollment_calls[0]["mechanism_factory"], arm._AimdoComponentFactory)
        assert coordinator_calls == [{"free_memory": fake_inference_torch.dynamic_free_memory}]
        assert route_providers == []
        assert runtime_builds == []
        return

    arm._build_component_runtime_handle(
        descriptor,
        asset,
        "t5xxl",
        descriptor.component_identity("t5xxl", plans["t5xxl"], "float32"),
        torch,
        compute_dtype="float32",
    )
    arm._build_component_runtime_handle(
        descriptor,
        asset,
        "diffusion",
        descriptor.component_identity("diffusion", plans["diffusion"], "bfloat16"),
        torch,
        compute_dtype="bfloat16",
    )
    arm._build_component_runtime_handle(
        descriptor,
        asset,
        "diffusion",
        descriptor.component_identity("diffusion", plans["diffusion"], "bfloat16"),
        torch,
        compute_dtype="bfloat16",
        as_model=True,
    )

    assert [(call["expected_role"], call["load_device"]) for call in load_calls] == [
        ("t5xxl", selected),
        ("diffusion", selected),
        ("diffusion", selected),
    ]
    assert [call["attention_backend"] for call in load_calls] == ["t5", "flux", "flux"]
    assert enrollment_calls[0]["load_device"] == selected
    if outcome != "gate-fallback":
        assert all(
            isinstance(call["mechanism_factory"], arm._AimdoComponentFactory)
            for call in enrollment_calls
        )
        assert mechanism_calls == [
            {"load_device": selected, "offload_device": FakeDevice("cpu")},
            {
                "load_device": selected,
                "offload_device": FakeDevice("cpu"),
                "fixed_promotion": True,
                "promote_non_fp8_raw": True,
            },
        ]
        assert coordinator_calls == [
            {"free_memory": fake_inference_torch.dynamic_free_memory},
            {"free_memory": fake_inference_torch.dynamic_free_memory},
        ]
    else:
        assert all("mechanism_factory" not in call for call in enrollment_calls)
        assert mechanism_calls == []
        assert coordinator_calls == [{}, {}]
    facts = [cast(Any, provider()) for provider in route_providers]
    if outcome == "dynamic":
        assert [fact.dynamic_components for fact in facts] == [("t5xxl",), ("diffusion",)]
        assert all(fact.mechanism == "aimdo" for fact in facts)
    else:
        assert [fact.fallback_components for fact in facts] == [("t5xxl",), ("diffusion",)]
        assert all(fact.mechanism == "eager" and fact.fallback_reason for fact in facts)
    assert runtime_builds[0]["load_device"] == selected


def test_generation_clip_text_encode_binds_chroma_component_and_forwards_t5_options(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import ConditioningCarrier, split_component_conditioning

    arm = _native_arm()
    events: list[object] = []
    identity = "native:dinkster.chroma:" + "2" * 64

    class Handle:
        resource_identity = identity
        recipe = SimpleNamespace(
            family_id="dinkster.chroma",
            sources=(SimpleNamespace(role="t5xxl"),),
            runtime_identity=identity,
        )

        def require_active(self) -> None:
            pass

        @property
        def component(self) -> object:
            assert events[-1] == "stage"
            return "text-module"

        @contextmanager
        def stage(self):  # noqa: ANN201
            events.append("stage")
            try:
                yield
            finally:
                events.append("unstage")

    class TextRuntime:
        def __init__(self, component: object) -> None:
            assert component == "text-module"

        def encode_text(
            self,
            text: str,
            *,
            min_padding: int | None = None,
            min_length: int | None = None,
        ) -> object:
            assert text == "a radiant sculpture"
            events.append(("encode", min_padding, min_length))
            return object()

    carrier = _component_conditioning_carrier("chroma-component-text")
    fake_inference_torch = SimpleNamespace(
        ChromaTextRuntime=TextRuntime,
        basic_conditioning_to_carrier=lambda _value: carrier,
    )
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "NativeComponentHandle", Handle)
    monkeypatch.setattr(arm, "_torch", FakeTorch)

    selected = arm.GenerationT5TokenizerOptions.execute(
        clip=Handle(), min_padding=9, min_length=128
    )["clip"]
    result = arm.GenerationClipTextEncode.execute(text="a radiant sculpture", clip=selected)

    bound = cast("Any", result["conditioning"])
    assert type(bound) is ConditioningCarrier
    stripped, binding = split_component_conditioning(bound)
    assert binding is not None
    assert binding.role == "t5xxl"
    assert binding.family_id == "dinkster.chroma"
    assert binding.identity == identity
    assert stripped.conditioning == carrier.conditioning
    assert events == ["stage", ("encode", 9, 128), "unstage"]

    second = arm.GenerationClipTextEncode.execute(text="a radiant sculpture", clip=selected)
    assert type(second["conditioning"]) is ConditioningCarrier
    assert events == [
        "stage",
        ("encode", 9, 128),
        "unstage",
        "stage",
        ("encode", 9, 128),
        "unstage",
    ]


def test_chroma_execution_unloads_text_after_materializing_all_conditioning(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import (
        ComponentBinding,
        WeightSourceBinding,
        bind_component_conditioning,
    )

    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    identity = "native:dinkster.chroma:" + "2" * 64
    events: list[str] = []

    class Coordinator:
        busy = False

        def advisory_unload_components(self, resource_identity: str) -> None:
            assert resource_identity == identity
            if self.busy:
                raise arm.NativeResidencyBusyError("busy")
            events.append("unload")

    coordinator = Coordinator()

    class DiffusionRuntime:
        def __init__(
            self,
            diffusion: object,
            *,
            runtime_identity: str,
            compute_dtype: object,
            sampling_shift: float,
            option_windows: tuple[object, ...],
            attention_status: object,
        ) -> None:
            self.assembled = SimpleNamespace(diffusion=diffusion)
            self.family = inference.CHROMA_RADIANCE
            self.runtime_identity = runtime_identity
            self.compute_dtype = compute_dtype
            self.sampling_shift = sampling_shift
            self.option_windows = option_windows
            self.attention_status = attention_status

        @staticmethod
        def prepare_single_stream_conditioning(carrier: object) -> object:
            events.append("prepare")
            return SimpleNamespace(embeddings=object())

    base_recipe = _recipe()
    recipe = replace(
        base_recipe,
        sources=(WeightSourceBinding("diffusion", base_recipe.sources[0].source),),
        family_id=inference.CHROMA_RADIANCE.id,
        component_identity=("family=dinkster.chroma_radiance", "role=diffusion"),
    )
    base_runtime = DiffusionRuntime(
        object(),
        runtime_identity=recipe.runtime_identity,
        compute_dtype=FakeTorch.float16,
        sampling_shift=1.0,
        option_windows=(),
        attention_status="attention",
    )
    handle = SimpleNamespace(
        recipe=recipe,
        runtime=base_runtime,
        coordinator=coordinator,
    )
    binding = ComponentBinding("t5xxl", inference.CHROMA.id, identity)
    positive = bind_component_conditioning(_component_conditioning_carrier("positive"), binding)
    negative = bind_component_conditioning(_component_conditioning_carrier("negative"), binding)
    fake_inference_torch = SimpleNamespace(ChromaDiffusionRuntime=DiffusionRuntime)
    real_import = arm.importlib.import_module
    monkeypatch.setattr(
        arm.importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )
    monkeypatch.setattr(arm, "_torch_dtype", lambda *_args: FakeTorch.float16)
    monkeypatch.setattr(arm, "_torch", FakeTorch)

    runtime, rows, negative_rows = arm.resolve_component_execution(
        handle, positive, negative, inference
    )

    assert runtime.runtime_identity != recipe.runtime_identity
    assert len(rows) == len(negative_rows) == 1
    assert events == ["prepare", "prepare", "unload"]

    coordinator.busy = True
    events.clear()
    arm.resolve_component_execution(handle, positive, negative, inference)
    assert events == ["prepare", "prepare"]


def _chroma_radiance_model(arm: Any) -> Any:
    from dinkster_inference import WeightSourceBinding

    base = _recipe()
    recipe = replace(
        base,
        sources=(WeightSourceBinding("diffusion", base.sources[0].source),),
        family_id="dinkster.chroma_radiance",
        component_identity=("family=dinkster.chroma_radiance", "role=diffusion"),
    )
    runtime = SimpleNamespace(family=SimpleNamespace(id=recipe.family_id))
    return _handle(arm, runtime, recipe=recipe)


def test_chroma_radiance_options_noop_chaining_and_replacement(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    model = _chroma_radiance_model(arm)
    real_import = importlib.import_module
    fake_inference_torch = SimpleNamespace(
        ChromaRadianceOptions=lambda nerf_tile_size, force_sequential_txt_ids: SimpleNamespace(
            nerf_tile_size=nerf_tile_size,
            force_sequential_txt_ids=force_sequential_txt_ids,
        ),
        ChromaRadianceOptionWindow=lambda options, start_sigma, end_sigma: SimpleNamespace(
            options=options,
            start_sigma=start_sigma,
            end_sigma=end_sigma,
        ),
    )
    monkeypatch.setattr(
        importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )

    unchanged = arm.GenerationChromaRadianceOptions.execute(
        model=model,
        preserve_wrapper=True,
        start_sigma=1.0,
        end_sigma=0.0,
        nerf_tile_size=-1,
        force_sequential_txt_ids=False,
    )["model"]
    assert unchanged is model

    first = arm.GenerationChromaRadianceOptions.execute(
        model=model,
        preserve_wrapper=True,
        start_sigma=1.0,
        end_sigma=0.5,
        nerf_tile_size=8,
        force_sequential_txt_ids=False,
    )["model"]
    second = arm.GenerationChromaRadianceOptions.execute(
        model=first,
        preserve_wrapper=True,
        start_sigma=0.75,
        end_sigma=0.25,
        nerf_tile_size=-1,
        force_sequential_txt_ids=True,
    )["model"]
    assert type(second) is arm._NativeModelOverlay
    assert [window.options.nerf_tile_size for window in second.chroma_radiance_options] == [
        8,
        None,
    ]
    assert second.chroma_radiance_options[1].options.force_sequential_txt_ids is True

    replacement = arm.GenerationChromaRadianceOptions.execute(
        model=second,
        preserve_wrapper=False,
        start_sigma=0.0,
        end_sigma=1.0,
        nerf_tile_size=0,
        force_sequential_txt_ids=False,
    )["model"]
    assert len(replacement.chroma_radiance_options) == 1
    window = replacement.chroma_radiance_options[0]
    assert window.options.nerf_tile_size == 0
    assert (window.start_sigma, window.end_sigma) == (0.0, 1.0)


def test_chroma_diffusion_runtime_applies_shift_and_option_only_sampling_overlays(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    torch = FakeTorch()
    recipe = _chroma_radiance_model(arm).recipe

    class DiffusionRuntime:
        def __init__(
            self,
            diffusion: object,
            *,
            runtime_identity: str,
            compute_dtype: object = torch.float16,
            sampling_shift: float = 1.0,
            option_windows: tuple[object, ...] = (),
            attention_status: object = None,
        ) -> None:
            self.runtime_identity = runtime_identity
            self.family = SimpleNamespace(id=recipe.family_id)
            self.assembled = SimpleNamespace(
                diffusion=diffusion,
                compute_dtype=lambda component: compute_dtype if component == "diffusion" else None,
            )
            self.diffusion = diffusion
            self.sampling_shift = sampling_shift
            self.option_windows = option_windows
            self.attention_status = attention_status

    runtime = DiffusionRuntime(object(), runtime_identity=recipe.runtime_identity)
    runtime.attention_status = {"flux": "sdpa"}
    handle = _handle(arm, runtime, torch, recipe=recipe)
    options = (object(),)
    real_import = importlib.import_module
    fake_inference_torch = SimpleNamespace(ChromaDiffusionRuntime=DiffusionRuntime)
    monkeypatch.setattr(
        importlib,
        "import_module",
        lambda name: (
            fake_inference_torch if name == "dinkster_inference_torch" else real_import(name)
        ),
    )

    shifted = arm._NativeModelOverlay(
        handle=handle,
        overlays=(),
        source_resolvers={},
        sampling_shift=1.73,
    )
    shifted_runtime, scheduler_shift, schedule_device = arm._require_custom_sampling_runtime(
        shifted, "BasicScheduler"
    )
    assert scheduler_shift is None
    assert schedule_device == handle.load_device
    assert shifted_runtime.diffusion is runtime.assembled.diffusion
    assert shifted_runtime.sampling_shift == 1.73
    assert shifted_runtime.option_windows == ()
    assert shifted_runtime.attention_status == runtime.attention_status

    optioned = arm._NativeModelOverlay(
        handle=handle,
        overlays=(),
        source_resolvers={},
        chroma_radiance_options=options,
    )
    optioned_runtime, scheduler_shift, schedule_device = arm._require_custom_sampling_runtime(
        optioned, "BasicScheduler"
    )
    assert scheduler_shift is None
    assert schedule_device == handle.load_device
    assert optioned_runtime.diffusion is runtime.assembled.diffusion
    assert optioned_runtime.sampling_shift == 1.0
    assert optioned_runtime.option_windows == options
    assert optioned_runtime.attention_status == runtime.attention_status


