def test_trellis2_split_runtime_builds_and_retains_all_flow_sources(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    arm = _native_arm()
    inference = importlib.import_module("dinkster_inference")
    roles = ("structure", "shape", "shape-512", "texture", "texture-512")
    assets = _split_assets(tmp_path, roles)
    plans = {
        role: inference.ComponentPlan(
            role,
            assets[role].local_path(),
            SimpleNamespace(stage=role.partition("-")[0]),
            {},
            {},
            {},
        )
        for role in roles
    }
    plan = inference.Trellis2SplitModelPlan(
        structure=plans["structure"],
        shape=plans["shape"],
        shape_512=plans["shape-512"],
        texture=plans["texture"],
        texture_512=plans["texture-512"],
    )
    recipe = arm._trellis2_split_model_recipe(inference, assets, plan, "bfloat16")
    modules = {role: object() for role in roles}
    loaded: list[tuple[str, str, object]] = []

    def load_flow(path: Path, *, asset: AssetRef, expected_role: str, compute_dtype: object):
        assert path == assets[expected_role].local_path()
        assert asset is assets[expected_role] or asset.digest == assets[expected_role].digest
        loaded.append((expected_role, asset.digest, compute_dtype))
        return SimpleNamespace(plan=plans[expected_role], module=modules[expected_role])

    inference_torch = SimpleNamespace(
        load_trellis2_flow_artifact=load_flow,
        Trellis2FlowBundle=lambda **kwargs: SimpleNamespace(**kwargs),
        AssembledTrellis2=lambda diffusion, selected_plan: SimpleNamespace(
            diffusion=diffusion, plan=selected_plan
        ),
        Trellis2DiffusionRuntime=lambda assembled, **kwargs: SimpleNamespace(
            assembled=assembled, **kwargs
        ),
    )
    real_import = arm.importlib.import_module

    def import_module(name: str) -> object:
        if name == "dinkster_inference_torch":
            return inference_torch
        return real_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", import_module)
    built: list[dict[str, object]] = []

    def build_handle(runtime: object, _torch: object, **kwargs: object) -> object:
        built.append({"runtime": runtime, **kwargs})
        return SimpleNamespace(runtime=runtime, **kwargs)

    monkeypatch.setattr(arm, "_build_runtime_handle", build_handle)
    retained = {"blake3:" + "f" * 64: object()}

    handle = arm._build_trellis2_split_model_handle(
        assets,
        recipe.runtime_identity,
        FakeTorch(),
        compute_dtype="bfloat16",
        source_resolvers=retained,
    )

    assert [item[0] for item in loaded] == [
        "shape",
        "shape-512",
        "structure",
        "texture",
        "texture-512",
    ]
    assert all(item[2] == FakeTorch.bfloat16 for item in loaded)
    assembled = cast("Any", handle.runtime).assembled
    assert assembled.plan == plan
    assert (
        assembled.diffusion.structure,
        assembled.diffusion.shape,
        assembled.diffusion.shape_512,
        assembled.diffusion.texture,
        assembled.diffusion.texture_512,
    ) == tuple(modules[role] for role in roles)
    resolvers = cast("dict[str, object]", built[0]["source_resolvers"])
    assert retained.items() <= resolvers.items()
    assert {asset.digest for asset in assets.values()} <= set(resolvers)

    rebuilt = cast("Any", built[0]["materializer"])(recipe, resolvers)
    assert rebuilt.recipe == recipe
    assert len(loaded) == 10
    assert cast("dict[str, object]", built[1]["source_resolvers"]) == resolvers


