def test_model_sampling_sd3_applies_shift_to_any_flow_model() -> None:
    from dinkster_inference import FlowSigmas, builtin_scheduler_registry, sampling_sigmas

    arm = _native_arm()
    base = _recipe()
    recipe = replace(
        base,
        family_id="dinkster.trellis2",
        component_identity=("family=dinkster.trellis2",),
    )
    model = _handle(
        arm,
        SimpleNamespace(family=SimpleNamespace(id="dinkster.trellis2")),
        recipe=recipe,
    )

    output = arm.GenerationModelSamplingSD3.execute(model=model, shift=5.0)["model"]
    assert output.handle is model
    assert output.sampling_shift == 5.0
    integer_output = arm.GenerationModelSamplingSD3.execute(model=model, shift=5)["model"]
    assert integer_output.sampling_shift == 5.0
    added_noise = object()

    class Runtime:
        @staticmethod
        def custom_sampling_add_noise(latent: object, noise: object, sigma: float) -> object:
            assert (latent, noise, sigma) == ("latent", "noise", 0.75)
            return added_noise

    shifted = arm._ShiftedCustomSamplingRuntime(5.0, Runtime())
    scheduler = builtin_scheduler_registry().get("dinkster.simple")
    assert scheduler is not None
    assert shifted.custom_sampling_sigmas("dinkster.simple", 4, 1.0) == sampling_sigmas(
        scheduler, FlowSigmas(shift=5.0), 4
    )
    assert shifted.custom_sampling_add_noise("latent", "noise", 0.75) is added_noise

    with pytest.raises(ValueError, match="requires a flow model"):
        arm.GenerationModelSamplingSD3.execute(model=_handle(arm, _runtime()), shift=3.0)
    with pytest.raises(ValueError, match="positive finite"):
        arm.GenerationModelSamplingSD3.execute(model=model, shift=0.0)


def test_model_sampling_ltxv_uses_video_tokens_and_preserves_overlay_state(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from dinkster_inference import LTX_SAMPLING, MultiStreamLatent

    arm = _native_arm()
    torch = FakeTorch()
    runtime = _runtime()
    runtime.family = SimpleNamespace(id="dinkster.ltxv", sampling=LTX_SAMPLING)
    runtime.supports_sampling_shift = True
    handle = _handle(arm, runtime, torch)
    original = arm._NativeModelOverlay(
        handle,
        (_overlay(),),
        {"retained": object()},
        guidance_transforms=(("test", object()),),
        sampling_cache=object(),
        sampling_timeline=object(),
    )
    video = FakeTensor((1, 128, 4, 16, 16), "video")
    audio = FakeTensor((1, 8, 99, 16), "audio")
    streams = MultiStreamLatent.from_pairs((("video", video), ("audio", audio)))
    monkeypatch.setattr(arm, "_torch", lambda: torch)

    patched = arm.GenerationModelSamplingLTXV.execute(
        model=original,
        max_shift=3.5,
        base_shift=1.25,
        latent={"samples": streams},
    )["model"]

    assert patched.sampling_shift == pytest.approx(1.25)
    assert patched.handle is handle
    assert patched.overlays is original.overlays
    assert patched.source_resolvers is original.source_resolvers
    assert patched.guidance_transforms is original.guidance_transforms
    assert patched.sampling_cache is original.sampling_cache
    assert patched.sampling_timeline is original.sampling_timeline
    assert original.sampling_shift is None
    dense = arm.GenerationModelSamplingLTXV.execute(
        model=handle,
        max_shift=3.5,
        base_shift=1.25,
        latent={"samples": FakeTensor((1, 128, 16, 16, 16), "video")},
    )["model"]
    assert dense.sampling_shift == pytest.approx(3.5)
    defaulted = arm.GenerationModelSamplingLTXV.execute(model=handle)["model"]
    assert defaulted.sampling_shift == pytest.approx(2.05)


