def test_model_sampling_flux_geometry_preserves_overlay_state() -> None:
    from dinkster_inference import FluxFlowSigmas

    arm = _native_arm()
    runtime = _runtime()
    accepted: list[FluxFlowSigmas] = []

    def derive(space: FluxFlowSigmas) -> object:
        accepted.append(space)
        return runtime

    runtime.with_sampling_space = derive
    handle = _handle(arm, runtime)
    original = arm._NativeModelOverlay(
        handle,
        (_overlay(),),
        {"retained": object()},
        sampling_shift=3.0,
        guidance_transforms=(("test", object()),),
        sampling_cache=object(),
        sampling_timeline=object(),
    )
    golden = json.loads(
        (
            Path(__file__).parents[1]
            / "packages/dinkster-inference-torch/tests/goldens/model_sampling_flux.json"
        ).read_text()
    )
    for case in golden["cases"]:
        inputs = {key: case[key] for key in ("max_shift", "base_shift", "width", "height")}
        patched = arm.GenerationModelSamplingFlux.execute(model=original, **inputs)["model"]
        assert accepted[-1].shift == case["shift"]
        assert patched.sampling_space == FluxFlowSigmas(shift=case["shift"])
        assert patched.sampling_shift is None
        assert patched.handle is handle
        assert patched.overlays is original.overlays
        assert patched.source_resolvers is original.source_resolvers
        assert patched.guidance_transforms is original.guidance_transforms
        assert patched.sampling_cache is original.sampling_cache
        assert patched.sampling_timeline is original.sampling_timeline
        assert original.sampling_shift == 3.0 and original.sampling_space is None
        chained = arm.GenerationModelSamplingFlux.execute(model=patched)["model"]
        assert chained.sampling_space == FluxFlowSigmas(shift=1.15)
        assert patched.sampling_space == FluxFlowSigmas(shift=case["shift"])


