def test_cfg_override_binds_percent_range_to_model_sigmas(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    model = object()
    calls: list[tuple[object, ...]] = []

    def percent_to_sigma(
        percent: float,
        *,
        return_actual_sigma: bool,
        sampling_shift: float | None = None,
    ) -> float:
        calls.append((percent, return_actual_sigma, sampling_shift))
        return 1.0 - percent

    runtime = SimpleNamespace(
        custom_sampling_percent_to_sigma=percent_to_sigma,
    )
    contribution = object()
    monkeypatch.setattr(
        arm,
        "_require_custom_sampling_runtime",
        lambda value, _name: (runtime, 1.73, "cuda:0"),
    )
    monkeypatch.setattr(
        arm,
        "_guidance_transform_factory",
        lambda *args: calls.append(args) or contribution,
    )
    monkeypatch.setattr(
        arm,
        "_model_with_guidance_transform",
        lambda value, node_type, value_contribution: (
            value,
            node_type,
            value_contribution,
        ),
    )

    output = arm.GenerationCFGOverride.execute(
        model=model,
        cfg=1.0,
        start_percent=0.6,
        end_percent=1.0,
    )["model"]
    assert calls == [
        (0.6, True, 1.73),
        (1.0, True, 1.73),
        ("cfg_override", 1.0, 0.0, 0.4),
    ]
    assert output == (model, "dinkster.cfg_override", contribution)


