def test_trellis2_conditioning_connects_to_both_sampling_surfaces() -> None:
    arm = _native_arm()
    expected = ("dinkster.conditioning",)
    for node_type, input_ids in (
        ("dinkster.ksampler", ("positive", "negative")),
        ("dinkster.ksampler_advanced", ("positive", "negative")),
        ("dinkster.basic_guider", ("conditioning",)),
        ("dinkster.cfg_guider", ("positive", "negative")),
        ("dinkster.scheduled_cfg_guider", ("positive", "negative")),
        ("dinkster.sampler_custom", ("positive", "negative")),
    ):
        schema = arm._generation_provider_schema(node_type)
        inputs = {item.id: item for item in schema.inputs}
        assert all(inputs[input_id].type.types == expected for input_id in input_ids)


def test_trellis2_execution_model_wraps_resident_lanes_for_custom_sampling(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    arm = _native_arm()
    from dinkster_inference import (
        GuidanceRole,
        PreparedMultiStreamConditioning,
        ResidentConditioningCarrier,
    )

    class Runtime:
        runtime_identity = "runtime"
        conditioning_identity = "conditioning"

    class Resource:
        def __init__(self, role: GuidanceRole, backing: object) -> None:
            self.guidance_role = role
            self.stage = "shape"
            self.backing = backing

        def shares_backing(self, other: object) -> bool:
            return type(other) is Resource and self.backing is other.backing

    runtime = Runtime()
    module = SimpleNamespace(
        Trellis2DiffusionRuntime=Runtime,
        Trellis2ConditioningResource=Resource,
    )
    original_import = importlib.import_module

    def load_module(name: str):
        return module if name == "dinkster_inference_torch" else original_import(name)

    monkeypatch.setattr(arm.importlib, "import_module", load_module)
    family = SimpleNamespace(id="dinkster.trellis2")
    inference = SimpleNamespace(
        TRELLIS2=family,
        GuidanceRole=GuidanceRole,
        PreparedMultiStreamConditioning=PreparedMultiStreamConditioning,
        ResidentConditioningCarrier=ResidentConditioningCarrier,
    )
    handle = SimpleNamespace(
        runtime=runtime,
        recipe=SimpleNamespace(
            family_id=family.id,
            runtime_identity=runtime.runtime_identity,
            sources=(SimpleNamespace(role="diffusion"),),
        ),
    )
    backing = object()
    positive_resource = Resource(GuidanceRole.CONDITIONAL, backing)
    negative_resource = Resource(GuidanceRole.UNCONDITIONAL, backing)
    positive = ResidentConditioningCarrier(positive_resource)
    negative = ResidentConditioningCarrier(negative_resource)

    resolved = arm.resolve_trellis2_component_execution(handle, positive, negative, inference)
    assert resolved is not None
    resolved_runtime, positive_rows, negative_rows = resolved
    assert resolved_runtime is runtime
    assert positive_rows[0][0] == PreparedMultiStreamConditioning("conditioning", positive_resource)
    assert negative_rows[0][0] == PreparedMultiStreamConditioning("conditioning", negative_resource)

    handle.recipe.sources = tuple(
        SimpleNamespace(role=role)
        for role in ("shape", "shape-512", "structure", "texture", "texture-512")
    )
    assert (
        arm.resolve_trellis2_component_execution(handle, positive, negative, inference) is not None
    )

    handle.recipe.sources = (SimpleNamespace(role="structure"),)
    assert arm.resolve_trellis2_component_execution(handle, positive, negative, inference) is None

    handle.recipe.sources = (SimpleNamespace(role="diffusion"),)
    with pytest.raises(ValueError, match="share one backing"):
        arm.resolve_trellis2_component_execution(
            handle,
            positive,
            ResidentConditioningCarrier(Resource(GuidanceRole.UNCONDITIONAL, object())),
            inference,
        )


def test_scheduled_prompt_routes_follow_declared_encoders() -> None:
    from dataclasses import replace

    import dinkster_inference as inference

    arm = _native_arm()
    for family in (
        inference.SD15,
        inference.SDXL,
        inference.SDXL_REFINER,
        inference.FLUX_DEV,
        inference.FLUX_SCHNELL,
    ):
        routes = arm._prompt_routes(inference, family, "cat")
        assert (
            arm._prompt_routes(inference, replace(family, id="test.synthetic-family"), "cat")
            == routes
        )
    assert arm._prompt_routes(inference, inference.FLUX_DEV, "cat") == (
        inference.ScheduledPromptRoute(inference.EncoderStream.CLIP_L, "cat"),
        inference.ScheduledPromptRoute(inference.EncoderStream.T5, "cat"),
    )
